// Editorial enrichment content for /best/[slug] pages. All 7 locales.
// Auto-extended with de/ro/sr/bg/ru translations (gpt-4o + Halkidiki glossary).

type L = Record<string, string>;

export interface BestGuideEnrichment {
  intro?: L;
  criteria?: L;
  seasonal?: L;
  tips?: L;
  faqs?: { q: L; a: L }[];
}

export const ENRICHMENTS: Record<string, BestGuideEnrichment> = {
  "beaches-kassandra": {
    intro: { el: `<p>Η Κασσάνδρα είναι το πρώτο και πιο προσβάσιμο από τα τρία πόδια της Χαλκιδικής — μόλις μία ώρα από τη Θεσσαλονίκη. Έχει μερικές από τις πιο οργανωμένες, φωτογενείς και κοσμοπολίτικες παραλίες της βόρειας Ελλάδας: από μεγάλες αμμώδεις εκτάσεις με beach bars και ξαπλώστρες μέχρι ήσυχους όρμους που μένουν σχετικά απάτητοι ακόμη και τον Αύγουστο. Η ανατολική και η δυτική ακτή έχουν διαφορετικό χαρακτήρα — το ανατολικό προστατεύεται από τους ετήσιους ανέμους, το δυτικό προσφέρει εντυπωσιακό ηλιοβασίλεμα. Αυτή η λίστα συγκεντρώνει τις παραλίες που σταθερά ανεβαίνουν στις προτιμήσεις των επισκεπτών μας, με βάση αξιολογήσεις, διαθέσιμες υποδομές και ποιότητα νερού.</p>`, en: `<p>Kassandra is the first and most accessible of Halkidiki's three legs — just an hour from Thessaloniki. It has some of the most organised, photogenic and cosmopolitan beaches in northern Greece: long sandy stretches with beach bars and sun loungers, plus quiet bays that stay relatively unspoiled even in August. The east and west coasts have different characters — the east is sheltered from the seasonal winds, the west offers spectacular sunsets. This list collects the beaches that consistently top our visitors' preferences, based on ratings, available facilities and water quality.</p>`, de: `<p>Kassandra ist die erste und am leichtesten zugängliche der drei Halbinseln von Chalkidiki – nur eine Stunde von Thessaloniki entfernt. Sie bietet einige der am besten organisierten, fotogensten und kosmopolitischsten Strände Nordgriechenlands: von großen Sandflächen mit Beach Bars und Liegen bis hin zu ruhigen Buchten, die selbst im August relativ unberührt bleiben. Die Ost- und Westküste haben unterschiedliche Charaktere – die Ostküste ist vor den jährlichen Winden geschützt, die Westküste bietet beeindruckende Sonnenuntergänge. Diese Liste fasst die Strände zusammen, die bei unseren Besuchern konstant an Beliebtheit gewinnen, basierend auf Bewertungen, verfügbaren Einrichtungen und Wasserqualität.</p>`, ro: `<p>Kassandra este prima și cea mai accesibilă dintre cele trei peninsule ale regiunii Halkidiki — la doar o oră de Salonic. Are unele dintre cele mai organizate, fotogenice și cosmopolite plaje din nordul Greciei: de la întinderi mari de nisip cu beach baruri și șezlonguri până la golfuri liniștite care rămân relativ neatinse chiar și în august. Coasta de est și cea de vest au caracter diferit — estul este protejat de vânturile anuale, iar vestul oferă apusuri spectaculoase. Această listă reunește plajele care urcă constant în preferințele vizitatorilor noștri, pe baza evaluărilor, infrastructurii disponibile și calității apei.</p>`, sr: `<p>Kassandra je prvi i najpristupačniji od tri poluostrva Halkidikija — udaljena samo sat vremena od Soluna. Ima neke od najorganizovanijih, fotogeničnih i kosmopolitskih plaža severne Grčke: od velikih peščanih prostranstava sa beach barovima i ležaljkama do mirnih uvala koje ostaju relativno netaknute čak i u avgustu. Istočna i zapadna obala imaju različit karakter — istočna je zaštićena od godišnjih vetrova, dok zapadna nudi spektakularne zalaske sunca. Ova lista okuplja plaže koje konstantno rastu u popularnosti među našim posetiocima, na osnovu ocena, dostupne infrastrukture i kvaliteta vode.</p>`, bg: `<p>Касандра е първият и най-достъпен от трите полуострова на Халкидики — само на един час от Солун. Тя разполага с някои от най-организираните, фотогенични и космополитни плажове в Северна Гърция: от големи пясъчни ивици с beach bars и шезлонги до тихи заливи, които остават относително непокътнати дори през август. Източното и западното крайбрежие имат различен характер — източното е защитено от годишните ветрове, западното предлага впечатляващи залези. Този списък събира плажовете, които постоянно се изкачват в предпочитанията на нашите посетители, въз основа на оценки, налични удобства и качество на водата.</p>`, ru: `<p>Кассандра — это первый и самый доступный из трех полуостровов Халкидики, всего в часе езды от Салоник. Здесь находятся одни из самых организованных, фотогеничных и космополитичных пляжей северной Греции: от больших песчаных участков с beach bars и шезлонгами до тихих бухт, которые остаются относительно безлюдными даже в августе. Восточное и западное побережья имеют разный характер — восточное защищено от ежегодных ветров, западное предлагает впечатляющие закаты. Этот список собирает пляжи, которые стабильно поднимаются в предпочтениях наших посетителей, основываясь на оценках, доступной инфраструктуре и качестве воды.</p>` },
    seasonal: { el: `<h2>Πότε να πας</h2><p><strong>Ιούνιος:</strong> ιδανικός — θάλασσα 22-24°C, λίγος κόσμος, full υπηρεσίες ανοιχτές. <strong>Ιούλιος-Αύγουστος:</strong> peak — γέμισμα μετά τις 10:30, κράτηση beach bar συνιστάται. <strong>Σεπτέμβριος:</strong> το αγαπημένο των ντόπιων — ζεστή θάλασσα (25°C), αδειασμένες παραλίες μετά τις 7 του μήνα. Δείτε τον <a href="/blog/halkidiki-september-guide">πλήρη οδηγό Σεπτεμβρίου</a>.</p>`, en: `<h2>When to visit</h2><p><strong>June:</strong> ideal — sea 22-24°C, fewer crowds, full services open. <strong>July-August:</strong> peak — beaches fill up after 10:30, beach-bar reservations recommended. <strong>September:</strong> the locals' favourite — warm sea (25°C), empty beaches after the 7th. See our <a href="/blog/halkidiki-september-guide">full September guide</a>.</p>`, de: `<h2>Wann man reisen sollte</h2><p><strong>Juni:</strong> ideal – Meer 22-24°C, wenig Leute, alle Dienstleistungen geöffnet. <strong>Juli-August:</strong> Hochsaison – ab 10:30 Uhr voll, Reservierung im Beach Bar empfohlen. <strong>September:</strong> der Favorit der Einheimischen – warmes Meer (25°C), leere Strände nach dem 7. des Monats. Sehen Sie den <a href="/blog/halkidiki-september-guide">vollständigen September-Guide</a>.</p>`, ro: `<h2>Când să mergi</h2><p><strong>Iunie:</strong> ideal — mare 22-24°C, puțină lume, toate serviciile deschise. <strong>Iulie-August:</strong> vârf de sezon — aglomerare după ora 10:30, rezervarea la beach bar este recomandată. <strong>Septembrie:</strong> preferatul localnicilor — mare caldă (25°C), plaje golite după data de 7 a lunii. Vezi <a href="/blog/halkidiki-september-guide">ghidul complet pentru septembrie</a>.</p>`, sr: `<h2>Kada posetiti</h2><p><strong>Jun:</strong> idealan — more 22-24°C, malo ljudi, sve usluge otvorene. <strong>Jul-Avgust:</strong> vrhunac — popunjenost posle 10:30, preporučuje se rezervacija u beach baru. <strong>Septembar:</strong> omiljen među lokalnim stanovništvom — toplo more (25°C), prazne plaže posle 7. septembra. Pogledajte <a href="/blog/halkidiki-september-guide">kompletan vodič za septembar</a>.</p>`, bg: `<h2>Кога да отидете</h2><p><strong>Юни:</strong> идеален — море 22-24°C, малко хора, всички услуги отворени. <strong>Юли-Август:</strong> пик — запълване след 10:30, резервация на beach bar се препоръчва. <strong>Септември:</strong> любим на местните — топло море (25°C), празни плажове след 7-ми. Вижте <a href="/blog/halkidiki-september-guide">пълния септемврийски гид</a>.</p>`, ru: `<h2>Когда ехать</h2><p><strong>Июнь:</strong> идеальный — море 22-24°C, мало людей, все услуги открыты. <strong>Июль-август:</strong> пик — заполнение после 10:30, бронирование beach bar рекомендуется. <strong>Сентябрь:</strong> любимый у местных — теплое море (25°C), пляжи пустеют после 7 числа. Смотрите <a href="/blog/halkidiki-september-guide">полное руководство по сентябрю</a>.</p>` },
    tips: { el: `<h2>Συμβουλές επί τόπου</h2><ul><li><strong>Νωρίς το πρωί:</strong> Στις πιο γνωστές (Καλλιθέα, Σάνη, Χανιώτη), ξαπλώστρες πιάνονται 9:00-10:00. Φτάσε νωρίς ή πάρε δικό σου σετ.</li><li><strong>Parking:</strong> Σαββατοκύριακα Ιουλίου-Αυγούστου, παρκάρισμα είναι το πρόβλημα. Σε Καλλιθέα και Πευκοχώρι χρειάζεσαι patience.</li><li><strong>Πιο ήσυχες επιλογές:</strong> Δες τις <a href="/best/quiet-beaches">ήσυχες παραλίες της Χαλκιδικής</a> για αποφυγή πλήθους.</li><li><strong>Φαγητό:</strong> Φάε στα παραδοσιακά χωριά εσωτερικά (Άφυτος, Πευκοχώρι παλιό) αντί για beach restaurants — καλύτερη ποιότητα.</li><li><strong>Από Βαλκάνια οδικώς:</strong> Δες τους <a href="/guide/getting-here">οδηγούς πρόσβασης ανά πόλη</a>.</li></ul>`, en: `<h2>On-site tips</h2><ul><li><strong>Early morning:</strong> At the most famous beaches (Kallithea, Sani, Hanioti) loungers go between 9:00 and 10:00. Arrive early or bring your own kit.</li><li><strong>Parking:</strong> July-August weekends, parking is the bottleneck. In Kallithea and Pefkochori, plan for patience.</li><li><strong>Quieter alternatives:</strong> See our list of <a href="/best/quiet-beaches">Halkidiki's quiet beaches</a> for crowd-free options.</li><li><strong>Food:</strong> Eat in the traditional inland villages (Afytos, old Pefkochori) rather than beach restaurants — better quality.</li><li><strong>Coming from the Balkans by car:</strong> See our <a href="/guide/getting-here">access guides by city</a>.</li></ul>`, de: `<h2>Vor-Ort-Tipps</h2><ul><li><strong>Früh am Morgen:</strong> An den bekanntesten Stränden (Kallithea, Sani, Chanioti) sind die Liegen von 9:00-10:00 Uhr belegt. Kommen Sie früh oder bringen Sie Ihr eigenes Set mit.</li><li><strong>Parking:</strong> An den Wochenenden im Juli-August ist Parken ein Problem. In Kallithea und Pefkochori ist Geduld gefragt.</li><li><strong>Ruhigere Optionen:</strong> Sehen Sie sich die <a href="/best/quiet-beaches">ruhigen Strände von Chalkidiki</a> an, um Menschenmassen zu vermeiden.</li><li><strong>Essen:</strong> Essen Sie in den traditionellen Dörfern im Landesinneren (Afytos, altes Pefkochori) statt in Strandrestaurants – bessere Qualität.</li><li><strong>Mit dem Auto aus dem Balkan:</strong> Sehen Sie sich die <a href="/guide/getting-here">Zugangsguides pro Stadt</a> an.</li></ul>`, ro: `<h2>Sfaturi la fața locului</h2><ul><li><strong>Dimineața devreme:</strong> Pe cele mai cunoscute (Kallithea, Sani, Hanioti), șezlongurile se ocupă între 9:00-10:00. Ajungi devreme sau adu-ți propriul set.</li><li><strong>Parking:</strong> În weekendurile din iulie-august, parcarea este o problemă. În Kallithea și Pefkochori ai nevoie de răbdare.</li><li><strong>Opțiuni mai liniștite:</strong> Vezi <a href="/best/quiet-beaches">plajele liniștite din Halkidiki</a> pentru a evita mulțimile.</li><li><strong>Mâncare:</strong> Mănâncă în satele tradiționale din interior (Afytos, Pefkochori vechi) în loc de restaurantele de pe plajă — calitate mai bună.</li><li><strong>Din Balcani cu mașina:</strong> Vezi <a href="/guide/getting-here">ghidurile de acces pe oraș</a>.</li></ul>`, sr: `<h2>Saveti na licu mesta</h2><ul><li><strong>Rano ujutru:</strong> Na najpoznatijim plažama (Kallithea, Sani, Hanioti), ležaljke se zauzimaju od 9:00-10:00. Stignite rano ili ponesite svoj set.</li><li><strong>Parking:</strong> Vikendom u julu-avgustu, parkiranje je problem. U Kallithei i Pefkohoriju potrebna je strpljivost.</li><li><strong>Mirnije opcije:</strong> Pogledajte <a href="/best/quiet-beaches">mirne plaže Halkidikija</a> za izbegavanje gužve.</li><li><strong>Hrana:</strong> Jedite u tradicionalnim unutrašnjim selima (Afytos, stari Pefkohori) umesto u restoranima na plaži — bolji kvalitet.</li><li><strong>Iz Balkana automobilom:</strong> Pogledajte <a href="/guide/getting-here">vodiče za pristup po gradovima</a>.</li></ul>`, bg: `<h2>Съвети на място</h2><ul><li><strong>Рано сутрин:</strong> На най-известните (Калитея, Сани, Ханиоти), шезлонгите се заемат 9:00-10:00. Пристигнете рано или вземете собствен комплект.</li><li><strong>Паркинг:</strong> Уикендите през юли-август, паркирането е проблем. В Калитея и Пефкохори ще ви трябва търпение.</li><li><strong>По-тихи опции:</strong> Вижте <a href="/best/quiet-beaches">тихите плажове на Халкидики</a> за избягване на тълпите.</li><li><strong>Храна:</strong> Яжте в традиционните вътрешни села (Афитос, старо Пефкохори) вместо в плажните ресторанти — по-добро качество.</li><li><strong>От Балканите с кола:</strong> Вижте <a href="/guide/getting-here">гидовете за достъп по градове</a>.</li></ul>`, ru: `<h2>Советы на месте</h2><ul><li><strong>Рано утром:</strong> На самых известных (Каллифея, Сани, Ханиоти) шезлонги занимают с 9:00-10:00. Приходите рано или берите свой набор.</li><li><strong>Парковка:</strong> В выходные июля-августа парковка — это проблема. В Каллифее и Пефкохори нужно терпение.</li><li><strong>Более тихие варианты:</strong> Смотрите <a href="/best/quiet-beaches">тихие пляжи Халкидики</a> для избегания толпы.</li><li><strong>Еда:</strong> Ешьте в традиционных деревнях внутри (Афитос, старый Пефкохори) вместо пляжных ресторанов — лучшее качество.</li><li><strong>Из Балкан на машине:</strong> Смотрите <a href="/guide/getting-here">руководства по доступу по городам</a>.</li></ul>` },
    faqs: [
      { q: { el: `Ποια είναι η ωραιότερη παραλία της Κασσάνδρας;`, en: `Which is the most beautiful beach in Kassandra?`, de: `Welcher ist der schönste Strand von Kassandra?`, ro: `Care este cea mai frumoasă plajă din Kassandra?`, sr: `Koja je najlepša plaža na Kassandra?`, bg: `Кой е най-красивият плаж на Касандра?`, ru: `Какой самый красивый пляж Кассандры?` }, a: { el: `Το <strong>Ποσείδι</strong> με τον χαρακτηριστικό φάρο και τη γλώσσα γης ξεχωρίζει για φωτογενή ομορφιά. Η <strong>Σάνη</strong> ξεχωρίζει για οργανωμένη υποδομή και ποιότητα. Η <strong>Καλλιθέα</strong> για νυχτερινή ζωή και beach clubs. Δες όλες σε αυτή τη λίστα και διάλεξε με βάση τι αναζητάς.`, en: `<strong>Possidi</strong> with its iconic lighthouse and sand spit stands out for photogenic beauty. <strong>Sani</strong> for organised facilities and quality. <strong>Kallithea</strong> for nightlife and beach clubs. Browse them all in this list and choose by what you're after.`, de: `<strong>Possidi</strong> mit seinem charakteristischen Leuchtturm und der Landzunge besticht durch fotogene Schönheit. <strong>Sani</strong> zeichnet sich durch organisierte Infrastruktur und Qualität aus. <strong>Kallithea</strong> für Nachtleben und Beach Clubs. Sehen Sie alle in dieser Liste und wählen Sie basierend auf Ihren Vorlieben aus.`, ro: `<strong>Possidi</strong> cu farul său caracteristic și limba de pământ se remarcă prin frumusețea sa fotogenică. <strong>Sani</strong> se remarcă prin infrastructură organizată și calitate. <strong>Kallithea</strong> pentru viața de noapte și beach cluburi. Vezi toate în această listă și alege în funcție de ceea ce cauți.`, sr: `<strong>Possidi</strong> sa svojim karakterističnim svetionikom i peščanom prevlakom ističe se po fotogeničnoj lepoti. <strong>Sani</strong> se izdvaja po organizovanoj infrastrukturi i kvalitetu. <strong>Kallithea</strong> po noćnom životu i beach klubovima. Pogledajte sve na ovoj listi i izaberite prema onome što tražite.`, bg: `<strong>Посиди</strong> с характерния фар и езика земя се отличава с фотогенична красота. <strong>Сани</strong> се отличава с организирана инфраструктура и качество. <strong>Калитея</strong> за нощен живот и beach клубове. Вижте всички в този списък и изберете според това, което търсите.`, ru: `<strong>Посиди</strong> с характерным маяком и полосой земли выделяется своей фотогеничной красотой. <strong>Сани</strong> выделяется организованной инфраструктурой и качеством. <strong>Каллифея</strong> — ночной жизнью и beach clubs. Смотрите все в этом списке и выбирайте в зависимости от того, что вы ищете.` } },
      { q: { el: `Είναι οι παραλίες της Κασσάνδρας κατάλληλες για παιδιά;`, en: `Are Kassandra's beaches suitable for kids?`, de: `Sind die Strände von Kassandra für Kinder geeignet?`, ro: `Sunt plajele din Kassandra potrivite pentru copii?`, sr: `Da li su plaže na Kassandra pogodne za decu?`, bg: `Подходящи ли са плажовете на Касандра за деца?`, ru: `Подходят ли пляжи Кассандры для детей?` }, a: { el: `Ναι, πολλές. Η <strong>Σιβηρή</strong> και η <strong>Νέα Φώκαια</strong> έχουν ιδιαίτερα ρηχά νερά. Δες τις <a href="/best/family-beaches">οικογενειακές παραλίες</a> για πλήρη λίστα φιλτραρισμένη με κριτήριο τη ρηχή ζώνη.`, en: `Yes, many of them. <strong>Siviri</strong> and <strong>Nea Fokaia</strong> have especially shallow water. See our <a href="/best/family-beaches">family beaches</a> page for a full list filtered by shallow-water criteria.`, de: `Ja, viele. <strong>Siviri</strong> und <strong>Nea Fokea</strong> haben besonders flaches Wasser. Sehen Sie sich die <a href="/best/family-beaches">Familienstrände</a> für eine vollständige Liste gefiltert nach flachen Zonen an.`, ro: `Da, multe. <strong>Siviri</strong> și <strong>Nea Fokea</strong> au ape deosebit de puțin adânci. Vezi <a href="/best/family-beaches">plajele de familie</a> pentru o listă completă filtrată după criteriul zonei puțin adânci.`, sr: `Da, mnoge jesu. <strong>Siviri</strong> i <strong>Nea Fokea</strong> imaju posebno plitku vodu. Pogledajte <a href="/best/family-beaches">porodične plaže</a> za kompletnu listu filtriranu prema plitkoj zoni.`, bg: `Да, много. <strong>Сивири</strong> и <strong>Неа Фокеа</strong> имат особено плитки води. Вижте <a href="/best/family-beaches">семейните плажове</a> за пълен списък, филтриран по критерий плитка зона.`, ru: `Да, многие. <strong>Сивири</strong> и <strong>Неа Фокеа</strong> имеют особенно мелководные воды. Смотрите <a href="/best/family-beaches">семейные пляжи</a> для полного списка, отфильтрованного по критерию мелководья.` } },
      { q: { el: `Είναι ελεύθερη η πρόσβαση στις παραλίες;`, en: `Are the beaches free to access?`, de: `Ist der Zugang zu den Stränden frei?`, ro: `Este accesul liber la plaje?`, sr: `Da li je pristup plažama slobodan?`, bg: `Свободен ли е достъпът до плажовете?`, ru: `Свободен ли доступ к пляжам?` }, a: { el: `Ναι, σε όλες τις δημόσιες παραλίες η πρόσβαση είναι ελεύθερη. Πληρώνεις μόνο για ξαπλώστρες/ομπρέλες αν θες (€8-15 set/μέρα συνήθως). Δες τις <a href="/best/free-beaches">ελεύθερες παραλίες</a> για επιλογές χωρίς οργανωμένες υπηρεσίες.`, en: `Yes — public access is free everywhere. You only pay for sun loungers/umbrellas if you want them (typically €8-15 for a set/day). See our <a href="/best/free-beaches">free beaches</a> page for options without organised facilities.`, de: `Ja, der Zugang zu allen öffentlichen Stränden ist frei. Sie zahlen nur für Liegen/Sonnenschirme, wenn Sie möchten (€8-15 Set/Tag normalerweise). Sehen Sie sich die <a href="/best/free-beaches">freien Strände</a> für Optionen ohne organisierte Dienstleistungen an.`, ro: `Da, la toate plajele publice accesul este liber. Plătești doar pentru șezlonguri/umbrele dacă dorești (€8-15 set/zi de obicei). Vezi <a href="/best/free-beaches">plajele libere</a> pentru opțiuni fără servicii organizate.`, sr: `Da, na svim javnim plažama pristup je slobodan. Plaća se samo za ležaljke/suncobrane ako želite (€8-15 set/dan obično). Pogledajte <a href="/best/free-beaches">slobodne plaže</a> za opcije bez organizovanih usluga.`, bg: `Да, на всички обществени плажове достъпът е свободен. Плащате само за шезлонги/чадъри, ако желаете (€8-15 комплект/ден обикновено). Вижте <a href="/best/free-beaches">свободните плажове</a> за опции без организирани услуги.`, ru: `Да, на всех общественных пляжах доступ свободен. Платите только за шезлонги/зонтики, если хотите (€8-15 комплект/день обычно). Смотрите <a href="/best/free-beaches">свободные пляжи</a> для выбора без организованных услуг.` } },
      { q: { el: `Πόσο μακριά είναι η Κασσάνδρα από τη Θεσσαλονίκη;`, en: `How far is Kassandra from Thessaloniki?`, de: `Wie weit ist Kassandra von Thessaloniki entfernt?`, ro: `Cât de departe este Kassandra de Salonic?`, sr: `Koliko je Kassandra udaljena od Soluna?`, bg: `Колко далеч е Касандра от Солун?`, ru: `Как далеко Кассандра от Салоник?` }, a: { el: `Περίπου 100 χλμ (~1 ώρα 15 λεπτά οδικώς) από το αεροδρόμιο SKG. Η Σάνη και η Νέα Ποτίδαια είναι οι πιο κοντινές παραλίες (~75 χλμ). Δες τον <a href="/from/thessaloniki">οδηγό μετακίνησης από Θεσσαλονίκη</a>.`, en: `About 100 km (~1h 15min driving) from SKG airport. Sani and Nea Potidaia are the closest beaches (~75 km). See our <a href="/from/thessaloniki">guide from Thessaloniki</a>.`, de: `Ungefähr 100 km (~1 Stunde 15 Minuten mit dem Auto) vom Flughafen SKG. Sani und Nea Potidea sind die nächstgelegenen Strände (~75 km). Sehen Sie den <a href="/from/thessaloniki">Transportführer von Thessaloniki</a>.`, ro: `Aproximativ 100 km (~1 oră și 15 minute cu mașina) de la aeroportul SKG. Sani și Nea Potidea sunt cele mai apropiate plaje (~75 km). Vezi <a href="/from/thessaloniki">ghidul de transport din Salonic</a>.`, sr: `Otprilike 100 km (~1 sat i 15 minuta vožnje) od aerodroma SKG. Sani i Nea Potidea su najbliže plaže (~75 km). Pogledajte <a href="/from/thessaloniki">vodič za prevoz iz Soluna</a>.`, bg: `Около 100 км (~1 час и 15 минути с кола) от летище SKG. Сани и Неа Потидея са най-близките плажове (~75 км). Вижте <a href="/from/thessaloniki">гид за транспорт от Солун</a>.`, ru: `Примерно 100 км (~1 час 15 минут на машине) от аэропорта SKG. Сани и Неа Потидеа — самые близкие пляжи (~75 км). Смотрите <a href="/from/thessaloniki">руководство по перемещению из Салоник</a>.` } },
    ],
  },
  "beaches-sithonia": {
    intro: { el: `<p>Η Σιθωνία, το μεσαίο πόδι της Χαλκιδικής, είναι ίσως ο πιο φωτογενής προορισμός παραλιών στη βόρεια Ελλάδα. Σε αντίθεση με την αναπτυγμένη Κασσάνδρα, εδώ το πευκόδασος φτάνει πολλές φορές μέχρι την άμμο, οι παραλίες είναι μικρότερες αλλά πιο εξωτικές, και οι αποχρώσεις του νερού — από βαθύ τυρκουάζ μέχρι ζαφειρένιο μπλε — θυμίζουν Κυκλάδες. Παραλίες όπως οι Καβουρότρυπες (Orange Beach), <a href="/beaches/fava-beach-sithonia">Φάβα</a>, Καρύδι και Πλατανίτσι έχουν γίνει Instagram benchmarks. Αυτή η λίστα συγκεντρώνει τις παραλίες που ξεχωρίζουν με βάση αξιολογήσεις, χαρακτηριστικά (ρηχή ζώνη, οργάνωση, snorkeling) και τη φυσική τους ομορφιά.</p>`, en: `<p>Sithonia, the middle leg of Halkidiki, is arguably the most photogenic beach destination in northern Greece. Unlike the developed Kassandra, here pine forest often reaches the sand, beaches are smaller but more exotic, and the colour of the water — from deep turquoise to sapphire blue — feels Cycladic. Beaches like Kavourotrypes (Orange Beach), <a href="/beaches/fava-beach-sithonia">Fava</a>, Karydi and Platanitsi have become Instagram benchmarks. This list collects the beaches that stand out based on ratings, features (shallow water, organisation, snorkelling) and natural beauty.</p>`, de: `<p>Sithonia, der mittlere Finger von Chalkidiki, ist vielleicht das fotogenste Strandziel in Nordgriechenland. Im Gegensatz zum entwickelten Kassandra reicht hier der Pinienwald oft bis zum Sand, die Strände sind kleiner, aber exotischer, und die Wasserfarben — von tiefem Türkis bis Saphirblau — erinnern an die Kykladen. Strände wie Kavourotrypes (Orange Beach), <a href="/beaches/fava-beach-sithonia">Fava</a>, Karydi und Platanitsi sind zu Instagram-Benchmarks geworden. Diese Liste fasst die Strände zusammen, die sich durch Bewertungen, Merkmale (flache Zone, Organisation, Schnorcheln) und ihre natürliche Schönheit auszeichnen.</p>`, ro: `<p>Sithonia, brațul din mijloc al regiunii Halkidiki, este poate cea mai fotogenică destinație de plajă din nordul Greciei. Spre deosebire de Kassandra dezvoltată, aici pădurea de pini ajunge de multe ori până la nisip, plajele sunt mai mici, dar mai exotice, iar nuanțele apei — de la turcoaz adânc la albastru safir — amintesc de Ciclade. Plaje precum Kavourotrypes (Orange Beach), <a href="/beaches/fava-beach-sithonia">Fava</a>, Karydi și Platanitsi au devenit repere pe Instagram. Această listă reunește plajele care se remarcă pe baza evaluărilor, caracteristicilor (zonă de mică adâncime, organizare, snorkeling) și frumuseții lor naturale.</p>`, sr: `<p>Sitonija, srednji prst Halkidikija, je možda najfotogeničnija destinacija za plaže u severnoj Grčkoj. Za razliku od razvijene Kasandre, ovde borova šuma često dopire do peska, plaže su manje, ali egzotičnije, a nijanse vode — od dubokog tirkiznog do safirno plave — podsećaju na Kiklade. Plaže kao što su Kavourotrypes (Orange Beach), <a href="/beaches/fava-beach-sithonia">Fava</a>, Karydi i Platanitsi postale su Instagram reperi. Ova lista okuplja plaže koje se izdvajaju na osnovu ocena, karakteristika (plitka zona, organizacija, snorkeling) i prirodne lepote.</p>`, bg: `<p>Ситония, средният ръкав на Халкидики, е може би най-фотогеничната дестинация за плажове в Северна Гърция. За разлика от развитата Касандра, тук боровите гори често достигат до пясъка, плажовете са по-малки, но по-екзотични, а нюансите на водата — от дълбоко тюркоазено до сапфирено синьо — напомнят на Цикладите. Плажове като Кавуротрипес (Orange Beach), <a href="/beaches/fava-beach-sithonia">Фава</a>, Кариди и Платаници са станали Instagram еталони. Този списък събира плажовете, които се отличават въз основа на оценки, характеристики (плитка зона, организация, snorkeling) и естествената им красота.</p>`, ru: `<p>Ситония, средний полуостров Халкидики, возможно, самый фотогеничный пляжный курорт в северной Греции. В отличие от развитой Кассандры, здесь сосновые леса часто доходят до самого песка, пляжи меньше, но более экзотичны, а оттенки воды — от глубокого бирюзового до сапфирово-синего — напоминают Киклады. Пляжи, такие как Кавуротрипес (Orange Beach), <a href="/beaches/fava-beach-sithonia">Фава</a>, Кариди и Платаници стали эталонами Instagram. Этот список собирает пляжи, которые выделяются по оценкам, характеристикам (мелководье, организация, сноркелинг) и их природной красоте.</p>` },
    seasonal: { el: `<h2>Πότε να πας</h2><p><strong>Ιούνιος:</strong> sweet spot — θάλασσα 22-24°C, λίγος κόσμος ακόμα. <strong>Ιούλιος-Αύγουστος:</strong> πολυσύχναστο σε γνωστές παραλίες (Καβουρότρυπες, Φάβα), τα μικρά parking γεμίζουν 9-10. Καλό να φτάσεις νωρίς ή να βρεις λιγότερο γνωστές. <strong>Σεπτέμβριος:</strong> ιδανικός — αδειάζουν δραματικά μετά τις 5-7 του μήνα, νερό ακόμα 24°C. <a href="/blog/halkidiki-september-guide">Πλήρης οδηγός Σεπτεμβρίου</a>.</p>`, en: `<h2>When to visit</h2><p><strong>June:</strong> the sweet spot — sea 22-24°C, still few crowds. <strong>July-August:</strong> busy at the famous beaches (Kavourotrypes, Fava), small car parks fill up 9-10. Aim to arrive early or pick lesser-known options. <strong>September:</strong> ideal — beaches empty out dramatically after the 5-7th, water still 24°C. <a href="/blog/halkidiki-september-guide">Full September guide</a>.</p>`, de: `<h2>Wann man reisen sollte</h2><p><strong>Juni:</strong> Sweet Spot — Meer 22-24°C, noch wenig Leute. <strong>Juli-August:</strong> belebt an bekannten Stränden (Kavourotrypes, Fava), die kleinen Parkplätze sind von 9-10 Uhr voll. Es ist gut, früh anzukommen oder weniger bekannte Strände zu finden. <strong>September:</strong> ideal — leeren sich dramatisch nach dem 5.-7. des Monats, Wasser immer noch 24°C. <a href="/blog/halkidiki-september-guide">Vollständiger September-Guide</a>.</p>`, ro: `<h2>Când să mergi</h2><p><strong>Iunie:</strong> moment ideal — mare 22-24°C, puțină lume încă. <strong>Iulie-August:</strong> aglomerat pe plajele cunoscute (Kavourotrypes, Fava), parcările mici se umplu între 9-10. E bine să ajungi devreme sau să găsești plaje mai puțin cunoscute. <strong>Septembrie:</strong> ideal — se golesc dramatic după 5-7 ale lunii, apa încă 24°C. <a href="/blog/halkidiki-september-guide">Ghid complet pentru septembrie</a>.</p>`, sr: `<h2>Kada posetiti</h2><p><strong>Jun:</strong> idealno vreme — more 22-24°C, još uvek malo ljudi. <strong>Jul-Avgust:</strong> gužve na poznatim plažama (Kavourotrypes, Fava), mala parking mesta se popunjavaju do 9-10 sati. Dobro je doći rano ili pronaći manje poznate plaže. <strong>Septembar:</strong> idealan — drastično se prazni posle 5-7. septembra, voda još uvek 24°C. <a href="/blog/halkidiki-september-guide">Potpuni vodič za septembar</a>.</p>`, bg: `<h2>Кога да отидете</h2><p><strong>Юни:</strong> идеален момент — море 22-24°C, все още малко хора. <strong>Юли-Август:</strong> оживено на известни плажове (Кавуротрипес, Фава), малките паркинги се запълват между 9-10 ч. Добре е да пристигнете рано или да намерите по-малко известни. <strong>Септември:</strong> идеален — драстично се изпразват след 5-7 число, водата все още 24°C. <a href="/blog/halkidiki-september-guide">Пълен септемврийски гид</a>.</p>`, ru: `<h2>Когда ехать</h2><p><strong>Июнь:</strong> идеальное время — море 22-24°C, еще немного людей. <strong>Июль-Август:</strong> многолюдно на известных пляжах (Кавуротрипес, Фава), маленькие парковки заполняются к 9-10 часам. Лучше приезжать рано или искать менее известные пляжи. <strong>Сентябрь:</strong> идеальный — пляжи заметно пустеют после 5-7 числа, вода все еще 24°C. <a href="/blog/halkidiki-september-guide">Полный гид по сентябрю</a>.</p>` },
    tips: { el: `<h2>Συμβουλές επί τόπου</h2><ul><li><strong>Καβουρότρυπες/Orange:</strong> Parking μακριά + ~15' περπάτημα. Φέρε αρκετό νερό και σνακ — δεν έχει καντίνα.</li><li><strong>Snorkeling:</strong> Η Σιθωνία είναι από τις καλύτερες περιοχές για snorkeling στη Χαλκιδική. Δες τις <a href="/best/snorkeling-spots">καλύτερες παραλίες snorkeling</a>.</li><li><strong>Σκιά:</strong> Σε φυσικές παραλίες δεν υπάρχει — φέρε ομπρέλα.</li><li><strong>Πρόσβαση:</strong> Από Νικήτη η ανατολική ακτή χρειάζεται 30-45' οδήγηση. Από Σάρτη ή Καλαμίτσι, πιο γρήγορα.</li><li><strong>Νυχτερινό φαγητό:</strong> Στα παραδοσιακά χωριά Καλαμίτσι, Παρθενώνας — όχι στις παραλίες.</li></ul>`, en: `<h2>On-site tips</h2><ul><li><strong>Kavourotrypes/Orange:</strong> Parking is far + ~15-min walk. Bring plenty of water and snacks — no canteen.</li><li><strong>Snorkelling:</strong> Sithonia is one of Halkidiki's best areas for snorkelling. See our <a href="/best/snorkeling-spots">best snorkelling beaches</a>.</li><li><strong>Shade:</strong> Natural beaches have none — bring your own umbrella.</li><li><strong>Access:</strong> From Nikiti the east coast takes 30-45 min of driving. From Sarti or Kalamitsi, it's quicker.</li><li><strong>Dinner:</strong> Eat in traditional villages — Kalamitsi, Parthenonas — not at the beach.</li></ul>`, de: `<h2>Vor-Ort-Tipps</h2><ul><li><strong>Kavourotrypes/Orange:</strong> Parkplatz weit entfernt + ~15' Fußweg. Bringe ausreichend Wasser und Snacks mit — es gibt keine Kantine.</li><li><strong>Schnorcheln:</strong> Sithonia ist eine der besten Regionen zum Schnorcheln in Chalkidiki. Siehe die <a href="/best/snorkeling-spots">besten Schnorchelstrände</a>.</li><li><strong>Schatten:</strong> An natürlichen Stränden gibt es keinen — bring einen Sonnenschirm mit.</li><li><strong>Zugang:</strong> Von Nikiti aus benötigt die Ostküste 30-45' Fahrt. Von Sarti oder Kalamitsi aus geht es schneller.</li><li><strong>Nachtessen:</strong> In den traditionellen Dörfern Kalamitsi, Parthenonas — nicht an den Stränden.</li></ul>`, ro: `<h2>Sfaturi la fața locului</h2><ul><li><strong>Kavourotrypes/Orange:</strong> Parcare departe + ~15' de mers pe jos. Adu suficientă apă și gustări — nu există cantină.</li><li><strong>Snorkeling:</strong> Sithonia este una dintre cele mai bune zone pentru snorkeling din Halkidiki. Vezi <a href="/best/snorkeling-spots">cele mai bune plaje pentru snorkeling</a>.</li><li><strong>Umbra:</strong> Pe plajele naturale nu există — adu o umbrelă.</li><li><strong>Acces:</strong> Din Nikiti, coasta de est necesită 30-45' de condus. Din Sarti sau Kalamitsi, mai rapid.</li><li><strong>Cina de seară:</strong> În satele tradiționale Kalamitsi, Parthenonas — nu pe plaje.</li></ul>`, sr: `<h2>Saveti na licu mesta</h2><ul><li><strong>Kavourotrypes/Orange:</strong> Parking daleko + ~15 minuta hoda. Ponesite dovoljno vode i grickalica — nema kantine.</li><li><strong>Snorkeling:</strong> Sitonija je jedna od najboljih oblasti za snorkeling na Halkidikiju. Pogledajte <a href="/best/snorkeling-spots">najbolje plaže za snorkeling</a>.</li><li><strong>Sena:</strong> Na prirodnim plažama nema — ponesite suncobran.</li><li><strong>Pristup:</strong> Od Nikitija do istočne obale potrebno je 30-45 minuta vožnje. Od Sartija ili Kalamitsija, brže.</li><li><strong>Noćna večera:</strong> U tradicionalnim selima Kalamitsi, Parthenonas — ne na plažama.</li></ul>`, bg: `<h2>Съвети на място</h2><ul><li><strong>Кавуротрипес/Orange:</strong> Паркинг далеч + ~15' ходене. Носете достатъчно вода и закуски — няма кантинa.</li><li><strong>Snorkeling:</strong> Ситония е една от най-добрите области за snorkeling в Халкидики. Вижте <a href="/best/snorkeling-spots">най-добрите плажове за snorkeling</a>.</li><li><strong>Сянка:</strong> На естествените плажове няма — носете чадър.</li><li><strong>Достъп:</strong> От Никити източното крайбрежие изисква 30-45' шофиране. От Сарти или Каламици, по-бързо.</li><li><strong>Нощно хранене:</strong> В традиционните села Каламици, Партенонас — не на плажовете.</li></ul>`, ru: `<h2>Советы на месте</h2><ul><li><strong>Кавуротрипес/Orange:</strong> Парковка далеко + ~15 минут пешком. Возьмите достаточно воды и закусок — здесь нет киоска.</li><li><strong>Сноркелинг:</strong> Ситония — одно из лучших мест для сноркелинга на Халкидики. Смотрите <a href="/best/snorkeling-spots">лучшие пляжи для сноркелинга</a>.</li><li><strong>Тень:</strong> На природных пляжах ее нет — возьмите зонт.</li><li><strong>Доступ:</strong> От Никити до восточного побережья требуется 30-45 минут езды. От Сарти или Каламици быстрее.</li><li><strong>Ночной ужин:</strong> В традиционных деревнях Каламици, Партенонас — не на пляжах.</li></ul>` },
    faqs: [
      { q: { el: `Ποια είναι η ομορφότερη παραλία της Σιθωνίας;`, en: `Which is the most beautiful beach in Sithonia?`, de: `Welcher ist der schönste Strand in Sithonia?`, ro: `Care este cea mai frumoasă plajă din Sithonia?`, sr: `Koja je najlepša plaža na Sitoniji?`, bg: `Кой е най-красивият плаж на Ситония?`, ru: `Какой самый красивый пляж Ситонии?` }, a: { el: `Οι <strong>Καβουρότρυπες (Orange Beach)</strong> έχουν τη μεγαλύτερη Instagram φήμη με τους πορτοκαλί βραχώδεις σχηματισμούς. Η <strong>Καρύδι</strong> και η <strong>Φάβα</strong> ακολουθούν με τυρκουάζ νερά και λευκή άμμο. Δες όλες σε αυτή τη λίστα.`, en: `<strong>Kavourotrypes (Orange Beach)</strong> has the biggest Instagram reputation with its orange rock formations. <strong>Karydi</strong> and <strong>Fava</strong> follow with turquoise water and white sand. Browse them all in this list.`, de: `Die <strong>Kavourotrypes (Orange Beach)</strong> haben den größten Instagram-Ruhm mit den orangefarbenen Felsformationen. <strong>Karydi</strong> und <strong>Fava</strong> folgen mit türkisfarbenem Wasser und weißem Sand. Siehe alle in dieser Liste.`, ro: `<strong>Kavourotrypes (Orange Beach)</strong> are cea mai mare faimă pe Instagram cu formațiunile sale stâncoase portocalii. <strong>Karydi</strong> și <strong>Fava</strong> urmează cu ape turcoaz și nisip alb. Vezi toate în această listă.`, sr: `<strong>Kavourotrypes (Orange Beach)</strong> ima najveću Instagram slavu sa narandžastim stenovitim formacijama. <strong>Karydi</strong> i <strong>Fava</strong> slede sa tirkiznom vodom i belim peskom. Pogledajte sve na ovoj listi.`, bg: `<strong>Кавуротрипес (Orange Beach)</strong> имат най-голяма Instagram слава с оранжевите си скални образувания. <strong>Кариди</strong> и <strong>Фава</strong> следват с тюркоазени води и бял пясък. Вижте всички в този списък.`, ru: `<strong>Кавуротрипес (Orange Beach)</strong> имеет наибольшую известность в Instagram благодаря своим оранжевым скалистым образованиям. <strong>Кариди</strong> и <strong>Фава</strong> следуют с бирюзовой водой и белым песком. Смотрите все в этом списке.` } },
      { q: { el: `Σιθωνία ή Κασσάνδρα — ποια ταιριάζει σε μένα;`, en: `Sithonia or Kassandra — which fits me?`, de: `Sithonia oder Kassandra — was passt zu mir?`, ro: `Sithonia sau Kassandra — care mi se potrivește?`, sr: `Sitonija ili Kasandra — koja odgovara meni?`, bg: `Ситония или Касандра — коя е подходяща за мен?`, ru: `Ситония или Кассандра — что выбрать?` }, a: { el: `Διάλεξε <strong>Σιθωνία</strong> αν θες φυσικές, φωτογενείς παραλίες, πεύκα δίπλα στη θάλασσα και πιο ήσυχη ατμόσφαιρα. Διάλεξε <strong>Κασσάνδρα</strong> αν θες οργανωμένες παραλίες, beach clubs, νυχτερινή ζωή και ευκολότερη πρόσβαση. Δες τη <a href="/best/beaches-kassandra">λίστα παραλιών Κασσάνδρας</a> για σύγκριση.`, en: `Pick <strong>Sithonia</strong> if you want natural, photogenic beaches with pine forest by the sea and a quieter vibe. Pick <strong>Kassandra</strong> if you want organised beaches, beach clubs, nightlife and easier access. See the <a href="/best/beaches-kassandra">Kassandra beaches list</a> for comparison.`, de: `Wähle <strong>Sithonia</strong>, wenn du natürliche, fotogene Strände, Pinien neben dem Meer und eine ruhigere Atmosphäre möchtest. Wähle <strong>Kassandra</strong>, wenn du organisierte Strände, Beachclubs, Nachtleben und leichtere Zugänglichkeit suchst. Siehe die <a href="/best/beaches-kassandra">Liste der Kassandra-Strände</a> zum Vergleich.`, ro: `Alege <strong>Sithonia</strong> dacă vrei plaje naturale, fotogenice, pini lângă mare și o atmosferă mai liniștită. Alege <strong>Kassandra</strong> dacă vrei plaje organizate, cluburi de plajă, viață de noapte și acces mai ușor. Vezi <a href="/best/beaches-kassandra">lista plajelor din Kassandra</a> pentru comparație.`, sr: `Izaberite <strong>Sitoniju</strong> ako želite prirodne, fotogenične plaže, borove pored mora i mirniju atmosferu. Izaberite <strong>Kasandru</strong> ako želite organizovane plaže, beach klubove, noćni život i lakši pristup. Pogledajte <a href="/best/beaches-kassandra">listu plaža Kasandre</a> za poređenje.`, bg: `Изберете <strong>Ситония</strong>, ако искате естествени, фотогенични плажове, борове до морето и по-тиха атмосфера. Изберете <strong>Касандра</strong>, ако искате организирани плажове, beach клубове, нощен живот и по-лесен достъп. Вижте <a href="/best/beaches-kassandra">списъка с плажове на Касандра</a> за сравнение.`, ru: `Выберите <strong>Ситонию</strong>, если хотите природные, фотогеничные пляжи, сосны рядом с морем и более спокойную атмосферу. Выберите <strong>Кассандру</strong>, если хотите организованные пляжи, пляжные клубы, ночную жизнь и более легкий доступ. Смотрите <a href="/best/beaches-kassandra">список пляжей Кассандры</a> для сравнения.` } },
      { q: { el: `Χρειάζεται 4x4 για να φτάσω;`, en: `Do I need a 4x4 to reach them?`, de: `Brauche ich ein 4x4, um dorthin zu gelangen?`, ro: `Este necesar un 4x4 pentru a ajunge?`, sr: `Da li je potreban 4x4 da bih stigao?`, bg: `Нужен ли е 4x4, за да стигна?`, ru: `Нужно ли 4x4, чтобы добраться?` }, a: { el: `Όχι. Όλες οι παραλίες σε αυτή τη λίστα είναι προσβάσιμες με κανονικό αυτοκίνητο. Σε ορισμένες (Καβουρότρυπες, Καρύδι) έχει χωμάτινο δρόμο στα τελευταία χιλιόμετρα αλλά καλά συντηρημένο.`, en: `No. All beaches in this list are accessible with a regular car. A few (Kavourotrypes, Karydi) have a dirt road for the last kilometre but it's well maintained.`, de: `Nein. Alle Strände in dieser Liste sind mit einem normalen Auto erreichbar. Bei einigen (Kavourotrypes, Karydi) gibt es auf den letzten Kilometern eine Schotterstraße, die jedoch gut instand gehalten ist.`, ro: `Nu. Toate plajele din această listă sunt accesibile cu o mașină obișnuită. La unele (Kavourotrypes, Karydi) există drum de pământ pe ultimele kilometri, dar bine întreținut.`, sr: `Ne. Sve plaže na ovoj listi su dostupne običnim automobilom. Na nekima (Kavourotrypes, Karydi) ima zemljanog puta na poslednjim kilometrima, ali je dobro održavan.`, bg: `Не. Всички плажове в този списък са достъпни с обикновен автомобил. На някои (Кавуротрипес, Кариди) има черен път в последните километри, но добре поддържан.`, ru: `Нет. Все пляжи в этом списке доступны на обычном автомобиле. На некоторых (Кавуротрипес, Кариди) последние километры — грунтовая дорога, но она хорошо ухожена.` } },
      { q: { el: `Πού να μείνω για εύκολη πρόσβαση στις καλύτερες παραλίες;`, en: `Where to stay for easy beach access?`, de: `Wo soll ich übernachten, um einfachen Zugang zu den besten Stränden zu haben?`, ro: `Unde să stau pentru acces ușor la cele mai bune plaje?`, sr: `Gde da odsednem za lak pristup najboljim plažama?`, bg: `Къде да отседна за лесен достъп до най-добрите плажове?`, ru: `Где остановиться для легкого доступа к лучшим пляжам?` }, a: { el: `<strong>Νικήτη</strong> για κεντρική πρόσβαση και στις δύο ακτές. <strong>Σάρτη</strong> ή <strong>Καλαμίτσι</strong> για να είσαι κοντά στις ανατολικές παραλίες. <strong>Νέος Μαρμαράς</strong> ή <strong>Βουρβουρού</strong> για τη δυτική. Δες τα <a href="/listings">διαθέσιμα καταλύματα</a>.`, en: `<strong>Nikiti</strong> for central access to both coasts. <strong>Sarti</strong> or <strong>Kalamitsi</strong> to be near the east. <strong>Neos Marmaras</strong> or <strong>Vourvourou</strong> for the west. See <a href="/listings">available accommodation</a>.`, de: `<strong>Nikiti</strong> für zentralen Zugang zu beiden Küsten. <strong>Sarti</strong> oder <strong>Kalamitsi</strong>, um nahe an den östlichen Stränden zu sein. <strong>Neos Marmaras</strong> oder <strong>Vourvourou</strong> für die westliche Küste. Siehe die <a href="/listings">verfügbaren Unterkünfte</a>.`, ro: `<strong>Nikiti</strong> pentru acces central la ambele coaste. <strong>Sarti</strong> sau <strong>Kalamitsi</strong> pentru a fi aproape de plajele estice. <strong>Neos Marmaras</strong> sau <strong>Vourvourou</strong> pentru cele vestice. Vezi <a href="/listings">cazările disponibile</a>.`, sr: `<strong>Nikiti</strong> za centralni pristup obe obale. <strong>Sarti</strong> ili <strong>Kalamitsi</strong> da budete blizu istočnih plaža. <strong>Neos Marmaras</strong> ili <strong>Vourvourou</strong> za zapadnu obalu. Pogledajte <a href="/listings">dostupne smeštaje</a>.`, bg: `<strong>Никити</strong> за централен достъп и до двете крайбрежия. <strong>Сарти</strong> или <strong>Каламици</strong> за да сте близо до източните плажове. <strong>Неос Мармарас</strong> или <strong>Вурвуру</strong> за западното. Вижте <a href="/listings">наличните места за настаняване</a>.`, ru: `<strong>Никити</strong> для центрального доступа к обоим побережьям. <strong>Сарти</strong> или <strong>Каламици</strong> для близости к восточным пляжам. <strong>Неос Мармарас</strong> или <strong>Вурвуру</strong> для западного побережья. Смотрите <a href="/listings">доступные варианты размещения</a>.` } },
    ],
  },
  "family-beaches": {
    intro: { el: `<p>Με μικρά παιδιά μια παραλία δεν επιλέγεται μόνο από ομορφιά — επιλέγεται από <strong>ασφάλεια</strong>. Ρηχή ζώνη που εκτείνεται τουλάχιστον 20-30 μέτρα από την ακτή, χωρίς ξαφνικές βαθιές περιοχές. Άμμος που μπορούν να περπατήσουν χωρίς να πληγωθούν. Υπηρεσίες όπως ντουζ, lifeguard, ξαπλώστρες με ομπρέλα για να γλιτώσεις από τον ήλιο των 12. Σκιά για τη σιέστα. Αυτή η λίστα συγκεντρώνει τις παραλίες της Χαλκιδικής που έχουν χαρακτηριστικό shallowWater από τη βάση μας — δηλαδή έχουν επιβεβαιωθεί ως ασφαλείς για μικρά παιδιά — και προστίθενται κατά rating.</p>`, en: `<p>With small children a beach isn't picked just for looks — it's picked for <strong>safety</strong>. A shallow zone stretching at least 20-30 metres from shore, with no sudden drops. Sand they can walk on without hurting themselves. Services like showers, lifeguards, loungers with umbrellas so you can escape the noon sun. Shade for the afternoon nap. This list collects Halkidiki beaches tagged with shallowWater in our database — confirmed safe for small children — sorted by rating.</p>`, de: `<p>Mit kleinen Kindern wählt man einen Strand nicht nur nach Schönheit aus — sondern nach <strong>Sicherheit</strong>. Eine flache Zone, die sich mindestens 20-30 Meter vom Ufer erstreckt, ohne plötzliche Tiefen. Sand, auf dem sie laufen können, ohne sich zu verletzen. Einrichtungen wie Duschen, Rettungsschwimmer, Liegen mit Sonnenschirmen, um der Mittagssonne zu entkommen. Schatten für die Siesta. Diese Liste fasst die Strände in Chalkidiki zusammen, die in unserer Datenbank als shallowWater gekennzeichnet sind — das heißt, sie wurden als sicher für kleine Kinder bestätigt — und werden nach Bewertung hinzugefügt.</p>`, ro: `<p>Cu copii mici, o plajă nu este aleasă doar pentru frumusețe — este aleasă pentru <strong>siguranță</strong>. Zonă de mică adâncime care se extinde cel puțin 20-30 de metri de la țărm, fără zone adânci bruște. Nisip pe care pot merge fără să se rănească. Servicii precum dușuri, salvamar, șezlonguri cu umbrelă pentru a te feri de soarele de la ora 12. Umbra pentru siestă. Această listă adună plajele din Halkidiki care au caracteristică shallowWater din baza noastră — adică au fost confirmate ca fiind sigure pentru copii mici — și sunt adăugate în funcție de rating.</p>`, sr: `<p>Kada putujete sa malom decom, plaža se ne bira samo po lepoti — bira se po <strong>bezbednosti</strong>. Plitka zona koja se proteže najmanje 20-30 metara od obale, bez naglih dubokih delova. Pesak po kojem mogu hodati bez povreda. Usluge kao što su tuševi, spasioci, ležaljke sa suncobranom za zaštitu od podnevnog sunca. Hlad za popodnevni odmor. Ova lista okuplja plaže Halkidikija koje imaju karakteristiku shallowWater iz naše baze — što znači da su potvrđene kao bezbedne za malu decu — i dodaju se prema oceni.</p>`, bg: `<p>С малки деца плажът не се избира само по красота — избира се по <strong>безопасност</strong>. Плитка зона, която се простира поне 20-30 метра от брега, без внезапни дълбоки участъци. Пясък, по който могат да ходят, без да се наранят. Услуги като душове, спасител, шезлонги с чадър, за да се предпазите от слънцето в 12 часа. Сянка за следобедна почивка. Този списък събира плажовете на Халкидики, които имат характеристика shallowWater от нашата база данни — тоест са потвърдени като безопасни за малки деца — и са подредени по рейтинг.</p>`, ru: `<p>С маленькими детьми пляж выбирается не только по красоте — он выбирается по <strong>безопасности</strong>. Мелководная зона, простирающаяся как минимум на 20-30 метров от берега, без резких глубоких участков. Песок, по которому можно ходить, не поранившись. Услуги, такие как душ, спасатель, шезлонги с зонтиками, чтобы укрыться от полуденного солнца. Тень для сиесты. Этот список собирает пляжи Халкидики, которые имеют характеристику shallowWater в нашей базе данных — то есть подтверждены как безопасные для маленьких детей — и добавляются по рейтингу.</p>` },
    seasonal: { el: `<h2>Πότε να πας με παιδιά</h2><p><strong>Ιούνιος:</strong> το καλύτερο — θάλασσα 22-24°C, ζεσταίνεται γρήγορα στο ρηχό. Λίγος κόσμος. <strong>Σεπτέμβριος:</strong> εξίσου καλός — νερό ακόμα ζεστό, σαφώς λιγότερος κόσμος, καλύτερες τιμές. <strong>Αύγουστος:</strong> προσοχή — πολυκοσμία, ξαπλώστρες πιάνονται νωρίς, οι αργές χιλιάδες αγγίζουν το όριο των παιδικών αντοχών. Πρωινό 8-12 πρωτότυπη επιλογή.</p>`, en: `<h2>When to visit with kids</h2><p><strong>June:</strong> the best — sea 22-24°C, warms up fast in the shallows. Few crowds. <strong>September:</strong> equally good — water still warm, much smaller crowds, better prices. <strong>August:</strong> caution — high temperatures and crowds push the limits of small children. A morning swim 8-12 is the smart move.</p>`, de: `<h2>Wann man mit Kindern reisen sollte</h2><p><strong>Juni:</strong> der beste Monat — Meer 22-24°C, erwärmt sich schnell im Flachen. Wenig Leute. <strong>September:</strong> ebenso gut — Wasser noch warm, deutlich weniger Menschen, bessere Preise. <strong>August:</strong> Vorsicht — überfüllt, Liegen sind früh besetzt, die langsamen Tausenden erreichen die Grenzen der kindlichen Ausdauer. Morgens 8-12 eine originelle Wahl.</p>`, ro: `<h2>Când să mergi cu copiii</h2><p><strong>Iunie:</strong> cea mai bună perioadă — mare 22-24°C, se încălzește rapid în zonele de mică adâncime. Puțină lume. <strong>Septembrie:</strong> la fel de bun — apa încă caldă, mult mai puțină lume, prețuri mai bune. <strong>August:</strong> atenție — aglomerație, șezlongurile sunt ocupate devreme, mulțimile lente ating limita rezistenței copiilor. Dimineața 8-12 o alegere originală.</p>`, sr: `<h2>Kada ići sa decom</h2><p><strong>Jun:</strong> najbolji period — more 22-24°C, brzo se zagreva u plićaku. Malo ljudi. <strong>Septembar:</strong> jednako dobar — voda još uvek topla, znatno manje ljudi, bolje cene. <strong>Avgust:</strong> oprez — gužve, ležaljke se zauzimaju rano, velike gužve mogu biti naporne za decu. Jutarnji termin 8-12 je originalan izbor.</p>`, bg: `<h2>Кога да отидете с деца</h2><p><strong>Юни:</strong> най-добрият — море 22-24°C, бързо се затопля в плиткото. Малко хора. <strong>Септември:</strong> също добър — водата все още топла, значително по-малко хора, по-добри цени. <strong>Август:</strong> внимание — много хора, шезлонгите се заемат рано, бавните хиляди достигат границата на детските възможности. Сутрешен 8-12 оригинален избор.</p>`, ru: `<h2>Когда ехать с детьми</h2><p><strong>Июнь:</strong> лучшее время — море 22-24°C, быстро прогревается на мелководье. Мало людей. <strong>Сентябрь:</strong> также хорош — вода еще теплая, значительно меньше людей, лучшие цены. <strong>Август:</strong> осторожно — многолюдно, шезлонги занимают рано, медленные тысячи достигают предела детской выносливости. Утренний выбор 8-12 — оригинальный вариант.</p>` },
    tips: { el: `<h2>Συμβουλές για οικογένειες</h2><ul><li><strong>Πρωινό slot:</strong> Φτάσε 8:30-9:00. Σιγουρεύεις ξαπλώστρα με σκιά, παίρνεις τα κρύα νερά πριν γεμίσει.</li><li><strong>Παιδικός εξοπλισμός:</strong> Φέρε σαμπρέλα/βραχιολάκι, χονδρό αντηλιακό (SPF 50+), καπέλο. Φουσκωτά για το κλιμακούμενο σερφάρισμα — προαιρετικά.</li><li><strong>Lifeguard:</strong> Σε οργανωμένες παραλίες (Σάνη, Καλλιθέα, Χανιώτη). Στις φυσικές (Σιθωνία) δεν υπάρχει — απαιτεί επίβλεψη.</li><li><strong>Φαγητό:</strong> Έχε snacks και νερό — δεν περιμένεις παιδί 4 ετών για 30' fish meal με ορθανοιχτό 35°C.</li><li><strong>Εναλλακτικά:</strong> Αν θες λιγότερο πλήθος, δες τις <a href="/best/quiet-beaches">ήσυχες παραλίες</a>.</li></ul>`, en: `<h2>Tips for families</h2><ul><li><strong>Morning slot:</strong> Arrive 8:30-9:00. You lock in a shaded lounger and get the cooler water before the crowds.</li><li><strong>Kid kit:</strong> Bring floats/armbands, thick sunscreen (SPF 50+), hats. Inflatables for graduated splashing — optional.</li><li><strong>Lifeguard:</strong> Available on organised beaches (Sani, Kallithea, Hanioti). On natural ones (Sithonia) there's none — supervision required.</li><li><strong>Food:</strong> Pack snacks and water — don't expect a 4-year-old to sit through a 30-min fish meal at 35°C.</li><li><strong>Alternatives:</strong> For smaller crowds, see our <a href="/best/quiet-beaches">quiet beaches</a> list.</li></ul>`, de: `<h2>Tipps für Familien</h2><ul><li><strong>Morgenslot:</strong> Ankunft um 8:30-9:00. Sicher dir eine Liege mit Schatten, hol dir das kalte Wasser, bevor es voll wird.</li><li><strong>Kinder-Ausrüstung:</strong> Bring Schwimmring/Schwimmflügel, dicke Sonnencreme (SPF 50+), Hut. Aufblasbares für das allmähliche Surfen — optional.</li><li><strong>Rettungsschwimmer:</strong> An organisierten Stränden (Sani, Kallithea, Chanioti). An natürlichen (Sithonia) gibt es keine — Aufsicht erforderlich.</li><li><strong>Essen:</strong> Hab Snacks und Wasser dabei — du kannst nicht erwarten, dass ein 4-jähriges Kind 30 Minuten auf ein Fischgericht bei offenen 35°C wartet.</li><li><strong>Alternativen:</strong> Wenn du weniger Menschenmengen möchtest, sieh dir die <a href="/best/quiet-beaches">ruhigen Strände</a> an.</li></ul>`, ro: `<h2>Sfaturi pentru familii</h2><ul><li><strong>Slot de dimineață:</strong> Ajungeți la 8:30-9:00. Asigurați-vă un șezlong cu umbră, luați apă rece înainte să se aglomereze.</li><li><strong>Echipament pentru copii:</strong> Aduceți colac/brațare, cremă de protecție solară groasă (SPF 50+), pălărie. Gonflabile pentru surfing progresiv — opțional.</li><li><strong>Salvamar:</strong> Pe plajele organizate (Sani, Kallithea, Hanioti). Pe cele naturale (Sithonia) nu există — necesită supraveghere.</li><li><strong>Mâncare:</strong> Aveți gustări și apă — nu așteptați un copil de 4 ani pentru o masă de pește de 30' la 35°C deschis.</li><li><strong>Alternative:</strong> Dacă doriți mai puțină aglomerație, vedeți <a href="/best/quiet-beaches">plajele liniștite</a>.</li></ul>`, sr: `<h2>Saveti za porodice</h2><ul><li><strong>Jutarnji termin:</strong> Stignite između 8:30-9:00. Osiguravate ležaljku sa hladom, uzimate hladnu vodu pre nego što se napuni.</li><li><strong>Dečija oprema:</strong> Ponesite šlauf/narukvice, gusti zaštitni faktor (SPF 50+), šešir. Na naduvavanje za postepeno surfovanje — opcionalno.</li><li><strong>Spasilac:</strong> Na organizovanim plažama (Sani, Kallithea, Hanioti). Na prirodnim (Sithonia) nema — potrebna je nadgledanje.</li><li><strong>Hrana:</strong> Ponesite grickalice i vodu — ne očekujte da dete od 4 godine čeka 30 minuta na riblji obrok na 35°C.</li><li><strong>Alternativa:</strong> Ako želite manje gužve, pogledajte <a href="/best/quiet-beaches">mirne plaže</a>.</li></ul>`, bg: `<h2>Съвети за семейства</h2><ul><li><strong>Сутрешен слот:</strong> Пристигнете 8:30-9:00. Осигурявате си шезлонг със сянка, вземате студените води преди да се напълни.</li><li><strong>Детско оборудване:</strong> Донесете пояс/гривна, дебел слънцезащитен крем (SPF 50+), шапка. Надуваеми за постепенно сърфиране — по желание.</li><li><strong>Спасител:</strong> На организирани плажове (Сани, Калифея, Ханиоти). На природните (Ситония) няма — изисква се наблюдение.</li><li><strong>Храна:</strong> Имайте закуски и вода — не очаквайте дете на 4 години да чака 30' рибно ястие при 35°C.</li><li><strong>Алтернативи:</strong> Ако искате по-малко хора, вижте <a href="/best/quiet-beaches">тихите плажове</a>.</li></ul>`, ru: `<h2>Советы для семей</h2><ul><li><strong>Утреннее время:</strong> Прибывайте в 8:30-9:00. Гарантируете себе шезлонг с тенью, берете холодную воду до того, как станет многолюдно.</li><li><strong>Детское снаряжение:</strong> Возьмите круг/нарукавники, плотный солнцезащитный крем (SPF 50+), шляпу. Надувные игрушки для постепенного серфинга — по желанию.</li><li><strong>Спасатель:</strong> На организованных пляжах (Сани, Каллифея, Ханиоти). На природных (Ситония) отсутствует — требуется наблюдение.</li><li><strong>Еда:</strong> Имейте при себе закуски и воду — не ждите, что ребенок 4 лет будет ждать 30 минут рыбного обеда при 35°C.</li><li><strong>Альтернативы:</strong> Если хотите меньше людей, посмотрите <a href="/best/quiet-beaches">тихие пляжи</a>.</li></ul>` },
    faqs: [
      { q: { el: `Σε ποια παραλία να πάμε με μωρό 1-2 ετών;`, en: `Best beach with a 1-2 year old baby?`, de: `Welchen Strand sollten wir mit einem 1-2 Jahre alten Baby besuchen?`, ro: `La ce plajă să mergem cu un bebeluș de 1-2 ani?`, sr: `Koju plažu da izaberemo sa bebom od 1-2 godine?`, bg: `На кой плаж да отидем с бебе на 1-2 години?`, ru: `На какой пляж пойти с ребенком 1-2 лет?` }, a: { el: `Επιλέξτε παραλία με <strong>ρηχή ζώνη + σκιά + lifeguard + κοντινό parking</strong>. Η <strong>Σάνη Marina</strong>, η <strong>Σιβηρή</strong> και η <strong>Νέα Φώκαια</strong> πληρούν όλα. Αποφύγετε χωμάτινες προσβάσεις και απόμακρες παραλίες.`, en: `Choose a beach with <strong>shallow zone + shade + lifeguard + nearby parking</strong>. <strong>Sani Marina</strong>, <strong>Siviri</strong> and <strong>Nea Fokaia</strong> tick all boxes. Avoid dirt-road approaches and remote beaches.`, de: `Wähle einen Strand mit <strong>flacher Zone + Schatten + Rettungsschwimmer + nahegelegenem Parkplatz</strong>. <strong>Sani Marina</strong>, <strong>Siviri</strong> und <strong>Nea Fokea</strong> erfüllen alle Kriterien. Vermeide unbefestigte Zugänge und abgelegene Strände.`, ro: `Alegeți o plajă cu <strong>zonă de mică adâncime + umbră + salvamar + parcare apropiată</strong>. <strong>Sani Marina</strong>, <strong>Siviri</strong> și <strong>Nea Fokea</strong> îndeplinesc toate aceste condiții. Evitați accesul pe drumuri de pământ și plajele îndepărtate.`, sr: `Izaberite plažu sa <strong>plitkom zonom + hladom + spasiocem + bliskim parkingom</strong>. <strong>Sani Marina</strong>, <strong>Siviri</strong> i <strong>Nea Fokea</strong> ispunjavaju sve uslove. Izbegavajte zemljane prilaze i udaljene plaže.`, bg: `Изберете плаж с <strong>плитка зона + сянка + спасител + близък паркинг</strong>. <strong>Сани Марина</strong>, <strong>Сивири</strong> и <strong>Неа Фокеа</strong> отговарят на всички изисквания. Избягвайте черни пътища и отдалечени плажове.`, ru: `Выбирайте пляж с <strong>мелководной зоной + тенью + спасателем + близкой парковкой</strong>. <strong>Сани Марина</strong>, <strong>Сивири</strong> и <strong>Неа Фокеа</strong> соответствуют всем требованиям. Избегайте грунтовых дорог и удаленных пляжей.` } },
      { q: { el: `Υπάρχουν φιλικά για άτομα με αναπηρία;`, en: `Are there beaches accessible for disabled visitors?`, de: `Gibt es behindertengerechte Strände?`, ro: `Există plaje prietenoase pentru persoanele cu dizabilități?`, sr: `Postoje li plaže prilagođene osobama sa invaliditetom?`, bg: `Има ли удобства за хора с увреждания?`, ru: `Есть ли пляжи, доступные для людей с ограниченными возможностями?` }, a: { el: `Ναι — οι περισσότερες οργανωμένες παραλίες (Σάνη, Καλλιθέα, Μυκονιάτικα) έχουν Disabled Access. Συμπεριλαμβάνουν seatrac (αυτόματο μηχανισμό για είσοδο στο νερό σε αναπηρικό αμαξίδιο) σε αρκετές.`, en: `Yes — most organised beaches (Sani, Kallithea, Mykoniatika) offer disabled access. Several include a seatrac (an automated lift for entering the water in a wheelchair).`, de: `Ja — die meisten organisierten Strände (Sani, Kallithea, Mykoniatika) haben Behindertenzugang. Sie beinhalten seatrac (automatischer Mechanismus für den Zugang zum Wasser im Rollstuhl) an mehreren Orten.`, ro: `Da — majoritatea plajelor organizate (Sani, Kallithea, Mykoniatika) au acces pentru persoane cu dizabilități. Includ seatrac (mecanism automat pentru intrarea în apă cu scaun cu rotile) în multe dintre ele.`, sr: `Da — većina organizovanih plaža (Sani, Kallithea, Mykoniatika) ima pristup za osobe sa invaliditetom. Uključuju seatrac (automatski mehanizam za ulazak u vodu u invalidskim kolicima) na mnogim mestima.`, bg: `Да — повечето организирани плажове (Сани, Калифея, Миконятика) имат достъп за хора с увреждания. Включват сеатрак (автоматичен механизъм за влизане във водата с инвалидна количка) на много места.`, ru: `Да — большинство организованных пляжей (Сани, Каллифея, Миконьятика) имеют доступ для инвалидов. Включают seatrac (автоматический механизм для входа в воду на инвалидной коляске) на многих из них.` } },
      { q: { el: `Πόσο κοστίζει για 4μελή οικογένεια;`, en: `How much for a family of 4?`, de: `Wie viel kostet es für eine 4-köpfige Familie?`, ro: `Cât costă pentru o familie de 4 persoane?`, sr: `Koliko košta za četvoročlanu porodicu?`, bg: `Колко струва за 4-членно семейство?`, ru: `Сколько стоит для семьи из 4 человек?` }, a: { el: `<strong>Beach set</strong> (ξαπλώστρες + ομπρέλα): €15-25/μέρα στις πιο γνωστές. <strong>Φαγητό μεσημεριανό</strong>: €40-70 για 4 σε beach restaurant, €30-50 σε ταβέρνα στο χωριό. <strong>Σνακ/παγωτό</strong>: €15-20. Σύνολο μέρας: €70-130 για 4 άτομα.`, en: `<strong>Beach set</strong> (loungers + umbrella): €15-25/day at the famous beaches. <strong>Lunch</strong>: €40-70 for 4 at a beach restaurant, €30-50 at a village taverna. <strong>Snacks/ice cream</strong>: €15-20. Total day: €70-130 for four.`, de: `<strong>Beach-Set</strong> (Liegen + Schirm): €15-25/Tag an den bekanntesten Stränden. <strong>Mittagessen</strong>: €40-70 für 4 Personen im Strandrestaurant, €30-50 in einer Dorftaverne. <strong>Snacks/Eis</strong>: €15-20. Gesamttageskosten: €70-130 für 4 Personen.`, ro: `<strong>Set de plajă</strong> (șezlonguri + umbrelă): €15-25/zi la cele mai cunoscute. <strong>Masa de prânz</strong>: €40-70 pentru 4 persoane la un restaurant de plajă, €30-50 la o tavernă în sat. <strong>Gustări/înghețată</strong>: €15-20. Total pe zi: €70-130 pentru 4 persoane.`, sr: `<strong>Set na plaži</strong> (ležaljke + suncobran): €15-25/dan na najpoznatijim plažama. <strong>Ručak</strong>: €40-70 za 4 osobe u restoranu na plaži, €30-50 u taverni u selu. <strong>Grickalice/sladoled</strong>: €15-20. Ukupno za dan: €70-130 za 4 osobe.`, bg: `<strong>Комплект за плаж</strong> (шезлонги + чадър): €15-25/ден на най-известните. <strong>Обяд</strong>: €40-70 за 4 в плажно заведение, €30-50 в таверна в селото. <strong>Закуски/сладолед</strong>: €15-20. Общо за деня: €70-130 за 4 души.`, ru: `<strong>Набор на пляже</strong> (шезлонги + зонтик): €15-25/день на самых известных. <strong>Обед</strong>: €40-70 для 4 человек в пляжном ресторане, €30-50 в таверне в деревне. <strong>Закуски/мороженое</strong>: €15-20. Общая стоимость дня: €70-130 для 4 человек.` } },
      { q: { el: `Είναι ασφαλή τα νερά για κολύμπι παιδιών;`, en: `Is the water safe for children to swim in?`, de: `Sind die Gewässer sicher für das Schwimmen von Kindern?`, ro: `Sunt sigure apele pentru înotul copiilor?`, sr: `Da li je voda bezbedna za dečije plivanje?`, bg: `Безопасни ли са водите за плуване на деца?`, ru: `Безопасны ли воды для купания детей?` }, a: { el: `Ναι — η Χαλκιδική έχει πάνω από 100 Γαλάζιες Σημαίες, που πιστοποιούν ποιότητα νερού και ασφάλεια. Οι παραλίες αυτής της λίστας έχουν ρηχή ζώνη επιβεβαιωμένη από τα OSM tags. Πάντα προσέχεις τα παιδιά σου ασχέτως ποιότητας νερού.`, en: `Yes — Halkidiki has over 100 Blue Flag beaches, certifying water quality and safety. The beaches in this list have shallow zones confirmed via OSM tags. Always supervise children regardless of water quality.`, de: `Ja — Chalkidiki hat über 100 Blaue Flaggen, die Wasserqualität und Sicherheit zertifizieren. Die Strände dieser Liste haben eine flache Zone, die durch OSM-Tags bestätigt wurde. Achte immer auf deine Kinder, unabhängig von der Wasserqualität.`, ro: `Da — Halkidiki are peste 100 de Steaguri Albastre, care certifică calitatea apei și siguranța. Plajele din această listă au zonă de mică adâncime confirmată de tagurile OSM. Întotdeauna supravegheați copiii, indiferent de calitatea apei.`, sr: `Da — Halkidiki ima preko 100 Plavih zastava, što potvrđuje kvalitet vode i sigurnost. Plaže sa ove liste imaju potvrđenu plitku zonu prema OSM oznakama. Uvek pazite na svoju decu bez obzira na kvalitet vode.`, bg: `Да — Халкидики има над 100 Сини флага, които удостоверяват качеството на водата и безопасността. Плажовете в този списък имат плитка зона, потвърдена от OSM тагове. Винаги наблюдавайте децата си, независимо от качеството на водата.`, ru: `Да — Халкидики имеет более 100 Голубых флагов, подтверждающих качество воды и безопасность. Пляжи из этого списка имеют мелководную зону, подтвержденную тегами OSM. Всегда следите за своими детьми, независимо от качества воды.` } },
    ],
  },
  "quiet-beaches": {
    intro: { el: `<p>Όχι όλοι αναζητούν τη Καλλιθέα τον Αύγουστο. Για κάποιους, οι διακοπές σημαίνει αποσύνδεση: παραλία χωρίς μουσική, χωρίς ξαπλώστρες, χωρίς ώρα έναρξης πανηγυριού. Η Χαλκιδική έχει πολλές τέτοιες παραλίες — απλώς δεν είναι αυτές που εμφανίζονται στις τουριστικές διαφημίσεις. Αυτή η λίστα συγκεντρώνει ελεύθερες παραλίες χωρίς οργανωμένη υποδομή ή με ελάχιστη — μερικές απομονωμένες (Καβουρότρυπες, Διάπορος), άλλες απλώς λιγότερο διαφημισμένες (Τσούκα, Καρύδι Δυτική). Όλες χαρακτηρίζονται 'free' στη βάση μας, που σημαίνει ότι μπορείς να στρώσεις πετσέτα όπου θες.</p>`, en: `<p>Not everyone is looking for Kallithea in August. For some people, holidays mean disconnection: a beach without music, without sun loungers, without a fixed start time for the party. Halkidiki has many such beaches — they just don't show up in tourist ads. This list gathers free, unorganised beaches — some isolated (Kavourotrypes, Diaporos), others simply less advertised (Tsouka, west Karydi). All are tagged 'free' in our database, meaning you can spread a towel anywhere.</p>`, de: `<p>Nicht jeder sucht im August Kallithea auf. Für manche bedeutet Urlaub Abschalten: Strand ohne Musik, ohne Liegen, ohne festgelegte Partyzeiten. Chalkidiki hat viele solcher Strände — sie sind einfach nicht die, die in den Tourismuswerbungen auftauchen. Diese Liste sammelt unberührte Strände ohne organisierte Infrastruktur oder mit minimaler — einige sind abgelegen (Kavourotrypes, Diaporos), andere einfach weniger beworben (Tsouka, Karydi West). Alle sind in unserer Datenbank als 'frei' gekennzeichnet, was bedeutet, dass du dein Handtuch überall ausbreiten kannst.</p>`, ro: `<p>Nu toată lumea caută Kallithea în august. Pentru unii, vacanța înseamnă deconectare: plajă fără muzică, fără șezlonguri, fără ora de începere a petrecerii. Halkidiki are multe astfel de plaje — doar că nu sunt cele care apar în reclamele turistice. Această listă reunește plaje libere fără infrastructură organizată sau cu minimă — unele izolate (Kavourotrypes, Diaporos), altele doar mai puțin promovate (Tsouka, Karydi Vest). Toate sunt caracterizate ca 'libere' în baza noastră, ceea ce înseamnă că poți să-ți așezi prosopul oriunde dorești.</p>`, sr: `<p>Nisu svi u potrazi za Kallitheom u avgustu. Za neke, odmor znači isključenje: plaža bez muzike, bez ležaljki, bez početka žurke. Halkidiki ima mnogo takvih plaža — jednostavno nisu one koje se pojavljuju u turističkim reklamama. Ova lista okuplja slobodne plaže bez organizovane infrastrukture ili sa minimalnom — neke izolovane (Kavourotrypes, Diaporos), druge jednostavno manje reklamirane (Tsouka, Karydi Zapadna). Sve su označene kao 'slobodne' u našoj bazi, što znači da možeš da prostreš peškir gde god želiš.</p>`, bg: `<p>Не всички търсят Калифея през август. За някои, ваканцията означава откъсване: плаж без музика, без шезлонги, без начало на празненства. Халкидики има много такива плажове — просто те не са тези, които се появяват в туристическите реклами. Този списък събира свободни плажове без организирана инфраструктура или с минимална — някои изолирани (Кавуротрипес, Диапорос), други просто по-малко рекламирани (Цука, Кариди Западен). Всички се характеризират като 'свободни' в нашата база, което означава, че можеш да постелиш кърпа където пожелаеш.</p>`, ru: `<p>Не все ищут Калифею в августе. Для некоторых отдых означает отключение: пляж без музыки, без шезлонгов, без расписания вечеринок. Халкидики предлагает множество таких пляжей — просто они не появляются в туристических рекламах. Этот список собирает свободные пляжи без организованной инфраструктуры или с минимальной — некоторые изолированные (Кавуротрипес, Диапорос), другие просто менее рекламируемые (Цука, Кариди Западный). Все они отмечены как 'свободные' в нашей базе, что означает, что вы можете разложить полотенце где угодно.</p>` },
    seasonal: { el: `<h2>Πότε να πας</h2><p><strong>Όλο το χρόνο εκτός peak weekends:</strong> Αυτές οι παραλίες δεν γεμίζουν ποτέ. Η μόνη εξαίρεση: Σαββατοκύριακα Ιουλίου-Αυγούστου σε όσες πλησίον γνωστών τοποθεσιών. <strong>Sweet spot:</strong> Μάιος-Ιούνιος και Σεπτέμβριος-Οκτώβριος — έχεις την παραλία σχεδόν για σένα.</p>`, en: `<h2>When to visit</h2><p><strong>Any time except peak weekends:</strong> These beaches never really get busy. The only exception: July-August weekends for those near famous spots. <strong>Sweet spot:</strong> May-June and September-October — you basically have the beach to yourself.</p>`, de: `<h2>Wann man gehen sollte</h2><p><strong>Das ganze Jahr über außer an Spitzenwochenenden:</strong> Diese Strände sind nie überfüllt. Die einzige Ausnahme: Wochenenden im Juli-August in der Nähe bekannter Orte. <strong>Beste Zeit:</strong> Mai-Juni und September-Oktober — du hast den Strand fast für dich allein.</p>`, ro: `<h2>Când să mergi</h2><p><strong>Tot anul, cu excepția weekendurilor de vârf:</strong> Aceste plaje nu se aglomerează niciodată. Singura excepție: weekendurile din iulie-august în cele din apropierea locațiilor cunoscute. <strong>Perioada ideală:</strong> Mai-iunie și septembrie-octombrie — ai plaja aproape doar pentru tine.</p>`, sr: `<h2>Kada posetiti</h2><p><strong>Cele godine osim vikendima u špicu:</strong> Ove plaže nikada nisu pretrpane. Jedini izuzetak: vikendi u julu-avgustu u onima blizu poznatih lokacija. <strong>Idealno vreme:</strong> Maj-jun i septembar-oktobar — imaš plažu skoro samo za sebe.</p>`, bg: `<h2>Кога да отидеш</h2><p><strong>Целогодишно, освен през пиковите уикенди:</strong> Тези плажове никога не се пълнят. Единственото изключение: уикендите през юли-август в близост до известни места. <strong>Идеалният момент:</strong> Май-юни и септември-октомври — имаш плажа почти за себе си.</p>`, ru: `<h2>Когда ехать</h2><p><strong>Круглый год, кроме пиковых выходных:</strong> Эти пляжи никогда не заполняются. Единственное исключение: выходные июля-августа вблизи известных мест. <strong>Лучшее время:</strong> Май-июнь и сентябрь-октябрь — пляж почти в вашем распоряжении.</p>` },
    tips: { el: `<h2>Συμβουλές για ήσυχες παραλίες</h2><ul><li><strong>Πάρε όλα μαζί:</strong> Νερό, σνακ, ομπρέλα, πετσέτες, αντηλιακό. Δεν θα βρεις καντίνα.</li><li><strong>Σκουπίδια μαζί σου:</strong> Πάρε σακούλα. Αυτές οι παραλίες παραμένουν καθαρές γιατί οι επισκέπτες σέβονται τον χώρο.</li><li><strong>Πάρκαρε σωστά:</strong> Σε κάποιες (Καβουρότρυπες) είναι μακριά + περπάτημα. Παπούτσια κατάλληλα.</li><li><strong>Σήμα κινητού:</strong> Σε απομονωμένες περιοχές μπορεί να μην έχει — ενημέρωσε κάποιον πού πας.</li><li><strong>Snorkeling bonus:</strong> Οι ήσυχες παραλίες έχουν τα πιο διαυγή νερά. Δες τις <a href="/best/snorkeling-spots">καλύτερες παραλίες snorkeling</a>.</li></ul>`, en: `<h2>Tips for quiet beaches</h2><ul><li><strong>Bring everything:</strong> Water, snacks, umbrella, towels, sunscreen. There's no canteen.</li><li><strong>Pack your rubbish out:</strong> Bring a bag. These beaches stay clean because visitors respect them.</li><li><strong>Park sensibly:</strong> Some (Kavourotrypes) need a long walk. Wear suitable shoes.</li><li><strong>Mobile signal:</strong> Patchy in isolated areas — tell someone where you're going.</li><li><strong>Snorkelling bonus:</strong> Quiet beaches have the clearest water. See our <a href="/best/snorkeling-spots">best snorkelling beaches</a>.</li></ul>`, de: `<h2>Tipps für ruhige Strände</h2><ul><li><strong>Nimm alles mit:</strong> Wasser, Snacks, Sonnenschirm, Handtücher, Sonnencreme. Es gibt keinen Kiosk.</li><li><strong>Nimm deinen Müll mit:</strong> Bring einen Beutel mit. Diese Strände bleiben sauber, weil die Besucher den Ort respektieren.</li><li><strong>Richtig parken:</strong> Bei einigen (Kavourotrypes) ist es weit + zu Fuß. Geeignetes Schuhwerk.</li><li><strong>Handysignal:</strong> In abgelegenen Gebieten kann es keins geben — informiere jemanden, wohin du gehst.</li><li><strong>Schnorchel-Bonus:</strong> Die ruhigen Strände haben das klarste Wasser. Sieh dir die <a href="/best/snorkeling-spots">besten Schnorchelstrände</a> an.</li></ul>`, ro: `<h2>Sfaturi pentru plaje liniștite</h2><ul><li><strong>Ia totul cu tine:</strong> Apă, gustări, umbrelă, prosoape, cremă de protecție solară. Nu vei găsi cantină.</li><li><strong>Ia gunoiul cu tine:</strong> Ia un sac. Aceste plaje rămân curate pentru că vizitatorii respectă locul.</li><li><strong>Parchează corect:</strong> La unele (Kavourotrypes) este departe + mers pe jos. Încălțăminte adecvată.</li><li><strong>Semnal mobil:</strong> În zonele izolate poate lipsi — informează pe cineva unde mergi.</li><li><strong>Bonus snorkeling:</strong> Plajele liniștite au cele mai limpezi ape. Vezi <a href="/best/snorkeling-spots">cele mai bune plaje pentru snorkeling</a>.</li></ul>`, sr: `<h2>Saveti za mirne plaže</h2><ul><li><strong>Ponesi sve sa sobom:</strong> Vodu, grickalice, suncobran, peškire, kremu za sunčanje. Nećeš naći kantinu.</li><li><strong>Odnesi smeće sa sobom:</strong> Ponesi kesu. Ove plaže ostaju čiste jer posetioci poštuju prostor.</li><li><strong>Parkiraj pravilno:</strong> Na nekima (Kavourotrypes) je daleko + pešačenje. Odgovarajuća obuća.</li><li><strong>Signal za mobilni:</strong> U izolovanim područjima može biti slab — obavesti nekoga gde ideš.</li><li><strong>Snorkeling bonus:</strong> Mirne plaže imaju najčistiju vodu. Pogledaj <a href="/best/snorkeling-spots">najbolje plaže za snorkeling</a>.</li></ul>`, bg: `<h2>Съвети за тихи плажове</h2><ul><li><strong>Вземи всичко необходимо:</strong> Вода, закуски, чадър, кърпи, слънцезащитен крем. Няма да намериш кантинa.</li><li><strong>Вземи боклука със себе си:</strong> Вземи торба. Тези плажове остават чисти, защото посетителите уважават мястото.</li><li><strong>Паркирай правилно:</strong> На някои (Кавуротрипес) е далеч + ходене. Подходящи обувки.</li><li><strong>Мобилен сигнал:</strong> В изолирани райони може да няма — информирай някого къде отиваш.</li><li><strong>Snorkeling бонус:</strong> Тихите плажове имат най-чистите води. Виж <a href="/best/snorkeling-spots">най-добрите плажове за snorkeling</a>.</li></ul>`, ru: `<h2>Советы для тихих пляжей</h2><ul><li><strong>Возьмите все с собой:</strong> Воду, закуски, зонтик, полотенца, солнцезащитный крем. Кантину не найдете.</li><li><strong>Убирайте за собой:</strong> Возьмите пакет. Эти пляжи остаются чистыми, потому что посетители уважают место.</li><li><strong>Паркуйтесь правильно:</strong> На некоторых (Кавуротрипес) далеко + пешком. Подходящая обувь.</li><li><strong>Сигнал мобильного:</strong> В изолированных районах может не быть — сообщите кому-то, куда направляетесь.</li><li><strong>Бонус для снорклинга:</strong> Тихие пляжи имеют самые прозрачные воды. Посмотрите <a href="/best/snorkeling-spots">лучшие пляжи для снорклинга</a>.</li></ul>` },
    faqs: [
      { q: { el: `Πώς ξεχωρίζω μια "ήσυχη" παραλία στη Χαλκιδική;`, en: `How do I spot a "quiet" beach in Halkidiki?`, de: `Wie erkenne ich einen "ruhigen" Strand in Chalkidiki?`, ro: `Cum recunosc o plajă "liniștită" în Halkidiki?`, sr: `Kako da prepoznam "mirnu" plažu na Halkidikiju?`, bg: `Как да разпозная "тих" плаж в Халкидики?`, ru: `Как распознать "тихий" пляж на Халкидиках?` }, a: { el: `Ψάχνεις χωρίς beach bar visible, χωρίς γραμμές ξαπλώστρες, με χωμάτινο δρόμο τα τελευταία 500m. Συνήθως στις πιο απομακρυσμένες περιοχές της Σιθωνίας ή στη δυτική Κασσάνδρα.`, en: `Look for no visible beach bar, no rows of loungers, and a dirt road for the last 500m. Usually in the more remote parts of Sithonia or west Kassandra.`, de: `Suche nach Stränden ohne sichtbares Beach Bar, ohne Reihen von Liegen, mit Schotterstraße auf den letzten 500m. Meistens in den abgelegeneren Gebieten von Sithonia oder im westlichen Kassandra.`, ro: `Caută fără beach bar vizibil, fără linii de șezlonguri, cu drum de pământ în ultimele 500m. De obicei în zonele mai îndepărtate ale Sithoniei sau în vestul Kassandrei.`, sr: `Tražiš bez vidljivog beach bara, bez redova ležaljki, sa zemljanim putem poslednjih 500m. Obično u najudaljenijim delovima Sitonije ili zapadne Kasandre.`, bg: `Търсиш без видим beach bar, без редици шезлонги, с черен път последните 500м. Обикновено в по-отдалечените райони на Ситония или западната Касандра.`, ru: `Ищите без видимого beach bar, без рядов шезлонгов, с грунтовой дорогой последние 500 м. Обычно в самых удаленных районах Ситонии или на западной Кассандре.` } },
      { q: { el: `Είναι ασφαλές να μείνω μόνος/η σε απομονωμένη παραλία;`, en: `Is it safe to be alone at an isolated beach?`, de: `Ist es sicher, allein an einem abgelegenen Strand zu bleiben?`, ro: `Este sigur să rămân singur/ă pe o plajă izolată?`, sr: `Da li je bezbedno ostati sam/a na izolovanoj plaži?`, bg: `Безопасно ли е да остана сам/а на изолиран плаж?`, ru: `Безопасно ли оставаться одному на изолированном пляже?` }, a: { el: `Ναι, η Χαλκιδική έχει χαμηλό crime rate. Προσοχή κανονικά: μην αφήσεις πορτοφόλι ή τηλέφωνο μόνο όταν κολυμπάς — όπως οπουδήποτε στον κόσμο.`, en: `Yes, Halkidiki has a low crime rate. Standard caution applies: don't leave a wallet or phone unattended while swimming — same as anywhere.`, de: `Ja, Chalkidiki hat eine niedrige Kriminalitätsrate. Normale Vorsicht: Lass dein Portemonnaie oder Telefon nicht unbeaufsichtigt, während du schwimmst — wie überall auf der Welt.`, ro: `Da, Halkidiki are o rată scăzută a criminalității. Atenție normală: nu lăsa portofelul sau telefonul nesupravegheat când înoți — la fel ca oriunde în lume.`, sr: `Da, Halkidiki ima nizak stepen kriminala. Normalna pažnja: ne ostavljaj novčanik ili telefon sami dok plivaš — kao bilo gde u svetu.`, bg: `Да, Халкидики има ниско ниво на престъпност. Внимавай нормално: не оставяй портфейл или телефон сам, когато плуваш — както навсякъде по света.`, ru: `Да, на Халкидиках низкий уровень преступности. Обычная осторожность: не оставляйте кошелек или телефон без присмотра, когда купаетесь — как и везде в мире.` } },
      { q: { el: `Υπάρχουν φυσιοκρατικές (nudist) παραλίες;`, en: `Are there naturist (nudist) beaches?`, de: `Gibt es FKK-Strände?`, ro: `Există plaje naturiste (nudiste)?`, sr: `Postoje li nudističke plaže?`, bg: `Има ли нудистки плажове?`, ru: `Есть ли нудистские пляжи?` }, a: { el: `Ναι — η <strong>Μυκονιάτικα</strong> στην Κασσάνδρα έχει επίσημη ζώνη γυμνιστών. Σε αρκετές απομονωμένες παραλίες της Σιθωνίας τοπική ανοχή.`, en: `Yes — <strong>Mykoniatika</strong> in Kassandra has an official nudist zone. Several isolated Sithonia beaches have informal local tolerance.`, de: `Ja — <strong>Mykoniatika</strong> in Kassandra hat eine offizielle FKK-Zone. An mehreren abgelegenen Stränden in Sithonia gibt es lokale Toleranz.`, ro: `Da — <strong>Mykoniatika</strong> în Kassandra are o zonă oficială pentru nudiști. În multe plaje izolate din Sithonia există toleranță locală.`, sr: `Da — <strong>Mykoniatika</strong> na Kasandri ima zvaničnu zonu za nudiste. Na mnogim izolovanim plažama u Sitoniji postoji lokalna tolerancija.`, bg: `Да — <strong>Миконятика</strong> в Касандра има официална зона за нудисти. На доста изолирани плажове в Ситония има местна толерантност.`, ru: `Да — <strong>Миконьятика</strong> на Кассандре имеет официальную зону для нудистов. На многих изолированных пляжах Ситонии местная терпимость.` } },
    ],
  },
  "seafood-restaurants": {
    intro: { el: `<p>Η Χαλκιδική, με 550 χλμ ακτογραμμής, έχει εξαιρετική παράδοση στα ψαρικά. Οι περισσότερες ταβέρνες σερβίρουν φρέσκο ψάρι από τοπικές αλιείες (κυρίως Νέα Μουδανιά, Σάρτη, Πυργαδίκια), τοπικά μύδια Καλλίστης και χταπόδι ψημένο στα κάρβουνα. Αυτή η λίστα συγκεντρώνει τις ψαροταβέρνες με τις υψηλότερες αξιολογήσεις από επισκέπτες — από εγκαταστάσεις στο λιμάνι μέχρι παραδοσιακές ταβέρνες σε χωριά. Πολλές από αυτές δεν είναι σε beachfront prime locations — αξίζει η οδήγηση.</p>`, en: `<p>Halkidiki, with 550 km of coastline, has an outstanding seafood tradition. Most tavernas serve fresh fish from local fisheries (mostly Nea Moudania, Sarti, Pyrgadikia), local Kallisti mussels, and charcoal-grilled octopus. This list collects the seafood restaurants with the highest visitor ratings — from harbour-front establishments to traditional tavernas in inland villages. Many aren't at beachfront prime locations — the drive is worth it.</p>`, de: `<p>Chalkidiki, mit 550 km Küstenlinie, hat eine hervorragende Tradition in Fischgerichten. Die meisten Tavernen servieren frischen Fisch aus lokalen Fischereien (hauptsächlich Nea Moudania, Sarti, Pyrgadikia), lokale Kallisti-Muscheln und gegrillten Oktopus. Diese Liste fasst die am besten bewerteten Fisch-Tavernen von Besuchern zusammen — von Einrichtungen im Hafen bis hin zu traditionellen Tavernen in Dörfern. Viele davon befinden sich nicht in erstklassigen Lagen am Strand — die Fahrt lohnt sich.</p>`, ro: `<p>Halkidiki, cu 550 km de coastă, are o tradiție excelentă în preparatele din pește. Majoritatea tavernelor servesc pește proaspăt din pescuit local (în principal Nea Moudania, Sarti, Pyrgadikia), midii locale Kallisti și caracatiță la grătar. Această listă reunește tavernele de pește cu cele mai bune evaluări de la vizitatori — de la locații din port până la taverne tradiționale din sate. Multe dintre acestea nu sunt în locații de top pe plajă — merită să conduci până acolo.</p>`, sr: `<p>Halkidiki, sa 550 km obale, ima izuzetnu tradiciju u ribljim specijalitetima. Većina taverni služi svežu ribu iz lokalnog ulova (uglavnom Nea Moudania, Sarti, Pyrgadikia), lokalne školjke Kallistis i hobotnicu pečenu na roštilju. Ova lista okuplja riblje taverne sa najvišim ocenama posetilaca — od objekata u luci do tradicionalnih taverni u selima. Mnoge od njih nisu na vrhunskim lokacijama uz plažu — vredne su vožnje.</p>`, bg: `<p>Халкидики, с 550 км брегова линия, има изключителна традиция в рибните ястия. Повечето таверни сервират прясна риба от местни риболови (главно Неа Мудания, Сарти, Пиргадикия), местни миди Калистис и октопод, печен на въглища. Този списък събира рибните таверни с най-високи оценки от посетители — от заведения в пристанището до традиционни таверни в селата. Много от тях не са на първокласни локации на плажа — заслужава си шофирането.</p>`, ru: `<p>Халкидики, с 550 км береговой линии, имеет отличные традиции в рыбной кухне. Большинство таверн подают свежую рыбу из местных уловов (в основном Неа Мудания, Сарти, Пиргадикия), местные мидии Каллисти и осьминога, приготовленного на углях. Этот список собирает рыбные таверны с самыми высокими оценками от посетителей — от заведений в порту до традиционных таверн в деревнях. Многие из них не находятся на первоклассных пляжных локациях — поездка стоит того.</p>` },
    seasonal: { el: `<h2>Πότε να πας</h2><p><strong>Φρέσκα ψάρια όλη χρονιά</strong> — αλλά καλύτερη ποικιλία Απρίλιο-Οκτώβριο όταν λειτουργούν όλες οι αλιείες. <strong>Σεπτέμβριος-Οκτώβριος:</strong> ιδανικός — οι τιμές πέφτουν 10-20% μετά τη σεζόν, ποιότητα ίδια. <strong>Αύγουστος Σαββατοκύριακα:</strong> κράτηση συνιστάται 1-2 ημέρες πριν, ειδικά για ώρες 21:00-22:30.</p>`, en: `<h2>When to visit</h2><p><strong>Fresh fish year-round</strong> — but the best variety is April-October when all fisheries operate. <strong>September-October:</strong> ideal — prices drop 10-20% after the season, quality identical. <strong>August weekends:</strong> book 1-2 days ahead, especially for 21:00-22:30 slots.</p>`, de: `<h2>Wann man reisen sollte</h2><p><strong>Frischer Fisch das ganze Jahr über</strong> — aber die beste Auswahl gibt es von April bis Oktober, wenn alle Fischereien in Betrieb sind. <strong>September-Oktober:</strong> ideal — die Preise fallen nach der Saison um 10-20%, die Qualität bleibt gleich. <strong>August Wochenenden:</strong> Reservierung 1-2 Tage im Voraus empfohlen, besonders für die Zeiten 21:00-22:30 Uhr.</p>`, ro: `<h2>Când să mergi</h2><p><strong>Pește proaspăt tot anul</strong> — dar cea mai bună varietate din aprilie până în octombrie, când toate pescăriile sunt deschise. <strong>Septembrie-octombrie:</strong> ideal — prețurile scad cu 10-20% după sezon, calitatea rămâne aceeași. <strong>Weekend-urile din august:</strong> rezervarea este recomandată cu 1-2 zile înainte, mai ales pentru orele 21:00-22:30.</p>`, sr: `<h2>Kada posetiti</h2><p><strong>Sveža riba tokom cele godine</strong> — ali najbolja raznovrsnost od aprila do oktobra kada sve ribarske aktivnosti funkcionišu. <strong>Septembar-oktobar:</strong> idealno — cene padaju 10-20% nakon sezone, kvalitet isti. <strong>Avgust vikendi:</strong> preporučuje se rezervacija 1-2 dana unapred, posebno za termine 21:00-22:30.</p>`, bg: `<h2>Кога да отидете</h2><p><strong>Прясна риба през цялата година</strong> — но най-добро разнообразие от април до октомври, когато работят всички риболови. <strong>Септември-октомври:</strong> идеално — цените падат с 10-20% след сезона, качеството е същото. <strong>Август уикенди:</strong> резервация се препоръчва 1-2 дни предварително, особено за часове 21:00-22:30.</p>`, ru: `<h2>Когда ехать</h2><p><strong>Свежая рыба круглый год</strong> — но лучший выбор с апреля по октябрь, когда работают все рыболовные хозяйства. <strong>Сентябрь-октябрь:</strong> идеальное время — цены падают на 10-20% после сезона, качество остается прежним. <strong>Август, выходные:</strong> рекомендуется бронирование за 1-2 дня, особенно на время с 21:00 до 22:30.</p>` },
    tips: { el: `<h2>Συμβουλές για ψαροφαγία</h2><ul><li><strong>Φρέσκο vs κατεψυγμένο:</strong> Ρώτα ρητά "fresh ή frozen?". Καλές ταβέρνες απαντούν ειλικρινά. Το φρέσκο τιμολογείται με το κιλό, το κατεψυγμένο με τη μερίδα.</li><li><strong>Τιμή ψαριού:</strong> €35-60/κιλό για φρέσκο. Διάλεγε ολόκληρο ψάρι και ζύγισέ το μαζί με τον σερβιτόρο.</li><li><strong>Μύδια:</strong> Από τα μύδια Καλλίστης, τοπική παραγωγή — εξαιρετική ποιότητα. Δοκίμασε αχνιστά ή κρασάτα.</li><li><strong>Χταπόδι ψητό:</strong> Σχεδόν παντού καλό. Καλά ψημένο πρέπει να είναι τραγανό απ'έξω, μαλακό μέσα.</li><li><strong>Συνοδευτικά:</strong> Με ψάρι ντόπιο λευκό κρασί (Μαλαγουζιά, Ασύρτικο Σιθωνίας) ή τσίπουρο.</li><li><strong>Καλύτερες περιοχές για ψαροφαγία:</strong> Νέα Μουδανιά, Πυργαδίκια, Σάρτη, Ποσείδι.</li></ul>`, en: `<h2>Seafood-eating tips</h2><ul><li><strong>Fresh vs frozen:</strong> Ask explicitly "fresh or frozen?". Good tavernas answer honestly. Fresh is priced per kilo, frozen per portion.</li><li><strong>Fish price:</strong> €35-60/kg for fresh. Pick a whole fish and weigh it with the waiter.</li><li><strong>Mussels:</strong> From Kallisti mussel farms, local production — excellent quality. Try them steamed or wine-braised.</li><li><strong>Grilled octopus:</strong> Almost always good. Properly grilled means crispy outside, tender inside.</li><li><strong>Pairings:</strong> Local white wine (Malagouzia, Sithonia Assyrtiko) or tsipouro with fish.</li><li><strong>Best seafood areas:</strong> Nea Moudania, Pyrgadikia, Sarti, Possidi.</li></ul>`, de: `<h2>Tipps für den Fischgenuss</h2><ul><li><strong>Frisch vs. gefroren:</strong> Frage ausdrücklich "frisch oder gefroren?". Gute Tavernen antworten ehrlich. Frischer Fisch wird nach Kilo berechnet, gefrorener nach Portion.</li><li><strong>Fischpreis:</strong> €35-60/Kilo für frischen Fisch. Wähle einen ganzen Fisch und wiege ihn zusammen mit dem Kellner.</li><li><strong>Muscheln:</strong> Von den Kallisti-Muscheln, lokale Produktion — hervorragende Qualität. Probiere sie gedünstet oder in Wein.</li><li><strong>Gegrillter Oktopus:</strong> Fast überall gut. Gut gegrillt sollte er außen knusprig und innen weich sein.</li><li><strong>Beilagen:</strong> Mit Fisch einheimischer Weißwein (Malagousia, Assyrtiko aus Sithonia) oder Tsipouro.</li><li><strong>Beste Gebiete für Fischgenuss:</strong> Nea Moudania, Pyrgadikia, Sarti, Possidi.</li></ul>`, ro: `<h2>Sfaturi pentru consumul de pește</h2><ul><li><strong>Proaspăt vs congelat:</strong> Întreabă clar "proaspăt sau congelat?". Tavernele bune răspund sincer. Peștele proaspăt este tarifat la kilogram, cel congelat la porție.</li><li><strong>Prețul peștelui:</strong> €35-60/kg pentru pește proaspăt. Alege un pește întreg și cântărește-l împreună cu chelnerul.</li><li><strong>Midii:</strong> Din midiile Kallisti, producție locală — calitate excelentă. Încearcă-le aburite sau cu vin.</li><li><strong>Caracatiță la grătar:</strong> Aproape peste tot este bună. Bine gătită trebuie să fie crocantă la exterior, moale în interior.</li><li><strong>Garnituri:</strong> Cu pește, vin alb local (Malagouzia, Assyrtiko din Sithonia) sau tsipouro.</li><li><strong>Cele mai bune zone pentru consumul de pește:</strong> Nea Moudania, Pyrgadikia, Sarti, Possidi.</li></ul>`, sr: `<h2>Saveti za uživanje u ribi</h2><ul><li><strong>Sveže vs zamrznuto:</strong> Pitaj izričito "fresh ili frozen?". Dobre taverne odgovaraju iskreno. Sveže se naplaćuje po kilogramu, zamrznuto po porciji.</li><li><strong>Cena ribe:</strong> €35-60/kg za svežu. Odaberi celu ribu i izmeri je zajedno sa konobarom.</li><li><strong>Školjke:</strong> Od školjki Kallistis, lokalna proizvodnja — izuzetnog kvaliteta. Probaj kuvane na pari ili u vinu.</li><li><strong>Pečena hobotnica:</strong> Skoro svuda dobra. Dobro pečena treba da bude hrskava spolja, mekana iznutra.</li><li><strong>Prilozi:</strong> Uz ribu lokalno belo vino (Malagouzia, Asyrtiko Sithonias) ili tsipouro.</li><li><strong>Najbolje oblasti za uživanje u ribi:</strong> Nea Moudania, Pyrgadikia, Sarti, Possidi.</li></ul>`, bg: `<h2>Съвети за рибна храна</h2><ul><li><strong>Прясно срещу замразено:</strong> Питайте изрично "fresh или frozen?". Добрите таверни отговарят честно. Прясното се ценообразува на килограм, замразеното на порция.</li><li><strong>Цена на рибата:</strong> €35-60/килограм за прясна. Избирайте цяла риба и я претеглете заедно със сервитьора.</li><li><strong>Миди:</strong> От миди Калистис, местно производство — изключително качество. Опитайте задушени или с вино.</li><li><strong>Печен октопод:</strong> Почти навсякъде добър. Добре изпечен трябва да е хрупкав отвън, мек отвътре.</li><li><strong>Гарнитури:</strong> С риба местно бяло вино (Малагузия, Асиртико Ситония) или ципуро.</li><li><strong>Най-добри райони за рибна храна:</strong> Неа Мудания, Пиргадикия, Сарти, Посиди.</li></ul>`, ru: `<h2>Советы по рыбной кухне</h2><ul><li><strong>Свежая vs замороженная:</strong> Спрашивайте прямо "fresh или frozen?". Хорошие таверны отвечают честно. Свежая рыба оценивается по килограмму, замороженная — по порции.</li><li><strong>Цена рыбы:</strong> €35-60/кг за свежую. Выбирайте целую рыбу и взвешивайте ее вместе с официантом.</li><li><strong>Мидии:</strong> Из мидий Каллисти, местного производства — отличное качество. Попробуйте на пару или в вине.</li><li><strong>Жареный осьминог:</strong> Почти везде хороший. Хорошо приготовленный должен быть хрустящим снаружи, мягким внутри.</li><li><strong>Сопровождение:</strong> С рыбой местное белое вино (Малагузья, Ассиртико Ситонии) или ципуро.</li><li><strong>Лучшие районы для рыбной кухни:</strong> Неа Мудания, Пиргадикия, Сарти, Посиди.</li></ul>` },
    faqs: [
      { q: { el: `Πόσο κοστίζει ένα γεύμα για 2 άτομα;`, en: `How much does a meal for 2 cost?`, de: `Wie viel kostet eine Mahlzeit für 2 Personen?`, ro: `Cât costă o masă pentru 2 persoane?`, sr: `Koliko košta obrok za 2 osobe?`, bg: `Колко струва едно ястие за 2 души?`, ru: `Сколько стоит обед на 2 человек?` }, a: { el: `Με <strong>ορεκτικά + ένα ψάρι ~600g + κρασί</strong> για 2 άτομα: €60-100 σε ταβέρνα μέσης κατηγορίας, €80-130 σε premium. Με χταπόδι/καλαμάρι/μύδια: €40-70.`, en: `With <strong>starters + one ~600g fish + wine</strong> for 2 people: €60-100 at a mid-range taverna, €80-130 at a premium one. With octopus/squid/mussels: €40-70.`, de: `Mit <strong>Vorspeisen + einem Fisch ~600g + Wein</strong> für 2 Personen: €60-100 in einer mittelklassigen Taverne, €80-130 in einer Premium-Taverne. Mit Oktopus/Kalamari/Muscheln: €40-70.`, ro: `Cu <strong>aperitive + un pește ~600g + vin</strong> pentru 2 persoane: €60-100 într-o tavernă de categorie medie, €80-130 în una premium. Cu caracatiță/calamari/midii: €40-70.`, sr: `Sa <strong>predjelima + jednom ribom ~600g + vinom</strong> za 2 osobe: €60-100 u taverni srednje kategorije, €80-130 u premium. Sa hobotnicom/lignjama/školjkama: €40-70.`, bg: `С <strong>предястия + една риба ~600г + вино</strong> за 2 души: €60-100 в средна категория таверна, €80-130 в премиум. С октопод/калмари/миди: €40-70.`, ru: `С <strong>закусками + одной рыбой ~600г + вином</strong> для 2 человек: €60-100 в таверне среднего класса, €80-130 в премиум. С осьминогом/кальмарами/мидиями: €40-70.` } },
      { q: { el: `Πού να φάω φρέσκα ψάρια στη Σιθωνία;`, en: `Where to eat fresh fish in Sithonia?`, de: `Wo kann ich frischen Fisch in Sithonia essen?`, ro: `Unde să mănânc pește proaspăt în Sithonia?`, sr: `Gde jesti svežu ribu u Sitoniji?`, bg: `Къде да ям прясна риба в Ситония?`, ru: `Где поесть свежую рыбу в Ситонии?` }, a: { el: `<strong>Σάρτη</strong> για ψαροταβέρνες στο λιμανάκι. <strong>Πυργαδίκια</strong> για παραδοσιακές καλόγουστες ταβέρνες με θέα. <strong>Βουρβουρού</strong> για πιο cosmopolitan επιλογές. Δες όλες σε αυτή τη λίστα.`, en: `<strong>Sarti</strong> for harbourside seafood tavernas. <strong>Pyrgadikia</strong> for traditional, well-priced tavernas with a view. <strong>Vourvourou</strong> for more cosmopolitan options. See them all in this list.`, de: `<strong>Sarti</strong> für Fisch-Tavernen am kleinen Hafen. <strong>Pyrgadikia</strong> für traditionelle, geschmackvolle Tavernen mit Aussicht. <strong>Vourvourou</strong> für kosmopolitischere Optionen. Sieh dir alle in dieser Liste an.`, ro: `<strong>Sarti</strong> pentru tavernele de pește din micul port. <strong>Pyrgadikia</strong> pentru taverne tradiționale cu gust și vedere. <strong>Vourvourou</strong> pentru opțiuni mai cosmopolite. Vezi toate în această listă.`, sr: `<strong>Sarti</strong> za riblje taverne u maloj luci. <strong>Pyrgadikia</strong> za tradicionalne ukusne taverne s pogledom. <strong>Vourvourou</strong> za kosmopolitske opcije. Pogledaj sve na ovoj listi.`, bg: `<strong>Сарти</strong> за рибни таверни в малкото пристанище. <strong>Пиргадикия</strong> за традиционни стилни таверни с изглед. <strong>Вурвуру</strong> за по-космополитни избори. Вижте всички в този списък.`, ru: `<strong>Сарти</strong> для рыбных таверн в порту. <strong>Пиргадикия</strong> для традиционных стильных таверн с видом. <strong>Вурвуру</strong> для более космополитичных вариантов. Смотрите все в этом списке.` } },
      { q: { el: `Είναι όλα τα ψάρια ντόπια;`, en: `Are all fish local?`, de: `Sind alle Fische lokal?`, ro: `Sunt toate peștele locale?`, sr: `Da li su sve ribe lokalne?`, bg: `Всички риби ли са местни?`, ru: `Вся ли рыба местная?` }, a: { el: `Όχι όλα. Τοπικά: τσιπούρα, λαβράκι, κουτσομούρα, σαρδέλα, μύδια Καλλίστης. Συχνά εισαγόμενο: σολομός, αχινός, μπακαλιάρος. Καλές ταβέρνες σημειώνουν την προέλευση στο μενού.`, en: `No, not all of them. Local: sea bream, sea bass, red mullet, sardine, Kallisti mussels. Often imported: salmon, sea urchin, cod. Good tavernas label provenance on the menu.`, de: `Nicht alle. Lokal: Dorade, Wolfsbarsch, Rotbarbe, Sardine, Kallisti-Muscheln. Häufig importiert: Lachs, Seeigel, Kabeljau. Gute Tavernen geben die Herkunft auf der Speisekarte an.`, ro: `Nu toate. Locale: doradă, biban, barbun, sardine, midii Kallisti. Adesea importate: somon, arici de mare, cod. Tavernele bune menționează originea în meniu.`, sr: `Ne sve. Lokalno: orada, brancin, barbun, sardina, školjke Kallistis. Često uvozno: losos, morski jež, bakalar. Dobre taverne navode poreklo na meniju.`, bg: `Не всички. Местни: ципура, лаврак, кутсомура, сардина, миди Калистис. Често вносни: сьомга, морски таралеж, треска. Добрите таверни отбелязват произхода в менюто.`, ru: `Не вся. Местные: дорада, сибас, барабулька, сардина, мидии Каллисти. Часто импортируемые: лосось, морской еж, треска. Хорошие таверны указывают происхождение в меню.` } },
      { q: { el: `Χρειάζομαι κράτηση;`, en: `Do I need a reservation?`, de: `Brauche ich eine Reservierung?`, ro: `Am nevoie de rezervare?`, sr: `Da li je potrebna rezervacija?`, bg: `Трябва ли ми резервация?`, ru: `Нужна ли бронь?` }, a: { el: `Σε peak season (Ιούλιος-Αύγουστος) Σαββατοκύριακα ναι, ειδικά για παραθαλάσσιες θέσεις σε γνωστές ταβέρνες. Λοιπές ημέρες/μήνες συνήθως όχι.`, en: `In peak season (July-August) weekends yes, especially for seafront tables at popular tavernas. Other days/months usually not.`, de: `In der Hochsaison (Juli-August) an Wochenenden ja, besonders für Plätze am Meer in bekannten Tavernen. An anderen Tagen/Monaten normalerweise nicht.`, ro: `În sezonul de vârf (iulie-august) în weekend-uri da, mai ales pentru locuri pe malul mării în taverne cunoscute. În restul zilelor/lunilor, de obicei nu.`, sr: `U špicu sezone (jul-avgust) vikendima da, posebno za mesta uz more u poznatim tavernama. Ostali dani/meseci obično ne.`, bg: `В пиковия сезон (юли-август) уикендите да, особено за крайбрежни места в известни таверни. Останалите дни/месеци обикновено не.`, ru: `В пиковый сезон (июль-август) в выходные да, особенно для мест у моря в известных тавернах. В остальные дни/месяцы обычно нет.` } },
    ],
  },
  "beach-bars": {
    intro: { el: `<p>Τα beach bars της Χαλκιδικής είναι από τα πιο εξελιγμένα στη βόρεια Ελλάδα. Πέρα από έναν απλό χώρο για cocktail κάτω από την ομπρέλα, πολλά λειτουργούν ως πλήρη day-to-night destinations: ξεκινούν με coffee και smoothies στις 9 το πρωί, σερβίρουν μεσημεριανό από καλά μενού, αλλάζουν σε beach party με DJs τα απογεύματα, και κλείνουν με sunset cocktails ή ολονύκτια events. Η Κασσάνδρα (κυρίως Καλλιθέα, Χανιώτη, Πευκοχώρι) έχει τα πιο πολυσύχναστα και κοσμοπολίτικα — η Σιθωνία (Βουρβουρού, Νικήτη) πιο χαλαρά αλλά εξίσου ποιοτικά. Αυτή η λίστα συγκεντρώνει τα beach bars με υψηλότερες αξιολογήσεις, βάσει εμπειρίας επισκεπτών μας.</p>`, en: `<p>Halkidiki's beach bars are some of the most evolved in northern Greece. Beyond just a place for a cocktail under an umbrella, many run as full day-to-night destinations: opening with coffee and smoothies at 9 AM, serving solid lunch menus, switching to beach parties with DJs in the afternoon, and closing with sunset cocktails or late-night events. Kassandra (mainly Kallithea, Hanioti, Pefkochori) has the most popular, cosmopolitan venues — Sithonia (Vourvourou, Nikiti) is more relaxed but equally high quality. This list collects beach bars with the highest visitor ratings.</p>`, de: `<p>Die Beach Bars in Chalkidiki gehören zu den fortschrittlichsten in Nordgriechenland. Abgesehen von einem einfachen Ort für Cocktails unter dem Sonnenschirm, fungieren viele als vollständige Day-to-Night-Destinationen: Sie beginnen mit Kaffee und Smoothies um 9 Uhr morgens, servieren Mittagessen von guten Menüs, verwandeln sich nachmittags in Beachpartys mit DJs und schließen mit Sunset-Cocktails oder nächtlichen Events. Kassandra (hauptsächlich Kallithea, Chanioti, Pefkochori) hat die belebtesten und kosmopolitischsten — Sithonia (Vourvourou, Nikiti) ist entspannter, aber ebenso qualitativ. Diese Liste fasst die Beach Bars mit den höchsten Bewertungen basierend auf den Erfahrungen unserer Besucher zusammen.</p>`, ro: `<p>Beach barurile din Halkidiki sunt printre cele mai dezvoltate din nordul Greciei. Dincolo de a fi un simplu loc pentru cocktailuri sub umbrelă, multe funcționează ca destinații complete de zi și noapte: încep cu cafea și smoothie-uri la 9 dimineața, servesc prânzul din meniuri bune, se transformă în petreceri pe plajă cu DJ după-amiaza și se încheie cu cocktailuri la apus sau evenimente nocturne. Kassandra (în special Kallithea, Hanioti, Pefkochori) are cele mai aglomerate și cosmopolite — Sithonia (Vourvourou, Nikiti) mai relaxate, dar la fel de calitative. Această listă reunește beach barurile cu cele mai bune evaluări, pe baza experiențelor vizitatorilor noștri.</p>`, sr: `<p>Beach barovi u Halkidikiju su među najrazvijenijima u severnoj Grčkoj. Osim što su jednostavno mesto za koktel ispod suncobrana, mnogi funkcionišu kao potpune destinacije od jutra do večeri: počinju sa kafom i smutijima u 9 ujutru, služe ručak sa dobrim menijima, popodne se pretvaraju u beach party sa DJ-evima, a završavaju sa koktelima uz zalazak sunca ili celonoćnim događajima. Kasandra (posebno Kallithea, Hanioti, Pefkochori) ima najprometnije i najkosmopolitskije — Sitonija (Vourvourou, Nikiti) je opuštenija, ali jednako kvalitetna. Ova lista okuplja beach barove sa najvišim ocenama, na osnovu iskustava naših posetilaca.</p>`, bg: `<p>Beach bar-овете на Халкидики са едни от най-развитите в северна Гърция. Освен че предлагат коктейли под чадъра, много от тях функционират като пълни day-to-night дестинации: започват с кафе и смутита в 9 сутринта, сервират обяд от добри менюта, преминават в beach party с DJ следобедите и завършват със залезни коктейли или целонощни събития. Касандра (главно Калитея, Ханиоти, Пефкохори) има най-оживените и космополитни — Ситония (Вурвуру, Никити) е по-спокойна, но също толкова качествена. Този списък събира beach bar-овете с най-високи оценки, базирани на опита на нашите посетители.</p>`, ru: `<p>Beach bars Халкидики — одни из самых продвинутых в северной Греции. Помимо простого места для коктейля под зонтиком, многие из них функционируют как полноценные day-to-night направления: начинают с кофе и смузи в 9 утра, подают обед по хорошему меню, превращаются в пляжные вечеринки с диджеями по вечерам и завершают день коктейлями на закате или ночными мероприятиями. Кассандра (в основном Каллифея, Ханиоти, Пефкохори) имеет самые оживленные и космополитичные — Ситония (Вурвуру, Никити) более расслабленные, но не менее качественные. Этот список собирает beach bars с самыми высокими оценками на основе опыта наших посетителей.</p>` },
    seasonal: { el: `<h2>Πότε να πας</h2><p><strong>Πρωί 9:00-12:00:</strong> Brunch + φρουτοχυμοί, ηρεμία, καλό για couples ή solo travelers. <strong>Μεσημέρι 13:00-16:00:</strong> Lunch, λίγος κόσμος. <strong>17:00-20:00:</strong> Cocktail hour με DJ, peak ατμόσφαιρας. <strong>20:00 και μετά:</strong> Είτε relax mode (Σιθωνία) είτε party mode (Κασσάνδρα Σαββατοκύριακα). <strong>Σεζόν:</strong> Μάιος-Σεπτέμβριος. Τα μεγαλύτερα beach clubs ανοίγουν Ιούνιο και κλείνουν στις 20-25 Σεπτεμβρίου.</p>`, en: `<h2>When to visit</h2><p><strong>Morning 9:00-12:00:</strong> Brunch + fresh juices, quieter, good for couples or solo travellers. <strong>Midday 13:00-16:00:</strong> Lunch, fewer crowds. <strong>17:00-20:00:</strong> Cocktail hour with a DJ, peak atmosphere. <strong>20:00 onwards:</strong> Either relax mode (Sithonia) or party mode (Kassandra weekends). <strong>Season:</strong> May-September. The bigger beach clubs open in June and close around September 20-25.</p>`, de: `<h2>Wann man gehen sollte</h2><p><strong>Morgens 9:00-12:00:</strong> Brunch + Fruchtsäfte, Ruhe, gut für Paare oder Alleinreisende. <strong>Mittag 13:00-16:00:</strong> Mittagessen, wenig Leute. <strong>17:00-20:00:</strong> Cocktailstunde mit DJ, Höhepunkt der Atmosphäre. <strong>20:00 und später:</strong> Entweder Relax-Modus (Sithonia) oder Party-Modus (Kassandra an Wochenenden). <strong>Saison:</strong> Mai-September. Die größten Beach Clubs öffnen im Juni und schließen am 20.-25. September.</p>`, ro: `<h2>Când să mergi</h2><p><strong>Dimineața 9:00-12:00:</strong> Brunch + sucuri de fructe, liniște, bun pentru cupluri sau călători singuri. <strong>Prânz 13:00-16:00:</strong> Prânz, puțină lume. <strong>17:00-20:00:</strong> Ora de cocktailuri cu DJ, atmosferă de vârf. <strong>20:00 și după:</strong> Fie mod relaxare (Sithonia) fie mod petrecere (Kassandra în weekenduri). <strong>Sezon:</strong> Mai-Septembrie. Cele mai mari beach cluburi se deschid în iunie și se închid între 20-25 septembrie.</p>`, sr: `<h2>Kada posetiti</h2><p><strong>Jutro 9:00-12:00:</strong> Brunch + voćni sokovi, mirno, dobro za parove ili solo putnike. <strong>Podne 13:00-16:00:</strong> Ručak, malo ljudi. <strong>17:00-20:00:</strong> Sat koktela sa DJ-em, vrhunac atmosfere. <strong>20:00 i kasnije:</strong> Ili opušteni mod (Sitonija) ili party mod (Kasandra vikendom). <strong>Sezona:</strong> Maj-septembar. Najveći beach klubovi otvaraju u junu i zatvaraju se 20-25. septembra.</p>`, bg: `<h2>Кога да отидете</h2><p><strong>Сутрин 9:00-12:00:</strong> Брънч + плодови сокове, спокойствие, подходящо за двойки или соло пътешественици. <strong>Обед 13:00-16:00:</strong> Обяд, малко хора. <strong>17:00-20:00:</strong> Час за коктейли с DJ, пик на атмосферата. <strong>20:00 и след това:</strong> Или режим релакс (Ситония) или парти режим (Касандра през уикендите). <strong>Сезон:</strong> Май-септември. Най-големите beach клубове отварят през юни и затварят на 20-25 септември.</p>`, ru: `<h2>Когда поехать</h2><p><strong>Утро 9:00-12:00:</strong> Бранч + фруктовые соки, спокойствие, подходит для пар или одиночных путешественников. <strong>День 13:00-16:00:</strong> Обед, немного людей. <strong>17:00-20:00:</strong> Час коктейлей с диджеем, пик атмосферы. <strong>20:00 и позже:</strong> Либо режим релакса (Ситония), либо режим вечеринки (Кассандра по выходным). <strong>Сезон:</strong> Май-сентябрь. Крупные beach clubs открываются в июне и закрываются 20-25 сентября.</p>` },
    tips: { el: `<h2>Συμβουλές</h2><ul><li><strong>Κράτηση sun bed:</strong> Στα δημοφιλή beach clubs (κυρίως Κασσάνδρα), online κράτηση 1-2 μέρες πριν για Σαββατοκύριακα. Premium σετ €30-60/μέρα για 2.</li><li><strong>Dress code:</strong> Καθαρό beachwear το μεσημέρι, smart casual μετά τις 19:00. Πολλά δεν αφήνουν φόρμα φλιπ-φλοπ μετά τις 21:00.</li><li><strong>Παιδιά:</strong> Πολλά beach bars είναι family-friendly μέχρι τις 18:00. Μετά γίνονται adult-only ατμόσφαιρας.</li><li><strong>Pricing:</strong> Cocktail €8-14, beer €5-7. Συνήθως service fee 10% περιλαμβάνεται.</li><li><strong>Δείτε επίσης:</strong> <a href="/best/romantic-restaurants">Ρομαντικά εστιατόρια</a> για μετά το beach bar dinner.</li></ul>`, en: `<h2>Tips</h2><ul><li><strong>Sun-bed reservation:</strong> At popular beach clubs (mainly Kassandra), book online 1-2 days ahead for weekends. Premium sets €30-60/day for two.</li><li><strong>Dress code:</strong> Clean beachwear at midday, smart-casual after 19:00. Many won't let flip-flops in after 21:00.</li><li><strong>Kids:</strong> Many beach bars are family-friendly until 18:00. After that they shift to an adult-only vibe.</li><li><strong>Pricing:</strong> Cocktail €8-14, beer €5-7. A 10% service fee is usually included.</li><li><strong>See also:</strong> <a href="/best/romantic-restaurants">Romantic restaurants</a> for the post-beach-bar dinner.</li></ul>`, de: `<h2>Tipps</h2><ul><li><strong>Reservierung von Sonnenliegen:</strong> In den beliebten Beach Clubs (hauptsächlich Kassandra) Online-Reservierung 1-2 Tage vorher für Wochenenden. Premium-Set €30-60/Tag für 2 Personen.</li><li><strong>Kleiderordnung:</strong> Saubere Strandkleidung am Mittag, smart casual nach 19:00 Uhr. Viele erlauben nach 21:00 Uhr keine Flip-Flops mehr.</li><li><strong>Kinder:</strong> Viele Beach Bars sind familienfreundlich bis 18:00 Uhr. Danach wird die Atmosphäre nur für Erwachsene.</li><li><strong>Preise:</strong> Cocktail €8-14, Bier €5-7. In der Regel ist eine Servicegebühr von 10% enthalten.</li><li><strong>Siehe auch:</strong> <a href="/best/romantic-restaurants">Romantische Restaurants</a> für nach dem Beach Bar Dinner.</li></ul>`, ro: `<h2>Sfaturi</h2><ul><li><strong>Rezervare sun bed:</strong> La beach cluburile populare (în special Kassandra), rezervare online cu 1-2 zile înainte pentru weekenduri. Set premium €30-60/zi pentru 2 persoane.</li><li><strong>Cod vestimentar:</strong> Îmbrăcăminte de plajă curată la prânz, smart casual după ora 19:00. Multe nu permit flip-flops după ora 21:00.</li><li><strong>Copii:</strong> Multe beach baruri sunt prietenoase cu familiile până la ora 18:00. După devin cu atmosferă doar pentru adulți.</li><li><strong>Preturi:</strong> Cocktail €8-14, bere €5-7. De obicei, taxa de serviciu de 10% este inclusă.</li><li><strong>Vezi de asemenea:</strong> <a href="/best/romantic-restaurants">Restaurante romantice</a> pentru după cina la beach bar.</li></ul>`, sr: `<h2>Saveti</h2><ul><li><strong>Rezervacija ležaljki:</strong> U popularnim beach klubovima (posebno Kasandra), online rezervacija 1-2 dana unapred za vikende. Premium set €30-60/dan za 2 osobe.</li><li><strong>Dress code:</strong> Čista odeća za plažu u podne, smart casual posle 19:00. Mnogi ne dozvoljavaju flip-flop posle 21:00.</li><li><strong>Deca:</strong> Mnogi beach barovi su porodično-prijateljski do 18:00. Posle toga postaju atmosfera samo za odrasle.</li><li><strong>Cene:</strong> Koktel €8-14, pivo €5-7. Obično je uključena usluga od 10%.</li><li><strong>Pogledajte takođe:</strong> <a href="/best/romantic-restaurants">Romantični restorani</a> za posle večere u beach baru.</li></ul>`, bg: `<h2>Съвети</h2><ul><li><strong>Резервация на шезлонг:</strong> В популярните beach клубове (главно Касандра), онлайн резервация 1-2 дни предварително за уикендите. Премиум комплект €30-60/ден за 2-ма.</li><li><strong>Дрескод:</strong> Чисто плажно облекло на обяд, smart casual след 19:00. Много не допускат джапанки след 21:00.</li><li><strong>Деца:</strong> Много beach bar-ове са подходящи за семейства до 18:00. След това стават за възрастни.</li><li><strong>Цени:</strong> Коктейл €8-14, бира €5-7. Обикновено такса за обслужване 10% е включена.</li><li><strong>Вижте също:</strong> <a href="/best/romantic-restaurants">Романтични ресторанти</a> за след вечеря в beach bar.</li></ul>`, ru: `<h2>Советы</h2><ul><li><strong>Бронирование шезлонга:</strong> В популярных beach clubs (особенно Кассандра) онлайн-бронирование за 1-2 дня до выходных. Премиум-набор €30-60/день на двоих.</li><li><strong>Дресс-код:</strong> Чистая пляжная одежда днем, smart casual после 19:00. Многие не допускают шлепанцы после 21:00.</li><li><strong>Дети:</strong> Многие beach bars подходят для семей до 18:00. После этого они становятся атмосферой только для взрослых.</li><li><strong>Цены:</strong> Коктейль €8-14, пиво €5-7. Обычно включена плата за обслуживание 10%.</li><li><strong>Смотрите также:</strong> <a href="/best/romantic-restaurants">Романтические рестораны</a> для ужина после beach bar.</li></ul>` },
    faqs: [
      { q: { el: `Ποια είναι τα καλύτερα beach clubs στη Χαλκιδική;`, en: `Which are the best beach clubs in Halkidiki?`, de: `Welche sind die besten Beach Clubs in Chalkidiki?`, ro: `Care sunt cele mai bune beach cluburi din Halkidiki?`, sr: `Koji su najbolji beach klubovi u Halkidikiju?`, bg: `Кои са най-добрите beach клубове на Халкидики?`, ru: `Какие лучшие beach clubs в Халкидики?` }, a: { el: `Στην <strong>Καλλιθέα</strong> τα Cabana, Coco Beach Bar. Στη <strong>Χανιώτη</strong> τα Caribbean, Plaja. Στη <strong>Σιθωνία</strong> πιο χαλαρά αλλά ποιοτικά (Vourvourou area). Δες όλες τις τοποθεσίες σε αυτή τη λίστα — οι πραγματικές αξιολογήσεις των επισκεπτών είναι ο καλύτερος οδηγός.`, en: `In <strong>Kallithea</strong>: Cabana, Coco Beach Bar. In <strong>Hanioti</strong>: Caribbean, Plaja. In <strong>Sithonia</strong> more chilled but high quality (Vourvourou area). Browse all the listings — actual visitor ratings are the best guide.`, de: `In <strong>Kallithea</strong> die Cabana, Coco Beach Bar. In <strong>Chanioti</strong> die Caribbean, Plaja. In <strong>Sithonia</strong> entspannter, aber qualitativ (Vourvourou-Gegend). Sieh dir alle Standorte in dieser Liste an — die echten Bewertungen der Besucher sind der beste Leitfaden.`, ro: `În <strong>Kallithea</strong> sunt Cabana, Coco Beach Bar. În <strong>Hanioti</strong> sunt Caribbean, Plaja. În <strong>Sithonia</strong> mai relaxate, dar calitative (zona Vourvourou). Vezi toate locațiile din această listă — evaluările reale ale vizitatorilor sunt cel mai bun ghid.`, sr: `U <strong>Kallithei</strong> su Cabana, Coco Beach Bar. U <strong>Haniotiju</strong> su Caribbean, Plaja. U <strong>Sitoniji</strong> su opušteniji, ali kvalitetni (područje Vourvourou). Pogledajte sve lokacije na ovoj listi — stvarne ocene posetilaca su najbolji vodič.`, bg: `В <strong>Калитея</strong> са Cabana, Coco Beach Bar. В <strong>Ханиоти</strong> са Caribbean, Plaja. В <strong>Ситония</strong> по-спокойни, но качествени (район Вурвуру). Вижте всички локации в този списък — реалните оценки на посетителите са най-добрият гид.`, ru: `В <strong>Каллифее</strong> Cabana, Coco Beach Bar. В <strong>Ханиоти</strong> Caribbean, Plaja. В <strong>Ситонии</strong> более расслабленные, но качественные (район Вурвуру). Смотрите все локации в этом списке — реальные отзывы посетителей — лучший гид.` } },
      { q: { el: `Πληρώνω είσοδο σε beach club;`, en: `Do I pay an entrance fee at a beach club?`, de: `Zahle ich Eintritt in einem Beach Club?`, ro: `Plătesc intrare la un beach club?`, sr: `Da li plaćam ulaz u beach klub?`, bg: `Плащам ли вход в beach клуб?`, ru: `Нужно ли платить за вход в beach club?` }, a: { el: `Όχι entry fee σε καμία περίπτωση. Πληρώνεις για ξαπλώστρες/ομπρέλες και τις παραγγελίες σου. Σε ειδικά events ή Saturday parties μπορεί να ζητάνε reservation με minimum spend €40-80.`, en: `No entry fee in any case. You pay for loungers/umbrellas and your orders. For special events or Saturday parties, some venues require a reservation with a €40-80 minimum spend.`, de: `Nein, es gibt keine Eintrittsgebühr. Du zahlst für Liegen/Sonnenschirme und deine Bestellungen. Bei speziellen Events oder Samstagspartys kann eine Reservierung mit Mindestverzehr von €40-80 verlangt werden.`, ro: `Nu se percepe taxă de intrare în niciun caz. Plătești pentru șezlonguri/umbrele și comenzile tale. La evenimente speciale sau petreceri de sâmbătă pot solicita rezervare cu cheltuială minimă de €40-80.`, sr: `Ne postoji ulazna naknada ni u jednom slučaju. Plaćate za ležaljke/suncobrane i vaše porudžbine. Na posebnim događajima ili subotnjim žurkama može se tražiti rezervacija sa minimalnom potrošnjom od €40-80.`, bg: `Не, няма входна такса в никакъв случай. Плащате за шезлонги/чадъри и вашите поръчки. При специални събития или съботни партита може да изискват резервация с минимален разход €40-80.`, ru: `Нет, входной платы нет ни в коем случае. Вы платите за шезлонги/зонтики и свои заказы. На специальных мероприятиях или вечеринках по субботам может потребоваться бронирование с минимальной тратой €40-80.` } },
      { q: { el: `Πιο ωραίο Κασσάνδρα ή Σιθωνία για beach bars;`, en: `More fun: Kassandra or Sithonia for beach bars?`, de: `Ist Kassandra oder Sithonia besser für Beach Bars?`, ro: `Mai frumos Kassandra sau Sithonia pentru beach baruri?`, sr: `Šta je lepše, Kasandra ili Sitonija za beach barove?`, bg: `Кое е по-хубаво, Касандра или Ситония за beach bar-ове?`, ru: `Что лучше: Кассандра или Ситония для beach bars?` }, a: { el: `Διάλεξε <strong>Κασσάνδρα</strong> για high-energy, big-DJ atmosphere, parties. Διάλεξε <strong>Σιθωνία</strong> για χαλαρά cocktails, sunset, photography. Δες και τις <a href="/best/beaches-kassandra">καλύτερες παραλίες Κασσάνδρας</a> ή <a href="/best/beaches-sithonia">Σιθωνίας</a>.`, en: `Pick <strong>Kassandra</strong> for high-energy, big-DJ atmosphere and parties. Pick <strong>Sithonia</strong> for chilled cocktails, sunsets, photography. See the <a href="/best/beaches-kassandra">best beaches of Kassandra</a> or <a href="/best/beaches-sithonia">Sithonia</a>.`, de: `Wähle <strong>Kassandra</strong> für eine energiegeladene, große DJ-Atmosphäre und Partys. Wähle <strong>Sithonia</strong> für entspannte Cocktails, Sonnenuntergänge, Fotografie. Sieh dir auch die <a href="/best/beaches-kassandra">besten Strände von Kassandra</a> oder <a href="/best/beaches-sithonia">Sithonia</a> an.`, ro: `Alege <strong>Kassandra</strong> pentru atmosferă energică, DJ mari, petreceri. Alege <strong>Sithonia</strong> pentru cocktailuri relaxate, apus, fotografie. Vezi și <a href="/best/beaches-kassandra">cele mai bune plaje din Kassandra</a> sau <a href="/best/beaches-sithonia">Sithonia</a>.`, sr: `Izaberite <strong>Kasandru</strong> za energičnu atmosferu sa velikim DJ-evima, žurke. Izaberite <strong>Sitoniju</strong> za opuštene koktele, zalazak sunca, fotografiju. Pogledajte i <a href="/best/beaches-kassandra">najbolje plaže Kasandre</a> ili <a href="/best/beaches-sithonia">Sitonije</a>.`, bg: `Изберете <strong>Касандра</strong> за high-energy, големи DJ атмосфера, партита. Изберете <strong>Ситония</strong> за спокойни коктейли, залез, фотография. Вижте и <a href="/best/beaches-kassandra">най-добрите плажове на Касандра</a> или <a href="/best/beaches-sithonia">Ситония</a>.`, ru: `Выберите <strong>Кассандру</strong> для энергичной атмосферы с большими диджеями и вечеринками. Выберите <strong>Ситонию</strong> для расслабленных коктейлей, заката, фотографии. Также смотрите <a href="/best/beaches-kassandra">лучшие пляжи Кассандры</a> или <a href="/best/beaches-sithonia">Ситонии</a>.` } },
    ],
  },
  "romantic-restaurants": {
    intro: { el: `<p>Όταν ψάχνεις ρομαντικό δείπνο στη Χαλκιδική, ο σημαντικότερος παράγοντας είναι η <strong>θέα στη θάλασσα</strong> κατά το σούρουπο. Η ηπειρωτική γεωγραφία της Χαλκιδικής με τις τρεις χερσονήσους δημιουργεί φυσικά μοναδικά τοπία: εστιατόρια που κοιτάζουν τη μία χερσόνησο μπροστά τους ή τη μεγάλη λίμνη ανάμεσα στη Σιθωνία και τον Άθω. Αυτή η λίστα συγκεντρώνει εστιατόρια με προφίλ "sea view" από τη βάση μας — από κομψά rooftop restaurants σε boutique hotels μέχρι παραδοσιακές ταβέρνες σε γραφικά λιμανάκια. Όλα κερδίζουν πραγματικές αξιολογήσεις από couples που δοκίμασαν τις εμπειρίες αυτές.</p>`, en: `<p>When you're looking for a romantic dinner in Halkidiki, the most important factor is the <strong>sea view at sunset</strong>. Halkidiki's mainland geography with three peninsulas creates uniquely framed landscapes: restaurants looking out at the next peninsula or at the large lagoon between Sithonia and Athos. This list collects restaurants tagged with "sea view" in our database — from elegant rooftop restaurants in boutique hotels to traditional tavernas in picturesque little harbours. All earn real ratings from couples who tried the experience.</p>`, de: `<p>Wenn du ein romantisches Abendessen in Chalkidiki suchst, ist der wichtigste Faktor der <strong>Meerblick</strong> bei Sonnenuntergang. Die kontinentale Geografie von Chalkidiki mit ihren drei Halbinseln schafft einzigartige natürliche Landschaften: Restaurants, die auf eine der Halbinseln oder den großen See zwischen Sithonia und dem Berg Athos blicken. Diese Liste versammelt Restaurants mit "Meerblick"-Profilen aus unserer Datenbank — von eleganten Rooftop-Restaurants in Boutique-Hotels bis hin zu traditionellen Tavernen in malerischen kleinen Häfen. Alle erhalten echte Bewertungen von Paaren, die diese Erlebnisse ausprobiert haben.</p>`, ro: `<p>Când cauți o cină romantică în Halkidiki, cel mai important factor este <strong>vederea la mare</strong> la apus. Geografia continentală a Halkidiki-ului cu cele trei peninsule creează peisaje naturale unice: restaurante care privesc spre o peninsulă în față sau spre marea întindere de apă dintre Sithonia și Athos. Această listă adună restaurante cu profil "sea view" din baza noastră de date — de la restaurante elegante pe acoperișuri în hoteluri boutique până la taverne tradiționale în porturi pitorești. Toate primesc evaluări reale de la cupluri care au încercat aceste experiențe.</p>`, sr: `<p>Kada tražite romantičnu večeru u Halkidikiju, najvažniji faktor je <strong>pogled na more</strong> u sumrak. Kontinentalna geografija Halkidikija sa tri poluostrva stvara prirodno jedinstvene pejzaže: restorani koji gledaju na jedno poluostrvo ispred sebe ili na veliko jezero između Sitonije i Svete Gore. Ova lista okuplja restorane sa "pogledom na more" iz naše baze — od elegantnih rooftop restorana u butik hotelima do tradicionalnih taverni u slikovitim lukama. Svi dobijaju stvarne ocene od parova koji su iskusili ova iskustva.</p>`, bg: `<p>Когато търсиш романтична вечеря в Халкидики, най-важният фактор е <strong>гледката към морето</strong> по залез слънце. Континенталната география на Халкидики с трите полуострова създава уникални природни пейзажи: ресторанти, които гледат към един от полуостровите пред тях или към голямото езеро между Ситония и Света гора. Този списък събира ресторанти с профил "sea view" от нашата база данни — от елегантни rooftop ресторанти в бутикови хотели до традиционни таверни в живописни пристанища. Всички получават реални оценки от двойки, които са изпробвали тези преживявания.</p>`, ru: `<p>Когда ищешь романтический ужин на Халкидиках, самым важным фактором является <strong>вид на море</strong> на закате. Континентальная география Халкидики с тремя полуостровами создает уникальные природные пейзажи: рестораны, которые смотрят на один из полуостровов перед собой или на большое озеро между Ситонией и Афоном. Этот список собирает рестораны с профилем "sea view" из нашей базы данных — от элегантных ресторанов на крышах в бутик-отелях до традиционных таверн в живописных гаванях. Все они получают реальные отзывы от пар, которые испытали эти впечатления.</p>` },
    seasonal: { el: `<h2>Πότε να κρατήσεις</h2><p><strong>Σούρουπο:</strong> Σε όλα τα sea-view εστιατόρια, κράτηση για 19:30-20:30 το καλοκαίρι — βλέπεις το ηλιοβασίλεμα. Σεπτέμβριο νωρίτερα (18:30-19:30). <strong>Νεκρή ώρα:</strong> 16:00-18:00 αν θες απόλυτη ησυχία και πιθανώς open-bar specials. <strong>Νύχτα κάτω από τα αστέρια:</strong> 21:30+ ιδανικό αν δεν θες ζέστη.</p>`, en: `<h2>When to book</h2><p><strong>Sunset:</strong> At every sea-view restaurant, book for 19:30-20:30 in summer — you'll catch the sunset. In September, earlier (18:30-19:30). <strong>Quiet hour:</strong> 16:00-18:00 if you want total calm and possibly open-bar specials. <strong>Under the stars:</strong> 21:30+ ideal if you want to avoid the heat.</p>`, de: `<h2>Wann reservieren</h2><p><strong>Sonnenuntergang:</strong> In allen Restaurants mit Meerblick Reservierung für 19:30-20:30 im Sommer — du siehst den Sonnenuntergang. Im September früher (18:30-19:30). <strong>Ruhezeit:</strong> 16:00-18:00, wenn du absolute Ruhe und möglicherweise Open-Bar-Specials möchtest. <strong>Nacht unter den Sternen:</strong> Ab 21:30 ideal, wenn du keine Hitze möchtest.</p>`, ro: `<h2>Când să faci rezervare</h2><p><strong>Apus:</strong> La toate restaurantele cu vedere la mare, rezervă pentru 19:30-20:30 vara — vezi apusul. În septembrie mai devreme (18:30-19:30). <strong>Oră moartă:</strong> 16:00-18:00 dacă vrei liniște absolută și posibil open-bar specials. <strong>Noapte sub stele:</strong> 21:30+ ideal dacă nu vrei căldură.</p>`, sr: `<h2>Kada rezervisati</h2><p><strong>Sumrak:</strong> U svim restoranima sa pogledom na more, rezervacija za 19:30-20:30 leti — gledaš zalazak sunca. U septembru ranije (18:30-19:30). <strong>Mrtvo vreme:</strong> 16:00-18:00 ako želiš apsolutni mir i moguće open-bar specijale. <strong>Noć pod zvezdama:</strong> 21:30+ idealno ako ne želiš vrućinu.</p>`, bg: `<h2>Кога да резервираш</h2><p><strong>Залез:</strong> Във всички sea-view ресторанти, резервация за 19:30-20:30 през лятото — виждаш залеза. През септември по-рано (18:30-19:30). <strong>Мъртъв час:</strong> 16:00-18:00, ако искаш абсолютна тишина и възможни open-bar специалитети. <strong>Нощ под звездите:</strong> 21:30+ идеално, ако не искаш жега.</p>`, ru: `<h2>Когда бронировать</h2><p><strong>Закат:</strong> Во всех ресторанах с видом на море бронируйте на 19:30-20:30 летом — увидите закат. В сентябре раньше (18:30-19:30). <strong>Мертвое время:</strong> 16:00-18:00, если хотите абсолютной тишины и, возможно, специальные предложения open-bar. <strong>Ночь под звездами:</strong> 21:30+ идеально, если не хотите жары.</p>` },
    tips: { el: `<h2>Συμβουλές για ρομαντικό δείπνο</h2><ul><li><strong>Κράτηση εκ των προτέρων:</strong> 2-3 μέρες πριν για Σαββατοκύριακα Ιουλίου-Αυγούστου, ειδικά για θέσεις με την καλύτερη θέα.</li><li><strong>Ζητάς "outside terrace":</strong> Σε όσα έχουν επιλογές inside/outside, το terrace με sea view είναι το ζητούμενο.</li><li><strong>Bottle of wine:</strong> Επίλεξε ντόπιο λευκό (Μαλαγουζιά Σιθωνίας, Ασύρτικο Σαντορίνης) για να ταιριάζει με το ψάρι.</li><li><strong>Dress code:</strong> Smart casual συνήθως. Σε premium boutique restaurants συνιστάται πιο επιμελής.</li><li><strong>Special occasions:</strong> Ζητάς εκ των προτέρων για κάτι ξεχωριστό (κερί, λουλούδι στο τραπέζι, τούρτα γενεθλίων). Συνήθως δωρεάν.</li></ul>`, en: `<h2>Tips for a romantic dinner</h2><ul><li><strong>Book ahead:</strong> 2-3 days in advance for July-August weekends, especially for the best-view tables.</li><li><strong>Ask for the outside terrace:</strong> At venues with inside/outside options, the terrace with sea view is what you want.</li><li><strong>Bottle of wine:</strong> Pick a local white (Sithonia Malagouzia, Santorini Assyrtiko) to match the fish.</li><li><strong>Dress code:</strong> Smart casual usually. Premium boutique restaurants prefer something more polished.</li><li><strong>Special occasions:</strong> Ask in advance for something extra (candle, flower on the table, birthday cake). Usually free.</li></ul>`, de: `<h2>Tipps für ein romantisches Abendessen</h2><ul><li><strong>Im Voraus reservieren:</strong> 2-3 Tage vorher für Wochenenden im Juli-August, besonders für Plätze mit der besten Aussicht.</li><li><strong>Frage nach "Außenterrasse":</strong> In Restaurants mit Innen-/Außenoptionen ist die Terrasse mit Meerblick das Ziel.</li><li><strong>Flasche Wein:</strong> Wähle einen lokalen Weißwein (Malagousia aus Sithonia, Assyrtiko aus Santorini), um ihn mit Fisch zu kombinieren.</li><li><strong>Kleiderordnung:</strong> Meistens smart casual. In Premium-Boutique-Restaurants wird ein gepflegteres Outfit empfohlen.</li><li><strong>Besondere Anlässe:</strong> Frage im Voraus nach etwas Besonderem (Kerze, Blume auf dem Tisch, Geburtstagskuchen). Meistens kostenlos.</li></ul>`, ro: `<h2>Sfaturi pentru o cină romantică</h2><ul><li><strong>Rezervare în avans:</strong> 2-3 zile înainte pentru weekendurile din iulie-august, mai ales pentru locurile cu cea mai bună vedere.</li><li><strong>Cere "terasa exterioară":</strong> La cele care au opțiuni inside/outside, terasa cu vedere la mare este de dorit.</li><li><strong>Sticlă de vin:</strong> Alege un vin alb local (Malagouzia din Sithonia, Assyrtiko din Santorini) pentru a se potrivi cu peștele.</li><li><strong>Cod vestimentar:</strong> Smart casual de obicei. În restaurantele boutique premium se recomandă o ținută mai îngrijită.</li><li><strong>Ocazii speciale:</strong> Cere în avans pentru ceva special (lumânare, floare pe masă, tort de aniversare). De obicei gratuit.</li></ul>`, sr: `<h2>Saveti za romantičnu večeru</h2><ul><li><strong>Rezervacija unapred:</strong> 2-3 dana pre za vikende u julu-avgustu, posebno za mesta sa najboljim pogledom.</li><li><strong>Traži "spoljnu terasu":</strong> U onima koji imaju opcije unutra/spolja, terasa sa pogledom na more je ono što tražiš.</li><li><strong>Boca vina:</strong> Izaberi lokalno belo (Malaguzija Sitonije, Asirtiko Santorinija) da se slaže sa ribom.</li><li><strong>Dress code:</strong> Smart casual obično. U premium butik restoranima preporučuje se elegantniji izgled.</li><li><strong>Posebne prilike:</strong> Traži unapred za nešto posebno (sveća, cvet na stolu, torta za rođendan). Obično besplatno.</li></ul>`, bg: `<h2>Съвети за романтична вечеря</h2><ul><li><strong>Резервация предварително:</strong> 2-3 дни преди за уикендите през юли-август, особено за места с най-добрата гледка.</li><li><strong>Искай "външна тераса":</strong> В тези, които имат опции вътре/вън, терасата с гледка към морето е желаната.</li><li><strong>Бутилка вино:</strong> Избери местно бяло (Малагузия от Ситония, Асиртико от Санторини), за да съчетаеш с рибата.</li><li><strong>Дрескод:</strong> Обикновено smart casual. В премиум бутикови ресторанти се препоръчва по-елегантно облекло.</li><li><strong>Специални поводи:</strong> Искай предварително за нещо специално (свещ, цвете на масата, торта за рожден ден). Обикновено безплатно.</li></ul>`, ru: `<h2>Советы для романтического ужина</h2><ul><li><strong>Бронируйте заранее:</strong> за 2-3 дня до выходных в июле-августе, особенно для мест с лучшим видом.</li><li><strong>Просите "внешнюю террасу":</strong> В тех, где есть выбор внутри/снаружи, терраса с видом на море — это то, что нужно.</li><li><strong>Бутылка вина:</strong> Выберите местное белое (Малагузья Ситонии, Ассиртико Санторини), чтобы оно подходило к рыбе.</li><li><strong>Дресс-код:</strong> Обычно smart casual. В премиум бутик-ресторанах рекомендуется более тщательный.</li><li><strong>Особые случаи:</strong> Просите заранее что-то особенное (свеча, цветок на столе, торт на день рождения). Обычно бесплатно.</li></ul>` },
    faqs: [
      { q: { el: `Ποιο είναι το ρομαντικότερο εστιατόριο της Χαλκιδικής;`, en: `Which is the most romantic restaurant in Halkidiki?`, de: `Welches ist das romantischste Restaurant in Chalkidiki?`, ro: `Care este cel mai romantic restaurant din Halkidiki?`, sr: `Koji je najromantičniji restoran u Halkidikiju?`, bg: `Кой е най-романтичният ресторант в Халкидики?`, ru: `Какой самый романтичный ресторан на Халкидиках?` }, a: { el: `Δύσκολο να ξεχωρίσει ένα. Στη <strong>Βουρβουρού</strong> εξαιρετική θέα προς τα νησάκια. Στη <strong>Σάνη Marina</strong> ελεγμένα γαστρονομικά εστιατόρια. Στην <strong>Ουρανούπολη</strong> θέα στο Άγιο Όρος. Δες όλα τα sea-view εστιατόρια σε αυτή τη λίστα.`, en: `Hard to pick just one. <strong>Vourvourou</strong> has stunning views over the islets. <strong>Sani Marina</strong> features curated gastro restaurants. <strong>Ouranoupoli</strong> has Mount Athos views. Browse all sea-view restaurants in this list.`, de: `Schwer, sich auf eines festzulegen. In <strong>Vourvourou</strong> gibt es eine hervorragende Aussicht auf die Inseln. In der <strong>Sani Marina</strong> gibt es geprüfte gastronomische Restaurants. In <strong>Ouranoupoli</strong> hat man Blick auf den Berg Athos. Sieh dir alle Restaurants mit Meerblick in dieser Liste an.`, ro: `Este greu de ales unul singur. În <strong>Vourvourou</strong> priveliște excelentă spre insulițe. În <strong>Sani Marina</strong> restaurante gastronomice verificate. În <strong>Ouranoupoli</strong> vedere spre Muntele Athos. Vezi toate restaurantele cu vedere la mare în această listă.`, sr: `Teško je izdvojiti jedan. U <strong>Vurvuru</strong> izvanredan pogled ka ostrvcima. U <strong>Sani Marini</strong> provereni gastronomski restorani. U <strong>Uranopolisu</strong> pogled na Svetu Goru. Pogledaj sve restorane sa pogledom na more na ovoj listi.`, bg: `Трудно е да се отличи един. В <strong>Вурвуру</strong> има отлична гледка към островчетата. В <strong>Сани Марина</strong> проверени гастрономически ресторанти. В <strong>Урануполи</strong> гледка към Света гора. Виж всички sea-view ресторанти в този списък.`, ru: `Трудно выделить один. В <strong>Вурвуру</strong> отличный вид на островки. В <strong>Сани Марина</strong> проверенные гастрономические рестораны. В <strong>Урануполи</strong> вид на Афон. Смотрите все рестораны с видом на море в этом списке.` } },
      { q: { el: `Πόσο κοστίζει ρομαντικό δείπνο 2 ατόμων;`, en: `How much for a romantic dinner for two?`, de: `Wie viel kostet ein romantisches Abendessen für 2 Personen?`, ro: `Cât costă o cină romantică pentru 2 persoane?`, sr: `Koliko košta romantična večera za 2 osobe?`, bg: `Колко струва романтична вечеря за двама?`, ru: `Сколько стоит романтический ужин на двоих?` }, a: { el: `Mid-range: €60-100 (3-course + κρασί). Premium boutique: €100-180. Με ψάρι ολόκληρο ψυτό + premium κρασί: €150-250.`, en: `Mid-range: €60-100 (3-course + wine). Premium boutique: €100-180. With whole grilled fish + premium wine: €150-250.`, de: `Mittelklasse: €60-100 (3-Gänge-Menü + Wein). Premium-Boutique: €100-180. Mit ganzem gegrillten Fisch + Premium-Wein: €150-250.`, ro: `Mid-range: €60-100 (3 feluri + vin). Boutique premium: €100-180. Cu pește întreg la grătar + vin premium: €150-250.`, sr: `Srednji rang: €60-100 (3 jela + vino). Premium butik: €100-180. Sa celom pečenom ribom + premium vinom: €150-250.`, bg: `Среден клас: €60-100 (3-степенно меню + вино). Премиум бутикови: €100-180. С цяла печена риба + премиум вино: €150-250.`, ru: `Средний уровень: €60-100 (3 блюда + вино). Премиум бутик: €100-180. С целой запеченной рыбой + премиум вино: €150-250.` } },
      { q: { el: `Που υπάρχουν εστιατόρια με sunset θέα;`, en: `Where are restaurants with sunset views?`, de: `Wo gibt es Restaurants mit Sonnenuntergangsausblick?`, ro: `Unde sunt restaurante cu vedere la apus?`, sr: `Gde postoje restorani sa pogledom na zalazak sunca?`, bg: `Къде има ресторанти с гледка към залеза?`, ru: `Где есть рестораны с видом на закат?` }, a: { el: `<strong>Δυτική Χαλκιδική</strong> για ηλιοβασίλεμα (Ποσείδι, Καλλιθέα δυτικά). <strong>Σιθωνία ανατολική</strong> αν θες απόσταξη στο Άγιο Όρος αντί ηλιοβασιλέματος. <strong>Ουρανούπολη</strong> έχει και τα δύο μέσα από διαφορετικά εστιατόρια.`, en: `<strong>Western Halkidiki</strong> for sunsets (Possidi, western Kallithea). <strong>Eastern Sithonia</strong> if you prefer Mount Athos views over sunset. <strong>Ouranoupoli</strong> offers both depending on the restaurant.`, de: `<strong>Westliches Chalkidiki</strong> für Sonnenuntergänge (Possidi, westliches Kallithea). <strong>Östliches Sithonia</strong>, wenn du den Berg Athos statt des Sonnenuntergangs sehen möchtest. <strong>Ouranoupoli</strong> bietet beides aus verschiedenen Restaurants.`, ro: `<strong>Vestul Halkidiki</strong> pentru apus (Possidi, Kallithea vest). <strong>Sithonia est</strong> dacă vrei priveliște spre Muntele Athos în loc de apus. <strong>Ouranoupoli</strong> le are pe ambele din restaurante diferite.`, sr: `<strong>Zapadni Halkidiki</strong> za zalazak sunca (Posidi, Kalitea zapadno). <strong>Istočna Sitonija</strong> ako želiš pogled na Svetu Goru umesto zalaska sunca. <strong>Uranopolis</strong> ima oba iz različitih restorana.`, bg: `<strong>Западен Халкидики</strong> за залез (Посиди, Калитея на запад). <strong>Източна Ситония</strong>, ако искаш гледка към Света гора вместо залез. <strong>Урануполи</strong> има и двете в различни ресторанти.`, ru: `<strong>Западные Халкидики</strong> для заката (Посиди, Каллифея на западе). <strong>Восточная Ситония</strong>, если хотите вид на Афон вместо заката. <strong>Урануполи</strong> предлагает оба варианта из разных ресторанов.` } },
    ],
  },
  "traditional-tavernas": {
    intro: { el: `<p>Οι παραδοσιακές ταβέρνες της Χαλκιδικής είναι το αυθεντικό πρόσωπο της τοπικής γαστρονομίας — μακριά από τις τουριστικές beach restaurants, βαθιά στα γραφικά εσωτερικά χωριά. Παρθενώνας, Άφυτος, Καλαμίτσι, Πυργαδίκια, Καστρί. Σπιτικά μαγειρευτά, ψητά κρέατα στα κάρβουνα, ντόπιο τυρί, ψωμί ζυμωτό. Τιμές 30-50% κάτω από τη παραλιακή ζώνη. Πολλές διατηρούν την οικογενειακή λειτουργία 3 και 4 γενεών. Αυτή η λίστα συγκεντρώνει τις ταβέρνες που σταθερά εκπροσωπούν τη χαλκιδικιώτικη παράδοση με βάση τις αξιολογήσεις των επισκεπτών μας.</p>`, en: `<p>Halkidiki's traditional tavernas are the authentic face of local gastronomy — far from tourist beach restaurants, deep in the picturesque inland villages. Parthenonas, Afytos, Kalamitsi, Pyrgadikia, Kastri. Home-cooked dishes, charcoal-grilled meats, local cheese, hand-kneaded bread. Prices 30-50% below the seafront zone. Many remain family-run across 3-4 generations. This list collects the tavernas that consistently represent Halkidiki tradition, based on visitor ratings.</p>`, de: `<p>Die traditionellen Tavernen in Chalkidiki sind das authentische Gesicht der lokalen Gastronomie — fernab von den touristischen Beach-Restaurants, tief in den malerischen Dörfern im Landesinneren. Parthenonas, Afytos, Kalamitsi, Pyrgadikia, Kastrí. Hausgemachte Eintöpfe, gegrilltes Fleisch über Holzkohle, lokaler Käse, selbstgebackenes Brot. Preise 30-50% unterhalb der Küstenzone. Viele werden seit 3 oder 4 Generationen familiengeführt. Diese Liste versammelt die Tavernen, die beständig die Tradition von Chalkidiki repräsentieren, basierend auf den Bewertungen unserer Besucher.</p>`, ro: `<p>Tavernele tradiționale din Halkidiki reprezintă fața autentică a gastronomiei locale — departe de restaurantele turistice de pe plajă, adânc în satele pitorești din interior. Parthenonas, Afytos, Kalamitsi, Pyrgadikia, Kastrí. Mâncăruri gătite acasă, carne la grătar pe cărbuni, brânză locală, pâine de casă. Prețuri cu 30-50% mai mici decât în zona de coastă. Multe păstrează funcționarea familială de 3 și 4 generații. Această listă reunește tavernele care reprezintă constant tradiția din Halkidiki, pe baza evaluărilor vizitatorilor noștri.</p>`, sr: `<p>Tradicionalne taverne Halkidikija su autentično lice lokalne gastronomije — daleko od turističkih restorana na plaži, duboko u slikovitim unutrašnjim selima. Parthenonas, Afytos, Kalamitsi, Pyrgadikia, Kastri. Domaća kuvana jela, pečeno meso na roštilju, lokalni sir, domaći hleb. Cene 30-50% niže nego u obalskoj zoni. Mnoge zadržavaju porodično poslovanje 3 i 4 generacije. Ova lista okuplja taverne koje dosledno predstavljaju tradiciju Halkidikija na osnovu ocena naših posetilaca.</p>`, bg: `<p>Традиционните таверни на Халкидики са автентичното лице на местната гастрономия — далеч от туристическите beach restaurants, дълбоко в живописните вътрешни села. Партенонас, Афитос, Каламици, Пиргадикия, Кастри. Домашно приготвени ястия, печено месо на въглища, местно сирене, замесен хляб. Цени 30-50% по-ниски от крайбрежната зона. Много от тях запазват семейната традиция на 3 и 4 поколения. Този списък събира таверните, които стабилно представляват традицията на Халкидики въз основа на оценките на нашите посетители.</p>`, ru: `<p>Традиционные таверны Халкидики — это подлинное лицо местной гастрономии, вдали от туристических пляжных ресторанов, глубоко в живописных внутренних деревнях. Партенонас, Афитос, Каламици, Пиргадикия, Кастри. Домашние блюда, жареное на углях мясо, местный сыр, хлеб из закваски. Цены на 30-50% ниже, чем в прибрежной зоне. Многие сохраняют семейное управление на протяжении 3 и 4 поколений. Этот список собирает таверны, которые стабильно представляют традиции Халкидики на основе отзывов наших посетителей.</p>` },
    seasonal: { el: `<h2>Πότε να πας</h2><p><strong>Όλο τον χρόνο:</strong> Σε αντίθεση με τις παραλιακές, οι παραδοσιακές ταβέρνες είναι ανοιχτές όλη χρονιά. <strong>Καλύτερη εμπειρία:</strong> Σεπτέμβριο-Οκτώβριο όταν φεύγει ο μαζικός τουρισμός — οι ντόπιοι επιστρέφουν, βλέπεις πραγματική ατμόσφαιρα. <strong>Άνοιξη:</strong> Φρέσκα τυριά, βότανα. Καλό timing για μεζέδες με ούζο. <strong>Δείπνο:</strong> 20:00-22:00 παραδοσιακά — οι Έλληνες τρώνε αργά.</p>`, en: `<h2>When to visit</h2><p><strong>Year-round:</strong> Unlike beachside restaurants, traditional tavernas are open all year. <strong>Best experience:</strong> September-October when mass tourism leaves — locals return, you see the real atmosphere. <strong>Spring:</strong> Fresh cheeses, herbs. Great timing for meze with ouzo. <strong>Dinner:</strong> 20:00-22:00 traditionally — Greeks eat late.</p>`, de: `<h2>Wann man reisen sollte</h2><p><strong>Ganzjährig:</strong> Im Gegensatz zu den Küstenrestaurants sind die traditionellen Tavernen das ganze Jahr über geöffnet. <strong>Beste Erfahrung:</strong> September-Oktober, wenn der Massentourismus abnimmt — die Einheimischen kehren zurück, man erlebt die echte Atmosphäre. <strong>Frühling:</strong> Frische Käse, Kräuter. Gute Zeit für Mezedes mit Ouzo. <strong>Abendessen:</strong> Traditionell von 20:00-22:00 Uhr — die Griechen essen spät.</p>`, ro: `<h2>Când să mergi</h2><p><strong>Tot anul:</strong> Spre deosebire de cele de pe litoral, tavernele tradiționale sunt deschise tot anul. <strong>Cea mai bună experiență:</strong> Septembrie-Octombrie, când pleacă turismul de masă — localnicii se întorc, vezi atmosfera autentică. <strong>Primăvara:</strong> Brânzeturi proaspete, ierburi. Moment bun pentru meze cu ouzo. <strong>Cina:</strong> 20:00-22:00 tradițional — grecii mănâncă târziu.</p>`, sr: `<h2>Kada posetiti</h2><p><strong>Cele godine:</strong> Za razliku od obalskih, tradicionalne taverne su otvorene cele godine. <strong>Najbolje iskustvo:</strong> Septembar-oktobar kada masovni turizam odlazi — lokalci se vraćaju, vidiš pravu atmosferu. <strong>Proleće:</strong> Sveži sirevi, bilje. Dobar trenutak za meze sa uzoom. <strong>Večera:</strong> 20:00-22:00 tradicionalno — Grci jedu kasno.</p>`, bg: `<h2>Кога да отидете</h2><p><strong>Целогодишно:</strong> За разлика от крайбрежните, традиционните таверни са отворени целогодишно. <strong>Най-добро преживяване:</strong> Септември-Октомври, когато масовият туризъм си отива — местните се връщат, виждате истинска атмосфера. <strong>Пролет:</strong> Пресни сирена, билки. Добро време за мезета с узо. <strong>Вечеря:</strong> 20:00-22:00 традиционно — гърците ядат късно.</p>`, ru: `<h2>Когда поехать</h2><p><strong>Круглый год:</strong> В отличие от прибрежных, традиционные таверны открыты круглый год. <strong>Лучший опыт:</strong> Сентябрь-октябрь, когда массовый туризм уходит — местные возвращаются, видишь настоящую атмосферу. <strong>Весна:</strong> Свежие сыры, травы. Хорошее время для мезе с узо. <strong>Ужин:</strong> 20:00-22:00 традиционно — греки едят поздно.</p>` },
    tips: { el: `<h2>Συμβουλές για παραδοσιακή εμπειρία</h2><ul><li><strong>Άσε τον ιδιοκτήτη να σου προτείνει:</strong> "Τι έχεις σήμερα φρέσκο/καλό;" — τυπικός κανόνας. Παίρνεις πάντα το πιο νόστιμο της ημέρας.</li><li><strong>Μεζέδες:</strong> Παράγγειλε 4-6 για 2 άτομα: τυρί φέτα, ντομάτα, γεμιστά, κεφτεδάκια, τυροπιτάκια, ντόπιο σαλάμι. Συνοδεία ούζο ή ρακή.</li><li><strong>Κύριο:</strong> Σουβλάκι, μοσχαρίσιο σπαλομπριζόλα, αρνί παϊδάκια. Σπιτικά γεμιστά, μουσακάς.</li><li><strong>Επιδόρπιο:</strong> Σπιτικό γιαούρτι με μέλι. Φρεσκοτηγανισμένο λουκουμάδες.</li><li><strong>Πληρωμή:</strong> Συχνά μόνο μετρητά. Έχε €30-60 cash για 2 άτομα.</li><li><strong>Καλύτερα χωριά:</strong> Παρθενώνας (Σιθωνία), Άφυτος (Κασσάνδρα), Καλαμίτσι (Σιθωνία ανατολική), Πυργαδίκια (μεταξύ Σιθωνίας-Άθω).</li></ul>`, en: `<h2>Tips for the traditional experience</h2><ul><li><strong>Let the owner suggest:</strong> "What's fresh / good today?" — a typical rule. You always get the tastiest dish of the day.</li><li><strong>Meze:</strong> Order 4-6 for two people: feta, tomatoes, stuffed vegetables, meatballs, tiropitakia, local salami. Pair with ouzo or raki.</li><li><strong>Main:</strong> Souvlaki, beef rib steak, lamb chops. Homemade stuffed vegetables, moussaka.</li><li><strong>Dessert:</strong> Homemade yogurt with honey. Fresh loukoumades.</li><li><strong>Payment:</strong> Often cash only. Bring €30-60 cash for two.</li><li><strong>Best villages:</strong> Parthenonas (Sithonia), Afytos (Kassandra), Kalamitsi (eastern Sithonia), Pyrgadikia (between Sithonia-Athos).</li></ul>`, de: `<h2>Tipps für ein traditionelles Erlebnis</h2><ul><li><strong>Lass den Besitzer dir etwas empfehlen:</strong> "Was hast du heute frisch/gut?" — eine typische Regel. Man bekommt immer das Leckerste des Tages.</li><li><strong>Mezedes:</strong> Bestelle 4-6 für 2 Personen: Feta-Käse, Tomaten, gefüllte Gerichte, Fleischbällchen, Käsepasteten, lokale Salami. Dazu Ouzo oder Raki.</li><li><strong>Hauptgericht:</strong> Souvlaki, Rindersteak, Lammkoteletts. Hausgemachte gefüllte Gerichte, Moussaka.</li><li><strong>Dessert:</strong> Hausgemachter Joghurt mit Honig. Frisch gebratene Loukoumades.</li><li><strong>Zahlung:</strong> Oft nur Barzahlung. Habe €30-60 in bar für 2 Personen dabei.</li><li><strong>Beste Dörfer:</strong> Parthenonas (Sithonia), Afytos (Kassandra), Kalamitsi (östliches Sithonia), Pyrgadikia (zwischen Sithonia und Athos).</li></ul>`, ro: `<h2>Sfaturi pentru o experiență tradițională</h2><ul><li><strong>Lasă proprietarul să îți recomande:</strong> "Ce ai astăzi proaspăt/bun?" — regulă tipică. Primești întotdeauna cel mai gustos preparat al zilei.</li><li><strong>Meze:</strong> Comandă 4-6 pentru 2 persoane: brânză feta, roșii, gemista, chiftele, plăcinte cu brânză, salam local. Însoțite de ouzo sau raki.</li><li><strong>Fel principal:</strong> Souvlaki, cotlet de vită, coaste de miel. Gemista de casă, musaca.</li><li><strong>Desert:</strong> Iaurt de casă cu miere. Loukoumades proaspăt prăjiți.</li><li><strong>Plată:</strong> Adesea doar numerar. Ai la tine €30-60 cash pentru 2 persoane.</li><li><strong>Cele mai bune sate:</strong> Parthenonas (Sithonia), Afytos (Kassandra), Kalamitsi (Sithonia est), Pyrgadikia (între Sithonia-Athos).</li></ul>`, sr: `<h2>Saveti za tradicionalno iskustvo</h2><ul><li><strong>Pusti vlasnika da ti predloži:</strong> "Šta imaš danas sveže/dobro?" — tipično pravilo. Uvek uzimaš najukusnije tog dana.</li><li><strong>Meze:</strong> Naruči 4-6 za 2 osobe: feta sir, paradajz, punjeno povrće, ćufte, pite sa sirom, lokalni salami. Uz uzo ili rakiju.</li><li><strong>Glavno jelo:</strong> Souvlaki, juneći biftek, jagnjeći kotleti. Domaće punjeno povrće, musaka.</li><li><strong>Dezert:</strong> Domaći jogurt sa medom. Sveže prženi loukoumades.</li><li><strong>Plaćanje:</strong> Često samo gotovina. Imati €30-60 keša za 2 osobe.</li><li><strong>Najbolja sela:</strong> Parthenonas (Sitonija), Afytos (Kasandra), Kalamitsi (istočna Sitonija), Pyrgadikia (između Sitonije i Atosa).</li></ul>`, bg: `<h2>Съвети за традиционно преживяване</h2><ul><li><strong>Оставете собственика да ви предложи:</strong> "Какво имате днес прясно/добро?" — типично правило. Винаги получавате най-вкусното за деня.</li><li><strong>Мезета:</strong> Поръчайте 4-6 за 2 души: сирене фета, домат, пълнени зеленчуци, кюфтенца, сиренки, местен салам. Съпровод с узо или ракия.</li><li><strong>Основно:</strong> Сувлаки, телешка пържола, агнешки ребра. Домашно приготвени пълнени зеленчуци, мусака.</li><li><strong>Десерт:</strong> Домашно кисело мляко с мед. Прясно изпържени локумади.</li><li><strong>Плащане:</strong> Често само в брой. Носете €30-60 в брой за 2 души.</li><li><strong>Най-добри села:</strong> Партенонас (Ситония), Афитос (Касандра), Каламици (източна Ситония), Пиргадикия (между Ситония и Света гора).</li></ul>`, ru: `<h2>Советы для традиционного опыта</h2><ul><li><strong>Позвольте владельцу предложить вам:</strong> "Что у вас сегодня свежее/хорошее?" — типичное правило. Всегда берите самое вкусное за день.</li><li><strong>Мезе:</strong> Закажите 4-6 на 2 человека: сыр фета, томаты, фаршированные овощи, кефтедес, сырные пирожки, местная колбаса. Сопровождается узо или раки.</li><li><strong>Основное:</strong> Сувлаки, говяжья рибай, баранина. Домашние фаршированные овощи, мусака.</li><li><strong>Десерт:</strong> Домашний йогурт с медом. Свежеприготовленные лукумадес.</li><li><strong>Оплата:</strong> Часто только наличными. Имейте €30-60 наличными на 2 человека.</li><li><strong>Лучшие деревни:</strong> Партенонас (Ситония), Афитос (Кассандра), Каламици (восточная Ситония), Пиргадикия (между Ситонией и Афоном).</li></ul>` },
    faqs: [
      { q: { el: `Σε ποιο χωριό να πάω για παραδοσιακή ταβέρνα;`, en: `Which village for a traditional taverna?`, de: `In welches Dorf soll ich für eine traditionelle Taverne gehen?`, ro: `În ce sat să merg pentru o tavernă tradițională?`, sr: `U koje selo da idem za tradicionalnu tavernu?`, bg: `В кое село да отида за традиционна таверна?`, ru: `В какую деревню поехать для традиционной таверны?` }, a: { el: `<strong>Άφυτος</strong> για κλασική Κασσάνδρα εμπειρία με θέα. <strong>Παρθενώνας</strong> για ορεινή Σιθωνία. <strong>Καλαμίτσι</strong> για ψαρομεζέδες. <strong>Πυργαδίκια</strong> για παραθαλάσσια ταβέρνες με παράδοση. Βλέπε όλες τις τοποθεσίες σε αυτή τη λίστα.`, en: `<strong>Afytos</strong> for a classic Kassandra experience with a view. <strong>Parthenonas</strong> for hillside Sithonia. <strong>Kalamitsi</strong> for fish meze. <strong>Pyrgadikia</strong> for seafront tavernas with tradition. See all locations in this list.`, de: `<strong>Afytos</strong> für ein klassisches Kassandra-Erlebnis mit Aussicht. <strong>Parthenonas</strong> für das bergige Sithonia. <strong>Kalamitsi</strong> für Fischmezedes. <strong>Pyrgadikia</strong> für Küstentavernen mit Tradition. Siehe alle Orte in dieser Liste.`, ro: `<strong>Afytos</strong> pentru o experiență clasică în Kassandra cu vedere. <strong>Parthenonas</strong> pentru Sithonia montană. <strong>Kalamitsi</strong> pentru meze de pește. <strong>Pyrgadikia</strong> pentru taverne tradiționale pe malul mării. Vezi toate locațiile din această listă.`, sr: `<strong>Afytos</strong> za klasično iskustvo Kasandre sa pogledom. <strong>Parthenonas</strong> za planinsku Sitoniju. <strong>Kalamitsi</strong> za riblje meze. <strong>Pyrgadikia</strong> za obalske taverne sa tradicijom. Pogledaj sve lokacije na ovoj listi.`, bg: `<strong>Афитос</strong> за класическо Касандра преживяване с гледка. <strong>Партенонас</strong> за планинска Ситония. <strong>Каламици</strong> за рибни мезета. <strong>Пиргадикия</strong> за крайбрежни таверни с традиция. Вижте всички локации в този списък.`, ru: `<strong>Афитос</strong> для классического опыта Кассандры с видом. <strong>Партенонас</strong> для горной Ситонии. <strong>Каламици</strong> для рыбных мезе. <strong>Пиргадикия</strong> для прибрежных таверн с традициями. Смотрите все места в этом списке.` } },
      { q: { el: `Είναι κατάλληλο για παιδιά;`, en: `Suitable for kids?`, de: `Ist es für Kinder geeignet?`, ro: `Este potrivit pentru copii?`, sr: `Da li je pogodno za decu?`, bg: `Подходящо ли е за деца?`, ru: `Подходит ли для детей?` }, a: { el: `Ναι — οι ελληνικές ταβέρνες είναι extra φιλικές με παιδιά. Συνήθως ηγέτης οικογενειακή ατμόσφαιρα. Επιπλέον σνακς (πατάτες τηγανητές, τυρόπιτα), παγωτό από το ψυγείο.`, en: `Yes — Greek tavernas are extra kid-friendly. Family atmosphere is the norm. Easy snacks (fries, tyropita), ice cream from the fridge.`, de: `Ja — die griechischen Tavernen sind besonders kinderfreundlich. In der Regel herrscht eine familiäre Atmosphäre. Zusätzliche Snacks (Pommes frites, Käsepastete), Eis aus der Kühltruhe.`, ro: `Da — tavernele grecești sunt extrem de prietenoase cu copiii. De obicei, conduc o atmosferă familială. Gustări suplimentare (cartofi prăjiți, plăcintă cu brânză), înghețată din congelator.`, sr: `Da — grčke taverne su izuzetno prijateljske prema deci. Obično vlada porodična atmosfera. Dodatni grickalice (pomfrit, pita sa sirom), sladoled iz frižidera.`, bg: `Да — гръцките таверни са изключително приятелски настроени към деца. Обикновено водят семейна атмосфера. Допълнителни закуски (пържени картофи, сиренки), сладолед от фризера.`, ru: `Да — греческие таверны очень дружелюбны к детям. Обычно преобладает семейная атмосфера. Дополнительные закуски (жареный картофель, сырные пирожки), мороженое из холодильника.` } },
      { q: { el: `Πόσο κοστίζει 4-μελής οικογένεια;`, en: `How much for a family of four?`, de: `Wie viel kostet es für eine 4-köpfige Familie?`, ro: `Cât costă pentru o familie de 4 persoane?`, sr: `Koliko košta za četvoročlanu porodicu?`, bg: `Колко струва за 4-членно семейство?`, ru: `Сколько стоит для семьи из 4 человек?` }, a: { el: `Παραδοσιακό δείπνο με 6 μεζέδες + 2 κύρια + κρασί + νερό για 4 άτομα: €45-80. Σαφώς πιο φθηνά από beach restaurants.`, en: `A traditional dinner with 6 meze + 2 mains + wine + water for 4 people: €45-80. Clearly cheaper than beach restaurants.`, de: `Traditionelles Abendessen mit 6 Mezedes + 2 Hauptgerichten + Wein + Wasser für 4 Personen: €45-80. Deutlich günstiger als Beach-Restaurants.`, ro: `Cină tradițională cu 6 meze + 2 feluri principale + vin + apă pentru 4 persoane: €45-80. Clar mai ieftin decât restaurantele de pe plajă.`, sr: `Tradicionalna večera sa 6 mezea + 2 glavna jela + vino + voda za 4 osobe: €45-80. Znatno jeftinije od restorana na plaži.`, bg: `Традиционна вечеря с 6 мезета + 2 основни + вино + вода за 4 души: €45-80. Ясно по-евтино от beach restaurants.`, ru: `Традиционный ужин с 6 мезе + 2 основных блюда + вино + вода для 4 человек: €45-80. Значительно дешевле, чем в пляжных ресторанах.` } },
    ],
  },
  "restaurants-kassandra": {
    intro: { el: `<p>Η Κασσάνδρα έχει την πιο πυκνή γαστρονομική σκηνή της Χαλκιδικής — από διεθνή cuisine και sushi bars στις πιο τουριστικές περιοχές (Καλλιθέα, Σάνη, Χανιώτη), μέχρι παραδοσιακές ταβέρνες με ψαρομεζέδες στα παραδοσιακά χωριά (Άφυτος, Νέα Φώκαια). Αυτή η λίστα συγκεντρώνει τα εστιατόρια της Κασσάνδρας με τις υψηλότερες αξιολογήσεις, φιλτραρισμένα ανά κουζίνα. Είτε ψάχνεις χαλαρό μεσημεριανό beach lunch, είτε ρομαντικό δείπνο sunset, είτε αυθεντική greek experience — υπάρχει κατάλληλο εστιατόριο για σένα.</p>`, en: `<p>Kassandra has Halkidiki's densest gastronomy scene — from international cuisine and sushi bars in the most touristy areas (Kallithea, Sani, Hanioti) to traditional tavernas with seafood meze in the historic villages (Afytos, Nea Fokaia). This list collects Kassandra's highest-rated restaurants, filterable by cuisine. Whether you're after a relaxed beach lunch, a romantic sunset dinner, or an authentic Greek experience — there's a restaurant for you.</p>`, de: `<p>Kassandra hat die dichteste gastronomische Szene in Chalkidiki — von internationaler Küche und Sushi-Bars in den touristischsten Gebieten (Kallithea, Sani, Chanioti) bis hin zu traditionellen Tavernen mit Fischmezedes in den traditionellen Dörfern (Afytos, Nea Fokea). Diese Liste fasst die bestbewerteten Restaurants in Kassandra zusammen, gefiltert nach Küche. Egal, ob du ein entspanntes Mittagessen am Strand, ein romantisches Abendessen bei Sonnenuntergang oder ein authentisches griechisches Erlebnis suchst — es gibt das passende Restaurant für dich.</p>`, ro: `<p>Kassandra are cea mai densă scenă gastronomică din Halkidiki — de la cuisine internațională și sushi bars în zonele cele mai turistice (Kallithea, Sani, Hanioti), până la taverne tradiționale cu mezeuri de pește în satele tradiționale (Afytos, Nea Fokea). Această listă reunește restaurantele din Kassandra cu cele mai înalte evaluări, filtrate după bucătărie. Fie că cauți un prânz relaxant pe plajă, o cină romantică la apus sau o experiență autentică grecească — există un restaurant potrivit pentru tine.</p>`, sr: `<p>Kassandra ima najbogatiju gastronomsku scenu u Halkidikiju — od međunarodne kuhinje i sushi barova u najturističkijim oblastima (Kallithea, Sani, Hanioti), do tradicionalnih taverni sa ribljim specijalitetima u tradicionalnim selima (Afytos, Nea Fokea). Ova lista okuplja restorane u Kassandra sa najvišim ocenama, filtrirane po kuhinji. Bilo da tražite opušteni ručak na plaži, romantičnu večeru uz zalazak sunca, ili autentično grčko iskustvo — postoji odgovarajući restoran za vas.</p>`, bg: `<p>Касандра има най-гъстата гастрономическа сцена в Халкидики — от международна кухня и суши барове в най-туристическите райони (Калитея, Сани, Ханиоти), до традиционни таверни с рибни мезета в традиционните села (Афитос, Неа Фокеа). Този списък събира ресторантите в Касандра с най-високи оценки, филтрирани по кухня. Независимо дали търсиш спокойно обедно плажно хранене, романтична вечеря на залез или автентично гръцко преживяване — има подходящ ресторант за теб.</p>`, ru: `<p>Кассандра предлагает самую насыщенную гастрономическую сцену Халкидики — от международной кухни и суши-баров в самых туристических районах (Каллифея, Сани, Ханиоти) до традиционных таверн с рыбными закусками в традиционных деревнях (Афитос, Неа Фокеа). Этот список собирает рестораны Кассандры с самыми высокими оценками, отфильтрованные по кухне. Ищете ли вы расслабленный обед на пляже, романтический ужин на закате или аутентичный греческий опыт — найдется подходящий ресторан для вас.</p>` },
    seasonal: { el: `<h2>Πότε να κρατήσεις</h2><p><strong>Peak season (Ιούλιος-Αύγουστος):</strong> Κράτηση υποχρεωτική 2-3 μέρες πριν σε γνωστές μονάδες. Σαββατοκύριακα οι παραλιακές γεμίζουν 20:30-22:30. <strong>Σεπτέμβριος:</strong> Καλύτερη εμπειρία — σταθερά διαθέσιμα τραπέζια, χαλαρό σέρβις, ίδια ποιότητα. <strong>Μη-σεζόν (Νοέμβριος-Μάρτιος):</strong> Πολλές παραλιακές κλειστές, αλλά οι παραδοσιακές στο εσωτερικό (Άφυτος) ανοιχτές.</p>`, en: `<h2>When to book</h2><p><strong>Peak season (July-August):</strong> Booking is essential 2-3 days ahead at popular venues. On weekends, beachfront tables fill up 20:30-22:30. <strong>September:</strong> Better experience — tables consistently available, relaxed service, same quality. <strong>Off-season (November-March):</strong> Many beachside spots closed, but inland traditional tavernas (Afytos) stay open.</p>`, de: `<h2>Wann reservieren</h2><p><strong>Hochsaison (Juli-August):</strong> Reservierung 2-3 Tage im Voraus in bekannten Lokalen obligatorisch. An Wochenenden sind die Strandrestaurants von 20:30-22:30 Uhr voll. <strong>September:</strong> Beste Erfahrung — konstant verfügbare Tische, entspannter Service, gleiche Qualität. <strong>Außerhalb der Saison (November-März):</strong> Viele Strandrestaurants geschlossen, aber die traditionellen im Landesinneren (Afytos) geöffnet.</p>`, ro: `<h2>Când să faci rezervare</h2><p><strong>Sezon de vârf (iulie-august):</strong> Rezervare obligatorie cu 2-3 zile înainte la unitățile cunoscute. În weekend, cele de pe plajă se umplu între 20:30-22:30. <strong>Septembrie:</strong> Experiență mai bună — mese disponibile constant, serviciu relaxat, aceeași calitate. <strong>Extra-sezon (noiembrie-martie):</strong> Multe restaurante de pe plajă sunt închise, dar cele tradiționale din interior (Afytos) sunt deschise.</p>`, sr: `<h2>Kada rezervisati</h2><p><strong>Vrh sezone (jul-avgust):</strong> Rezervacija obavezna 2-3 dana unapred u poznatim objektima. Vikendom se obalski restorani pune od 20:30 do 22:30. <strong>Septembar:</strong> Najbolje iskustvo — uvek dostupni stolovi, opuštena usluga, isti kvalitet. <strong>Van sezone (novembar-mart):</strong> Mnogi obalski restorani zatvoreni, ali tradicionalni u unutrašnjosti (Afytos) otvoreni.</p>`, bg: `<h2>Кога да резервираш</h2><p><strong>Пиков сезон (юли-август):</strong> Резервация задължителна 2-3 дни предварително в известните заведения. Уикендите крайбрежните се пълнят 20:30-22:30. <strong>Септември:</strong> По-добро преживяване — стабилно налични маси, спокойно обслужване, същото качество. <strong>Извън сезона (ноември-март):</strong> Много крайбрежни затворени, но традиционните във вътрешността (Афитос) отворени.</p>`, ru: `<h2>Когда бронировать</h2><p><strong>Пик сезона (июль-август):</strong> Бронирование обязательно за 2-3 дня в известных заведениях. В выходные пляжные рестораны заполняются с 20:30 до 22:30. <strong>Сентябрь:</strong> Лучший опыт — всегда доступны столики, расслабленное обслуживание, то же качество. <strong>Не сезон (ноябрь-март):</strong> Многие пляжные закрыты, но традиционные в глубине (Афитос) открыты.</p>` },
    tips: { el: `<h2>Που να φας ανά κατηγορία</h2><ul><li><strong>Beach lunch:</strong> Σάνη Marina, Καλλιθέα παραλιακά. Mid-range €25-40/άτομο.</li><li><strong>Sunset dinner:</strong> Άφυτος για χωριό + sea view. Δες <a href="/best/romantic-restaurants">ρομαντικά εστιατόρια</a>.</li><li><strong>Ψαρομεζέδες:</strong> Νέα Φώκαια λιμανάκι, Άφυτος ταβέρνες. Δες <a href="/best/seafood-restaurants">ψαροταβέρνες</a>.</li><li><strong>Παραδοσιακή ταβέρνα:</strong> Άφυτος εσωτερικό, παρόμοιες πιο φθηνές. Δες <a href="/best/traditional-tavernas">παραδοσιακές ταβέρνες</a>.</li><li><strong>International:</strong> Σάνη Marina έχει sushi, italian, asian fusion για όσους θέλουν αλλαγή.</li></ul>`, en: `<h2>Where to eat by category</h2><ul><li><strong>Beach lunch:</strong> Sani Marina, Kallithea seafront. Mid-range €25-40/person.</li><li><strong>Sunset dinner:</strong> Afytos village with sea view. See <a href="/best/romantic-restaurants">romantic restaurants</a>.</li><li><strong>Seafood meze:</strong> Nea Fokaia harbour, Afytos tavernas. See <a href="/best/seafood-restaurants">seafood restaurants</a>.</li><li><strong>Traditional taverna:</strong> Inland Afytos, similar villages cheaper. See <a href="/best/traditional-tavernas">traditional tavernas</a>.</li><li><strong>International:</strong> Sani Marina has sushi, Italian, Asian fusion if you want a change.</li></ul>`, de: `<h2>Wo man je nach Kategorie essen sollte</h2><ul><li><strong>Strandmittagessen:</strong> Sani Marina, Kallithea am Strand. Mittlere Preisklasse €25-40/Person.</li><li><strong>Abendessen bei Sonnenuntergang:</strong> Afytos für Dorf + Meerblick. Siehe <a href="/best/romantic-restaurants">romantische Restaurants</a>.</li><li><strong>Fischmezedes:</strong> Nea Fokea Hafen, Afytos Tavernen. Siehe <a href="/best/seafood-restaurants">Fischtavernen</a>.</li><li><strong>Traditionelle Taverne:</strong> Afytos im Landesinneren, ähnliche günstigere Optionen. Siehe <a href="/best/traditional-tavernas">traditionelle Tavernen</a>.</li><li><strong>International:</strong> Sani Marina bietet Sushi, italienische und asiatische Fusion für diejenigen, die Abwechslung suchen.</li></ul>`, ro: `<h2>Unde să mănânci în funcție de categorie</h2><ul><li><strong>Prânz pe plajă:</strong> Sani Marina, Kallithea pe plajă. Prețuri medii €25-40/persoană.</li><li><strong>Cină la apus:</strong> Afytos pentru sat + vedere la mare. Vezi <a href="/best/romantic-restaurants">restaurante romantice</a>.</li><li><strong>Mezeuri de pește:</strong> Nea Fokea la mic port, taverne în Afytos. Vezi <a href="/best/seafood-restaurants">taverne de pește</a>.</li><li><strong>Tavernă tradițională:</strong> Interiorul Afytos, similare mai ieftine. Vezi <a href="/best/traditional-tavernas">taverne tradiționale</a>.</li><li><strong>Internațional:</strong> Sani Marina are sushi, italian, fusion asiatic pentru cei care vor schimbare.</li></ul>`, sr: `<h2>Gde jesti po kategorijama</h2><ul><li><strong>Ručak na plaži:</strong> Sani Marina, Kallithea obalski restorani. Srednji cenovni rang €25-40/osobi.</li><li><strong>Večera uz zalazak sunca:</strong> Afytos za selo + pogled na more. Pogledajte <a href="/best/romantic-restaurants">romantične restorane</a>.</li><li><strong>Riblji specijaliteti:</strong> Nea Fokea mala luka, Afytos taverne. Pogledajte <a href="/best/seafood-restaurants">ribarske taverne</a>.</li><li><strong>Tradicionalna taverna:</strong> Afytos unutrašnjost, slične su jeftinije. Pogledajte <a href="/best/traditional-tavernas">tradicionalne taverne</a>.</li><li><strong>Međunarodna kuhinja:</strong> Sani Marina ima sushi, italijansku, azijsku fuziju za one koji žele promenu.</li></ul>`, bg: `<h2>Къде да ядеш по категория</h2><ul><li><strong>Плажен обяд:</strong> Сани Марина, Калитея крайбрежни. Среден клас €25-40/човек.</li><li><strong>Вечеря на залез:</strong> Афитос за село + морска гледка. Виж <a href="/best/romantic-restaurants">романтични ресторанти</a>.</li><li><strong>Рибни мезета:</strong> Неа Фокеа пристанище, Афитос таверни. Виж <a href="/best/seafood-restaurants">рибни таверни</a>.</li><li><strong>Традиционна таверна:</strong> Афитос вътрешност, подобни по-евтини. Виж <a href="/best/traditional-tavernas">традиционни таверни</a>.</li><li><strong>Международна:</strong> Сани Марина има суши, италианска, азиатска фюжън за тези, които искат промяна.</li></ul>`, ru: `<h2>Где поесть по категориям</h2><ul><li><strong>Обед на пляже:</strong> Сани Марина, Каллифея на побережье. Средний уровень €25-40/человек.</li><li><strong>Ужин на закате:</strong> Афитос для деревни + вид на море. Смотрите <a href="/best/romantic-restaurants">романтические рестораны</a>.</li><li><strong>Рыбные закуски:</strong> Неа Фокеа набережная, таверны Афитоса. Смотрите <a href="/best/seafood-restaurants">рыбные таверны</a>.</li><li><strong>Традиционная таверна:</strong> Афитос в глубине, аналогичные более дешевые. Смотрите <a href="/best/traditional-tavernas">традиционные таверны</a>.</li><li><strong>Интернациональная кухня:</strong> Сани Марина предлагает суши, итальянскую, азиатскую фьюжн для тех, кто хочет разнообразия.</li></ul>` },
    faqs: [
      { q: { el: `Που να φάω καλύτερα στην Κασσάνδρα;`, en: `Where to eat best in Kassandra?`, de: `Wo kann ich am besten in Kassandra essen?`, ro: `Unde să mănânc cel mai bine în Kassandra?`, sr: `Gde najbolje jesti u Kassandra?`, bg: `Къде да ям най-добре в Касандра?`, ru: `Где лучше поесть на Кассандре?` }, a: { el: `Εξαρτάται τι θες: <strong>Άφυτος</strong> για παραδοσιακό + θέα. <strong>Σάνη Marina</strong> για premium variety. <strong>Καλλιθέα παραλιακά</strong> για cosmopolitan. <strong>Νέα Φώκαια</strong> για authentic ψαρομεζέδες. Δες όλες σε αυτή τη λίστα.`, en: `Depends on what you want: <strong>Afytos</strong> for traditional + view. <strong>Sani Marina</strong> for premium variety. <strong>Kallithea seafront</strong> for cosmopolitan. <strong>Nea Fokaia</strong> for authentic seafood meze. See all in this list.`, de: `Es hängt davon ab, was du willst: <strong>Afytos</strong> für traditionell + Aussicht. <strong>Sani Marina</strong> für Premium-Vielfalt. <strong>Kallithea am Strand</strong> für kosmopolitisch. <strong>Nea Fokea</strong> für authentische Fischmezedes. Siehe alle in dieser Liste.`, ro: `Depinde ce vrei: <strong>Afytos</strong> pentru tradițional + vedere. <strong>Sani Marina</strong> pentru varietate premium. <strong>Kallithea pe plajă</strong> pentru cosmopolit. <strong>Nea Fokea</strong> pentru mezeuri de pește autentice. Vezi toate în această listă.`, sr: `Zavisi šta želite: <strong>Afytos</strong> za tradicionalno + pogled. <strong>Sani Marina</strong> za premium raznovrsnost. <strong>Kallithea obalski restorani</strong> za kosmopolitski doživljaj. <strong>Nea Fokea</strong> za autentične riblje specijalitete. Pogledajte sve na ovoj listi.`, bg: `Зависи какво искаш: <strong>Афитос</strong> за традиционно + гледка. <strong>Сани Марина</strong> за премиум разнообразие. <strong>Калитея крайбрежни</strong> за космополитен стил. <strong>Неа Фокеа</strong> за автентични рибни мезета. Виж всички в този списък.`, ru: `Зависит от того, что вы ищете: <strong>Афитос</strong> для традиционного + вид. <strong>Сани Марина</strong> для премиум разнообразия. <strong>Каллифея на побережье</strong> для космополитического. <strong>Неа Фокеа</strong> для аутентичных рыбных закусок. Смотрите все в этом списке.` } },
      { q: { el: `Πληρώνω more στα παραλιακά;`, en: `Do I pay more at the beachfront places?`, de: `Zahle ich mehr am Strand?`, ro: `Plătesc mai mult pe plajă?`, sr: `Da li plaćam više u obalskim restoranima?`, bg: `Плащам ли повече на крайбрежните?`, ru: `Плачу ли я больше на побережье?` }, a: { el: `Ναι, 20-40% παραπάνω από αντίστοιχης ποιότητας εστιατόρια στα χωριά εσωτερικά. Η θέα κοστίζει.`, en: `Yes, 20-40% more than equivalent-quality restaurants in inland villages. The view comes at a price.`, de: `Ja, 20-40% mehr als in Restaurants gleicher Qualität in den Dörfern im Landesinneren. Die Aussicht kostet.`, ro: `Da, cu 20-40% mai mult decât la restaurante de calitate similară în satele din interior. Vederea costă.`, sr: `Da, 20-40% više nego u restoranima iste kvalitete u unutrašnjim selima. Pogled košta.`, bg: `Да, 20-40% повече от съответстващи по качество ресторанти във вътрешните села. Гледката струва.`, ru: `Да, на 20-40% больше, чем в ресторанах аналогичного качества в деревнях в глубине. Вид стоит денег.` } },
      { q: { el: `Πιο φθηνά Κασσάνδρα ή Σιθωνία;`, en: `Cheaper: Kassandra or Sithonia?`, de: `Günstiger Kassandra oder Sithonia?`, ro: `Mai ieftin Kassandra sau Sithonia?`, sr: `Šta je jeftinije, Kassandra ili Sitonija?`, bg: `По-евтино Касандра или Ситония?`, ru: `Где дешевле: Кассандра или Ситония?` }, a: { el: `<strong>Σιθωνία:</strong> Λίγο πιο φθηνά γενικά (-10-15%) επειδή πιο λιγότερο τουριστικά αναπτυγμένη. Δες τα <a href="/best/restaurants-sithonia">εστιατόρια Σιθωνίας</a>.`, en: `<strong>Sithonia:</strong> Slightly cheaper overall (-10-15%) because it's less touristically developed. See <a href="/best/restaurants-sithonia">Sithonia restaurants</a>.`, de: `<strong>Sithonia:</strong> Etwas günstiger allgemein (-10-15%), da weniger touristisch entwickelt. Siehe die <a href="/best/restaurants-sithonia">Restaurants in Sithonia</a>.`, ro: `<strong>Sithonia:</strong> Puțin mai ieftin în general (-10-15%) deoarece este mai puțin dezvoltat turistic. Vezi <a href="/best/restaurants-sithonia">restaurantele din Sithonia</a>.`, sr: `<strong>Sitonija:</strong> Malo jeftinije uopšte (-10-15%) jer je manje turistički razvijena. Pogledajte <a href="/best/restaurants-sithonia">restorane Sitonije</a>.`, bg: `<strong>Ситония:</strong> Малко по-евтино като цяло (-10-15%) поради по-слабо туристическо развитие. Виж <a href="/best/restaurants-sithonia">ресторанти в Ситония</a>.`, ru: `<strong>Ситония:</strong> Немного дешевле в целом (-10-15%), так как менее туристически развита. Смотрите <a href="/best/restaurants-sithonia">рестораны Ситонии</a>.` } },
    ],
  },
  "restaurants-sithonia": {
    intro: { el: `<p>Η γαστρονομική σκηνή της Σιθωνίας είναι πιο χαλαρή και φυσική από αυτή της Κασσάνδρας — λιγότερα διεθνή concept, περισσότερες ψαροταβέρνες σε γραφικά λιμανάκια και παραδοσιακές ταβέρνες στα ορεινά χωριά. Είναι ιδανική για όσους ψάχνουν αυθεντική ελληνική γαστρονομία χωρίς τον αναπτυγμένο τουριστικό χαρακτήρα. Από τα ψαρολίμανα του Πυργαδίκι και της Σάρτης, μέχρι τις παραδοσιακές ταβέρνες του Παρθενώνα και της Νικήτης — η Σιθωνία είναι το παράδειγμα της απλής, ποιοτικής ελληνικής εστίασης. Αυτή η λίστα συγκεντρώνει τα κορυφαία εστιατόρια της περιοχής.</p>`, en: `<p>Sithonia's gastronomy scene is more relaxed and natural than Kassandra's — fewer international concepts, more seafood tavernas in picturesque harbours and traditional tavernas in mountain villages. Ideal for those wanting authentic Greek gastronomy without the developed tourist character. From the fishing harbours of Pyrgadikia and Sarti to the traditional tavernas of Parthenonas and Nikiti — Sithonia exemplifies simple, quality Greek dining. This list collects the area's top restaurants.</p>`, de: `<p>Die gastronomische Szene von Sithonia ist entspannter und natürlicher als die von Kassandra — weniger internationale Konzepte, mehr Fisch-Tavernen in malerischen kleinen Häfen und traditionelle Tavernen in den Bergdörfern. Sie ist ideal für diejenigen, die authentische griechische Gastronomie ohne den ausgeprägten touristischen Charakter suchen. Von den Fischhäfen von Pyrgadikia und Sarti bis zu den traditionellen Tavernen von Parthenonas und Nikiti — Sithonia ist das Paradebeispiel für einfache, qualitativ hochwertige griechische Gastronomie. Diese Liste versammelt die besten Restaurants der Region.</p>`, ro: `<p>Scena gastronomică din Sithonia este mai relaxată și mai naturală decât cea din Kassandra — mai puține concepte internaționale, mai multe taverne pescărești în porturi pitorești și taverne tradiționale în satele montane. Este ideală pentru cei care caută gastronomie grecească autentică fără caracterul turistic dezvoltat. De la porturile pescărești din Pyrgadikia și Sarti, până la tavernele tradiționale din Parthenonas și Nikiti — Sithonia este exemplul simplității și calității în gastronomia grecească. Această listă reunește cele mai bune restaurante din regiune.</p>`, sr: `<p>Gastronomska scena Sitonije je opuštenija i prirodnija od one na Kasandri — manje međunarodnih koncepata, više ribljih taverni u slikovitim lukama i tradicionalnih taverni u planinskim selima. Idealna je za one koji traže autentičnu grčku gastronomiju bez razvijenog turističkog karaktera. Od ribarskih luka Pirgadikija i Sartija, do tradicionalnih taverni Parthenonasa i Nikitija — Sitonija je primer jednostavne, kvalitetne grčke kuhinje. Ova lista okuplja vrhunske restorane u regionu.</p>`, bg: `<p>Гастрономическата сцена на Ситония е по-спокойна и естествена от тази на Касандра — по-малко международни концепции, повече рибни таверни в живописни пристанища и традиционни таверни в планинските села. Тя е идеална за тези, които търсят автентична гръцка гастрономия без развит туристически характер. От рибарските пристанища на Пиргадики и Сарти, до традиционните таверни на Партенонас и Никити — Ситония е пример за проста, качествена гръцка кухня. Този списък събира най-добрите ресторанти в региона.</p>`, ru: `<p>Гастрономическая сцена Ситонии более расслабленная и естественная по сравнению с Кассандрой — меньше международных концепций, больше рыбных таверн в живописных портах и традиционных таверн в горных деревнях. Это идеальный выбор для тех, кто ищет аутентичную греческую гастрономию без развитого туристического характера. От рыбных портов Пиргадики и Сарти до традиционных таверн Парфенона и Никити — Ситония является примером простой, качественной греческой кухни. Этот список собирает лучшие рестораны региона.</p>` },
    seasonal: { el: `<h2>Πότε να πας</h2><p><strong>Καλοκαίρι:</strong> Σαββατοκύριακα Ιουλίου-Αυγούστου, κράτηση συνιστάται. Καθημερινές παίρνεις τραπέζι εύκολα. <strong>Σεπτέμβριος:</strong> Ιδανικό — οι ντόπιοι επιστρέφουν στις παραδοσιακές. Χαλαρό σέρβις, μεγαλύτερη ποικιλία (ψάρια). <strong>Χειμώνας:</strong> Λιγοστές επιλογές, ταβέρνες χωριών εσωτερικού (Παρθενώνας) ανοιχτές. Ζεστή σόμπα, σπιτικό κρασί, χειμωνιάτικα μενού.</p>`, en: `<h2>When to visit</h2><p><strong>Summer:</strong> July-August weekends, booking advised. Weekdays, getting a table is easy. <strong>September:</strong> Ideal — locals return to traditional tavernas. Relaxed service, more fish on the menu. <strong>Winter:</strong> Fewer options, but inland village tavernas (Parthenonas) stay open. Warm stove, house wine, winter menus.</p>`, de: `<h2>Wann man gehen sollte</h2><p><strong>Sommer:</strong> Wochenenden im Juli-August, Reservierung empfohlen. Unter der Woche bekommt man leicht einen Tisch. <strong>September:</strong> Ideal — die Einheimischen kehren zu den traditionellen Tavernen zurück. Entspannter Service, größere Auswahl (Fisch). <strong>Winter:</strong> Wenige Optionen, Tavernen in den Dörfern im Landesinneren (Parthenonas) geöffnet. Warmer Ofen, Hauswein, winterliche Menüs.</p>`, ro: `<h2>Când să mergi</h2><p><strong>Vara:</strong> Weekend-urile din iulie-august, rezervarea este recomandată. În timpul săptămânii găsești ușor masă. <strong>Septembrie:</strong> Ideal — localnicii se întorc la tavernele tradiționale. Serviciu relaxat, varietate mai mare (pește). <strong>Iarna:</strong> Puține opțiuni, tavernele din satele interioare (Parthenonas) sunt deschise. Sobă caldă, vin de casă, meniuri de iarnă.</p>`, sr: `<h2>Kada posetiti</h2><p><strong>Leto:</strong> Vikendi u julu-avgustu, preporučuje se rezervacija. Radnim danima lako se nalazi sto. <strong>Septembar:</strong> Idealno — meštani se vraćaju u tradicionalne. Opuštena usluga, veći izbor (riba). <strong>Zima:</strong> Malo opcija, taverne u unutrašnjim selima (Parthenonas) otvorene. Topla peć, domaće vino, zimski meni.</p>`, bg: `<h2>Кога да отидете</h2><p><strong>Лято:</strong> Уикендите на юли-август, резервация се препоръчва. През седмицата лесно се намира маса. <strong>Септември:</strong> Идеално — местните се връщат в традиционните. Спокойно обслужване, по-голямо разнообразие (риба). <strong>Зима:</strong> Малко възможности, отворени са таверните в селата във вътрешността (Партенонас). Топла печка, домашно вино, зимни менюта.</p>`, ru: `<h2>Когда поехать</h2><p><strong>Лето:</strong> В выходные дни июля-августа рекомендуется бронирование. В будние дни столик можно получить легко. <strong>Сентябрь:</strong> Идеально — местные возвращаются в традиционные места. Расслабленное обслуживание, большее разнообразие (рыба). <strong>Зима:</strong> Небольшой выбор, открыты таверны в деревнях (Парфенон). Теплая печь, домашнее вино, зимнее меню.</p>` },
    tips: { el: `<h2>Συμβουλές για Σιθωνία γαστρονομία</h2><ul><li><strong>Πυργαδίκια:</strong> Παραθαλάσσιες ψαροταβέρνες, σχεδόν όλες ποιοτικές. Sunset δείπνο εξαιρετικό.</li><li><strong>Σάρτη:</strong> Παραλιακές ψαροταβέρνες με θέα Άθω. Φρέσκα ψάρια από καθημερινό ψάρεμα.</li><li><strong>Νικήτη παλιά:</strong> Πάνω από τη νέα Νικήτη — εστιατόρια με προδιάθεση στη γεωγραφική ιδιαιτερότητα του χωριού.</li><li><strong>Παρθενώνας:</strong> Ορεινό χωριό, παραδοσιακές ταβέρνες με κρέατα, τυριά, μεζέδες.</li><li><strong>Βουρβουρού:</strong> Πιο cosmopolitan, sea-view εστιατόρια με θέα στα νησάκια. Πιο pricey.</li><li><strong>Καλαμίτσι:</strong> Παραδοσιακό, ποιοτικά, σπιτικά γλυκά.</li></ul>`, en: `<h2>Tips for Sithonia gastronomy</h2><ul><li><strong>Pyrgadikia:</strong> Seafront seafood tavernas, almost all high quality. Sunset dinner is exceptional.</li><li><strong>Sarti:</strong> Beachfront seafood tavernas with views of Mount Athos. Fresh fish from daily catch.</li><li><strong>Old Nikiti:</strong> Above new Nikiti — restaurants leaning into the village's geographic character.</li><li><strong>Parthenonas:</strong> Mountain village, traditional tavernas with meats, cheeses, meze.</li><li><strong>Vourvourou:</strong> More cosmopolitan, sea-view restaurants over the islets. Pricier.</li><li><strong>Kalamitsi:</strong> Traditional, high quality, homemade desserts.</li></ul>`, de: `<h2>Tipps für die Gastronomie in Sithonia</h2><ul><li><strong>Pyrgadikia:</strong> Fisch-Tavernen am Meer, fast alle von hoher Qualität. Sonnenuntergangs-Dinner hervorragend.</li><li><strong>Sarti:</strong> Strandnahe Fisch-Tavernen mit Blick auf den Athos. Frischer Fisch aus täglichem Fang.</li><li><strong>Altes Nikiti:</strong> Oberhalb des neuen Nikiti — Restaurants mit Fokus auf die geografische Besonderheit des Dorfes.</li><li><strong>Parthenonas:</strong> Bergdorf, traditionelle Tavernen mit Fleisch, Käse, Mezedes.</li><li><strong>Vourvourou:</strong> Mehr kosmopolitisch, Restaurants mit Meerblick auf die Inselchen. Teurer.</li><li><strong>Kalamitsi:</strong> Traditionell, qualitativ, hausgemachte Süßigkeiten.</li></ul>`, ro: `<h2>Sfaturi pentru gastronomia din Sithonia</h2><ul><li><strong>Pyrgadikia:</strong> Taverne pescărești pe malul mării, aproape toate de calitate. Cină la apus excelentă.</li><li><strong>Sarti:</strong> Taverne pescărești pe plajă cu vedere la Muntele Athos. Pește proaspăt din pescuitul zilnic.</li><li><strong>Nikiti veche:</strong> Deasupra noii Nikiti — restaurante cu predispoziție pentru particularitatea geografică a satului.</li><li><strong>Parthenonas:</strong> Sat montan, taverne tradiționale cu carne, brânzeturi, meze.</li><li><strong>Vourvourou:</strong> Mai cosmopolit, restaurante cu vedere la mare și insulițe. Mai scump.</li><li><strong>Kalamitsi:</strong> Tradițional, calitate, dulciuri de casă.</li></ul>`, sr: `<h2>Saveti za gastronomiju Sitonije</h2><ul><li><strong>Pirgadikia:</strong> Riblje taverne uz obalu, gotovo sve kvalitetne. Večera uz zalazak sunca je izvanredna.</li><li><strong>Sarti:</strong> Riblje taverne na plaži s pogledom na Atos. Sveža riba iz svakodnevnog ribolova.</li><li><strong>Stari Nikiti:</strong> Iznad novog Nikitija — restorani s naglaskom na geografsku posebnost sela.</li><li><strong>Parthenonas:</strong> Planinsko selo, tradicionalne taverne s mesom, sirom, mezetlucima.</li><li><strong>Vourvourou:</strong> Više kosmopolitski, restorani s pogledom na more i ostrvca. Više cene.</li><li><strong>Kalamitsi:</strong> Tradicionalno, kvalitetno, domaći slatkiši.</li></ul>`, bg: `<h2>Съвети за гастрономията на Ситония</h2><ul><li><strong>Пиргадики:</strong> Рибни таверни на брега, почти всички са качествени. Вечеря на залез е отлична.</li><li><strong>Сарти:</strong> Рибни таверни на плажа с гледка към Света гора. Прясна риба от ежедневен улов.</li><li><strong>Старо Никити:</strong> Над новото Никити — ресторанти с предразположение към географската особеност на селото.</li><li><strong>Партенонас:</strong> Планинско село, традиционни таверни с меса, сирена, мезета.</li><li><strong>Вурвуру:</strong> По-космополитно, ресторанти с изглед към морето и островчетата. По-скъпо.</li><li><strong>Каламици:</strong> Традиционно, качествени, домашни сладкиши.</li></ul>`, ru: `<h2>Советы по гастрономии Ситонии</h2><ul><li><strong>Пиргадики:</strong> Прибрежные рыбные таверны, почти все качественные. Ужин на закате — отличный.</li><li><strong>Сарти:</strong> Прибрежные рыбные таверны с видом на Афон. Свежая рыба из ежедневного улова.</li><li><strong>Старый Никити:</strong> Выше нового Никити — рестораны с акцентом на географическую особенность деревни.</li><li><strong>Парфенон:</strong> Горная деревня, традиционные таверны с мясом, сыром, мезе.</li><li><strong>Вурвуру:</strong> Более космополитичный, рестораны с видом на море и островки. Более дорогие.</li><li><strong>Каламити:</strong> Традиционные, качественные, домашние сладости.</li></ul>` },
    faqs: [
      { q: { el: `Που να φάω καλύτερα στη Σιθωνία;`, en: `Where to eat best in Sithonia?`, de: `Wo kann ich am besten in Sithonia essen?`, ro: `Unde să mănânc cel mai bine în Sithonia?`, sr: `Gde najbolje jesti u Sitoniji?`, bg: `Къде да ям най-добре в Ситония?`, ru: `Где лучше поесть в Ситонии?` }, a: { el: `Για ψαρομεζέδες: <strong>Πυργαδίκια</strong> ή <strong>Σάρτη</strong>. Για παραδοσιακό: <strong>Παρθενώνας</strong> ή <strong>Καλαμίτσι</strong>. Για premium θέα: <strong>Βουρβουρού</strong>. Δες όλες σε αυτή τη λίστα φιλτραρισμένες κατά rating.`, en: `For seafood meze: <strong>Pyrgadikia</strong> or <strong>Sarti</strong>. For traditional: <strong>Parthenonas</strong> or <strong>Kalamitsi</strong>. For premium view: <strong>Vourvourou</strong>. See all in this list sorted by rating.`, de: `Für Fisch-Mezedes: <strong>Pyrgadikia</strong> oder <strong>Sarti</strong>. Für traditionell: <strong>Parthenonas</strong> oder <strong>Kalamitsi</strong>. Für Premium-Aussicht: <strong>Vourvourou</strong>. Sieh dir alle in dieser nach Bewertung gefilterten Liste an.`, ro: `Pentru meze de pește: <strong>Pyrgadikia</strong> sau <strong>Sarti</strong>. Pentru tradițional: <strong>Parthenonas</strong> sau <strong>Kalamitsi</strong>. Pentru vedere premium: <strong>Vourvourou</strong>. Vezi toate în această listă filtrate după rating.`, sr: `Za riblje mezetluke: <strong>Pirgadikia</strong> ili <strong>Sarti</strong>. Za tradicionalno: <strong>Parthenonas</strong> ili <strong>Kalamitsi</strong>. Za premium pogled: <strong>Vourvourou</strong>. Pogledajte sve na ovoj listi filtrirane po oceni.`, bg: `За рибни мезета: <strong>Пиргадики</strong> или <strong>Сарти</strong>. За традиционно: <strong>Партенонас</strong> или <strong>Каламици</strong>. За премиум гледка: <strong>Вурвуру</strong>. Виж всички в този списък, филтрирани по рейтинг.`, ru: `Для рыбных закусок: <strong>Пиргадики</strong> или <strong>Сарти</strong>. Для традиционной кухни: <strong>Парфенон</strong> или <strong>Каламити</strong>. Для премиального вида: <strong>Вурвуру</strong>. Смотрите все в этом списке, отфильтрованном по рейтингу.` } },
      { q: { el: `Σιθωνία vs Κασσάνδρα για φαγητό;`, en: `Sithonia vs Kassandra for food?`, de: `Sithonia vs. Kassandra zum Essen?`, ro: `Sithonia vs Kassandra pentru mâncare?`, sr: `Sitonija vs Kasandra za hranu?`, bg: `Ситония срещу Касандра за храна?`, ru: `Ситония vs Кассандра для еды?` }, a: { el: `<strong>Σιθωνία:</strong> Πιο αυθεντικό, φρέσκα ψαρικά, χαλαρή ατμόσφαιρα. <strong>Κασσάνδρα:</strong> Μεγαλύτερη ποικιλία, διεθνές cuisine, πιο πολυσύχναστα. Δες και τα <a href="/best/restaurants-kassandra">εστιατόρια Κασσάνδρας</a>.`, en: `<strong>Sithonia:</strong> More authentic, fresh seafood, relaxed atmosphere. <strong>Kassandra:</strong> Wider variety, international cuisine, more crowded. See <a href="/best/restaurants-kassandra">Kassandra restaurants</a> too.`, de: `<strong>Sithonia:</strong> Authentischer, frische Meeresfrüchte, entspannte Atmosphäre. <strong>Kassandra:</strong> Größere Vielfalt, internationale Küche, belebter. Sieh dir auch die <a href="/best/restaurants-kassandra">Restaurants in Kassandra</a> an.`, ro: `<strong>Sithonia:</strong> Mai autentic, pește proaspăt, atmosferă relaxată. <strong>Kassandra:</strong> Mai mare varietate, bucătărie internațională, mai aglomerat. Vezi și <a href="/best/restaurants-kassandra">restaurantele din Kassandra</a>.`, sr: `<strong>Sitonija:</strong> Autentičnije, sveža riba, opuštena atmosfera. <strong>Kasandra:</strong> Veći izbor, međunarodna kuhinja, više gužve. Pogledajte i <a href="/best/restaurants-kassandra">restorane Kasandre</a>.`, bg: `<strong>Ситония:</strong> По-автентично, прясна риба, спокойна атмосфера. <strong>Касандра:</strong> По-голямо разнообразие, международна кухня, по-оживено. Виж и <a href="/best/restaurants-kassandra">ресторантите на Касандра</a>.`, ru: `<strong>Ситония:</strong> Более аутентичная, свежая рыба, расслабленная атмосфера. <strong>Кассандра:</strong> Больший выбор, международная кухня, более оживленно. Смотрите также <a href="/best/restaurants-kassandra">рестораны Кассандры</a>.` } },
      { q: { el: `Είναι ανοιχτές οι ταβέρνες χειμώνα;`, en: `Are tavernas open in winter?`, de: `Sind die Tavernen im Winter geöffnet?`, ro: `Sunt deschise tavernele iarna?`, sr: `Da li su taverne otvorene zimi?`, bg: `Отворени ли са таверните през зимата?`, ru: `Открыты ли таверны зимой?` }, a: { el: `Στα παραθαλάσσια — όχι ή ελάχιστα. Στα εσωτερικά χωριά (Παρθενώνας, Καλαμίτσι) ναι, και έχουν ωραία χειμωνιάτικη ατμόσφαιρα με σόμπα.`, en: `Seafront — no or very few. Inland villages (Parthenonas, Kalamitsi) yes, with a nice winter atmosphere around the stove.`, de: `An der Küste — nein oder nur wenige. In den Dörfern im Landesinneren (Parthenonas, Kalamitsi) ja, und sie haben eine schöne winterliche Atmosphäre mit Ofen.`, ro: `În zonele de coastă — nu sau foarte puțin. În satele interioare (Parthenonas, Kalamitsi) da, și au o atmosferă de iarnă plăcută cu sobă.`, sr: `Na obali — ne ili vrlo malo. U unutrašnjim selima (Parthenonas, Kalamitsi) da, i imaju lepu zimsku atmosferu s peći.`, bg: `На брега — не или много малко. Във вътрешните села (Партенонас, Каламици) да, и имат приятна зимна атмосфера с печка.`, ru: `В прибрежных районах — нет или очень мало. В внутренних деревнях (Парфенон, Каламити) да, и у них приятная зимняя атмосфера с печью.` } },
    ],
  },
  "free-beaches": {
    intro: { el: `<p>Ελεύθερες παραλίες — χωρίς ξαπλώστρες, χωρίς beach bar, χωρίς οργανωμένη λειτουργία. Στρώνεις την πετσέτα σου, βάζεις τη σκιά σου, και χαλαρώνεις χωρίς κανονικά να ξοδεύεις τίποτα. Στη Χαλκιδική, αυτές οι παραλίες είναι συνήθως ή απομονωμένες (Καβουρότρυπες, διαπόρου, μικρές παραλίες Σιθωνίας) ή απλώς λιγότερο διαφημισμένες. Πολλές έχουν τα καθαρότερα νερά και την πιο αυθεντική εμπειρία. Αυτή η λίστα συγκεντρώνει τις παραλίες που χαρακτηρίζονται "free" στη βάση μας — μπορείς να στρώσεις όπου θες, χωρίς πληρωμή.</p>`, en: `<p>Free beaches — no loungers, no beach bar, no organised setup. Spread your towel, set up your shade, and relax without spending anything. In Halkidiki these beaches are usually either isolated (Kavourotrypes, Diaporos, small Sithonia beaches) or simply less advertised. Many have the cleanest water and most authentic experience. This list collects beaches tagged as "free" in our database — you can spread out anywhere without paying.</p>`, de: `<p>Freie Strände — ohne Liegen, ohne Beach Bar, ohne organisierte Einrichtungen. Du legst dein Handtuch aus, suchst dir einen schattigen Platz und entspannst, ohne tatsächlich Geld auszugeben. In Chalkidiki sind diese Strände meist entweder abgelegen (Kavourotrypes, Diaporos, kleine Strände von Sithonia) oder einfach weniger beworben. Viele haben das sauberste Wasser und bieten das authentischste Erlebnis. Diese Liste fasst die Strände zusammen, die in unserer Datenbank als "frei" gekennzeichnet sind — du kannst dich hinlegen, wo du möchtest, ohne zu bezahlen.</p>`, ro: `<p>Plaje libere — fără șezlonguri, fără beach bar, fără facilități organizate. Îți așezi prosopul, îți pui umbra și te relaxezi fără să cheltuiești nimic în mod normal. În Halkidiki, aceste plaje sunt de obicei fie izolate (Kavourotrypes, Diaporos, plaje mici din Sithonia) fie pur și simplu mai puțin promovate. Multe dintre ele au cele mai curate ape și oferă cea mai autentică experiență. Această listă reunește plajele care sunt caracterizate ca "libere" în baza noastră de date — poți să te așezi unde vrei, fără plată.</p>`, sr: `<p>Slobodne plaže — bez ležaljki, bez beach bar-a, bez organizovanih sadržaja. Postaviš svoj peškir, napraviš sebi hladovinu i opuštaš se bez potrebe da trošiš novac. U Halkidikiju, ove plaže su obično ili izolovane (Kavourotrypes, Diaporos, male plaže Sitonije) ili jednostavno manje reklamirane. Mnoge od njih imaju najčistiju vodu i najautentičnije iskustvo. Ova lista okuplja plaže koje su označene kao "slobodne" u našoj bazi — možeš se smestiti gde želiš, bez plaćanja.</p>`, bg: `<p>Свободни плажове — без шезлонги, без beach bar, без организирана дейност. Разстилаш си кърпата, слагаш си сянката и релаксираш, без да харчиш нищо. В Халкидики тези плажове обикновено са или изолирани (Кавуротрипес, Диапорос, малки плажове на Ситония) или просто по-малко рекламирани. Много от тях имат най-чистите води и най-автентичното изживяване. Този списък събира плажовете, които се характеризират като "свободни" в нашата база — можеш да се разположиш където искаш, без заплащане.</p>`, ru: `<p>Свободные пляжи — без шезлонгов, без beach bar, без организованной инфраструктуры. Расстилаешь полотенце, находишь тень и расслабляешься, не тратя практически ничего. На Халкидиках такие пляжи обычно либо изолированы (Кавуротропис, Диапорос, маленькие пляжи Ситонии), либо просто менее рекламируемы. Многие из них имеют самую чистую воду и предлагают наиболее аутентичный опыт. Этот список собирает пляжи, которые в нашей базе данных отмечены как "свободные" — можно расположиться где угодно, без оплаты.</p>` },
    seasonal: { el: `<h2>Πότε να πας</h2><p><strong>Όλο τον χρόνο σχεδόν:</strong> Αυτές οι παραλίες δεν γεμίζουν ποτέ. Μόνη εξαίρεση: τα γνωστά Καβουρότρυπες/Orange Beach γεμίζουν 9-12 Σαββατοκύριακα Ιουλίου-Αυγούστου. <strong>Καλύτερη εποχή:</strong> Μάιος-Ιούνιος και Σεπτέμβριος-Οκτώβριος — έχεις την παραλία σχεδόν για εσάς. <strong>Ωραίος καιρός χωρίς κόσμο:</strong> Καθημερινές Σεπτεμβρίου είναι το απόλυτο sweet spot.</p>`, en: `<h2>When to visit</h2><p><strong>Almost year-round:</strong> These beaches never really fill up. The only exception: the famous Kavourotrypes/Orange Beach fills up 9-12 on July-August weekends. <strong>Best season:</strong> May-June and September-October — you basically have the beach to yourself. <strong>Nice weather without crowds:</strong> September weekdays are the absolute sweet spot.</p>`, de: `<h2>Wann man hingehen sollte</h2><p><strong>Fast das ganze Jahr über:</strong> Diese Strände sind nie überfüllt. Einzige Ausnahme: Die bekannten Kavourotrypes/Orange Beach sind an den Wochenenden von Juli bis August von 9 bis 12 Uhr voll. <strong>Beste Zeit:</strong> Mai-Juni und September-Oktober — du hast den Strand fast für dich allein. <strong>Schönes Wetter ohne Menschenmassen:</strong> Die Wochentage im September sind der absolute Sweet Spot.</p>`, ro: `<h2>Când să mergi</h2><p><strong>Aproape tot anul:</strong> Aceste plaje nu se aglomerează niciodată. Singura excepție: cunoscutele Kavourotrypes/Orange Beach se aglomerează în weekendurile din iulie-august. <strong>Cea mai bună perioadă:</strong> Mai-iunie și septembrie-octombrie — ai plaja aproape doar pentru tine. <strong>Vreme frumoasă fără mulțimi:</strong> Zilele lucrătoare din septembrie sunt momentul ideal.</p>`, sr: `<h2>Kada posetiti</h2><p><strong>Gotovo tokom cele godine:</strong> Ove plaže nikada nisu pretrpane. Jedini izuzetak: poznate Kavourotrypes/Orange Beach su pune 9-12 vikenda u julu-avgustu. <strong>Najbolje vreme:</strong> Maj-jun i septembar-oktobar — plaža je gotovo samo tvoja. <strong>Lepo vreme bez gužve:</strong> Radni dani u septembru su apsolutni sweet spot.</p>`, bg: `<h2>Кога да отидеш</h2><p><strong>Почти през цялата година:</strong> Тези плажове никога не се пълнят. Единствено изключение: известните Кавуротрипес/Orange Beach се пълнят 9-12 уикенда през юли-август. <strong>Най-добро време:</strong> Май-юни и септември-октомври — имаш плажа почти за себе си. <strong>Хубаво време без тълпи:</strong> Дните през седмицата през септември са абсолютното "sweet spot".</p>`, ru: `<h2>Когда поехать</h2><p><strong>Почти круглый год:</strong> Эти пляжи никогда не переполнены. Единственное исключение: известные Кавуротропис/Orange Beach переполнены в выходные с июля по август. <strong>Лучшее время:</strong> Май-июнь и сентябрь-октябрь — пляж практически в вашем распоряжении. <strong>Прекрасная погода без толпы:</strong> Будние дни сентября — это идеальное время.</p>` },
    tips: { el: `<h2>Πρακτικές συμβουλές για ελεύθερες παραλίες</h2><ul><li><strong>Πάρε τα πάντα:</strong> Νερό (τουλάχιστον 2L/άτομο), σνακ, ομπρέλα, αντηλιακό. Δεν υπάρχει καντίνα.</li><li><strong>Καθαριότητα:</strong> Σακούλα για σκουπίδια — πάρε τα μαζί σου. Αυτές οι παραλίες διατηρούνται καθαρές γιατί οι επισκέπτες σέβονται.</li><li><strong>Parking:</strong> Σε ορισμένες (Καβουρότρυπες) είναι μακριά + 5-15' περπάτημα. Παπούτσια κατάλληλα.</li><li><strong>Snorkeling:</strong> Οι ελεύθερες παραλίες έχουν συχνά τα καθαρότερα νερά. Δες τις <a href="/best/snorkeling-spots">καλύτερες snorkeling παραλίες</a>.</li><li><strong>Σκιά:</strong> Συνήθως πεύκα προσφέρουν φυσική σκιά — αλλά όχι παντού. Φέρε ομπρέλα ή tarp.</li><li><strong>Σήμα κινητού:</strong> Σε απομονωμένες περιοχές μπορεί να μην έχει — ενημέρωσε κάποιον πού πας.</li></ul>`, en: `<h2>Practical tips for free beaches</h2><ul><li><strong>Bring everything:</strong> Water (at least 2L/person), snacks, umbrella, sunscreen. No canteen.</li><li><strong>Cleanliness:</strong> Pack a rubbish bag — take it with you. These beaches stay clean because visitors respect them.</li><li><strong>Parking:</strong> Some (Kavourotrypes) need a 5-15-min walk. Bring suitable shoes.</li><li><strong>Snorkelling:</strong> Free beaches often have the clearest water. See our <a href="/best/snorkeling-spots">best snorkelling beaches</a>.</li><li><strong>Shade:</strong> Pine trees usually provide natural shade — but not everywhere. Bring an umbrella or tarp.</li><li><strong>Mobile signal:</strong> May be patchy in isolated spots — tell someone where you're going.</li></ul>`, de: `<h2>Praktische Tipps für freie Strände</h2><ul><li><strong>Nimm alles mit:</strong> Wasser (mindestens 2L/Person), Snacks, Sonnenschirm, Sonnencreme. Es gibt keinen Kiosk.</li><li><strong>Sauberkeit:</strong> Müllbeutel — nimm deinen Müll mit. Diese Strände bleiben sauber, weil die Besucher respektvoll sind.</li><li><strong>Parking:</strong> Bei einigen (Kavourotrypes) ist es weit entfernt + 5-15 Minuten zu Fuß. Geeignetes Schuhwerk.</li><li><strong>Snorkeling:</strong> Die freien Strände haben oft das sauberste Wasser. Siehe die <a href="/best/snorkeling-spots">besten Strände zum Schnorcheln</a>.</li><li><strong>Schatten:</strong> Normalerweise bieten Kiefern natürlichen Schatten — aber nicht überall. Bring einen Sonnenschirm oder eine Plane mit.</li><li><strong>Mobilfunksignal:</strong> In abgelegenen Gebieten kann es keines geben — informiere jemanden, wohin du gehst.</li></ul>`, ro: `<h2>Sfaturi practice pentru plaje libere</h2><ul><li><strong>Adu totul:</strong> Apă (cel puțin 2L/persoană), gustări, umbrelă, cremă de protecție solară. Nu există cantină.</li><li><strong>Curățenie:</strong> Sac pentru gunoi — ia-le cu tine. Aceste plaje se mențin curate pentru că vizitatorii respectă.</li><li><strong>Parking:</strong> La unele (Kavourotrypes) este departe + 5-15' de mers pe jos. Încălțăminte adecvată.</li><li><strong>Snorkeling:</strong> Plajele libere au adesea cele mai curate ape. Vezi <a href="/best/snorkeling-spots">cele mai bune plaje pentru snorkeling</a>.</li><li><strong>Umbră:</strong> De obicei, pini oferă umbră naturală — dar nu peste tot. Adu o umbrelă sau un tarp.</li><li><strong>Semnal mobil:</strong> În zonele izolate poate să nu fie — informează pe cineva unde mergi.</li></ul>`, sr: `<h2>Praktični saveti za slobodne plaže</h2><ul><li><strong>Ponesi sve:</strong> Vodu (najmanje 2L/osobi), grickalice, suncobran, kremu za sunčanje. Nema kantine.</li><li><strong>Čistoća:</strong> Kesa za smeće — ponesi ga sa sobom. Ove plaže ostaju čiste jer ih posetioci poštuju.</li><li><strong>Parking:</strong> Na nekima (Kavourotrypes) je udaljen + 5-15' hoda. Prikladna obuća.</li><li><strong>Snorkeling:</strong> Slobodne plaže često imaju najčistiju vodu. Pogledaj <a href="/best/snorkeling-spots">najbolje snorkeling plaže</a>.</li><li><strong>Hladovina:</strong> Obično borovi pružaju prirodnu hladovinu — ali ne svuda. Ponesi suncobran ili tarp.</li><li><strong>Signal mobilnog:</strong> U izolovanim područjima možda nema signala — obavesti nekoga gde ideš.</li></ul>`, bg: `<h2>Практични съвети за свободни плажове</h2><ul><li><strong>Вземи всичко необходимо:</strong> Вода (поне 2L/човек), закуски, чадър, слънцезащитен крем. Няма кантина.</li><li><strong>Чистота:</strong> Торба за боклук — вземи ги с теб. Тези плажове се поддържат чисти, защото посетителите ги уважават.</li><li><strong>Parking:</strong> На някои (Кавуротрипес) е далеч + 5-15' пеша. Подходящи обувки.</li><li><strong>Snorkeling:</strong> Свободните плажове често имат най-чистите води. Виж <a href="/best/snorkeling-spots">най-добрите плажове за snorkeling</a>.</li><li><strong>Сянка:</strong> Обикновено борове предлагат естествена сянка — но не навсякъде. Вземи чадър или tarp.</li><li><strong>Сигнал на мобилен:</strong> В изолирани райони може да няма — информирай някого къде отиваш.</li></ul>`, ru: `<h2>Практические советы для свободных пляжей</h2><ul><li><strong>Возьмите все необходимое:</strong> Вода (не менее 2 л/чел), закуски, зонтик, солнцезащитный крем. Кафе нет.</li><li><strong>Чистота:</strong> Пакет для мусора — заберите его с собой. Эти пляжи остаются чистыми, потому что посетители уважают их.</li><li><strong>Parking:</strong> На некоторых (Кавуротропис) парковка далеко + 5-15 минут пешком. Подходящая обувь.</li><li><strong>Snorkeling:</strong> Свободные пляжи часто имеют самую чистую воду. Смотрите <a href="/best/snorkeling-spots">лучшие пляжи для снорклинга</a>.</li><li><strong>Тень:</strong> Обычно сосны предоставляют естественную тень — но не везде. Возьмите зонтик или тент.</li><li><strong>Сотовая связь:</strong> В изолированных районах может отсутствовать — сообщите кому-то, куда вы направляетесь.</li></ul>` },
    faqs: [
      { q: { el: `Είναι όλες οι παραλίες Χαλκιδικής ελεύθερες;`, en: `Are all Halkidiki beaches free?`, de: `Sind alle Strände in Chalkidiki frei?`, ro: `Sunt toate plajele din Halkidiki libere?`, sr: `Da li su sve plaže u Halkidikiju slobodne?`, bg: `Всички плажове в Халкидики ли са свободни?`, ru: `Все ли пляжи Халкидик свободные?` }, a: { el: `Νομικά ναι — όλες οι ακτές είναι δημόσιες στην Ελλάδα. Στην πράξη, οι "οργανωμένες" παραλίες έχουν ξαπλώστρες/ομπρέλες (€8-15 σετ/μέρα). Σε αυτή τη λίστα συγκεντρώνουμε τις πλήρως φυσικές, χωρίς οργανωμένη λειτουργία.`, en: `Legally yes — all coast is public in Greece. In practice, "organised" beaches have loungers/umbrellas (€8-15 set/day). This list collects fully natural beaches without organised facilities.`, de: `Rechtlich ja — alle Küsten sind in Griechenland öffentlich. In der Praxis haben die "organisierten" Strände Liegen/Sonnenschirme (€8-15 Set/Tag). In dieser Liste sammeln wir die vollständig natürlichen Strände ohne organisierte Einrichtungen.`, ro: `Legal da — toate țărmurile sunt publice în Grecia. În practică, plajele "organizate" au șezlonguri/umbrele (€8-15 set/zi). În această listă reunim plajele complet naturale, fără facilități organizate.`, sr: `Pravno da — sve obale su javne u Grčkoj. U praksi, "organizovane" plaže imaju ležaljke/suncobrane (€8-15 set/dan). Na ovoj listi okupljamo potpuno prirodne, bez organizovanih sadržaja.`, bg: `Юридически да — всички брегове в Гърция са обществени. На практика, "организираните" плажове имат шезлонги/чадъри (€8-15 комплект/ден). В този списък събираме напълно естествените, без организирана дейност.`, ru: `Юридически да — все побережья в Греции являются общественными. На практике "организованные" пляжи имеют шезлонги/зонтики (€8-15 комплект/день). В этом списке мы собираем полностью природные, без организованной инфраструктуры.` } },
      { q: { el: `Πιο καλό για ησυχία ελεύθερες ή ήσυχες;`, en: `Better for peace: free or quiet beaches?`, de: `Was ist besser für Ruhe: freie oder ruhige Strände?`, ro: `Ce este mai bine pentru liniște, plaje libere sau liniștite?`, sr: `Šta je bolje za mir, slobodne ili mirne plaže?`, bg: `Кое е по-добро за спокойствие — свободни или тихи плажове?`, ru: `Что лучше для тишины — свободные или тихие пляжи?` }, a: { el: `Πολλές <a href="/best/quiet-beaches">ήσυχες παραλίες</a> είναι ταυτόχρονα ελεύθερες. Διαφορά: "ελεύθερες" είναι χωρίς υποδομές. "Ήσυχες" είναι χωρίς πολυκοσμία (μπορεί να έχουν beach bar χωρίς να γεμίζουν).`, en: `Many <a href="/best/quiet-beaches">quiet beaches</a> are also free. Difference: "free" means no facilities. "Quiet" means no crowds (may have a beach bar that doesn't fill up).`, de: `Viele <a href="/best/quiet-beaches">ruhige Strände</a> sind gleichzeitig frei. Unterschied: "freie" Strände sind ohne Infrastruktur. "Ruhige" Strände sind ohne Menschenmassen (können Beach Bars haben, ohne voll zu werden).`, ro: `Multe <a href="/best/quiet-beaches">plaje liniștite</a> sunt și libere. Diferența: "libere" sunt fără infrastructură. "Liniștite" sunt fără aglomerație (pot avea beach bar fără să se aglomereze).`, sr: `Mnoge <a href="/best/quiet-beaches">mirne plaže</a> su istovremeno slobodne. Razlika: "slobodne" su bez infrastrukture. "Mirne" su bez gužve (mogu imati beach bar a da nisu pretrpane).`, bg: `Много <a href="/best/quiet-beaches">тихи плажове</a> са едновременно и свободни. Разлика: "свободни" са без инфраструктура. "Тихи" са без много хора (може да имат beach bar, без да се пълнят).`, ru: `Многие <a href="/best/quiet-beaches">тихие пляжи</a> одновременно являются свободными. Разница: "свободные" — без инфраструктуры. "Тихие" — без толпы (могут иметь beach bar, но не переполняются).` } },
      { q: { el: `Είναι ασφαλές να αφήσω πράγματα όταν κολυμπώ;`, en: `Is it safe to leave belongings while swimming?`, de: `Ist es sicher, Sachen am Strand zu lassen, wenn ich schwimme?`, ro: `Este sigur să-mi las lucrurile când înot?`, sr: `Da li je bezbedno ostaviti stvari dok plivam?`, bg: `Безопасно ли е да оставя неща, когато плувам?`, ru: `Безопасно ли оставлять вещи, когда купаешься?` }, a: { el: `Η Χαλκιδική έχει χαμηλό crime rate — οι κλοπές σε παραλίες είναι σπάνιες αλλά δεν εκμηδενίζονται. Άσε ομαδική τσάντα με 1 άτομο, ή έχε waterproof pouch με κινητό/χρήματα μαζί σου στο νερό.`, en: `Halkidiki has a low crime rate — beach thefts are rare but not zero. Leave a group bag with one person, or carry a waterproof pouch with phone/cash into the water.`, de: `Chalkidiki hat eine niedrige Kriminalitätsrate — Diebstähle an Stränden sind selten, aber nicht ausgeschlossen. Lass eine Gruppentasche bei einer Person, oder nimm eine wasserdichte Tasche mit Handy/Geld mit ins Wasser.`, ro: `Halkidiki are o rată scăzută a criminalității — furturile pe plaje sunt rare, dar nu inexistente. Lasă o geantă de grup cu o persoană sau poartă un pouch waterproof cu telefonul/banii la tine în apă.`, sr: `Halkidiki ima nisku stopu kriminala — krađe na plažama su retke, ali nisu nemoguće. Ostavite grupnu torbu sa jednom osobom, ili nosite vodootpornu torbicu sa mobilnim/novcem sa sobom u vodu.`, bg: `Халкидики има нисък процент на престъпност — кражбите на плажове са редки, но не и невъзможни. Остави групова чанта с 1 човек или носи водоустойчива торбичка с телефон/пари с теб във водата.`, ru: `На Халкидиках низкий уровень преступности — кражи на пляжах редки, но не исключены. Оставьте сумку с одним человеком или возьмите с собой в воду водонепроницаемый чехол с телефоном/деньгами.` } },
    ],
  },
  "hiking-trails": {
    intro: { el: `<p>Η Χαλκιδική δεν είναι μόνο παραλίες — πίσω από την ακτογραμμή απλώνεται ένα πευκόδασος που καλύπτει σχεδόν όλο το εσωτερικό. Οι χερσόνησοι έχουν χαμηλά βουνά (Ίταμος στη Σιθωνία, Κασσάνδρα ορεινή), μονοπάτια προς ξωκλήσια, βυζαντινούς πύργους και κρυμμένα μικρά μπαλκόνια θέας. Το διασημότερο πεζοπορικό δίκτυο είναι το <strong>Aristotle Trail</strong> — οδική σήμανση που συνδέει χωριά της ορεινής Χαλκιδικής με μοναστήρια του Αγίου Όρους. Αυτή η λίστα συγκεντρώνει τις πεζοπορικές διαδρομές και τα ορεινά αξιοθέατα με τις υψηλότερες αξιολογήσεις.</p>`, en: `<p>Halkidiki isn't only beaches — behind the coastline stretches a pine forest covering almost the entire inland. The peninsulas have low mountains (Itamos in Sithonia, mountainous Kassandra), trails to chapels, Byzantine towers and hidden viewpoints. The most famous hiking network is the <strong>Aristotle Trail</strong> — signed routes connecting mountain villages with Mount Athos monasteries. This list collects the highest-rated hiking routes and mountain attractions.</p>`, de: `<p>Chalkidiki ist nicht nur Strände — hinter der Küstenlinie erstreckt sich ein Pinienwald, der fast das gesamte Landesinnere bedeckt. Die Halbinseln haben niedrige Berge (Itamos in Sithonia, das Bergland von Kassandra), Pfade zu Kapellen, byzantinische Türme und versteckte kleine Aussichtsbalkone. Das berühmteste Wanderwegenetz ist der <strong>Aristotle Trail</strong> — eine Wegmarkierung, die die Dörfer des Berglands von Chalkidiki mit den Klöstern des Berg Athos verbindet. Diese Liste fasst die Wanderwege und Bergattraktionen mit den höchsten Bewertungen zusammen.</p>`, ro: `<p>Halkidiki nu înseamnă doar plaje — în spatele liniei de coastă se întinde o pădure de pini care acoperă aproape tot interiorul. Peninsulele au munți joși (Itamos în Sithonia, Kassandra montană), poteci către capele, turnuri bizantine și mici balcoane ascunse cu priveliști. Cea mai faimoasă rețea de drumeții este <strong>Traseul lui Aristotel</strong> — o semnalizare rutieră care leagă satele din Halkidiki montană de mănăstirile de pe Muntele Athos. Această listă adună traseele de drumeții și atracțiile montane cu cele mai bune evaluări.</p>`, sr: `<p>Halkidiki nije samo plaže — iza obale se prostire borova šuma koja pokriva gotovo celu unutrašnjost. Poluostrva imaju niska brda (Itamos na Sitoniji, planinska Kasandra), staze ka kapelama, vizantijske kule i skrivene male vidikovce. Najpoznatija mreža pešačkih staza je <strong>Aristotelova staza</strong> — putokazi koji povezuju sela planinske Halkidiki sa manastirima Svete Gore. Ova lista okuplja pešačke rute i planinske atrakcije sa najvišim ocenama.</p>`, bg: `<p>Халкидики не е само плажове — зад крайбрежието се простира борова гора, която покрива почти цялата вътрешност. Полуостровите имат ниски планини (Итамос в Ситония, Касандра планинска), пътеки към параклиси, византийски кули и скрити малки балкони с изглед. Най-известната пешеходна мрежа е <strong>Aristotle Trail</strong> — пътна маркировка, която свързва селата на планинския Халкидики с манастирите на Света гора. Този списък събира пешеходните маршрути и планинските забележителности с най-високи оценки.</p>`, ru: `<p>Халкидики — это не только пляжи. За береговой линией простирается сосновый лес, который покрывает почти всю внутреннюю часть региона. Полуострова имеют невысокие горы (Итамос на Ситонии, горная Кассандра), тропы к часовням, византийские башни и скрытые маленькие смотровые площадки. Самая известная сеть пеших маршрутов — это <strong>Aristotle Trail</strong> — дорожная разметка, соединяющая деревни горной Халкидики с монастырями Афона. Этот список собирает пешие маршруты и горные достопримечательности с наивысшими оценками.</p>` },
    seasonal: { el: `<h2>Πότε να πεζοπορήσεις</h2><p><strong>Άνοιξη (Μάιος-Ιούνιος):</strong> Η ιδανική εποχή — δροσερός καιρός, λουλουδιασμένο τοπίο, καθαρή ορατότητα. <strong>Φθινόπωρο (Σεπτέμβριος-Νοέμβριος):</strong> Εξαιρετικά — χρώματα φύλλων, καμία βροχή, λιγότερος κόσμος. <strong>Καλοκαίρι (Ιούλιος-Αύγουστος):</strong> Πεζοπορία πρωί 7-10 ή αργά απόγευμα 17-19 — μεσημέρι 35°C+ επικίνδυνο. <strong>Χειμώνας:</strong> Δροσερά πρωινά, σπάνιο χιόνι στις κορυφές, καλύτερη ορατότητα.</p>`, en: `<h2>When to hike</h2><p><strong>Spring (May-June):</strong> Ideal — cool weather, blooming landscape, clear visibility. <strong>Autumn (September-November):</strong> Excellent — autumn colours, no rain, fewer people. <strong>Summer (July-August):</strong> Hike morning 7-10 or late afternoon 17-19 — midday 35°C+ is dangerous. <strong>Winter:</strong> Cool mornings, rare snow on peaks, best visibility.</p>`, de: `<h2>Wann man wandern sollte</h2><p><strong>Frühling (Mai-Juni):</strong> Die ideale Jahreszeit — kühles Wetter, blühende Landschaft, klare Sicht. <strong>Herbst (September-November):</strong> Hervorragend — Blattfarben, kein Regen, weniger Menschen. <strong>Sommer (Juli-August):</strong> Wandern am Morgen 7-10 oder am späten Nachmittag 17-19 — Mittag 35°C+ gefährlich. <strong>Winter:</strong> Kühle Morgen, selten Schnee auf den Gipfeln, bessere Sicht.</p>`, ro: `<h2>Când să faci drumeții</h2><p><strong>Primăvara (Mai-Iunie):</strong> Perioada ideală — vreme răcoroasă, peisaj înflorit, vizibilitate clară. <strong>Toamna (Septembrie-Noiembrie):</strong> Excelentă — culori ale frunzelor, fără ploi, mai puțină aglomerație. <strong>Vara (Iulie-August):</strong> Drumeții dimineața 7-10 sau după-amiaza târziu 17-19 — la prânz 35°C+ periculos. <strong>Iarna:</strong> Dimineți răcoroase, zăpadă rară pe vârfuri, vizibilitate mai bună.</p>`, sr: `<h2>Kada pešačiti</h2><p><strong>Proleće (maj-jun):</strong> Idealno vreme — sveže vreme, cvetni pejzaž, čista vidljivost. <strong>Jesen (septembar-novembar):</strong> Odlično — boje lišća, bez kiše, manje gužve. <strong>Leto (jul-avgust):</strong> Pešačenje ujutru 7-10 ili kasno popodne 17-19 — u podne 35°C+ opasno. <strong>Zima:</strong> Sveža jutra, retko sneg na vrhovima, bolja vidljivost.</p>`, bg: `<h2>Кога да се разхождате</h2><p><strong>Пролет (май-юни):</strong> Идеалният сезон — прохладно време, цветен пейзаж, ясна видимост. <strong>Есен (септември-ноември):</strong> Отлично — цветове на листата, без дъжд, по-малко хора. <strong>Лято (юли-август):</strong> Разходки сутрин 7-10 или късен следобед 17-19 — обед 35°C+ опасно. <strong>Зима:</strong> Прохладни утрини, рядък сняг по върховете, по-добра видимост.</p>`, ru: `<h2>Когда лучше всего отправляться в поход</h2><p><strong>Весна (май-июнь):</strong> Идеальное время — прохладная погода, цветущий пейзаж, ясная видимость. <strong>Осень (сентябрь-ноябрь):</strong> Отлично — цвета листьев, отсутствие дождей, меньше людей. <strong>Лето (июль-август):</strong> Походы утром 7-10 или поздно вечером 17-19 — в полдень 35°C+ опасно. <strong>Зима:</strong> Прохладные утра, редкий снег на вершинах, лучшая видимость.</p>` },
    tips: { el: `<h2>Συμβουλές για πεζοπορία στη Χαλκιδική</h2><ul><li><strong>Νερό:</strong> 2L/άτομο τουλάχιστον. Πηγές νερού υπάρχουν αλλά σπάνια.</li><li><strong>Παπούτσια:</strong> Πεζοπορικά παπούτσια με grip. Tα μονοπάτια έχουν πέτρες και βρύα.</li><li><strong>Aristotle Trail:</strong> Σηματοδοτημένο, χωρισμένο σε στάδια. Πλήρης διάβαση 2-3 ημέρες με διανυκτερεύσεις σε χωριά.</li><li><strong>Πιστοί δρομολόγια:</strong> Όχι offline maps μόνο — οι σηματοδοτήσεις είναι αξιόπιστες αλλά κάνε download χάρτη πριν.</li><li><strong>Σήμα κινητού:</strong> Αδύναμο σε ορεινά. Πες σε κάποιον πού πας.</li><li><strong>Φίδια:</strong> Σπάνια αλλά υπάρχουν. Μην σηκώνεις πέτρες, ψηλά παπούτσια.</li><li><strong>Συνδυασμός με beaches:</strong> Πρωινή πεζοπορία + μεσημέρι παραλία = ιδανικό. Δες τις <a href="/best/beaches-sithonia">παραλίες Σιθωνίας</a>.</li></ul>`, en: `<h2>Hiking tips for Halkidiki</h2><ul><li><strong>Water:</strong> At least 2L/person. Water sources exist but rare.</li><li><strong>Shoes:</strong> Hiking shoes with grip. Trails have rocks and moss.</li><li><strong>Aristotle Trail:</strong> Signed, divided into stages. Full crossing 2-3 days with overnight stops in villages.</li><li><strong>Trusted routes:</strong> Not offline maps only — signage is reliable but download a map beforehand.</li><li><strong>Mobile signal:</strong> Weak in the mountains. Tell someone where you're going.</li><li><strong>Snakes:</strong> Rare but exist. Don't lift rocks, wear ankle-high shoes.</li><li><strong>Combine with beaches:</strong> Morning hike + afternoon swim = ideal. See <a href="/best/beaches-sithonia">Sithonia beaches</a>.</li></ul>`, de: `<h2>Tipps für das Wandern in Chalkidiki</h2><ul><li><strong>Wasser:</strong> Mindestens 2L/Person. Wasserquellen gibt es, aber selten.</li><li><strong>Schuhe:</strong> Wanderschuhe mit Grip. Die Pfade sind steinig und moosig.</li><li><strong>Aristotle Trail:</strong> Markiert, in Etappen unterteilt. Gesamtdurchquerung 2-3 Tage mit Übernachtungen in Dörfern.</li><li><strong>Verlässliche Routen:</strong> Nicht nur Offline-Karten — die Markierungen sind zuverlässig, aber lade eine Karte vorher herunter.</li><li><strong>Handysignal:</strong> Schwach in den Bergen. Sag jemandem, wohin du gehst.</li><li><strong>Schlangen:</strong> Selten, aber vorhanden. Keine Steine heben, hohe Schuhe tragen.</li><li><strong>Kombination mit Stränden:</strong> Morgenwanderung + Mittag am Strand = ideal. Siehe die <a href="/best/beaches-sithonia">Strände von Sithonia</a>.</li></ul>`, ro: `<h2>Sfaturi pentru drumeții în Halkidiki</h2><ul><li><strong>Apă:</strong> 2L/persoană cel puțin. Există izvoare de apă, dar sunt rare.</li><li><strong>Încălțăminte:</strong> Pantofi de drumeție cu aderență. Potecile au pietre și mușchi.</li><li><strong>Traseul lui Aristotel:</strong> Semnalizat, împărțit în etape. Traversare completă 2-3 zile cu înnoptări în sate.</li><li><strong>Trasee sigure:</strong> Nu doar hărți offline — semnalizările sunt de încredere, dar descarcă harta înainte.</li><li><strong>Semnal mobil:</strong> Slab în zonele montane. Spune cuiva unde mergi.</li><li><strong>Șerpi:</strong> Rari, dar există. Nu ridica pietre, poartă încălțăminte înaltă.</li><li><strong>Combinare cu plaje:</strong> Drumeție de dimineață + plajă la prânz = ideal. Vezi <a href="/best/beaches-sithonia">plajele din Sithonia</a>.</li></ul>`, sr: `<h2>Saveti za pešačenje u Halkidikiju</h2><ul><li><strong>Voda:</strong> 2L/osobi najmanje. Izvori vode postoje ali su retki.</li><li><strong>Obuća:</strong> Pešačke cipele sa dobrim gripom. Staze su kamenite i sa mahovinom.</li><li><strong>Aristotelova staza:</strong> Obeležena, podeljena u faze. Potpuno prelaženje 2-3 dana sa noćenjima u selima.</li><li><strong>Verodostojne rute:</strong> Ne samo offline mape — oznake su pouzdane ali preuzmi mapu pre.</li><li><strong>Mobilni signal:</strong> Slab u planinskim područjima. Reci nekome gde ideš.</li><li><strong>Zmije:</strong> Retke ali postoje. Ne diži kamenje, visoke cipele.</li><li><strong>Kombinacija sa plažama:</strong> Jutarnje pešačenje + popodne plaža = idealno. Pogledaj <a href="/best/beaches-sithonia">plaže Sitonije</a>.</li></ul>`, bg: `<h2>Съвети за разходки в Халкидики</h2><ul><li><strong>Вода:</strong> 2L/човек поне. Има водоизточници, но рядко.</li><li><strong>Обувки:</strong> Пешеходни обувки с добро сцепление. Пътеките имат камъни и мъхове.</li><li><strong>Aristotle Trail:</strong> Маркирана, разделена на етапи. Пълно преминаване 2-3 дни с нощувки в села.</li><li><strong>Надеждни маршрути:</strong> Не само офлайн карти — маркировките са надеждни, но изтеглете карта предварително.</li><li><strong>Мобилен сигнал:</strong> Слаб в планините. Кажете на някого къде отивате.</li><li><strong>Змии:</strong> Рядко, но има. Не вдигайте камъни, носете високи обувки.</li><li><strong>Комбинация с плажове:</strong> Сутрешна разходка + обед плаж = идеално. Вижте <a href="/best/beaches-sithonia">плажовете на Ситония</a>.</li></ul>`, ru: `<h2>Советы для пеших прогулок по Халкидики</h2><ul><li><strong>Вода:</strong> Минимум 2 литра на человека. Источники воды есть, но редко.</li><li><strong>Обувь:</strong> Походная обувь с хорошим сцеплением. Тропы каменистые и покрыты мхом.</li><li><strong>Aristotle Trail:</strong> Размеченный, разделён на этапы. Полное прохождение за 2-3 дня с ночёвками в деревнях.</li><li><strong>Маршруты:</strong> Не только офлайн карты — разметка надёжная, но загрузите карту заранее.</li><li><strong>Сигнал мобильной связи:</strong> Слабый в горах. Сообщите кому-нибудь, куда идёте.</li><li><strong>Змеи:</strong> Редки, но есть. Не поднимайте камни, носите высокую обувь.</li><li><strong>Совмещение с пляжами:</strong> Утренний поход + полдень на пляже = идеально. Посмотрите <a href="/best/beaches-sithonia">пляжи Ситонии</a>.</li></ul>` },
    faqs: [
      { q: { el: `Είναι το Aristotle Trail κατάλληλο για αρχάριους;`, en: `Is the Aristotle Trail suitable for beginners?`, de: `Ist der Aristotle Trail für Anfänger geeignet?`, ro: `Este Traseul lui Aristotel potrivit pentru începători?`, sr: `Da li je Aristotelova staza pogodna za početnike?`, bg: `Подходящо ли е Aristotle Trail за начинаещи?`, ru: `Подходит ли Aristotle Trail для начинающих?` }, a: { el: `Ναι, σε στάδια. Είναι χωρισμένο σε τμήματα 8-15 χλμ που ξεπερνιούνται σε 3-5 ώρες. Κάνε ένα στάδιο σαν day hike. Φάση 2-3 ημερών χρειάζεται μέτρια φυσική κατάσταση.`, en: `Yes, in stages. It's divided into 8-15 km sections finishable in 3-5 hours. Do one stage as a day hike. The full 2-3 day trek needs moderate fitness.`, de: `Ja, in Etappen. Er ist in Abschnitte von 8-15 km unterteilt, die in 3-5 Stunden bewältigt werden können. Mache eine Etappe als Tageswanderung. Eine 2-3-tägige Phase erfordert eine mittlere körperliche Verfassung.`, ro: `Da, pe etape. Este împărțit în secțiuni de 8-15 km care pot fi parcurse în 3-5 ore. Fă o etapă ca drumeție de o zi. Etapa de 2-3 zile necesită condiție fizică medie.`, sr: `Da, u fazama. Podeljena je na delove od 8-15 km koji se prelaze za 3-5 sati. Uradi jednu fazu kao dnevnu šetnju. Faza od 2-3 dana zahteva srednju fizičku kondiciju.`, bg: `Да, на етапи. Разделено е на участъци от 8-15 км, които се преодоляват за 3-5 часа. Направете един етап като дневна разходка. Етап от 2-3 дни изисква средна физическа форма.`, ru: `Да, по этапам. Он разделён на участки 8-15 км, которые можно пройти за 3-5 часов. Пройдите один этап как дневной поход. Этапы на 2-3 дня требуют средней физической подготовки.` } },
      { q: { el: `Που να μείνω για πεζοπορία;`, en: `Where to stay for hiking?`, de: `Wo soll ich für das Wandern übernachten?`, ro: `Unde să stau pentru drumeții?`, sr: `Gde da odsednem za pešačenje?`, bg: `Къде да остана за разходки?`, ru: `Где остановиться для походов?` }, a: { el: `Παραδοσιακά χωριά της Σιθωνίας (Παρθενώνας, Νεοχώρι) ή της Κασσάνδρας ορεινής. <a href="/listings">Δες διαθέσιμα καταλύματα</a> στη βάση μας.`, en: `Traditional Sithonia villages (Parthenonas, Neochori) or mountain Kassandra. <a href="/listings">Check available accommodation</a>.`, de: `Traditionelle Dörfer in Sithonia (Parthenonas, Neochori) oder im Bergland von Kassandra. <a href="/listings">Sieh dir verfügbare Unterkünfte</a> in unserer Datenbank an.`, ro: `Sate tradiționale din Sithonia (Parthenonas, Neochori) sau din Kassandra montană. <a href="/listings">Vezi cazările disponibile</a> în baza noastră de date.`, sr: `Tradicionalna sela Sitonije (Parthenonas, Neohori) ili planinske Kasandre. <a href="/listings">Pogledaj dostupne smeštaje</a> u našoj bazi.`, bg: `Традиционни села на Ситония (Партенонас, Неохори) или на планинска Касандра. <a href="/listings">Вижте наличните настанявания</a> в нашата база данни.`, ru: `Традиционные деревни Ситонии (Парфенонас, Неохори) или горной Кассандры. <a href="/listings">Посмотрите доступные варианты размещения</a> в нашей базе данных.` } },
      { q: { el: `Χρειάζομαι οδηγό;`, en: `Do I need a guide?`, de: `Brauche ich einen Führer?`, ro: `Am nevoie de ghid?`, sr: `Da li mi je potreban vodič?`, bg: `Имам ли нужда от водач?`, ru: `Нужен ли гид?` }, a: { el: `Όχι για βασικές διαδρομές με καλή σήμανση. Για διέλευση Αγίου Όρους από τα μοναστήρια προαπαιτεί διαμονητήριο και τοπικό οδηγό.`, en: `Not for the basic well-signed routes. For Mount Athos monastery crossings, a diamonitirion permit and local guide are required.`, de: `Nicht für grundlegende Routen mit guter Markierung. Für die Durchquerung des Berg Athos von den Klöstern aus ist ein Aufenthaltsgenehmigung und ein lokaler Führer erforderlich.`, ro: `Nu pentru traseele de bază cu semnalizare bună. Traversarea Muntelui Athos de la mănăstiri necesită permis de ședere și ghid local.`, sr: `Ne za osnovne rute sa dobrim oznakama. Za prelazak Svete Gore kroz manastire potreban je dozvola za boravak i lokalni vodič.`, bg: `Не за основни маршрути с добра маркировка. За преминаване на Света гора през манастирите се изисква разрешително и местен водач.`, ru: `Нет, для основных маршрутов с хорошей разметкой. Для прохождения Афона через монастыри требуется разрешение и местный гид.` } },
    ],
  },
  "water-sports": {
    intro: { el: `<p>Η ακτογραμμή της Χαλκιδικής, με 550 χλμ και τρεις χερσονήσους που δημιουργούν μικρές προστατευμένες ζώνες, είναι ιδανική για water sports. Τα beach clubs της Κασσάνδρας προσφέρουν jet ski, parasailing, banana boat. Η Σιθωνία είναι παράδεισος για SUP, kayak, snorkeling, scuba diving — λόγω της προστατευμένης γεωγραφίας με μικρά νησάκια και κόλπους. Στη Βουρβουρού και τα γύρω νησάκια κάνεις windsurfing και sailing. Αυτή η λίστα συγκεντρώνει τα κέντρα water sports και τις δραστηριότητες με τις υψηλότερες αξιολογήσεις.</p>`, en: `<p>Halkidiki's coastline, with 550 km and three peninsulas creating small protected zones, is ideal for water sports. Kassandra's beach clubs offer jet skis, parasailing, banana boats. Sithonia is a paradise for SUP, kayak, snorkelling, scuba diving — thanks to its sheltered geography with small islets and bays. In Vourvourou and the surrounding islets you can do windsurfing and sailing. This list collects the highest-rated water sports centres and activities.</p>`, de: `<p>Die Küstenlinie von Chalkidiki, mit 550 km und drei Halbinseln, die kleine geschützte Zonen schaffen, ist ideal für Wassersportarten. Die Beachclubs von Kassandra bieten Jet-Ski, Parasailing und Banana Boat an. Sithonia ist ein Paradies für SUP, Kajak, Schnorcheln und Tauchen — dank der geschützten Geografie mit kleinen Inseln und Buchten. In Vourvourou und den umliegenden Inseln kann man Windsurfen und Segeln. Diese Liste fasst die Wassersportzentren und Aktivitäten mit den besten Bewertungen zusammen.</p>`, ro: `<p>Coasta Halkidiki, cu 550 km și trei peninsule care creează mici zone protejate, este ideală pentru sporturi nautice. Beach cluburile din Kassandra oferă jet ski, parasailing, banana boat. Sithonia este un paradis pentru SUP, caiac, snorkeling, scuba diving — datorită geografiei protejate cu insulițe și golfuri mici. În Vourvourou și insulițele din jur poți face windsurfing și sailing. Această listă reunește centrele de sporturi nautice și activitățile cu cele mai bune evaluări.</p>`, sr: `<p>Obala Halkidikija, sa 550 km i tri poluostrva koja stvaraju male zaštićene zone, idealna je za sportove na vodi. Beach klubovi na Kasandri nude jet ski, parasailing, banana boat. Sitonija je raj za SUP, kajak, snorkeling, ronjenje — zbog zaštićene geografije sa malim ostrvcima i zalivima. U Vurvuru i okolnim ostrvcima možete se baviti jedrenjem na dasci i jedrenjem. Ova lista okuplja centre za sportove na vodi i aktivnosti sa najvišim ocenama.</p>`, bg: `<p>Актовата линия на Халкидики, с 550 км и три полуострова, които създават малки защитени зони, е идеална за водни спортове. Beach клубовете на Касандра предлагат джет ски, парасейлинг, бананова лодка. Ситония е рай за SUP, каяк, шнорхелинг, гмуркане — благодарение на защитената география с малки островчета и заливи. Във Вурвуру и околните островчета можеш да се занимаваш с уиндсърфинг и ветроходство. Този списък събира центровете за водни спортове и дейностите с най-високи оценки.</p>`, ru: `<p>Побережье Халкидики, протяженностью 550 км и с тремя полуостровами, создающими небольшие защищенные зоны, идеально подходит для водных видов спорта. В beach club на Кассандре предлагают катание на водных мотоциклах, парасейлинг, банан. Ситония — рай для SUP, каякинга, сноркелинга, дайвинга — благодаря защищенной географии с небольшими островками и бухтами. В Вурвуру и на окружающих островках можно заниматься виндсерфингом и парусным спортом. Этот список объединяет центры водных видов спорта и мероприятия с самыми высокими оценками.</p>` },
    seasonal: { el: `<h2>Πότε να κάνεις water sports</h2><p><strong>Καλοκαίρι (Ιούνιος-Σεπτέμβριος):</strong> Όλες οι δραστηριότητες λειτουργούν. Καλύτερο σερφ, kite, windsurf με τους ετήσιους ανέμους ιδίως στη βορεινή Σιθωνία. <strong>Άνοιξη/Φθινόπωρο:</strong> Sailing και SUP εξαιρετικά, λιγότερος κόσμος, καλύτερες τιμές. <strong>Καλύτερη ώρα μέρας:</strong> Πρωί 9-12 για ηρεμία, απόγευμα 16-18 για άνεμο.</p>`, en: `<h2>When to do water sports</h2><p><strong>Summer (June-September):</strong> All activities operate. Best surf, kite, windsurf with seasonal winds, especially on northern Sithonia. <strong>Spring/Autumn:</strong> Sailing and SUP are excellent, fewer crowds, better prices. <strong>Best time of day:</strong> Morning 9-12 for calm, afternoon 16-18 for wind.</p>`, de: `<h2>Wann man Wassersport machen sollte</h2><p><strong>Sommer (Juni-September):</strong> Alle Aktivitäten sind in Betrieb. Bestes Surfen, Kiten, Windsurfen mit den jährlichen Winden, besonders im nördlichen Sithonia. <strong>Frühling/Herbst:</strong> Segeln und SUP sind hervorragend, weniger Menschen, bessere Preise. <strong>Beste Tageszeit:</strong> Morgens 9-12 für Ruhe, nachmittags 16-18 für Wind.</p>`, ro: `<h2>Când să faci sporturi nautice</h2><p><strong>Vara (iunie-septembrie):</strong> Toate activitățile sunt disponibile. Cel mai bun surfing, kite, windsurfing cu vânturile anuale, în special în nordul Sithoniei. <strong>Primăvară/Toamnă:</strong> Sailing și SUP excelente, mai puțină aglomerație, prețuri mai bune. <strong>Cea mai bună oră a zilei:</strong> Dimineața 9-12 pentru liniște, după-amiaza 16-18 pentru vânt.</p>`, sr: `<h2>Kada se baviti sportovima na vodi</h2><p><strong>Leto (jun-septembar):</strong> Sve aktivnosti su u funkciji. Najbolji surf, kite, windsurf sa godišnjim vetrovima naročito na severnoj Sitoniji. <strong>Proleće/Jesen:</strong> Jedrenje i SUP su izvanredni, manje gužve, bolje cene. <strong>Najbolje vreme dana:</strong> Jutro 9-12 za mir, popodne 16-18 za vetar.</p>`, bg: `<h2>Кога да се занимаваш с водни спортове</h2><p><strong>Лято (юни-септември):</strong> Всички дейности функционират. Най-добро сърфиране, кайт, уиндсърфинг с годишните ветрове, особено в северна Ситония. <strong>Пролет/Есен:</strong> Ветроходство и SUP са отлични, по-малко хора, по-добри цени. <strong>Най-добро време на деня:</strong> Сутрин 9-12 за спокойствие, следобед 16-18 за вятър.</p>`, ru: `<h2>Когда заниматься водными видами спорта</h2><p><strong>Лето (июнь-сентябрь):</strong> Все мероприятия работают. Лучший серфинг, кайт, виндсерфинг с ежегодными ветрами, особенно на северной Ситонии. <strong>Весна/Осень:</strong> Парусный спорт и SUP отличные, меньше людей, лучшие цены. <strong>Лучшее время дня:</strong> Утро 9-12 для спокойствия, вечер 16-18 для ветра.</p>` },
    tips: { el: `<h2>Συμβουλές για water sports</h2><ul><li><strong>Κράτηση 1 μέρα πριν:</strong> Τα νοίκια εξοπλισμού γεμίζουν Σαββατοκύριακα. Online ή τηλεφωνική.</li><li><strong>Τιμές 2026:</strong> SUP €15-25/ώρα, jet ski €60-100/15min, parasailing €40-60/άτομο, scuba intro €70-100, kayak €15-25/ώρα.</li><li><strong>Ασφάλεια:</strong> Βεβαιώσου ότι το νοίκι έχει licensed instructors. Ζητάς συμβόλαιο.</li><li><strong>Snorkeling:</strong> Δες τις <a href="/best/snorkeling-spots">καλύτερες παραλίες snorkeling</a> για free αντίστοιχα.</li><li><strong>Sailing:</strong> Day cruises από Νέο Μαρμαρά ή Πόρτο Κουφό — €50-100/άτομο για 4-6 ώρες με γεύμα.</li><li><strong>Scuba diving:</strong> Καλύτερα κέντρα σε Νέο Μαρμαρά και Καλιθέα. Βυθίσματα 10-25m, καθαρότητα 15-25m.</li></ul>`, en: `<h2>Water sports tips</h2><ul><li><strong>Book 1 day ahead:</strong> Equipment rentals fill up on weekends. Online or by phone.</li><li><strong>2026 prices:</strong> SUP €15-25/hour, jet ski €60-100/15min, parasailing €40-60/person, scuba intro €70-100, kayak €15-25/hour.</li><li><strong>Safety:</strong> Make sure the rental has licensed instructors. Ask for a contract.</li><li><strong>Snorkelling:</strong> See our <a href="/best/snorkeling-spots">best snorkelling beaches</a> for free alternatives.</li><li><strong>Sailing:</strong> Day cruises from Neos Marmaras or Porto Koufo — €50-100/person for 4-6 hours with lunch.</li><li><strong>Scuba diving:</strong> Best centres in Neos Marmaras and Kalithea. 10-25m dives, 15-25m visibility.</li></ul>`, de: `<h2>Tipps für Wassersport</h2><ul><li><strong>Buchung 1 Tag vorher:</strong> Die Ausrüstungsverleihe sind an Wochenenden ausgebucht. Online oder telefonisch.</li><li><strong>Preise 2026:</strong> SUP €15-25/Stunde, Jet-Ski €60-100/15min, Parasailing €40-60/Person, Schnuppertauchen €70-100, Kajak €15-25/Stunde.</li><li><strong>Sicherheit:</strong> Stelle sicher, dass der Verleih lizenzierte Instruktoren hat. Fordere einen Vertrag an.</li><li><strong>Schnorcheln:</strong> Siehe die <a href="/best/snorkeling-spots">besten Schnorchelstrände</a> für kostenlose Alternativen.</li><li><strong>Segeln:</strong> Tageskreuzfahrten von Neos Marmaras oder Porto Koufo — €50-100/Person für 4-6 Stunden mit Mahlzeit.</li><li><strong>Tauchen:</strong> Beste Zentren in Neos Marmaras und Kallithea. Tauchtiefen 10-25m, Sichtweite 15-25m.</li></ul>`, ro: `<h2>Sfaturi pentru sporturi nautice</h2><ul><li><strong>Rezervare cu 1 zi înainte:</strong> Echipamentele de închiriat se epuizează în weekenduri. Online sau telefonic.</li><li><strong>Prețuri 2026:</strong> SUP €15-25/oră, jet ski €60-100/15min, parasailing €40-60/persoană, introducere scuba €70-100, caiac €15-25/oră.</li><li><strong>Siguranță:</strong> Asigură-te că închirierea are instructori licențiați. Cere un contract.</li><li><strong>Snorkeling:</strong> Vezi <a href="/best/snorkeling-spots">cele mai bune plaje pentru snorkeling</a> gratuit.</li><li><strong>Sailing:</strong> Croaziere de o zi din Neos Marmaras sau Porto Koufo — €50-100/persoană pentru 4-6 ore cu masă inclusă.</li><li><strong>Scuba diving:</strong> Cele mai bune centre în Neos Marmaras și Kallithea. Adâncimi de 10-25m, claritate 15-25m.</li></ul>`, sr: `<h2>Saveti za sportove na vodi</h2><ul><li><strong>Rezervacija 1 dan unapred:</strong> Iznajmljivanje opreme je popunjeno vikendom. Online ili telefonski.</li><li><strong>Cene 2026:</strong> SUP €15-25/sat, jet ski €60-100/15min, parasailing €40-60/osoba, uvodno ronjenje €70-100, kajak €15-25/sat.</li><li><strong>Bezbednost:</strong> Uverite se da iznajmljivanje ima licencirane instruktore. Tražite ugovor.</li><li><strong>Snorkeling:</strong> Pogledajte <a href="/best/snorkeling-spots">najbolje plaže za snorkeling</a> za besplatno uživanje.</li><li><strong>Jedrenje:</strong> Dnevni krstarenja iz Neos Marmarasa ili Porto Kufo — €50-100/osoba za 4-6 sati sa obrokom.</li><li><strong>Ronjenje:</strong> Najbolji centri u Neos Marmarasu i Kalitei. Dubine 10-25m, čistoća 15-25m.</li></ul>`, bg: `<h2>Съвети за водни спортове</h2><ul><li><strong>Резервация 1 ден предварително:</strong> Наемите на оборудване се запълват през уикендите. Онлайн или по телефон.</li><li><strong>Цени 2026:</strong> SUP €15-25/час, джет ски €60-100/15мин, парасейлинг €40-60/човек, въведение в гмуркането €70-100, каяк €15-25/час.</li><li><strong>Безопасност:</strong> Увери се, че наемът има лицензирани инструктори. Изисквай договор.</li><li><strong>Шнорхелинг:</strong> Виж <a href="/best/snorkeling-spots">най-добрите плажове за шнорхелинг</a> безплатно.</li><li><strong>Ветроходство:</strong> Дневни круизи от Неос Мармарас или Порто Куфо — €50-100/човек за 4-6 часа с обяд.</li><li><strong>Гмуркане:</strong> Най-добрите центрове в Неос Мармарас и Калитея. Дълбочини 10-25м, чистота 15-25м.</li></ul>`, ru: `<h2>Советы для водных видов спорта</h2><ul><li><strong>Бронирование за 1 день:</strong> Аренда оборудования заполняется на выходные. Онлайн или по телефону.</li><li><strong>Цены 2026:</strong> SUP €15-25/час, водный мотоцикл €60-100/15мин, парасейлинг €40-60/человек, вводный курс дайвинга €70-100, каяк €15-25/час.</li><li><strong>Безопасность:</strong> Убедитесь, что аренда имеет лицензированных инструкторов. Требуйте контракт.</li><li><strong>Snorkeling:</strong> Смотрите <a href="/best/snorkeling-spots">лучшие пляжи для сноркелинга</a> бесплатно.</li><li><strong>Sailing:</strong> Дневные круизы из Нео Мармараса или Порто Куфо — €50-100/человек за 4-6 часов с обедом.</li><li><strong>Scuba diving:</strong> Лучшие центры в Нео Мармарасе и Каллифее. Погружения 10-25м, чистота 15-25м.</li></ul>` },
    faqs: [
      { q: { el: `Που να κάνω scuba diving;`, en: `Where to go scuba diving?`, de: `Wo kann ich tauchen?`, ro: `Unde să fac scuba diving?`, sr: `Gde da ronim?`, bg: `Къде да се гмуркам?`, ru: `Где заняться дайвингом?` }, a: { el: `Καλύτερα κέντρα: <strong>Νέος Μαρμαράς</strong> και <strong>Καλιθέα</strong>. Όλα τα κέντρα είναι PADI certified. Intro dive για αρχάριους €70-100.`, en: `Best centres: <strong>Neos Marmaras</strong> and <strong>Kallithea</strong>. All are PADI certified. Intro dive for beginners €70-100.`, de: `Beste Zentren: <strong>Neos Marmaras</strong> und <strong>Kallithea</strong>. Alle Zentren sind PADI-zertifiziert. Schnuppertauchen für Anfänger €70-100.`, ro: `Cele mai bune centre: <strong>Neos Marmaras</strong> și <strong>Kallithea</strong>. Toate centrele sunt certificate PADI. Intro dive pentru începători €70-100.`, sr: `Najbolji centri: <strong>Neos Marmaras</strong> i <strong>Kalitea</strong>. Svi centri su PADI sertifikovani. Uvodno ronjenje za početnike €70-100.`, bg: `Най-добрите центрове: <strong>Неос Мармарас</strong> и <strong>Калитея</strong>. Всички центрове са PADI сертифицирани. Въведение в гмуркането за начинаещи €70-100.`, ru: `Лучшие центры: <strong>Нео Мармарас</strong> и <strong>Каллифея</strong>. Все центры сертифицированы PADI. Вводное погружение для новичков €70-100.` } },
      { q: { el: `Κατάλληλο για παιδιά;`, en: `Suitable for kids?`, de: `Geeignet für Kinder?`, ro: `Este potrivit pentru copii?`, sr: `Pogodno za decu?`, bg: `Подходящо ли е за деца?`, ru: `Подходит ли для детей?` }, a: { el: `SUP, kayak, banana boat από 6 ετών με συνοδό. Jet ski από 16 ετών με ενήλικα οδηγό. Scuba από 10 ετών (μόνο Discover Scuba).`, en: `SUP, kayak, banana boat from age 6 with adult. Jet ski from age 16 with adult driver. Scuba from age 10 (Discover Scuba only).`, de: `SUP, Kajak, Banana Boat ab 6 Jahren mit Begleitung. Jet-Ski ab 16 Jahren mit erwachsenem Fahrer. Tauchen ab 10 Jahren (nur Discover Scuba).`, ro: `SUP, caiac, banana boat de la 6 ani cu însoțitor. Jet ski de la 16 ani cu un adult ca șofer. Scuba de la 10 ani (doar Discover Scuba).`, sr: `SUP, kajak, banana boat od 6 godina uz pratnju. Jet ski od 16 godina uz odraslog vozača. Ronjenje od 10 godina (samo Discover Scuba).`, bg: `SUP, каяк, бананова лодка от 6 години с придружител. Джет ски от 16 години с възрастен водач. Гмуркане от 10 години (само Discover Scuba).`, ru: `SUP, каяк, банан с 6 лет в сопровождении взрослого. Водный мотоцикл с 16 лет с взрослым водителем. Дайвинг с 10 лет (только Discover Scuba).` } },
      { q: { el: `Που να κάνω SUP/kayak με ηρεμία;`, en: `Where for relaxed SUP/kayak?`, de: `Wo kann ich SUP/Kajak in Ruhe machen?`, ro: `Unde să fac SUP/caiac în liniște?`, sr: `Gde da se bavim SUP/kajak u miru?`, bg: `Къде да правя SUP/каяк на спокойствие?`, ru: `Где заняться SUP/каякингом в спокойствии?` }, a: { el: `<strong>Βουρβουρού</strong> — προστατευμένος κόλπος με μικρά νησάκια ιδανικά για εξερεύνηση. <strong>Πόρτο Κουφό</strong> — μικρός φυσικός κόλπος, ήρεμη θάλασσα.`, en: `<strong>Vourvourou</strong> — sheltered bay with small islets ideal for exploring. <strong>Porto Koufo</strong> — small natural bay, calm water.`, de: `<strong>Vourvourou</strong> — geschützte Bucht mit kleinen Inseln, ideal zum Erkunden. <strong>Porto Koufo</strong> — kleine natürliche Bucht, ruhiges Meer.`, ro: `<strong>Vourvourou</strong> — golf protejat cu insulițe mici ideale pentru explorare. <strong>Porto Koufo</strong> — mic golf natural, mare liniștită.`, sr: `<strong>Vurvuru</strong> — zaštićeni zaliv sa malim ostrvcima idealnim za istraživanje. <strong>Porto Kufo</strong> — mali prirodni zaliv, mirno more.`, bg: `<strong>Вурвуру</strong> — защитен залив с малки островчета, идеални за изследване. <strong>Порто Куфо</strong> — малък естествен залив, спокойна вода.`, ru: `<strong>Вурвуру</strong> — защищенная бухта с небольшими островками, идеально для исследования. <strong>Порто Куфо</strong> — маленькая природная бухта, спокойное море.` } },
    ],
  },
  "historical-sites": {
    intro: { el: `<p>Η Χαλκιδική κατοικείται συνεχώς από την προϊστορική εποχή και είναι ο γενέτειρος τόπος του <strong>Αριστοτέλη</strong> (Στάγειρα) και του <strong>Αλέξανδρου του Μεγάλου</strong> (γέννηση στις Αιγές αλλά μεγάλωμα στη γραμμή Χαλκιδικής). Η περιοχή έχει αρχαιολογικά ίχνη από ελληνιστική εποχή, βυζαντινούς πύργους από τους Σταυροφόρους, και μοναστήρια του Αγίου Όρους από τον 10ο αιώνα. Η <strong>Πετράλωνα</strong> είναι από τις σημαντικότερες παλαιολιθικές θέσεις της Ευρώπης (ηλικία ευρημάτων 200.000+ έτη). Αυτή η λίστα συγκεντρώνει τα κορυφαία ιστορικά μνημεία και αξιοθέατα.</p>`, en: `<p>Halkidiki has been continuously inhabited since prehistoric times and is the birthplace of <strong>Aristotle</strong> (Stagira) and where <strong>Alexander the Great</strong> grew up. The region has archaeological remains from the Hellenistic era, Byzantine towers from the Crusaders, and Mount Athos monasteries from the 10th century. <strong>Petralona</strong> is one of Europe's most important Palaeolithic sites (200,000+ year-old finds). This list collects the top historical monuments and attractions.</p>`, de: `<p>Chalkidiki ist seit der prähistorischen Zeit kontinuierlich bewohnt und ist der Geburtsort von <strong>Aristoteles</strong> (Stageira) und <strong>Alexander dem Großen</strong> (geboren in Aigai, aber aufgewachsen in der Region Chalkidiki). Die Region weist archäologische Spuren aus der hellenistischen Zeit, byzantinische Türme der Kreuzritter und Klöster des Berg Athos aus dem 10. Jahrhundert auf. <strong>Petralona</strong> gehört zu den bedeutendsten paläolithischen Fundstätten Europas (Alter der Funde 200.000+ Jahre). Diese Liste fasst die wichtigsten historischen Denkmäler und Sehenswürdigkeiten zusammen.</p>`, ro: `<p>Halkidiki este locuită continuu din perioada preistorică și este locul de naștere al lui <strong>Aristotel</strong> (Stagira) și al lui <strong>Alexandru cel Mare</strong> (născut în Aigai, dar crescut în zona Halkidiki). Regiunea are urme arheologice din perioada elenistică, turnuri bizantine de la cruciați și mănăstiri de pe Muntele Athos din secolul al X-lea. <strong>Petrálona</strong> este una dintre cele mai importante situri paleolitice din Europa (vârsta descoperirilor depășește 200.000 de ani). Această listă adună cele mai importante monumente istorice și atracții.</p>`, sr: `<p>Halkidiki je naseljena kontinuirano od praistorijskog doba i rodno je mesto <strong>Aristotela</strong> (Stageira) i <strong>Aleksandra Velikog</strong> (rođenje u Egi, ali odrastanje u oblasti Halkidikija). Region ima arheološke tragove iz helenističkog perioda, vizantijske kule iz vremena Krstaša i manastire Svete Gore iz 10. veka. <strong>Petralona</strong> je jedno od najvažnijih paleolitskih nalazišta u Evropi (starost nalaza 200.000+ godina). Ova lista okuplja najvažnije istorijske spomenike i znamenitosti.</p>`, bg: `<p>Халкидики е населяван непрекъснато от праисторическата епоха и е родното място на <strong>Аристотел</strong> (Стагира) и на <strong>Александър Велики</strong> (роден в Еге, но израснал в района на Халкидики). Регионът има археологически следи от елинистическата епоха, византийски кули от Кръстоносците и манастири на Света гора от 10-ти век. <strong>Петралона</strong> е едно от най-важните палеолитни находища в Европа (възраст на находките 200 000+ години). Този списък събира най-важните исторически паметници и забележителности.</p>`, ru: `<p>Халкидики населены с доисторических времен и являются родиной <strong>Аристотеля</strong> (Стагиры) и <strong>Александра Великого</strong> (родился в Эгах, но вырос на территории Халкидики). В регионе есть археологические следы эллинистической эпохи, византийские башни от крестоносцев и монастыри Афона с 10 века. <strong>Петралона</strong> — одно из важнейших палеолитических мест Европы (возраст находок более 200 000 лет). Этот список объединяет главные исторические памятники и достопримечательности.</p>` },
    seasonal: { el: `<h2>Πότε να επισκεφτείς</h2><p><strong>Άνοιξη και φθινόπωρο:</strong> Ιδανικά — δροσερός καιρός, λιγότερος κόσμος, καλύτερες ώρες ορατότητας. <strong>Καλοκαίρι:</strong> Επισκέψεις πρωί 9-12 πριν τη ζέστη. <strong>Χειμώνας:</strong> Πολλά αρχαιολογικά ανοιχτά αλλά με μειωμένο ωράριο.</p>`, en: `<h2>When to visit</h2><p><strong>Spring and autumn:</strong> Ideal — cool weather, fewer crowds, better visibility. <strong>Summer:</strong> Visit morning 9-12 before the heat. <strong>Winter:</strong> Many archaeological sites are open but with reduced hours.</p>`, de: `<h2>Wann zu besuchen</h2><p><strong>Frühling und Herbst:</strong> Ideal — kühles Wetter, weniger Menschen, bessere Sichtzeiten. <strong>Sommer:</strong> Besuche morgens 9-12 vor der Hitze. <strong>Winter:</strong> Viele archäologische Stätten sind geöffnet, aber mit verkürzten Öffnungszeiten.</p>`, ro: `<h2>Când să vizitezi</h2><p><strong>Primăvara și toamna:</strong> Ideal — vreme răcoroasă, mai puțină aglomerație, vizibilitate mai bună. <strong>Vara:</strong> Vizitează dimineața între 9-12 înainte de căldură. <strong>Iarna:</strong> Multe situri arheologice sunt deschise, dar cu program redus.</p>`, sr: `<h2>Kada posetiti</h2><p><strong>Proleće i jesen:</strong> Idealno — sveže vreme, manje gužve, bolja vidljivost. <strong>Leto:</strong> Posete ujutru od 9-12 pre vrućine. <strong>Zima:</strong> Mnoga arheološka mesta su otvorena, ali sa skraćenim radnim vremenom.</p>`, bg: `<h2>Кога да посетите</h2><p><strong>Пролет и есен:</strong> Идеални — прохладно време, по-малко хора, по-добра видимост. <strong>Лято:</strong> Посещения сутрин от 9 до 12 преди жегата. <strong>Зима:</strong> Много археологически обекти са отворени, но с намалено работно време.</p>`, ru: `<h2>Когда посетить</h2><p><strong>Весна и осень:</strong> Идеально — прохладная погода, меньше людей, лучшее время для осмотра. <strong>Лето:</strong> Посещения утром с 9 до 12 до жары. <strong>Зима:</strong> Многие археологические объекты открыты, но с сокращенным графиком.</p>` },
    tips: { el: `<h2>Συμβουλές για ιστορικές επισκέψεις</h2><ul><li><strong>Είσοδοι:</strong> Συνήθως €4-8/άτομο. Παιδιά και ηλικιωμένοι έχουν εκπτώσεις.</li><li><strong>Πετράλωνα:</strong> Συνδυασμός σπηλιάς + Μουσείου Παλαιολιθικού. 2-3 ώρες επίσκεψης.</li><li><strong>Στάγειρα (γενέτειρα Αριστοτέλη):</strong> Αρχαιολογικός χώρος + θεματικό πάρκο. Καλό για παιδιά που μαθαίνουν.</li><li><strong>Άγιο Όρος:</strong> Άνδρες μόνο με διαμονητήριο. Γυναίκες κάνουν κρουαζιέρα από Ουρανούπολη — βλέπουν τα μοναστήρια από τη θάλασσα.</li><li><strong>Πύργος Προσφορίου (Ουρανούπολη):</strong> Βυζαντινός πύργος 14ου αιώνα. Δωρεάν επίσκεψη εξωτερικού, μουσείο μέσα.</li><li><strong>Συνδυασμός:</strong> Πρωινό αρχαιολογικό + μεσημέρι παραλία είναι ιδανική ροή.</li></ul>`, en: `<h2>Historical visit tips</h2><ul><li><strong>Entry fees:</strong> Usually €4-8/person. Discounts for children and seniors.</li><li><strong>Petralona:</strong> Combined cave + Palaeolithic Museum visit. 2-3 hours.</li><li><strong>Stagira (Aristotle's birthplace):</strong> Archaeological site + theme park. Great for learning kids.</li><li><strong>Mount Athos:</strong> Men only, with a diamonitirion permit. Women take a cruise from Ouranoupoli — see the monasteries from the sea.</li><li><strong>Prosforion Tower (Ouranoupoli):</strong> 14th-century Byzantine tower. Free exterior visit, museum inside.</li><li><strong>Combine:</strong> Morning archaeology + afternoon beach is the ideal flow.</li></ul>`, de: `<h2>Tipps für historische Besuche</h2><ul><li><strong>Eintritte:</strong> Normalerweise €4-8/Person. Kinder und Senioren erhalten Ermäßigungen.</li><li><strong>Petralona:</strong> Kombination aus Höhle + Paläolithischem Museum. 2-3 Stunden Besuch.</li><li><strong>Stageira (Geburtsort von Aristoteles):</strong> Archäologische Stätte + Themenpark. Gut für Kinder, die lernen.</li><li><strong>Berg Athos:</strong> Nur Männer mit Aufenthaltsgenehmigung. Frauen machen eine Kreuzfahrt von Ouranoupoli — sie sehen die Klöster vom Meer aus.</li><li><strong>Prosforiou-Turm (Ouranoupoli):</strong> Byzantinischer Turm aus dem 14. Jahrhundert. Kostenloser Außenbesuch, Museum innen.</li><li><strong>Kombination:</strong> Morgens Archäologie + nachmittags Strand ist der ideale Ablauf.</li></ul>`, ro: `<h2>Sfaturi pentru vizite istorice</h2><ul><li><strong>Intrări:</strong> De obicei €4-8/persoană. Copiii și vârstnicii beneficiază de reduceri.</li><li><strong>Petrálona:</strong> Combinație de peșteră + Muzeu Paleolitic. Vizită de 2-3 ore.</li><li><strong>Stagira (locul de naștere al lui Aristotel):</strong> Sit arheologic + parc tematic. Bun pentru copii care învață.</li><li><strong>Muntele Athos:</strong> Doar bărbați cu permis de ședere. Femeile fac croaziere din Ouranoupoli — văd mănăstirile de pe mare.</li><li><strong>Turnul Prosforiou (Ouranoupoli):</strong> Turn bizantin din secolul al XIV-lea. Vizită gratuită la exterior, muzeu în interior.</li><li><strong>Combinare:</strong> Dimineața vizită arheologică + după-amiaza plajă este un flux ideal.</li></ul>`, sr: `<h2>Saveti za istorijske posete</h2><ul><li><strong>Ulazi:</strong> Obično €4-8/osobi. Deca i stariji imaju popuste.</li><li><strong>Petralona:</strong> Kombinacija pećine + Paleolitskog muzeja. Poseta traje 2-3 sata.</li><li><strong>Stageira (rodno mesto Aristotela):</strong> Arheološko nalazište + tematski park. Dobro za decu koja uče.</li><li><strong>Sveta Gora:</strong> Samo muškarci sa dozvolom za boravak. Žene mogu na krstarenje iz Uranopolisa — vide manastire sa mora.</li><li><strong>Kula Prosforion (Uranopolis):</strong> Vizantijska kula iz 14. veka. Besplatna poseta spolja, muzej unutra.</li><li><strong>Kombinacija:</strong> Jutarnja arheološka poseta + popodne na plaži je idealan raspored.</li></ul>`, bg: `<h2>Съвети за исторически посещения</h2><ul><li><strong>Входове:</strong> Обикновено €4-8/човек. Деца и възрастни имат отстъпки.</li><li><strong>Петралона:</strong> Комбинация от пещера + Палеолитен музей. 2-3 часа посещение.</li><li><strong>Стагира (родно място на Аристотел):</strong> Археологически обект + тематичен парк. Подходящо за деца, които учат.</li><li><strong>Света гора:</strong> Само мъже с разрешително за престой. Жените могат да направят круиз от Урануполи — виждат манастирите от морето.</li><li><strong>Кулата на Просфори (Урануполи):</strong> Византийска кула от 14-ти век. Безплатно посещение отвън, музей вътре.</li><li><strong>Комбинация:</strong> Сутрешно археологическо + следобед плаж е идеален план.</li></ul>`, ru: `<h2>Советы для исторических посещений</h2><ul><li><strong>Вход:</strong> Обычно €4-8/человек. Для детей и пожилых людей есть скидки.</li><li><strong>Петралона:</strong> Комбинация пещеры + Палеолитического музея. 2-3 часа на посещение.</li><li><strong>Стагиры (родина Аристотеля):</strong> Археологическая зона + тематический парк. Хорошо для детей, которые учатся.</li><li><strong>Афон:</strong> Только мужчины с разрешением на проживание. Женщины могут отправиться в круиз из Уранополиса — увидеть монастыри с моря.</li><li><strong>Башня Просфорион (Уранополис):</strong> Византийская башня 14 века. Бесплатное посещение снаружи, внутри музей.</li><li><strong>Комбинация:</strong> Утром археология + днем пляж — идеальный маршрут.</li></ul>` },
    faqs: [
      { q: { el: `Είναι αξίζει η επίσκεψη στην Πετράλωνα;`, en: `Is Petralona worth visiting?`, de: `Lohnt sich ein Besuch in Petralona?`, ro: `Merită vizita la Petrálona?`, sr: `Da li vredi posetiti Petralonu?`, bg: `Струва ли си посещението на Петралона?`, ru: `Стоит ли посетить Петралону?` }, a: { el: `Ναι, ιδιαίτερα. Η σπηλιά είναι ένα από τα σημαντικότερα παλαιολιθικά ευρήματα της Ευρώπης. Καλό και για παιδιά. Είσοδος €8, μέρα 9-17.`, en: `Yes, very much. The cave is one of Europe's most important Palaeolithic finds. Great for kids too. Entry €8, hours 9-17.`, de: `Ja, besonders. Die Höhle ist eines der bedeutendsten paläolithischen Funde Europas. Auch gut für Kinder. Eintritt €8, täglich 9-17 Uhr.`, ro: `Da, cu siguranță. Peștera este una dintre cele mai importante descoperiri paleolitice din Europa. Bună și pentru copii. Intrare €8, program 9-17.`, sr: `Da, posebno. Pećina je jedno od najvažnijih paleolitskih nalazišta u Evropi. Dobro i za decu. Ulaz €8, radno vreme 9-17.`, bg: `Да, определено. Пещерата е едно от най-важните палеолитни находища в Европа. Подходящо и за деца. Вход €8, работно време 9-17.</faq1_q>`, ru: `Да, особенно. Пещера — одно из важнейших палеолитических открытий Европы. Хорошо и для детей. Вход €8, часы работы 9-17.` } },
      { q: { el: `Μπορώ να επισκεφτώ το Άγιο Όρος;`, en: `Can I visit Mount Athos?`, de: `Kann ich den Berg Athos besuchen?`, ro: `Pot vizita Muntele Athos?`, sr: `Mogu li posetiti Svetu Goru?`, bg: `Мога ли да посетя Света гора?`, ru: `Могу ли я посетить Афон?` }, a: { el: `Άνδρες ναι με διαμονητήριο (κρατηση 6 μήνες πριν, €25/μέρα). Γυναίκες όχι — απαγορεύεται η είσοδος εδώ και αιώνες. Όμως οι κρουαζιέρες από Ουρανούπολη πλησιάζουν 500m από την ακτή.`, en: `Men yes, with a diamonitirion (book 6 months ahead, €25/day). Women no — entry has been forbidden for centuries. But cruises from Ouranoupoli approach within 500m of the coast.`, de: `Männer ja mit Aufenthaltsgenehmigung (Reservierung 6 Monate im Voraus, €25/Tag). Frauen nein — der Zutritt ist seit Jahrhunderten verboten. Aber die Kreuzfahrten von Ouranoupoli kommen bis auf 500m an die Küste heran.`, ro: `Bărbații da, cu permis de ședere (rezervare cu 6 luni înainte, €25/zi). Femeile nu — accesul este interzis de secole. Totuși, croazierele din Ouranoupoli se apropie la 500m de țărm.`, sr: `Muškarci mogu sa dozvolom za boravak (rezervacija 6 meseci unapred, €25/dan). Žene ne mogu — ulaz je zabranjen vekovima. Međutim, krstarenja iz Uranopolisa prilaze na 500m od obale.`, bg: `Мъже да, с разрешително за престой (резервация 6 месеца предварително, €25/ден). Жени не — входът е забранен от векове. Но круизите от Урануполи се приближават на 500 м от брега.`, ru: `Мужчины могут с разрешением на проживание (бронирование за 6 месяцев, €25/день). Женщины не могут — вход запрещен уже веками. Однако круизы из Уранополиса подходят на 500 м к берегу.` } },
      { q: { el: `Που είναι τα Στάγειρα;`, en: `Where is Stagira?`, de: `Wo befinden sich die Stageira?`, ro: `Unde se află Stagira?`, sr: `Gde se nalaze Stageira?`, bg: `Къде се намират Стагира?`, ru: `Где находятся Стагиры?` }, a: { el: `Στη βορειοανατολική Χαλκιδική, κοντά στη σύγχρονη Στρατώνι. Το αρχαιολογικό πάρκο έχει αρχαία ερείπια + θεματικό πάρκο για παιδιά αφιερωμένο στον Αριστοτέλη.`, en: `In northeastern Halkidiki, near modern Stratoni. The archaeological park has ancient ruins + a kids' theme park dedicated to Aristotle.`, de: `Im Nordosten von Chalkidiki, nahe dem modernen Stratoni. Der archäologische Park hat antike Ruinen + einen Themenpark für Kinder, der Aristoteles gewidmet ist.`, ro: `În nord-estul Halkidiki, lângă localitatea modernă Stratoni. Parcul arheologic are ruine antice + parc tematic pentru copii dedicat lui Aristotel.`, sr: `Na severoistoku Halkidikija, blizu modernog Stratonia. Arheološki park ima drevne ruševine + tematski park za decu posvećen Aristotelu.`, bg: `В североизточната част на Халкидики, близо до съвременния Стратони. Археологическият парк има древни руини + тематичен парк за деца, посветен на Аристотел.`, ru: `На северо-востоке Халкидики, рядом с современным Стратони. Археологический парк имеет древние руины + тематический парк для детей, посвященный Аристотелю.` } },
    ],
  },
  "snorkeling-spots": {
    intro: { el: `<p>Η Χαλκιδική, ιδίως η Σιθωνία, είναι από τους καλύτερους προορισμούς snorkeling στη βόρεια Ελλάδα. Τα νερά είναι ιδιαίτερα διαυγή (15-25m visibility τις περισσότερες μέρες), η ακτογραμμή έχει πλήθος μικρών κόλπων με βραχώδεις βυθούς που φιλοξενούν θαλάσσια ζωή, και οι περισσότερες παραλίες είναι προσβάσιμες χωρίς βάρκα. Δεν χρειάζεσαι εξοπλισμό πέρα από μάσκα και αναπνευστήρα — που μπορείς να αγοράσεις από οποιαδήποτε supermarket για €15-25. Αυτή η λίστα συγκεντρώνει τις παραλίες με τα καλύτερα snorkeling spots.</p>`, en: `<p>Halkidiki, especially Sithonia, is one of northern Greece's top snorkelling destinations. The water is particularly clear (15-25m visibility on most days), the coastline has many small bays with rocky bottoms hosting marine life, and most beaches are accessible without a boat. You don't need equipment beyond a mask and snorkel — buy them at any supermarket for €15-25. This list collects beaches with the best snorkelling spots.</p>`, de: `<p>Chalkidiki, insbesondere Sithonia, ist eines der besten Ziele zum Schnorcheln in Nordgriechenland. Das Wasser ist besonders klar (an den meisten Tagen 15-25 m Sichtweite), die Küstenlinie hat zahlreiche kleine Buchten mit felsigen Böden, die Meeresleben beherbergen, und die meisten Strände sind ohne Boot zugänglich. Du benötigst keine Ausrüstung außer Maske und Schnorchel — die du in jedem Supermarkt für €15-25 kaufen kannst. Diese Liste fasst die Strände mit den besten Schnorchelspots zusammen.</p>`, ro: `<p>Halkidiki, în special Sithonia, este una dintre cele mai bune destinații pentru snorkeling din nordul Greciei. Apele sunt deosebit de limpezi (vizibilitate de 15-25m în majoritatea zilelor), linia de coastă are numeroase golfulețe mici cu funduri stâncoase care găzduiesc viață marină, iar majoritatea plajelor sunt accesibile fără barcă. Nu ai nevoie de echipament în afară de mască și snorkel — pe care le poți cumpăra de la orice supermarket pentru €15-25. Această listă reunește plajele cu cele mai bune locuri pentru snorkeling.</p>`, sr: `<p>Halkidiki, posebno Sitonija, je jedan od najboljih destinacija za snorkeling u severnoj Grčkoj. Vode su izuzetno bistre (vidljivost 15-25m većinu dana), obala ima mnoštvo malih zaliva sa stenovitim dnom koje je dom morskom životu, a većina plaža je dostupna bez čamca. Ne treba ti oprema osim maske i disalice — koje možeš kupiti u bilo kojem supermarketu za €15-25. Ova lista okuplja plaže sa najboljim mestima za snorkeling.</p>`, bg: `<p>Халкидики, особено Ситония, е един от най-добрите дестинации за snorkeling в северна Гърция. Водите са изключително чисти (15-25m видимост през повечето дни), бреговата линия има множество малки заливи с каменисти дъна, които приютяват морски живот, и повечето плажове са достъпни без лодка. Не ти е необходима екипировка освен маска и шнорхел — които можеш да закупиш от всяко супермаркет за €15-25. Този списък събира плажовете с най-добрите места за snorkeling.</p>`, ru: `<p>Халкидики, особенно Ситония, является одним из лучших мест для сноркелинга на севере Греции. Воды здесь особенно прозрачные (видимость 15-25 м в большинстве дней), береговая линия изобилует множеством небольших бухт с каменистым дном, где обитает морская жизнь, и большинство пляжей доступны без лодки. Вам не понадобится оборудование, кроме маски и трубки — их можно купить в любом супермаркете за €15-25. Этот список собирает пляжи с лучшими местами для сноркелинга.</p>` },
    seasonal: { el: `<h2>Πότε να snorkeleάρεις</h2><p><strong>Καλύτερη ορατότητα:</strong> Σεπτέμβριος-Οκτώβριος (έως 25m). Καλοκαίρι 15-20m λόγω αλγών. <strong>Καλύτερη θερμοκρασία νερού:</strong> Αύγουστος-Σεπτέμβριος (25-26°C). <strong>Καλύτερη ώρα:</strong> Πρωί 8-11 πριν τον αέρα και την ανατάραξη του νερού. <strong>Αποφυγή:</strong> Μετά από μπόρα — αυξάνεται η θολούρα για 24-48h.</p>`, en: `<h2>When to snorkel</h2><p><strong>Best visibility:</strong> September-October (up to 25m). Summer 15-20m due to algae. <strong>Best water temperature:</strong> August-September (25-26°C). <strong>Best time of day:</strong> Morning 8-11 before wind stirs the water. <strong>Avoid:</strong> After a storm — turbidity stays for 24-48h.</p>`, de: `<h2>Wann schnorcheln</h2><p><strong>Beste Sicht:</strong> September-Oktober (bis zu 25 m). Sommer 15-20 m wegen Algen. <strong>Beste Wassertemperatur:</strong> August-September (25-26°C). <strong>Beste Zeit:</strong> Morgens 8-11 Uhr vor dem Wind und der Wasseraufwirbelung. <strong>Vermeiden:</strong> Nach einem Sturm — die Trübung nimmt für 24-48 Stunden zu.</p>`, ro: `<h2>Când să faci snorkeling</h2><p><strong>Cea mai bună vizibilitate:</strong> Septembrie-Octombrie (până la 25m). Vara 15-20m din cauza algelor. <strong>Cea mai bună temperatură a apei:</strong> August-Septembrie (25-26°C). <strong>Cea mai bună oră:</strong> Dimineața 8-11 înainte de vânt și de agitația apei. <strong>De evitat:</strong> După o furtună — crește tulburarea pentru 24-48h.</p>`, sr: `<h2>Kada je najbolje za snorkeling</h2><p><strong>Najbolja vidljivost:</strong> Septembar-Oktobar (do 25m). Leti 15-20m zbog algi. <strong>Najbolja temperatura vode:</strong> Avgust-Septembar (25-26°C). <strong>Najbolje vreme:</strong> Jutro 8-11 pre vetra i talasa. <strong>Izbegavaj:</strong> Posle oluje — zamućenje se povećava za 24-48h.</p>`, bg: `<h2>Кога да се занимаваш със snorkeling</h2><p><strong>Най-добра видимост:</strong> Септември-Октомври (до 25m). Лято 15-20m поради алги. <strong>Най-добра температура на водата:</strong> Август-Септември (25-26°C). <strong>Най-добро време:</strong> Сутрин 8-11 преди вятъра и вълнението на водата. <strong>Избягване:</strong> След буря — увеличава се мътността за 24-48h.</p>`, ru: `<h2>Когда заниматься сноркелингом</h2><p><strong>Лучшая видимость:</strong> Сентябрь-Октябрь (до 25 м). Летом 15-20 м из-за водорослей. <strong>Лучшая температура воды:</strong> Август-Сентябрь (25-26°C). <strong>Лучшее время:</strong> Утро 8-11 до ветра и волнения воды. <strong>Избегать:</strong> После грозы — увеличивается мутность на 24-48 ч.</p>` },
    tips: { el: `<h2>Συμβουλές για snorkeling</h2><ul><li><strong>Εξοπλισμός:</strong> Μάσκα + snorkel + παπούτσια ρηχών νερών. Δεν χρειάζονται πτερύγια αν είσαι σε ρηχά (1-3m).</li><li><strong>Καλύτερα spots:</strong> Βραχώδεις άκρες κόλπων με μικρά "παράθυρα" από το open sea — εκεί συγκεντρώνονται τα ψάρια.</li><li><strong>Τι θα δεις:</strong> Συνεχώς — βρώμικα (sea bream), σαρπες, λαβράκια. Σπάνια — χταπόδια, οκταπόδια, αχινούς. Πολύ σπάνια — μέδουσες.</li><li><strong>Ασφάλεια:</strong> Ποτέ μόνος. Ομόρευσε με snorkeling buddy.</li><li><strong>Sun protection:</strong> Reef-safe αντηλιακό. Καλύπτεις την πλάτη με rash guard — καίγεται.</li><li><strong>Συνδυασμός με water sports:</strong> Δες τα <a href="/best/water-sports">water sports</a> για guided tours.</li></ul>`, en: `<h2>Snorkelling tips</h2><ul><li><strong>Gear:</strong> Mask + snorkel + water shoes. Fins aren't needed in the shallows (1-3m).</li><li><strong>Best spots:</strong> Rocky edges of bays with small openings to the open sea — that's where fish gather.</li><li><strong>What you'll see:</strong> Common — sea bream, salpa, sea bass. Rare — octopus, sea urchins. Very rare — jellyfish.</li><li><strong>Safety:</strong> Never alone. Pair up with a snorkelling buddy.</li><li><strong>Sun protection:</strong> Reef-safe sunscreen. Cover your back with a rash guard — it burns.</li><li><strong>Combine with water sports:</strong> See our <a href="/best/water-sports">water sports</a> page for guided tours.</li></ul>`, de: `<h2>Tipps zum Schnorcheln</h2><ul><li><strong>Ausrüstung:</strong> Maske + Schnorchel + Wasserschuhe. Flossen sind nicht nötig, wenn du in flachem Wasser (1-3 m) bist.</li><li><strong>Beste Spots:</strong> Felsige Enden von Buchten mit kleinen "Fenstern" zum offenen Meer — dort sammeln sich die Fische.</li><li><strong>Was du sehen wirst:</strong> Häufig — Brassen (sea bream), Meeräschen, Wolfsbarsche. Selten — Oktopusse, Kraken, Seeigel. Sehr selten — Quallen.</li><li><strong>Sicherheit:</strong> Niemals allein. Schnorchelpartner mitnehmen.</li><li><strong>Sonnenschutz:</strong> Riff-sicheres Sonnenschutzmittel. Rücken mit Rash Guard bedecken — Sonnenbrandgefahr.</li><li><strong>Kombination mit Wassersport:</strong> Sieh dir die <a href="/best/water-sports">Wassersportarten</a> für geführte Touren an.</li></ul>`, ro: `<h2>Sfaturi pentru snorkeling</h2><ul><li><strong>Echipament:</strong> Mască + snorkel + pantofi pentru ape puțin adânci. Nu sunt necesare labe dacă ești în ape puțin adânci (1-3m).</li><li><strong>Cele mai bune locuri:</strong> Marginile stâncoase ale golfurilor cu mici "ferestre" către marea deschisă — acolo se adună peștii.</li><li><strong>Ce vei vedea:</strong> În mod constant — dorade (sea bream), sarpe, bibani. Rar — caracatițe, sepii, arici de mare. Foarte rar — meduze.</li><li><strong>Siguranță:</strong> Niciodată singur. Înoată cu un partener de snorkeling.</li><li><strong>Protecție solară:</strong> Cremă de protecție solară sigură pentru recif. Acoperă-ți spatele cu un rash guard — se arde.</li><li><strong>Combinare cu sporturi nautice:</strong> Vezi <a href="/best/water-sports">sporturile nautice</a> pentru tururi ghidate.</li></ul>`, sr: `<h2>Saveti za snorkeling</h2><ul><li><strong>Oprema:</strong> Maska + disalica + cipele za plitku vodu. Peraja nisu potrebna ako si u plitkom (1-3m).</li><li><strong>Najbolja mesta:</strong> Stenoviti krajevi zaliva sa malim "prozorima" ka otvorenom moru — tu se skupljaju ribe.</li><li><strong>Šta ćeš videti:</strong> Uvek — orade, sarpe, brancini. Retko — hobotnice, osmokrake, ježeve. Veoma retko — meduze.</li><li><strong>Bezbednost:</strong> Nikad sam. Uvek sa snorkeling partnerom.</li><li><strong>Zaštita od sunca:</strong> Krema za sunčanje bezbedna za korale. Pokrij leđa rash guard majicom — lako izgore.</li><li><strong>Kombinacija sa vodenim sportovima:</strong> Pogledaj <a href="/best/water-sports">vodene sportove</a> za vođene ture.</li></ul>`, bg: `<h2>Съвети за snorkeling</h2><ul><li><strong>Екипировка:</strong> Маска + шнорхел + обувки за плитки води. Не са нужни плавници, ако си в плитки води (1-3m).</li><li><strong>Най-добри места:</strong> Каменисти краища на заливи с малки "прозорци" към открито море — там се събират рибите.</li><li><strong>Какво ще видиш:</strong> Често — ципура, сарпи, лавраци. Рядко — октоподи, морски таралежи. Много рядко — медузи.</li><li><strong>Безопасност:</strong> Никога сам. Плувай с партньор за snorkeling.</li><li><strong>Защита от слънце:</strong> Риф-безопасен слънцезащитен крем. Покрий гърба си с rash guard — изгаря се.</li><li><strong>Комбинация с водни спортове:</strong> Виж <a href="/best/water-sports">водни спортове</a> за организирани турове.</li></ul>`, ru: `<h2>Советы для сноркелинга</h2><ul><li><strong>Оборудование:</strong> Маска + трубка + обувь для мелководья. Ласты не нужны, если вы на мелководье (1-3 м).</li><li><strong>Лучшие места:</strong> Каменистые края бухт с небольшими "окнами" в открытое море — там собираются рыбы.</li><li><strong>Что вы увидите:</strong> Постоянно — морской лещ, сарпы, лавраки. Редко — осьминоги, каракатицы, морские ежи. Очень редко — медузы.</li><li><strong>Безопасность:</strong> Никогда не плавайте в одиночку. Плавайте с напарником по сноркелингу.</li><li><strong>Защита от солнца:</strong> Риф-безопасный солнцезащитный крем. Покрывайте спину рашгардом — она обгорает.</li><li><strong>Сочетание с водными видами спорта:</strong> Смотрите <a href="/best/water-sports">водные виды спорта</a> для экскурсий с гидом.</li></ul>` },
    faqs: [
      { q: { el: `Που είναι τα καλύτερα νερά για snorkeling;`, en: `Where is the best water for snorkelling?`, de: `Wo sind die besten Gewässer zum Schnorcheln?`, ro: `Unde sunt cele mai bune ape pentru snorkeling?`, sr: `Gde su najbolje vode za snorkeling?`, bg: `Къде са най-добрите води за snorkeling?`, ru: `Где лучшие воды для сноркелинга?` }, a: { el: `<strong>Σιθωνία</strong> γενικά — δες <a href="/best/beaches-sithonia">όλες τις παραλίες Σιθωνίας</a>. Συγκεκριμένα: Διάπορος, Καρύδι, Φάβα, Λιμανάκι (Blue Lagoon).`, en: `<strong>Sithonia</strong> overall — see <a href="/best/beaches-sithonia">all Sithonia beaches</a>. Specifically: Diaporos, Karydi, Fava, Limanaki (Blue Lagoon).`, de: `<strong>Sithonia</strong> generell — siehe <a href="/best/beaches-sithonia">alle Strände von Sithonia</a>. Konkret: Diaporos, Karydi, Fava, Limanaki (Blue Lagoon).`, ro: `<strong>Sithonia</strong> în general — vezi <a href="/best/beaches-sithonia">toate plajele din Sithonia</a>. Specific: Diaporos, Karydi, Fava, Limanaki (Blue Lagoon).`, sr: `<strong>Sitonija</strong> generalno — pogledaj <a href="/best/beaches-sithonia">sve plaže Sitonije</a>. Konkretno: Diaporos, Karydi, Fava, Limanaki (Blue Lagoon).`, bg: `<strong>Ситония</strong> като цяло — виж <a href="/best/beaches-sithonia">всички плажове на Ситония</a>. Конкретно: Диапорос, Кариди, Фава, Лиманаки (Blue Lagoon).`, ru: `<strong>Ситония</strong> в целом — смотрите <a href="/best/beaches-sithonia">все пляжи Ситонии</a>. Конкретно: Диапорос, Кариди, Фава, Лиманаки (Голубая Лагуна).` } },
      { q: { el: `Υπάρχουν επικίνδυνα ζώα στο νερό;`, en: `Are there dangerous animals in the water?`, de: `Gibt es gefährliche Tiere im Wasser?`, ro: `Există animale periculoase în apă?`, sr: `Postoje li opasne životinje u vodi?`, bg: `Има ли опасни животни във водата?`, ru: `Есть ли опасные животные в воде?` }, a: { el: `Όχι ουσιαστικά. Σπάνια μέδουσες τον Αύγουστο. Δεν υπάρχουν επικίνδυνα ψάρια ή καρχαρίες στις ακτές της Χαλκιδικής.`, en: `Essentially no. Rare jellyfish in August. No dangerous fish or sharks along Halkidiki's coast.`, de: `Im Wesentlichen nein. Selten Quallen im August. Es gibt keine gefährlichen Fische oder Haie an den Küsten von Chalkidiki.`, ro: `Nu, în esență. Rar meduze în august. Nu există pești periculoși sau rechini pe coastele Halkidiki.</faq1_a>`, sr: `Ne u suštini. Retko meduze u avgustu. Nema opasnih riba ili ajkula na obalama Halkidikija.`, bg: `Не съществено. Рядко медузи през август. Няма опасни риби или акули по бреговете на Халкидики.`, ru: `Нет, по сути. Редко медузы в августе. Опасных рыб или акул на побережье Халкидики нет.` } },
      { q: { el: `Χρειάζομαι δίπλωμα/εκπαίδευση;`, en: `Do I need certification/training?`, de: `Brauche ich einen Schein/Ausbildung?`, ro: `Am nevoie de permis/instruire?`, sr: `Da li mi je potrebna dozvola/obuka?`, bg: `Нуждая ли се от диплома/обучение?`, ru: `Нужна ли лицензия/обучение?` }, a: { el: `Όχι για βασικό snorkeling. Είναι ασφαλές για όποιον μπορεί να κολυμπήσει. Για scuba diving βλέπε <a href="/best/water-sports">water sports</a>.`, en: `No for basic snorkelling. Safe for anyone who can swim. For scuba diving see <a href="/best/water-sports">water sports</a>.`, de: `Nicht für grundlegendes Schnorcheln. Es ist sicher für jeden, der schwimmen kann. Für Tauchen siehe <a href="/best/water-sports">Wassersportarten</a>.`, ro: `Nu pentru snorkeling de bază. Este sigur pentru oricine poate înota. Pentru scuba diving, vezi <a href="/best/water-sports">sporturile nautice</a>.`, sr: `Ne za osnovni snorkeling. Bezbedno je za svakoga ko zna da pliva. Za ronjenje sa bocama pogledaj <a href="/best/water-sports">vodene sportove</a>.`, bg: `Не за основно snorkeling. Безопасно е за всеки, който може да плува. За гмуркане виж <a href="/best/water-sports">водни спортове</a>.`, ru: `Нет для базового сноркелинга. Это безопасно для любого, кто умеет плавать. Для дайвинга смотрите <a href="/best/water-sports">водные виды спорта</a>.` } },
    ],
  },
  "instagram-spots": {
    intro: { el: `<p>Η Χαλκιδική, με τις τρεις χερσονήσους, τα τυρκουάζ νερά, τα ξωκλήσια στους λόφους και τα γραφικά λιμανάκια, είναι ένας πραγματικός θησαυρός για photographers και Instagram creators. Από τις χαρακτηριστικές <strong>Καβουρότρυπες (Orange Beach)</strong> με τους πορτοκαλί βραχώδεις σχηματισμούς, μέχρι την <strong>Παραλία Ποσειδίου</strong> με τη μοναδική γλώσσα γης και τον φάρο, η περιοχή έχει αρκετά iconic σημεία για να γεμίσεις ένα ολόκληρο Instagram archive. Αυτή η λίστα συγκεντρώνει τα πιο φωτογενή spots — από τα διάσημα μέχρι μυστικά που λίγοι ξέρουν.</p>`, en: `<p>Halkidiki, with its three peninsulas, turquoise water, hillside chapels and picturesque little harbours, is a real treasure for photographers and Instagram creators. From the iconic <strong>Kavourotrypes (Orange Beach)</strong> with its orange rock formations to <strong>Possidi Beach</strong> with its unique sand spit and lighthouse, the area has enough iconic spots to fill an entire Instagram archive. This list collects the most photogenic spots — from the famous to little-known secrets.</p>`, de: `<p>Chalkidiki, mit seinen drei Halbinseln, türkisfarbenem Wasser, Kapellen auf den Hügeln und malerischen kleinen Häfen, ist ein wahrer Schatz für Fotografen und Instagram-Creators. Von den charakteristischen <strong>Kavourotrypes (Orange Beach)</strong> mit den orangefarbenen Felsformationen bis zum <strong>Strand von Possidi</strong> mit der einzigartigen Landzunge und dem Leuchtturm hat die Region viele ikonische Orte, um ein ganzes Instagram-Archiv zu füllen. Diese Liste fasst die fotogensten Spots zusammen – von den berühmten bis zu den geheimen, die nur wenige kennen.</p>`, ro: `<p>Halkidiki, cu cele trei peninsule, apele turcoaz, bisericuțele de pe dealuri și porturile pitorești, este un adevărat tezaur pentru fotografi și creatorii de conținut pentru Instagram. De la caracteristicile <strong>Kavourotrypes (Orange Beach)</strong> cu formațiunile sale stâncoase portocalii, până la <strong>Plaja Possidi</strong> cu limba sa unică de pământ și farul, regiunea are suficiente locuri iconice pentru a umple un întreg arhivă Instagram. Această listă adună cele mai fotogenice locuri — de la cele celebre la secrete pe care puțini le cunosc.</p>`, sr: `<p>Halkidiki, sa tri poluostrva, tirkiznim vodama, kapelicama na brdima i slikovitim lukama, pravi je dragulj za fotografe i Instagram kreatore. Od karakterističnih <strong>Kavourotrypes (Orange Beach)</strong> sa narandžastim stenovitim formacijama, do <strong>Plaže Possidi</strong> sa jedinstvenim jezičkom zemlje i svetionikom, region ima dovoljno ikoničnih mesta da napuniš čitav Instagram arhiv. Ova lista okuplja najfotogeničnija mesta — od poznatih do tajnih koja malo ko zna.</p>`, bg: `<p>Халкидики, с трите си полуострова, тюркоазените води, параклисите по хълмовете и живописните пристанища, е истинско съкровище за фотографи и Instagram творци. От характерните <strong>Кавуротрипес (Orange Beach)</strong> с оранжевите скални образувания, до <strong>Плаж Посиди</strong> с уникалния език от земя и фара, регионът има достатъчно емблематични места, за да напълниш цял Instagram архив. Този списък събира най-фотогеничните места — от известните до тайни, които малцина знаят.</p>`, ru: `<p>Халкидики, с тремя полуостровами, бирюзовыми водами, часовнями на холмах и живописными гаванями, является настоящим сокровищем для фотографов и создателей Instagram. От характерных <strong>Кавуротрипес (Orange Beach)</strong> с оранжевыми скалистыми образованиями до <strong>пляжа Посиди</strong> с уникальной полосой земли и маяком, регион предлагает множество знаковых мест, чтобы заполнить целый Instagram-архив. Этот список собирает самые фотогеничные места — от известных до секретных, о которых знают немногие.</p>` },
    seasonal: { el: `<h2>Πότε για τις καλύτερες φωτογραφίες</h2><p><strong>Golden hour:</strong> 30 λεπτά μετά την ανατολή και 30 λεπτά πριν τη δύση — το μαλακό φως κάνει τα νερά να ακτινοβολούν. <strong>Καλοκαίρι:</strong> Μέγιστη φωτεινότητα, καθαρά νερά. <strong>Φθινόπωρο:</strong> Καλύτερα χρώματα, αδειασμένες παραλίες — τέλειο για landscape photography. <strong>Καλύτερη ώρα παραλίας:</strong> 7-9 το πρωί χωρίς κόσμο. Μετά τις 11 γεμίζει.</p>`, en: `<h2>When for the best shots</h2><p><strong>Golden hour:</strong> 30 minutes after sunrise and 30 minutes before sunset — soft light makes the water glow. <strong>Summer:</strong> Maximum brightness, clear water. <strong>Autumn:</strong> Better colours, empty beaches — perfect for landscape photography. <strong>Best beach time:</strong> 7-9 AM with no crowds. After 11 it fills up.</p>`, de: `<h2>Wann für die besten Fotos</h2><p><strong>Goldene Stunde:</strong> 30 Minuten nach Sonnenaufgang und 30 Minuten vor Sonnenuntergang – das weiche Licht lässt das Wasser strahlen. <strong>Sommer:</strong> Maximale Helligkeit, klares Wasser. <strong>Herbst:</strong> Bessere Farben, leere Strände – perfekt für Landschaftsfotografie. <strong>Beste Strandzeit:</strong> 7-9 Uhr morgens ohne Menschenmassen. Nach 11 Uhr wird es voll.</p>`, ro: `<h2>Când să faci cele mai bune fotografii</h2><p><strong>Ora de aur:</strong> 30 de minute după răsărit și 30 de minute înainte de apus — lumina moale face ca apele să strălucească. <strong>Vara:</strong> Luminozitate maximă, ape curate. <strong>Toamna:</strong> Culori mai bune, plaje goale — perfect pentru fotografia de peisaj. <strong>Cea mai bună oră pentru plajă:</strong> 7-9 dimineața fără mulțime. După ora 11 devine aglomerat.</p>`, sr: `<h2>Kada za najbolje fotografije</h2><p><strong>Zlatni sat:</strong> 30 minuta nakon izlaska i 30 minuta pre zalaska sunca — meka svetlost čini da vode sijaju. <strong>Leto:</strong> Maksimalna svetlost, čiste vode. <strong>Jesen:</strong> Bolje boje, prazne plaže — savršeno za pejzažnu fotografiju. <strong>Najbolje vreme za plažu:</strong> 7-9 ujutru bez gužve. Posle 11 se puni.</p>`, bg: `<h2>Кога за най-добрите снимки</h2><p><strong>Златен час:</strong> 30 минути след изгрев и 30 минути преди залез — меката светлина кара водите да блестят. <strong>Лято:</strong> Максимална яркост, чисти води. <strong>Есен:</strong> По-добри цветове, празни плажове — перфектно за пейзажна фотография. <strong>Най-добро време за плаж:</strong> 7-9 сутринта без хора. След 11 се пълни.</p>`, ru: `<h2>Когда лучше всего фотографировать</h2><p><strong>Золотой час:</strong> 30 минут после восхода и 30 минут до заката — мягкий свет делает воды сияющими. <strong>Лето:</strong> Максимальная яркость, чистые воды. <strong>Осень:</strong> Лучшие цвета, пустые пляжи — идеально для пейзажной фотографии. <strong>Лучшее время для пляжа:</strong> 7-9 утра без людей. После 11 становится многолюдно.</p>` },
    tips: { el: `<h2>Συμβουλές για φωτογράφιση</h2><ul><li><strong>Εξοπλισμός:</strong> Drone (επιτρέπεται με άδεια), wide-angle lens για beaches, polarizer για νερά. Mobile camera με filter απόλυτα επαρκής.</li><li><strong>Iconic spots:</strong> Φάρος Ποσειδίου, Καβουρότρυπες, Πύργος Προσφορίου (Ουρανούπολη), Άφυτος παλαιό χωριό, Βουρβουρού.</li><li><strong>Drone:</strong> Άδεια απαιτείται για εμπορική χρήση. Προσωπική χρήση επιτρέπεται κάτω από 120m. Όχι πάνω από κόσμο.</li><li><strong>Αποφυγή:</strong> Μην ενοχλείς ντόπιους ή ταβέρνες ζητώντας να βγάλεις stories. Ζητάς πρώτα.</li><li><strong>Sunset shots:</strong> Δυτική Χαλκιδική (Ποσείδι, δυτική Καλλιθέα) — όχι ανατολικά πόδια.</li><li><strong>Combine:</strong> Δες τις <a href="/best/beaches-sithonia">παραλίες Σιθωνίας</a> για photogenic επιλογές.</li></ul>`, en: `<h2>Photography tips</h2><ul><li><strong>Gear:</strong> Drone (permitted with license), wide-angle for beaches, polariser for water. A mobile camera with filters is plenty.</li><li><strong>Iconic spots:</strong> Possidi lighthouse, Kavourotrypes, Prosforion Tower (Ouranoupoli), old Afytos village, Vourvourou.</li><li><strong>Drone:</strong> Permit required for commercial use. Personal use allowed below 120m. Not over people.</li><li><strong>Etiquette:</strong> Don't bother locals or tavernas asking to shoot stories. Ask first.</li><li><strong>Sunset shots:</strong> Western Halkidiki (Possidi, western Kallithea) — not the eastern legs.</li><li><strong>Combine:</strong> See our <a href="/best/beaches-sithonia">Sithonia beaches</a> for photogenic picks.</li></ul>`, de: `<h2>Fototipps</h2><ul><li><strong>Ausrüstung:</strong> Drohne (erlaubt mit Genehmigung), Weitwinkelobjektiv für Strände, Polarisationsfilter für Wasser. Handykamera mit Filter völlig ausreichend.</li><li><strong>Ikonische Orte:</strong> Leuchtturm von Possidi, Kavourotrypes, Turm von Prosforiou (Ouranoupoli), altes Dorf Afytos, Vourvourou.</li><li><strong>Drohne:</strong> Genehmigung erforderlich für kommerzielle Nutzung. Persönliche Nutzung erlaubt unter 120m. Nicht über Menschenmengen.</li><li><strong>Vermeidung:</strong> Störe keine Einheimischen oder Tavernen, um Stories zu machen. Bitte vorher fragen.</li><li><strong>Sonnenuntergangsaufnahmen:</strong> Westliches Chalkidiki (Possidi, westliche Kallithea) – nicht östliche Beine.</li><li><strong>Kombinieren:</strong> Sieh dir die <a href="/best/beaches-sithonia">Strände von Sithonia</a> für fotogene Optionen an.</li></ul>`, ro: `<h2>Sfaturi pentru fotografiere</h2><ul><li><strong>Echipament:</strong> Dronă (permisă cu autorizație), obiectiv wide-angle pentru plaje, polarizator pentru ape. Camera mobilă cu filtru este absolut suficientă.</li><li><strong>Locuri iconice:</strong> Farul Possidi, Kavourotrypes, Turnul Prosforiou (Ouranoupoli), vechiul sat Afytos, Vourvourou.</li><li><strong>Dronă:</strong> Este necesară autorizație pentru utilizare comercială. Utilizarea personală este permisă sub 120m. Nu deasupra mulțimilor.</li><li><strong>Evitare:</strong> Nu deranja localnicii sau tavernele cerând să faci stories. Întreabă mai întâi.</li><li><strong>Fotografii la apus:</strong> Vestul Halkidiki (Possidi, vestul Kallithea) — nu pe picioarele estice.</li><li><strong>Combină:</strong> Vezi <a href="/best/beaches-sithonia">plajele din Sithonia</a> pentru opțiuni fotogenice.</li></ul>`, sr: `<h2>Saveti za fotografisanje</h2><ul><li><strong>Oprema:</strong> Dron (dozvoljen sa dozvolom), širokougaoni objektiv za plaže, polarizator za vode. Mobilna kamera sa filterom potpuno dovoljna.</li><li><strong>Ikonična mesta:</strong> Svetionik Possidi, Kavourotrypes, Toranj Prosforiou (Ouranoupoli), staro selo Afytos, Vourvourou.</li><li><strong>Dron:</strong> Dozvola je potrebna za komercijalnu upotrebu. Lična upotreba dozvoljena ispod 120m. Ne iznad ljudi.</li><li><strong>Izbegavanje:</strong> Ne uznemiravaj lokalce ili taverne tražeći da snimiš storije. Prvo pitaj.</li><li><strong>Snimci zalaska sunca:</strong> Zapadna Halkidiki (Possidi, zapadna Kallithea) — ne istočna stopala.</li><li><strong>Kombinuj:</strong> Pogledaj <a href="/best/beaches-sithonia">plaže Sitonije</a> za fotogenične opcije.</li></ul>`, bg: `<h2>Съвети за фотографиране</h2><ul><li><strong>Оборудване:</strong> Дрон (разрешен с лиценз), широкоъгълен обектив за плажове, поляризатор за води. Мобилна камера с филтър е напълно достатъчна.</li><li><strong>Емблематични места:</strong> Фарът Посиди, Кавуротрипес, Кулата Просфориу (Урануполи), старото село Афитос, Вурвуру.</li><li><strong>Дрон:</strong> Лиценз се изисква за търговска употреба. Лична употреба е позволена под 120м. Не над хора.</li><li><strong>Избягване:</strong> Не притеснявай местните или таверните, като искаш да правиш stories. Питай първо.</li><li><strong>Снимки на залез:</strong> Западно Халкидики (Посиди, западна Калитея) — не източните крака.</li><li><strong>Комбинирай:</strong> Виж <a href="/best/beaches-sithonia">плажовете на Ситония</a> за фотогенични опции.</li></ul>`, ru: `<h2>Советы по фотографии</h2><ul><li><strong>Оборудование:</strong> Дрон (разрешен с лицензией), широкоугольный объектив для пляжей, поляризатор для вод. Мобильная камера с фильтром вполне достаточна.</li><li><strong>Знаковые места:</strong> Маяк Посиди, Кавуротрипес, Башня Просфорио (Урануполи), старое село Афитос, Вурвуру.</li><li><strong>Дрон:</strong> Лицензия требуется для коммерческого использования. Личное использование разрешено ниже 120 м. Не летайте над людьми.</li><li><strong>Избегайте:</strong> Не беспокойте местных жителей или таверны, прося снять stories. Сначала спрашивайте разрешение.</li><li><strong>Съемка заката:</strong> Западные Халкидики (Посиди, западная Каллифея) — не восточные стороны.</li><li><strong>Совмещайте:</strong> Посмотрите <a href="/best/beaches-sithonia">пляжи Ситонии</a> для фотогеничных вариантов.</li></ul>` },
    faqs: [
      { q: { el: `Ποιο είναι το πιο iconic Instagram spot;`, en: `What's the most iconic Instagram spot?`, de: `Was ist der ikonischste Instagram-Spot?`, ro: `Care este cel mai iconic loc pentru Instagram?`, sr: `Koje je najikoničnije Instagram mesto?`, bg: `Кое е най-емблематичното Instagram място?`, ru: `Какое самое знаковое место для Instagram?` }, a: { el: `<strong>Καβουρότρυπες (Orange Beach)</strong> στη Σιθωνία — οι πορτοκαλί βράχοι + τυρκουάζ νερά είναι signature shot Χαλκιδικής. Δεύτερο: <strong>Φάρος Ποσειδίου</strong> με τη γλώσσα γης από drone.`, en: `<strong>Kavourotrypes (Orange Beach)</strong> in Sithonia — orange rocks + turquoise water is Halkidiki's signature shot. Second: <strong>Possidi lighthouse</strong> with the sand spit shot from a drone.`, de: `<strong>Kavourotrypes (Orange Beach)</strong> in Sithonia – die orangefarbenen Felsen + türkisfarbenes Wasser sind das Markenzeichen von Chalkidiki. Zweiter: <strong>Leuchtturm von Possidi</strong> mit der Landzunge aus der Drohne.</faq1_q>`, ro: `<strong>Kavourotrypes (Orange Beach)</strong> în Sithonia — stâncile portocalii + apele turcoaz sunt imaginea de marcă a Halkidiki. Al doilea: <strong>Farul Possidi</strong> cu limba de pământ văzută din dronă.`, sr: `<strong>Kavourotrypes (Orange Beach)</strong> na Sitoniji — narandžaste stene + tirkizne vode su prepoznatljiv snimak Halkidikija. Drugo: <strong>Svetionik Possidi</strong> sa jezičkom zemlje iz drona.`, bg: `<strong>Кавуротрипес (Orange Beach)</strong> в Ситония — оранжевите скали + тюркоазените води са запазена марка на Халкидики. Второ: <strong>Фарът Посиди</strong> с езика от земя от дрон.</faq1_q>`, ru: `<strong>Кавуротрипес (Orange Beach)</strong> в Ситонии — оранжевые скалы + бирюзовые воды являются фирменным кадром Халкидики. Второе: <strong>Маяк Посиди</strong> с полосой земли с дрона.` } },
      { q: { el: `Επιτρέπεται το drone στις παραλίες;`, en: `Are drones allowed at beaches?`, de: `Sind Drohnen an den Stränden erlaubt?`, ro: `Este permisă utilizarea dronei pe plaje?`, sr: `Da li je dozvoljen dron na plažama?`, bg: `Разрешено ли е използването на дрон на плажовете?`, ru: `Разрешены ли дроны на пляжах?` }, a: { el: `Ναι για προσωπική χρήση κάτω από 120m. Όχι πάνω από κόσμο. Εμπορική χρήση απαιτεί άδεια. Σε στρατιωτικές ζώνες (κοντά σύνορα) απαγορεύεται.`, en: `Yes for personal use below 120m. Not over people. Commercial use requires a permit. Forbidden in military zones (near borders).`, de: `Ja, für persönliche Nutzung unter 120m. Nicht über Menschenmengen. Kommerzielle Nutzung erfordert Genehmigung. In militärischen Zonen (nahe Grenzen) verboten.`, ro: `Da, pentru utilizare personală sub 120m. Nu deasupra mulțimilor. Utilizarea comercială necesită autorizație. În zonele militare (aproape de granițe) este interzisă.`, sr: `Da, za ličnu upotrebu ispod 120m. Ne iznad ljudi. Komercijalna upotreba zahteva dozvolu. U vojnim zonama (blizu granica) zabranjeno.`, bg: `Да, за лична употреба под 120м. Не над хора. Търговска употреба изисква лиценз. Във военни зони (близо до граници) е забранено.`, ru: `Да, для личного использования ниже 120 м. Не летайте над людьми. Коммерческое использование требует лицензии. В военных зонах (близ границ) запрещено.` } },
      { q: { el: `Που για sunset shots;`, en: `Where for sunset shots?`, de: `Wo für Sonnenuntergangsaufnahmen?`, ro: `Unde pentru fotografii la apus?`, sr: `Gde za snimke zalaska sunca?`, bg: `Къде за снимки на залез?`, ru: `Где лучше всего снимать закаты?` }, a: { el: `<strong>Ποσείδι</strong> — δυτική Κασσάνδρα, ηλιοβασίλεμα πάνω από τη γλώσσα γης. <strong>Δυτική Καλλιθέα</strong>. Σιθωνία δυτική (Πόρτο Κουφό). Φωτογραφία κατά της ανατολής/δύσης κάνει νερά να αστράφτουν.`, en: `<strong>Possidi</strong> — western Kassandra, sunset over the sand spit. <strong>Western Kallithea</strong>. Western Sithonia (Porto Koufo). Shooting into the sunset makes the water sparkle.`, de: `<strong>Possidi</strong> – westliche Kassandra, Sonnenuntergang über der Landzunge. <strong>Westliche Kallithea</strong>. Westliches Sithonia (Porto Koufo). Fotografie gegen Sonnenaufgang/-untergang lässt das Wasser funkeln.`, ro: `<strong>Possidi</strong> — vestul Kassandrei, apusul peste limba de pământ. <strong>Vestul Kallithea</strong>. Vestul Sithoniei (Porto Koufo). Fotografia împotriva răsăritului/apusului face ca apele să strălucească.`, sr: `<strong>Possidi</strong> — zapadna Kasandra, zalazak sunca iznad jezička zemlje. <strong>Zapadna Kallithea</strong>. Zapadna Sitonija (Porto Koufo). Fotografija protiv izlaska/zalaska čini da vode sijaju.`, bg: `<strong>Посиди</strong> — западна Касандра, залез над езика от земя. <strong>Западна Калитея</strong>. Западна Ситония (Порто Куфо). Фотография срещу изгрев/залез кара водите да блестят.`, ru: `<strong>Посиди</strong> — западная Кассандра, закат над полосой земли. <strong>Западная Каллифея</strong>. Западная Ситония (Порто Куфо). Фотография против восхода/заката делает воды сверкающими.` } },
    ],
  },
  "kids-activities": {
    intro: { el: `<p>Η Χαλκιδική είναι από τους πιο family-friendly προορισμούς της Ελλάδας — δεν είναι μόνο παραλίες με ρηχά νερά (δες τις <a href="/best/family-beaches">οικογενειακές παραλίες</a>), αλλά και ποικιλία δραστηριοτήτων για παιδιά κάθε ηλικίας. Από water parks και adventure parks, μέχρι θεματικά μουσεία και ζωολογικά πάρκα. Πολλά καταλύματα έχουν kids clubs και mini disco. Αυτή η λίστα συγκεντρώνει τις δραστηριότητες που σταθερά κερδίζουν θετικά reviews από οικογένειες.</p>`, en: `<p>Halkidiki is one of Greece's most family-friendly destinations — not just shallow-water beaches (see our <a href="/best/family-beaches">family beaches</a>), but a variety of activities for kids of every age. From water parks and adventure parks to themed museums and zoos. Many accommodations have kids clubs and mini discos. This list collects activities that consistently earn positive reviews from families.</p>`, de: `<p>Chalkidiki ist eines der familienfreundlichsten Reiseziele in Griechenland — es gibt nicht nur Strände mit seichtem Wasser (siehe die <a href="/best/family-beaches">Familienstrände</a>), sondern auch eine Vielzahl von Aktivitäten für Kinder jeden Alters. Von Wasserparks und Abenteuerparks bis hin zu Themenmuseen und Zoos. Viele Unterkünfte bieten Kids Clubs und Mini-Disco an. Diese Liste fasst die Aktivitäten zusammen, die von Familien durchweg positive Bewertungen erhalten.</p>`, ro: `<p>Halkidiki este una dintre cele mai prietenoase destinații din Grecia pentru familii — nu doar plaje cu ape puțin adânci (vezi <a href="/best/family-beaches">plajele pentru familii</a>), ci și o varietate de activități pentru copii de toate vârstele. De la parcuri acvatice și parcuri de aventură, până la muzee tematice și grădini zoologice. Multe unități de cazare au cluburi pentru copii și mini disco. Această listă reunește activitățile care primesc constant recenzii pozitive de la familii.</p>`, sr: `<p>Halkidiki je jedan od najprijateljskijih porodičnih destinacija u Grčkoj — nisu samo plaže sa plitkom vodom (pogledajte <a href="/best/family-beaches">porodične plaže</a>), već i raznovrsne aktivnosti za decu svih uzrasta. Od vodenih parkova i parkova avantura, do tematskih muzeja i zooloških vrtova. Mnoga smeštajna mesta imaju kids klubove i mini diskoteke. Ova lista okuplja aktivnosti koje konstantno dobijaju pozitivne recenzije od porodica.</p>`, bg: `<p>Халкидики е един от най-подходящите за семейства дестинации в Гърция — не само заради плажовете с плитки води (виж <a href="/best/family-beaches">семейни плажове</a>), но и заради разнообразието от дейности за деца на всякаква възраст. От водни паркове и приключенски паркове до тематични музеи и зоологически градини. Много от местата за настаняване разполагат с детски клубове и мини диско. Този списък събира дейностите, които постоянно получават положителни отзиви от семействата.</p>`, ru: `<p>Халкидики — один из самых дружелюбных для семейного отдыха регионов Греции — это не только пляжи с мелководьем (см. <a href="/best/family-beaches">семейные пляжи</a>), но и разнообразие развлечений для детей любого возраста. От аквапарков и парков приключений до тематических музеев и зоопарков. Многие отели предлагают kids clubs и мини-дискотеки. Этот список собирает мероприятия, которые стабильно получают положительные отзывы от семей.</p>` },
    seasonal: { el: `<h2>Πότε να πας με παιδιά</h2><p><strong>Ιούνιος:</strong> Ιδανικό — όλες οι δραστηριότητες ανοιχτές, λίγος κόσμος, καιρός 28-30°C. <strong>Ιούλιος-Αύγουστος:</strong> Peak, χρειάζεται κράτηση. Καλό για kids clubs καταλυμάτων. <strong>Σεπτέμβριος:</strong> Καλύτερες τιμές, λιγότερος κόσμος, αλλά μερικά κλείνουν στα τέλη του μήνα.</p>`, en: `<h2>When to visit with kids</h2><p><strong>June:</strong> Ideal — all activities open, fewer crowds, weather 28-30°C. <strong>July-August:</strong> Peak, needs booking. Great for accommodation kids clubs. <strong>September:</strong> Better prices, fewer crowds, but some close at end of month.</p>`, de: `<h2>Wann man mit Kindern reisen sollte</h2><p><strong>Juni:</strong> Ideal — alle Aktivitäten geöffnet, wenig Leute, Wetter 28-30°C. <strong>Juli-August:</strong> Hochsaison, Reservierungen erforderlich. Gut für Kids Clubs in Unterkünften. <strong>September:</strong> Bessere Preise, weniger Leute, aber einige schließen Ende des Monats.</p>`, ro: `<h2>Când să mergi cu copiii</h2><p><strong>Iunie:</strong> Ideal — toate activitățile sunt deschise, puțină lume, vremea 28-30°C. <strong>Iulie-August:</strong> Vârf de sezon, necesită rezervare. Bun pentru cluburile de copii ale unităților de cazare. <strong>Septembrie:</strong> Prețuri mai bune, mai puțină lume, dar unele se închid la sfârșitul lunii.</p>`, sr: `<h2>Kada ići sa decom</h2><p><strong>Jun:</strong> Idealno — sve aktivnosti otvorene, malo ljudi, vreme 28-30°C. <strong>Jul-Avgust:</strong> Vrh sezone, potrebna rezervacija. Dobro za kids klubove u smeštajima. <strong>Septembar:</strong> Bolje cene, manje ljudi, ali neka mesta se zatvaraju krajem meseca.</p>`, bg: `<h2>Кога да посетите с деца</h2><p><strong>Юни:</strong> Идеално — всички дейности са отворени, малко хора, времето е 28-30°C. <strong>Юли-Август:</strong> Пик, необходима е резервация. Добро за детски клубове в местата за настаняване. <strong>Септември:</strong> По-добри цени, по-малко хора, но някои затварят в края на месеца.</p>`, ru: `<h2>Когда ехать с детьми</h2><p><strong>Июнь:</strong> Идеально — все развлечения открыты, мало людей, погода 28-30°C. <strong>Июль-Август:</strong> Пик сезона, требуется бронирование. Хорошо для kids clubs в отелях. <strong>Сентябрь:</strong> Лучшие цены, меньше людей, но некоторые закрываются в конце месяца.</p>` },
    tips: { el: `<h2>Συμβουλές για διακοπές με παιδιά</h2><ul><li><strong>Σχεδιασμός:</strong> Πρωί παραλία (ρηχά + λιγότερη ζέστη) + απόγευμα δραστηριότητα + βραδινό φαγητό στις 19:00 (όχι 22:00 ελληνικό style).</li><li><strong>Kids equipment:</strong> Βραχιολάκι/σαμπρέλα, καπέλα, αντηλιακό SPF 50, φουσκωτό για μωρά.</li><li><strong>Water park:</strong> Aqualand Water Fun Park στη Νέα Πλάγια — μεγαλύτερο της περιοχής. Εισιτήριο €20-30/άτομο.</li><li><strong>Καταλύματα με kids club:</strong> Πολλά resorts στην Κασσάνδρα (Σάνη, Πευκοχώρι) έχουν επαγγελματικά kids clubs, mini disco, παιδικές πισίνες.</li><li><strong>Παραδοσιακή ταβέρνα:</strong> Δοκίμασε <a href="/best/traditional-tavernas">παραδοσιακές ταβέρνες</a> — οι Έλληνες είναι extra φιλικοί με παιδιά.</li><li><strong>Παιδικά μενού:</strong> Σχεδόν παντού. Συνήθως πατάτες/τυρόπιτα/σπαγγέτι.</li></ul>`, en: `<h2>Tips for a kids holiday</h2><ul><li><strong>Plan:</strong> Morning beach (shallow + less heat) + afternoon activity + 19:00 dinner (not 22:00 Greek style).</li><li><strong>Kids equipment:</strong> Armband/float, hats, SPF 50 sunscreen, baby float.</li><li><strong>Water park:</strong> Aqualand Water Fun Park in Nea Plagia — largest in the region. Ticket €20-30/person.</li><li><strong>Kids-club accommodation:</strong> Many Kassandra resorts (Sani, Pefkochori) have proper kids clubs, mini disco, kid pools.</li><li><strong>Traditional taverna:</strong> Try our <a href="/best/traditional-tavernas">traditional tavernas</a> — Greeks are extra kid-friendly.</li><li><strong>Kids menus:</strong> Almost everywhere. Usually fries/tyropita/pasta.</li></ul>`, de: `<h2>Tipps für den Urlaub mit Kindern</h2><ul><li><strong>Planung:</strong> Morgens Strand (seicht + weniger Hitze) + nachmittags Aktivität + Abendessen um 19:00 Uhr (nicht 22:00 Uhr im griechischen Stil).</li><li><strong>Ausrüstung für Kinder:</strong> Armband/Schwimmreifen, Hüte, Sonnencreme SPF 50, aufblasbare Schwimmhilfe für Babys.</li><li><strong>Wasserpark:</strong> Aqualand Water Fun Park in Nea Plagia — der größte der Region. Eintritt €20-30/Person.</li><li><strong>Unterkünfte mit Kids Club:</strong> Viele Resorts auf Kassandra (Sani, Pefkochori) haben professionelle Kids Clubs, Mini-Disco, Kinderpools.</li><li><strong>Traditionelle Taverne:</strong> Probiere <a href="/best/traditional-tavernas">traditionelle Tavernen</a> — die Griechen sind besonders kinderfreundlich.</li><li><strong>Kindergerichte:</strong> Fast überall. Normalerweise Pommes/Käsepastete/Spaghetti.</li></ul>`, ro: `<h2>Sfaturi pentru vacanțe cu copii</h2><ul><li><strong>Planificare:</strong> Dimineața la plajă (ape puțin adânci + mai puțină căldură) + activitate după-amiaza + cină la ora 19:00 (nu la 22:00 în stil grecesc).</li><li><strong>Echipament pentru copii:</strong> Brățară/colac, pălării, cremă de protecție solară SPF 50, colac pentru bebeluși.</li><li><strong>Parc acvatic:</strong> Aqualand Water Fun Park în Nea Plagia — cel mai mare din zonă. Bilet €20-30/persoană.</li><li><strong>Cazare cu cluburi pentru copii:</strong> Multe resorturi din Kassandra (Sani, Pefkochori) au cluburi pentru copii profesionale, mini disco, piscine pentru copii.</li><li><strong>Tavernă tradițională:</strong> Încearcă <a href="/best/traditional-tavernas">tavernele tradiționale</a> — grecii sunt extra prietenoși cu copiii.</li><li><strong>Meniuri pentru copii:</strong> Aproape peste tot. De obicei cartofi/piept de pui/spaghete.</li></ul>`, sr: `<h2>Saveti za odmor sa decom</h2><ul><li><strong>Planiranje:</strong> Jutarnja plaža (plitko + manje vruće) + popodnevna aktivnost + večera u 19:00 (ne u 22:00 po grčkom stilu).</li><li><strong>Oprema za decu:</strong> Narukvica/šlauf, šeširi, SPF 50 krema za sunčanje, dušek za bebe.</li><li><strong>Vodeni park:</strong> Aqualand Water Fun Park u Nea Plagiji — najveći u regionu. Ulaznica €20-30/osobi.</li><li><strong>Smeštaji sa kids klubom:</strong> Mnoga odmarališta na Kasandri (Sani, Pefkohori) imaju profesionalne kids klubove, mini diskoteke, dečje bazene.</li><li><strong>Tradicionalna taverna:</strong> Probajte <a href="/best/traditional-tavernas">tradicionalne taverne</a> — Grci su izuzetno prijateljski nastrojeni prema deci.</li><li><strong>Dečji meni:</strong> Skoro svuda. Obično krompirići/pita sa sirom/špageti.</li></ul>`, bg: `<h2>Съвети за почивка с деца</h2><ul><li><strong>Планиране:</strong> Сутрин на плаж (плитко + по-малко горещо) + следобед дейност + вечеря в 19:00 (не 22:00 по гръцки стил).</li><li><strong>Оборудване за деца:</strong> Гривна/пояс, шапки, слънцезащитен крем SPF 50, надуваемо за бебета.</li><li><strong>Воден парк:</strong> Aqualand Water Fun Park в Неа Плагия — най-големият в района. Билет €20-30/човек.</li><li><strong>Настаняване с детски клуб:</strong> Много курорти в Касандра (Сани, Пефкохори) имат професионални детски клубове, мини диско, детски басейни.</li><li><strong>Традиционна таверна:</strong> Опитайте <a href="/best/traditional-tavernas">традиционни таверни</a> — гърците са изключително приятелски настроени към децата.</li><li><strong>Детски менюта:</strong> Почти навсякъде. Обикновено картофи/тиропита/спагети.</li></ul>`, ru: `<h2>Советы для отдыха с детьми</h2><ul><li><strong>Планирование:</strong> Утром пляж (мелководье + меньше жара) + днем активность + ужин в 19:00 (не в 22:00, как по-гречески).</li><li><strong>Детское снаряжение:</strong> Браслет/нарукавники, шляпы, солнцезащитный крем SPF 50, надувной круг для малышей.</li><li><strong>Аквапарк:</strong> Aqualand Water Fun Park в Неа Плагия — самый большой в регионе. Билет €20-30/человек.</li><li><strong>Отели с kids club:</strong> Многие курорты на Кассандре (Сани, Певкохори) имеют профессиональные kids clubs, мини-дискотеки, детские бассейны.</li><li><strong>Традиционная таверна:</strong> Попробуйте <a href="/best/traditional-tavernas">традиционные таверны</a> — греки особенно дружелюбны к детям.</li><li><strong>Детское меню:</strong> Почти везде. Обычно картофель/пирог с сыром/спагетти.</li></ul>` },
    faqs: [
      { q: { el: `Υπάρχει water park κοντά;`, en: `Is there a water park nearby?`, de: `Gibt es einen Wasserpark in der Nähe?`, ro: `Există un parc acvatic în apropiere?`, sr: `Postoji li vodeni park u blizini?`, bg: `Има ли воден парк наблизо?`, ru: `Есть ли аквапарк поблизости?` }, a: { el: `<strong>Aqualand Water Fun Park</strong> στη Νέα Πλάγια είναι το μεγαλύτερο. Εισιτήριο €25-30/ενήλικα, €18-20/παιδί. Ανοιχτό Ιούνιος-Σεπτέμβριος.`, en: `<strong>Aqualand Water Fun Park</strong> in Nea Plagia is the biggest. Ticket €25-30/adult, €18-20/child. Open June-September.`, de: `<strong>Aqualand Water Fun Park</strong> in Nea Plagia ist der größte. Eintritt €25-30/Erwachsener, €18-20/Kind. Geöffnet Juni-September.`, ro: `<strong>Aqualand Water Fun Park</strong> în Nea Plagia este cel mai mare. Bilet €25-30/adult, €18-20/copil. Deschis iunie-septembrie.`, sr: `<strong>Aqualand Water Fun Park</strong> u Nea Plagiji je najveći. Ulaznica €25-30/odrasli, €18-20/dete. Otvoren jun-septembar.`, bg: `<strong>Aqualand Water Fun Park</strong> в Неа Плагия е най-големият. Билет €25-30/възрастен, €18-20/дете. Отворен Юни-Септември.`, ru: `<strong>Aqualand Water Fun Park</strong> в Неа Плагия — самый большой. Билет €25-30/взрослый, €18-20/ребенок. Открыт с июня по сентябрь.` } },
      { q: { el: `Πιο κατάλληλη χερσόνησος για παιδιά;`, en: `Best peninsula for kids?`, de: `Welche Halbinsel ist am besten für Kinder geeignet?`, ro: `Care peninsulă este mai potrivită pentru copii?`, sr: `Koji je poluostrvo najpogodnije za decu?`, bg: `Кой полуостров е най-подходящ за деца?`, ru: `Какой полуостров больше подходит для детей?` }, a: { el: `<strong>Κασσάνδρα</strong> — πιο αναπτυγμένη, καλύτερες υποδομές, kids clubs, water park κοντά. <strong>Σιθωνία</strong> πιο ήρεμη αλλά λιγότερες δομές για παιδιά.`, en: `<strong>Kassandra</strong> — more developed, better facilities, kids clubs, water park nearby. <strong>Sithonia</strong> is calmer but has fewer kid-specific facilities.`, de: `<strong>Kassandra</strong> — besser entwickelt, bessere Infrastruktur, Kids Clubs, Wasserpark in der Nähe. <strong>Sithonia</strong> ist ruhiger, hat aber weniger Einrichtungen für Kinder.`, ro: `<strong>Kassandra</strong> — mai dezvoltată, infrastructură mai bună, cluburi pentru copii, parc acvatic în apropiere. <strong>Sithonia</strong> este mai liniștită, dar mai puține facilități pentru copii.`, sr: `<strong>Kasandra</strong> — najrazvijenija, bolje infrastrukture, kids klubovi, vodeni park u blizini. <strong>Sitonija</strong> je mirnija, ali ima manje sadržaja za decu.`, bg: `<strong>Касандра</strong> — по-развита, по-добра инфраструктура, детски клубове, воден парк наблизо. <strong>Ситония</strong> е по-спокойна, но с по-малко съоръжения за деца.`, ru: `<strong>Кассандра</strong> — более развитая, лучшие инфраструктуры, kids clubs, аквапарк рядом. <strong>Ситония</strong> более спокойная, но меньше инфраструктур для детей.` } },
      { q: { el: `Είναι ασφαλή τα νερά για μωρά;`, en: `Is the water safe for babies?`, de: `Sind die Gewässer für Babys sicher?`, ro: `Sunt apele sigure pentru bebeluși?`, sr: `Da li je voda bezbedna za bebe?`, bg: `Безопасни ли са водите за бебета?`, ru: `Безопасны ли воды для малышей?` }, a: { el: `Ναι, στις <a href="/best/family-beaches">οικογενειακές παραλίες</a> με ρηχό βυθό. Σάνη Marina, Σιβηρή, Νέα Φώκαια έχουν 20-30m ρηχής ζώνης.`, en: `Yes, on our <a href="/best/family-beaches">family beaches</a> with shallow bottoms. Sani Marina, Siviri, Nea Fokaia have 20-30m of shallows.`, de: `Ja, an den <a href="/best/family-beaches">Familienstränden</a> mit flachem Grund. Sani Marina, Siviri, Nea Fokea haben eine 20-30m flache Zone.`, ro: `Da, pe <a href="/best/family-beaches">plajele pentru familii</a> cu fund puțin adânc. Sani Marina, Siviri, Nea Fokea au zone de 20-30m cu apă puțin adâncă.`, sr: `Da, na <a href="/best/family-beaches">porodičnim plažama</a> sa plitkim dnom. Sani Marina, Siviri, Nea Fokea imaju 20-30m plitke zone.`, bg: `Да, на <a href="/best/family-beaches">семейните плажове</a> с плитко дъно. Сани Марина, Сивири, Неа Фокеа имат 20-30м плитка зона.`, ru: `Да, на <a href="/best/family-beaches">семейных пляжах</a> с мелким дном. Сани Марина, Сивири, Неа Фокеа имеют 20-30 м мелководной зоны.` } },
    ],
  },
  "romantic-getaways": {
    intro: { el: `<p>Η Χαλκιδική είναι ιδανική για romantic getaways χωρίς να θυσιάζεις την πρόσβαση — σε αντίθεση με τα νησιά που χρειάζονται ferry, εδώ μπαίνεις και βγαίνεις με αυτοκίνητο. Boutique hotels με sea-view σουίτες, ιδιωτικές παραλίες, sunset δείπνα, spa treatments σε resorts — όλα διαθέσιμα. Τα πιο ρομαντικά spots: <strong>Σιθωνία</strong> για φυσικό romance (παραλίες, sunset σε Vourvourou), <strong>Άφυτος</strong> για χαριτωμένο παραδοσιακό χωριό με sea view, <strong>Ουρανούπολη</strong> για μυστικιστική απόσταξη του Άθω. Αυτή η λίστα συγκεντρώνει τα κορυφαία επιλογές για ζευγάρια και honeymooners.</p>`, en: `<p>Halkidiki is ideal for romantic getaways without sacrificing access — unlike Greek islands needing a ferry, here you drive in and out. Boutique hotels with sea-view suites, private beaches, sunset dinners, spa treatments at resorts — all available. The most romantic spots: <strong>Sithonia</strong> for natural romance (beaches, Vourvourou sunset), <strong>Afytos</strong> for a charming traditional village with sea view, <strong>Ouranoupoli</strong> for mystical Mount Athos vibes. This list collects the top picks for couples and honeymooners.</p>`, de: `<p>Chalkidiki ist ideal für romantische Ausflüge, ohne dass man auf die Erreichbarkeit verzichten muss – im Gegensatz zu den Inseln, die eine Fähre erfordern, kann man hier mit dem Auto ein- und ausfahren. Boutique-Hotels mit Suiten mit Meerblick, private Strände, Abendessen bei Sonnenuntergang, Spa-Behandlungen in Resorts – alles verfügbar. Die romantischsten Orte: <strong>Sithonia</strong> für natürliche Romantik (Strände, Sonnenuntergang in Vourvourou), <strong>Afytos</strong> für ein charmantes traditionelles Dorf mit Meerblick, <strong>Ouranoupoli</strong> für eine mystische Essenz des Athos. Diese Liste fasst die besten Optionen für Paare und Honeymooner zusammen.</p>`, ro: `<p>Halkidiki este ideală pentru escapade romantice fără a sacrifica accesibilitatea — spre deosebire de insulele care necesită ferry, aici poți intra și ieși cu mașina. Hoteluri boutique cu suite cu vedere la mare, plaje private, cine la apus, tratamente spa în resorturi — toate disponibile. Cele mai romantice locuri: <strong>Sithonia</strong> pentru un romantism natural (plaje, apus în Vourvourou), <strong>Afytos</strong> pentru un sat tradițional fermecător cu vedere la mare, <strong>Ouranoupoli</strong> pentru o distilare mistică a Muntelui Athos. Această listă reunește cele mai bune opțiuni pentru cupluri și proaspeți căsătoriți.</p>`, sr: `<p>Halkidiki je idealna za romantične izlete bez žrtvovanja pristupačnosti — za razliku od ostrva koja zahtevaju trajekt, ovde možete da uđete i izađete automobilom. Boutique hoteli sa apartmanima s pogledom na more, privatne plaže, večere uz zalazak sunca, spa tretmani u rizortima — sve je dostupno. Najromantičnija mesta: <strong>Sithonia</strong> za prirodni romantični ugođaj (plaže, zalazak sunca u Vourvourou), <strong>Afytos</strong> za šarmantno tradicionalno selo s pogledom na more, <strong>Ouranoupoli</strong> za mističnu atmosferu Svete Gore. Ova lista okuplja najbolje izbore za parove i mladence.</p>`, bg: `<p>Халкидики е идеално за романтични бягства без да жертвате достъпа си — за разлика от островите, които изискват ферибот, тук можете да влезете и излезете с кола. Бутик хотели с апартаменти с изглед към морето, частни плажове, вечеря на залез, спа процедури в курорти — всичко е налично. Най-романтичните места: <strong>Ситония</strong> за естествен романс (плажове, залез във Вурвуру), <strong>Афитос</strong> за чаровно традиционно село с изглед към морето, <strong>Урануполи</strong> за мистична дестилация на Света гора. Този списък събира най-добрите избори за двойки и младоженци.</p>`, ru: `<p>Халкидики — идеальное место для романтических поездок без необходимости жертвовать доступностью — в отличие от островов, куда нужно добираться на пароме, здесь можно легко приехать на автомобиле. Бутик-отели с номерами с видом на море, частные пляжи, ужины на закате, спа-процедуры в курортах — все это доступно. Самые романтичные места: <strong>Ситония</strong> для естественного романса (пляжи, закат в Вурвуру), <strong>Афитос</strong> для очаровательной традиционной деревни с видом на море, <strong>Урануполи</strong> для мистической атмосферы Афона. Этот список собрал лучшие варианты для пар и молодоженов.</p>` },
    seasonal: { el: `<h2>Πότε για romantic break</h2><p><strong>Μάιος-Ιούνιος:</strong> Ιδανικό — δροσερά απογεύματα, λουλούδια ανθίζουν, λίγος κόσμος, καλές τιμές. <strong>Σεπτέμβριος:</strong> Equally ideal — ζεστή θάλασσα, λιγότερος κόσμος, sunset δείπνα στα terraces. <strong>Καλοκαίρι:</strong> Pricey, busy. <strong>Χειμώνας:</strong> Cosy alternative — fireplace cabins, παραδοσιακά χωριά με fireplaces, λιγότερα ανοιχτά εστιατόρια.</p>`, en: `<h2>When for a romantic break</h2><p><strong>May-June:</strong> Ideal — cool afternoons, flowers blooming, fewer crowds, better prices. <strong>September:</strong> Equally ideal — warm sea, fewer crowds, sunset dinners on terraces. <strong>Summer:</strong> Pricey, busy. <strong>Winter:</strong> Cosy alternative — fireplace cabins, traditional villages, but fewer open restaurants.</p>`, de: `<h2>Wann für eine romantische Auszeit</h2><p><strong>Mai-Juni:</strong> Ideal – kühle Abende, blühende Blumen, wenig Menschen, gute Preise. <strong>September:</strong> Ebenso ideal – warmes Meer, weniger Menschen, Abendessen bei Sonnenuntergang auf Terrassen. <strong>Sommer:</strong> Teuer, voll. <strong>Winter:</strong> Gemütliche Alternative – Hütten mit Kamin, traditionelle Dörfer mit Kaminen, weniger geöffnete Restaurants.</p>`, ro: `<h2>Când să mergi pentru o escapadă romantică</h2><p><strong>Mai-Iunie:</strong> Ideal — după-amiezi răcoroase, flori în floare, puțină lume, prețuri bune. <strong>Septembrie:</strong> La fel de ideal — mare caldă, mai puțină lume, cine la apus pe terase. <strong>Vara:</strong> Scump, aglomerat. <strong>Iarna:</strong> Alternativă confortabilă — cabane cu șemineu, sate tradiționale cu șemineuri, mai puține restaurante deschise.</p>`, sr: `<h2>Kada za romantični odmor</h2><p><strong>Maj-jun:</strong> Idealno — sveže večeri, cveće cveta, malo ljudi, dobre cene. <strong>Septembar:</strong> Podjednako idealno — toplo more, manje gužve, večere uz zalazak sunca na terasama. <strong>Leto:</strong> Skupo, gužva. <strong>Zima:</strong> Ugodna alternativa — kabine s kaminom, tradicionalna sela s kaminima, manje otvorenih restorana.</p>`, bg: `<h2>Кога за романтична почивка</h2><p><strong>Май-Юни:</strong> Идеално — прохладни следобеди, цъфтящи цветя, малко хора, добри цени. <strong>Септември:</strong> Също толкова идеално — топло море, по-малко хора, вечеря на залез на терасите. <strong>Лято:</strong> Скъпо, натоварено. <strong>Зима:</strong> Уютна алтернатива — кабини с камини, традиционни села с камини, по-малко отворени ресторанти.</p>`, ru: `<h2>Когда поехать на романтический отдых</h2><p><strong>Май-июнь:</strong> Идеально — прохладные вечера, цветущие цветы, мало людей, хорошие цены. <strong>Сентябрь:</strong> Также идеально — теплая вода, меньше людей, ужины на закате на террасах. <strong>Лето:</strong> Дорого, многолюдно. <strong>Зима:</strong> Уютная альтернатива — домики с каминами, традиционные деревни с каминами, меньше открытых ресторанов.</p>` },
    tips: { el: `<h2>Συμβουλές για ζευγάρια</h2><ul><li><strong>Κράτηση 3-6 μήνες πριν:</strong> Τα κορυφαία boutique hotels (Νέος Μαρμαράς, Σάνη, Άφυτος) γεμίζουν νωρίς για peak season.</li><li><strong>Επιπλέον επιλογές:</strong> Σε resorts (Σάνη, Ekies) μπορείς να ζητήσεις champagne welcome, rose petals, special dinner — δωρεάν συνήθως.</li><li><strong>Day trips:</strong> Day cruise από Νέο Μαρμαρά (€80-150/couple για 4-6 ώρες με γεύμα). Sunset cruise από Ουρανούπολη.</li><li><strong>Δείπνα:</strong> Δες <a href="/best/romantic-restaurants">ρομαντικά εστιατόρια</a> για sunset views.</li><li><strong>Spa:</strong> Πολλά resorts έχουν couples treatments. Mediterranean massage €70-150.</li><li><strong>Off the beaten path:</strong> Πιο ρομαντική εμπειρία: μικρό boutique guest house σε παραδοσιακό χωριό αντί για mega resort.</li></ul>`, en: `<h2>Couples tips</h2><ul><li><strong>Book 3-6 months ahead:</strong> Top boutique hotels (Neos Marmaras, Sani, Afytos) fill up early for peak season.</li><li><strong>Extras:</strong> At resorts (Sani, Ekies) you can request champagne welcome, rose petals, special dinner — usually free.</li><li><strong>Day trips:</strong> Day cruise from Neos Marmaras (€80-150/couple for 4-6 hours with lunch). Sunset cruise from Ouranoupoli.</li><li><strong>Dinners:</strong> See our <a href="/best/romantic-restaurants">romantic restaurants</a> for sunset views.</li><li><strong>Spa:</strong> Many resorts have couples treatments. Mediterranean massage €70-150.</li><li><strong>Off the beaten path:</strong> A small boutique guest house in a traditional village is more romantic than a mega resort.</li></ul>`, de: `<h2>Tipps für Paare</h2><ul><li><strong>3-6 Monate im Voraus buchen:</strong> Die besten Boutique-Hotels (Neos Marmaras, Sani, Afytos) sind früh ausgebucht für die Hauptsaison.</li><li><strong>Zusätzliche Optionen:</strong> In Resorts (Sani, Ekies) kann man nach einem Champagner-Empfang, Rosenblättern, speziellem Abendessen fragen – meist kostenlos.</li><li><strong>Tagesausflüge:</strong> Tageskreuzfahrt von Neos Marmaras (€80-150/Paar für 4-6 Stunden mit Mahlzeit). Sonnenuntergangskreuzfahrt von Ouranoupoli.</li><li><strong>Abendessen:</strong> Siehe <a href="/best/romantic-restaurants">romantische Restaurants</a> für Sonnenuntergangsblick.</li><li><strong>Spa:</strong> Viele Resorts bieten Behandlungen für Paare an. Mediterrane Massage €70-150.</li><li><strong>Abseits der ausgetretenen Pfade:</strong> Romantischere Erfahrung: kleines Boutique-Gästehaus in einem traditionellen Dorf statt Mega-Resort.</li></ul>`, ro: `<h2>Sfaturi pentru cupluri</h2><ul><li><strong>Rezervare cu 3-6 luni înainte:</strong> Cele mai bune hoteluri boutique (Neos Marmaras, Sani, Afytos) se umplu devreme pentru sezonul de vârf.</li><li><strong>Opțiuni suplimentare:</strong> În resorturi (Sani, Ekies) poți solicita champagne welcome, petale de trandafir, cină specială — de obicei gratuit.</li><li><strong>Excursii de o zi:</strong> Croazieră de o zi din Neos Marmaras (€80-150/cuplu pentru 4-6 ore cu masă). Croazieră la apus din Ouranoupoli.</li><li><strong>Cine:</strong> Vezi <a href="/best/romantic-restaurants">restaurante romantice</a> pentru vederi la apus.</li><li><strong>Spa:</strong> Multe resorturi oferă tratamente pentru cupluri. Masaj mediteranean €70-150.</li><li><strong>Off the beaten path:</strong> Experiență mai romantică: mică pensiune boutique într-un sat tradițional în loc de mega resort.</li></ul>`, sr: `<h2>Saveti za parove</h2><ul><li><strong>Rezervacija 3-6 meseci unapred:</strong> Najbolji boutique hoteli (Neos Marmaras, Sani, Afytos) brzo se popune za vrhunac sezone.</li><li><strong>Dodatne opcije:</strong> U rizortima (Sani, Ekies) možete tražiti šampanjac dobrodošlice, latice ruža, posebnu večeru — obično besplatno.</li><li><strong>Izleti:</strong> Dnevni krstarenje iz Neos Marmarasa (€80-150/par za 4-6 sati s obrokom). Krstarenje uz zalazak sunca iz Ouranoupolija.</li><li><strong>Večere:</strong> Pogledajte <a href="/best/romantic-restaurants">romantične restorane</a> za poglede na zalazak sunca.</li><li><strong>Spa:</strong> Mnogi rizorti nude tretmane za parove. Mediteranska masaža €70-150.</li><li><strong>Van utabanih staza:</strong> Romantičnije iskustvo: mali boutique guest house u tradicionalnom selu umesto mega rizorta.</li></ul>`, bg: `<h2>Съвети за двойки</h2><ul><li><strong>Резервация 3-6 месеца предварително:</strong> Най-добрите бутик хотели (Неос Мармарас, Сани, Афитос) се запълват рано за пиковия сезон.</li><li><strong>Допълнителни опции:</strong> В курорти (Сани, Ekies) можете да поискате шампанско за добре дошли, розови листенца, специална вечеря — обикновено безплатно.</li><li><strong>Еднодневни екскурзии:</strong> Еднодневен круиз от Неос Мармарас (€80-150/двойка за 4-6 часа с обяд). Круиз на залез от Урануполи.</li><li><strong>Вечери:</strong> Вижте <a href="/best/romantic-restaurants">романтични ресторанти</a> за гледки на залез.</li><li><strong>Спа:</strong> Много курорти предлагат процедури за двойки. Средиземномасаж €70-150.</li><li><strong>Извън утъпканите пътеки:</strong> По-романтично преживяване: малка бутик къща за гости в традиционно село вместо мега курорт.</li></ul>`, ru: `<h2>Советы для пар</h2><ul><li><strong>Бронирование за 3-6 месяцев:</strong> Лучшие бутик-отели (Неос Мармарас, Сани, Афитос) заполняются рано в пиковый сезон.</li><li><strong>Дополнительные опции:</strong> В курортах (Сани, Ekies) можно заказать приветствие с шампанским, лепестки роз, специальный ужин — обычно бесплатно.</li><li><strong>Однодневные поездки:</strong> Круиз на день из Нео Мармараса (€80-150/пара за 4-6 часов с обедом). Круиз на закате из Урануполи.</li><li><strong>Ужины:</strong> Посмотрите <a href="/best/romantic-restaurants">романтические рестораны</a> с видами на закат.</li><li><strong>Спа:</strong> Многие курорты предлагают процедуры для пар. Средиземноморский массаж €70-150.</li><li><strong>Вдали от проторенных дорог:</strong> Более романтичный опыт: небольшой бутик-гостевой дом в традиционной деревне вместо мега-курорта.</li></ul>` },
    faqs: [
      { q: { el: `Καλύτερο μέρος για honeymoon;`, en: `Best for a honeymoon?`, de: `Bester Ort für Flitterwochen?`, ro: `Cel mai bun loc pentru luna de miere?`, sr: `Najbolje mesto za medeni mesec?`, bg: `Най-доброто място за меден месец?`, ru: `Лучшее место для медового месяца?` }, a: { el: `<strong>Σιθωνία</strong> για φυσικά απομονωμένη εμπειρία — boutique hotels με sea view, ιδιωτικές παραλίες. <strong>Σάνη/Καλλιθέα</strong> Κασσάνδρας για 5* luxury experience.`, en: `<strong>Sithonia</strong> for naturally secluded experience — boutique hotels with sea views, private beaches. <strong>Sani/Kallithea</strong> in Kassandra for 5* luxury experience.`, de: `<strong>Sithonia</strong> für eine natürlich abgeschiedene Erfahrung – Boutique-Hotels mit Meerblick, private Strände. <strong>Sani/Kallithea</strong> auf Kassandra für 5* Luxus-Erlebnis.`, ro: `<strong>Sithonia</strong> pentru o experiență natural izolată — hoteluri boutique cu vedere la mare, plaje private. <strong>Sani/Kallithea</strong> în Kassandra pentru o experiență de lux de 5*.`, sr: `<strong>Sithonia</strong> za prirodno izolovano iskustvo — boutique hoteli s pogledom na more, privatne plaže. <strong>Sani/Kallithea</strong> na Kasandri za luksuzno iskustvo s 5 zvezdica.`, bg: `<strong>Ситония</strong> за естествено изолирано преживяване — бутик хотели с изглед към морето, частни плажове. <strong>Сани/Калитея</strong> на Касандра за 5* луксозно преживяване.`, ru: `<strong>Ситония</strong> для естественно уединенного отдыха — бутик-отели с видом на море, частные пляжи. <strong>Сани/Калитея</strong> на Кассандре для 5* роскошного отдыха.` } },
      { q: { el: `Κόστος για 7 βραδινά honeymoon;`, en: `Cost for a 7-night honeymoon?`, de: `Kosten für 7 Nächte Flitterwochen?`, ro: `Costul pentru 7 nopți de luna de miere?`, sr: `Trošak za 7 noći medenog meseca?`, bg: `Цена за 7 нощувки за меден месец?`, ru: `Стоимость 7-дневного медового месяца?` }, a: { el: `<strong>Mid-luxury:</strong> €1500-3000/couple για 7 βραδιές με δείπνα. <strong>Premium:</strong> €3000-6000+ σε resorts όπως Σάνη ή Ekies.`, en: `<strong>Mid-luxury:</strong> €1500-3000/couple for 7 nights with dinners. <strong>Premium:</strong> €3000-6000+ at resorts like Sani or Ekies.`, de: `<strong>Mittelklasse-Luxus:</strong> €1500-3000/Paar für 7 Nächte mit Abendessen. <strong>Premium:</strong> €3000-6000+ in Resorts wie Sani oder Ekies.`, ro: `<strong>Mid-luxury:</strong> €1500-3000/cuplu pentru 7 nopți cu cine. <strong>Premium:</strong> €3000-6000+ în resorturi precum Sani sau Ekies.`, sr: `<strong>Srednji luksuz:</strong> €1500-3000/par za 7 noći s večerama. <strong>Premium:</strong> €3000-6000+ u rizortima kao što su Sani ili Ekies.`, bg: `<strong>Среден лукс:</strong> €1500-3000/двойка за 7 нощувки с вечери. <strong>Премиум:</strong> €3000-6000+ в курорти като Сани или Ekies.`, ru: `<strong>Средний уровень:</strong> €1500-3000/пара за 7 ночей с ужинами. <strong>Премиум:</strong> €3000-6000+ в курортах, таких как Сани или Ekies.` } },
      { q: { el: `Υπάρχουν private beaches;`, en: `Are there private beaches?`, de: `Gibt es private Strände?`, ro: `Există plaje private?`, sr: `Postoje li privatne plaže?`, bg: `Има ли частни плажове?`, ru: `Есть ли частные пляжи?` }, a: { el: `Νομικά όχι — όλες οι ακτές είναι δημόσιες. Στην πράξη, resorts όπως η Σάνη έχουν παραλίες που λειτουργούν "ιδιωτικά" λόγω αποκλειστικής πρόσβασης από το hotel.`, en: `Legally no — all coast is public. In practice, resorts like Sani have beaches that operate "privately" thanks to exclusive hotel access.`, de: `Rechtlich nein – alle Küsten sind öffentlich. In der Praxis haben Resorts wie Sani Strände, die aufgrund des exklusiven Zugangs vom Hotel "privat" funktionieren.`, ro: `Legal nu — toate țărmurile sunt publice. În practică, resorturi precum Sani au plaje care funcționează "privat" datorită accesului exclusiv din hotel.`, sr: `Pravno ne — sve obale su javne. U praksi, rizorti kao što je Sani imaju plaže koje funkcionišu "privatno" zbog ekskluzivnog pristupa iz hotela.`, bg: `Юридически не — всички брегове са обществени. На практика, курорти като Сани имат плажове, които функционират "частно" поради изключителен достъп от хотела.`, ru: `Юридически нет — все побережья общественные. На практике, курорты, такие как Сани, имеют пляжи, которые функционируют как "частные" из-за эксклюзивного доступа от отеля.` } },
    ],
  },
  "luxury-hotels": {
    intro: { el: `<p>Η Χαλκιδική φιλοξενεί μερικά από τα πιο αναγνωρισμένα luxury resorts της Ελλάδας — Σάνη Resort, Ikos Resorts, Eagles Palace, Ekies All Senses. Δεν είναι μόνο μεγάλα ξενοδοχεία, είναι ολοκληρωμένες εμπειρίες με ιδιωτικές παραλίες, fine dining εστιατόρια, spa centers, kids clubs επαγγελματικού επιπέδου και activities. Οι περισσότερα από αυτά συγκεντρώνονται στη <strong>δυτική Κασσάνδρα</strong> (Σάνη, Καλλιθέα) και ορισμένα boutique στη <strong>Σιθωνία</strong> (Νέος Μαρμαράς, Βουρβουρού). Αυτή η λίστα συγκεντρώνει τις premium επιλογές καταλύματος που σταθερά κερδίζουν 5* αξιολογήσεις.</p>`, en: `<p>Halkidiki hosts some of Greece's most recognised luxury resorts — Sani Resort, Ikos Resorts, Eagles Palace, Ekies All Senses. Not just big hotels — they're complete experiences with private beaches, fine-dining restaurants, spa centres, professional kids clubs and activities. Most are concentrated in <strong>western Kassandra</strong> (Sani, Kallithea), with some boutique options in <strong>Sithonia</strong> (Neos Marmaras, Vourvourou). This list collects premium accommodation that consistently earns 5* ratings.</p>`, de: `<p>Chalkidiki beherbergt einige der bekanntesten Luxusresorts Griechenlands — Sani Resort, Ikos Resorts, Eagles Palace, Ekies All Senses. Es sind nicht nur große Hotels, sondern umfassende Erlebnisse mit privaten Stränden, gehobenen Restaurants, Spa-Zentren, professionellen Kinderclubs und Aktivitäten. Die meisten davon befinden sich im <strong>westlichen Kassandra</strong> (Sani, Kallithea) und einige Boutique-Hotels in <strong>Sithonia</strong> (Neos Marmaras, Vourvourou). Diese Liste fasst die Premium-Unterkünfte zusammen, die konstant 5*-Bewertungen erhalten.</p>`, ro: `<p>Halkidiki găzduiește unele dintre cele mai recunoscute resorturi de lux din Grecia — Sani Resort, Ikos Resorts, Eagles Palace, Ekies All Senses. Nu sunt doar hoteluri mari, ci experiențe complete cu plaje private, restaurante fine dining, centre spa, cluburi pentru copii la nivel profesional și activități. Majoritatea acestora sunt concentrate în <strong>vestul peninsulei Kassandra</strong> (Sani, Kallithea) și câteva boutique-uri în <strong>Sithonia</strong> (Neos Marmaras, Vourvourou). Această listă adună opțiunile de cazare premium care câștigă constant evaluări de 5*.</p>`, sr: `<p>Halkidiki je dom nekih od najpoznatijih luksuznih rizorta u Grčkoj — Sani Resort, Ikos Resorts, Eagles Palace, Ekies All Senses. To nisu samo veliki hoteli, već kompletna iskustva sa privatnim plažama, fine dining restoranima, spa centrima, profesionalnim dečijim klubovima i aktivnostima. Većina njih je koncentrisana na <strong>zapadnoj Kasandri</strong> (Sani, Kalitea) i nekoliko boutique hotela na <strong>Sitoniji</strong> (Neos Marmaras, Vourvourou). Ova lista okuplja premium opcije smeštaja koje konstantno dobijaju 5* ocene.</p>`, bg: `<p>Халкидики е дом на някои от най-признатите луксозни курорти в Гърция — Сани Resort, Ikos Resorts, Eagles Palace, Ekies All Senses. Те не са просто големи хотели, а цялостни преживявания с частни плажове, изискани ресторанти, спа центрове, професионални детски клубове и активности. Повечето от тях са съсредоточени в <strong>западната Касандра</strong> (Сани, Калифея) и някои бутикови в <strong>Ситония</strong> (Неос Мармарас, Вурвуру). Този списък събира премиум опциите за настаняване, които стабилно печелят 5* оценки.</p>`, ru: `<p>Халкидики предлагает одни из самых известных luxury курортов Греции — Сани Resort, Ikos Resorts, Eagles Palace, Ekies All Senses. Это не просто большие отели, это полноценные впечатления с частными пляжами, ресторанами высокой кухни, спа-центрами, детскими клубами профессионального уровня и различными активностями. Большинство из них сосредоточены на <strong>западной Кассандре</strong> (Сани, Каллифея) и некоторые бутик-отели на <strong>Ситонии</strong> (Неос Мармарас, Вурвуру). Этот список собрал премиальные варианты размещения, которые стабильно получают 5* оценки.</p>` },
    seasonal: { el: `<h2>Πότε να κρατήσεις</h2><p><strong>Peak season (Ιούλιος-Αύγουστος):</strong> Κρατήσεις 6-12 μήνες πριν για τα top resorts. <strong>Shoulder (Μάιος-Ιούνιος, Σεπτέμβριος):</strong> Καλύτερη value — όλες οι υπηρεσίες ανοιχτές, τιμές 20-30% κάτω. <strong>Σεπτέμβριος:</strong> sweet spot για honeymoon — λιγότερα παιδιά, ζεστή θάλασσα. <strong>Off-season (Νοέμβριος-Μάρτιος):</strong> Πολλά κλειστά, εκτός από Σάνη και κάποια all-year.</p>`, en: `<h2>When to book</h2><p><strong>Peak season (July-August):</strong> Book 6-12 months ahead at top resorts. <strong>Shoulder (May-June, September):</strong> Best value — all services open, prices 20-30% lower. <strong>September:</strong> Sweet spot for honeymoon — fewer kids, warm sea. <strong>Off-season (November-March):</strong> Many closed except Sani and a few year-round operators.</p>`, de: `<h2>Wann buchen</h2><p><strong>Hochsaison (Juli-August):</strong> Buchungen 6-12 Monate im Voraus für die Top-Resorts. <strong>Zwischensaison (Mai-Juni, September):</strong> Bestes Preis-Leistungs-Verhältnis — alle Dienstleistungen geöffnet, Preise 20-30% niedriger. <strong>September:</strong> ideal für Flitterwochen — weniger Kinder, warmes Meer. <strong>Nebensaison (November-März):</strong> Viele geschlossen, außer Sani und einige ganzjährig geöffnete.</p>`, ro: `<h2>Când să rezervi</h2><p><strong>Sezon de vârf (iulie-august):</strong> Rezervări cu 6-12 luni înainte pentru top resorturi. <strong>Sezon intermediar (mai-iunie, septembrie):</strong> Cea mai bună valoare — toate serviciile deschise, prețuri cu 20-30% mai mici. <strong>Septembrie:</strong> moment ideal pentru luna de miere — mai puțini copii, mare caldă. <strong>Extrasezon (noiembrie-martie):</strong> Multe închise, cu excepția Sani și câteva deschise tot anul.</p>`, sr: `<h2>Kada rezervisati</h2><p><strong>Vrh sezone (jul-avgust):</strong> Rezervacije 6-12 meseci unapred za top rizorte. <strong>Prelazni period (maj-jun, septembar):</strong> Najbolja vrednost — sve usluge otvorene, cene 20-30% niže. <strong>Septembar:</strong> idealno za medeni mesec — manje dece, toplo more. <strong>Van sezone (novembar-mart):</strong> Mnogo toga zatvoreno, osim Sani i nekih koji rade cele godine.</p>`, bg: `<h2>Кога да резервирате</h2><p><strong>Пиков сезон (юли-август):</strong> Резервации 6-12 месеца предварително за топ курортите. <strong>Преходен сезон (май-юни, септември):</strong> Най-добра стойност — всички услуги са отворени, цени с 20-30% по-ниски. <strong>Септември:</strong> идеален за меден месец — по-малко деца, топло море. <strong>Извън сезона (ноември-март):</strong> Много затворени, освен Сани и някои целогодишни.</p>`, ru: `<h2>Когда бронировать</h2><p><strong>Пиковый сезон (июль-август):</strong> Бронирование за 6-12 месяцев до поездки для топовых курортов. <strong>Промежуточный сезон (май-июнь, сентябрь):</strong> Лучшее соотношение цены и качества — все услуги открыты, цены на 20-30% ниже. <strong>Сентябрь:</strong> идеальное время для медового месяца — меньше детей, тёплое море. <strong>Низкий сезон (ноябрь-март):</strong> Многие места закрыты, кроме Сани и некоторых круглогодичных.</p>` },
    tips: { el: `<h2>Συμβουλές για luxury stay</h2><ul><li><strong>All-inclusive vs B&B:</strong> Στα μεγάλα resorts (Ikos) το all-inclusive είναι value γιατί περιλαμβάνει premium φαγητά. Σε boutique hotels (Ekies) προτίμα B&B και βγες σε ταβέρνες.</li><li><strong>Sea view vs garden view:</strong> Διαφορά €50-150/βράδυ. Άξιο για sunset views ή Άγιο Όρος (Ουρανούπολη).</li><li><strong>Suite upgrade:</strong> Στο check-in συνήθως υπάρχει διαθεσιμότητα. Πληρωμή €100-300 extra για suite με ιδιωτική πισίνα.</li><li><strong>Spa:</strong> Couples ritual €150-300. Κράτηση 1-2 μέρες πριν.</li><li><strong>Excursions:</strong> Όλα τα resorts προσφέρουν private day cruises, helicopter tours σε Άγιο Όρος, fine dining specials.</li><li><strong>Loyalty:</strong> Σε επανεπίσκεψη πάντα ζητάς upgrade ή welcome amenity.</li></ul>`, en: `<h2>Luxury stay tips</h2><ul><li><strong>All-inclusive vs B&B:</strong> At big resorts (Ikos) all-inclusive is great value because it includes premium dining. At boutique hotels (Ekies) prefer B&B and go out to tavernas.</li><li><strong>Sea view vs garden view:</strong> €50-150/night difference. Worth it for sunsets or Mount Athos (Ouranoupoli).</li><li><strong>Suite upgrade:</strong> Often available at check-in. Pay €100-300 extra for a suite with private pool.</li><li><strong>Spa:</strong> Couples ritual €150-300. Book 1-2 days ahead.</li><li><strong>Excursions:</strong> All resorts offer private day cruises, helicopter tours to Mount Athos, fine-dining specials.</li><li><strong>Loyalty:</strong> On a return visit always ask for an upgrade or welcome amenity.</li></ul>`, de: `<h2>Tipps für einen luxuriösen Aufenthalt</h2><ul><li><strong>All-inclusive vs B&B:</strong> In großen Resorts (Ikos) ist All-inclusive lohnenswert, da es Premium-Essen beinhaltet. In Boutique-Hotels (Ekies) empfiehlt sich B&B und Essen in Tavernen.</li><li><strong>Meerblick vs Gartenblick:</strong> Unterschied €50-150/Nacht. Lohnt sich für Sonnenuntergangsblick oder Berg Athos (Ouranoupoli).</li><li><strong>Suite-Upgrade:</strong> Beim Check-in ist oft Verfügbarkeit vorhanden. Zahlung von €100-300 extra für eine Suite mit privatem Pool.</li><li><strong>Spa:</strong> Paar-Ritual €150-300. Buchung 1-2 Tage im Voraus.</li><li><strong>Ausflüge:</strong> Alle Resorts bieten private Tageskreuzfahrten, Helikoptertouren zum Berg Athos, gehobene Abendessen-Specials.</li><li><strong>Treue:</strong> Bei einem erneuten Besuch immer nach einem Upgrade oder Willkommensgeschenk fragen.</li></ul>`, ro: `<h2>Sfaturi pentru un sejur de lux</h2><ul><li><strong>All-inclusive vs B&B:</strong> În resorturile mari (Ikos), all-inclusive este avantajos deoarece include mâncăruri premium. În hotelurile boutique (Ekies), alege B&B și explorează tavernele locale.</li><li><strong>Vedere la mare vs vedere la grădină:</strong> Diferență de €50-150/noapte. Merită pentru apusuri sau Muntele Athos (Ouranoupoli).</li><li><strong>Upgrade la suită:</strong> La check-in, de obicei există disponibilitate. Plătește €100-300 în plus pentru o suită cu piscină privată.</li><li><strong>Spa:</strong> Ritual pentru cupluri €150-300. Rezervare cu 1-2 zile înainte.</li><li><strong>Excursii:</strong> Toate resorturile oferă croaziere private de o zi, tururi cu elicopterul la Muntele Athos, oferte speciale de fine dining.</li><li><strong>Loialitate:</strong> La o reîntoarcere, cere întotdeauna un upgrade sau un cadou de bun venit.</li></ul>`, sr: `<h2>Saveti za luksuzni boravak</h2><ul><li><strong>All-inclusive vs B&B:</strong> U velikim rizortima (Ikos) all-inclusive je isplativo jer uključuje premium hranu. U boutique hotelima (Ekies) izaberi B&B i večeraj u tavernama.</li><li><strong>Pogled na more vs pogled na vrt:</strong> Razlika €50-150/noć. Vredi za sunset poglede ili Svetu Goru (Uranopolis).</li><li><strong>Nadogradnja apartmana:</strong> Prilikom prijave obično ima dostupnosti. Plaćanje €100-300 dodatno za apartman sa privatnim bazenom.</li><li><strong>Spa:</strong> Ritual za parove €150-300. Rezervacija 1-2 dana unapred.</li><li><strong>Izleti:</strong> Svi rizorti nude privatne dnevne krstarenja, helikopterske ture do Svete Gore, specijalne večere.</li><li><strong>Lojalnost:</strong> Prilikom ponovne posete uvek traži nadogradnju ili dobrodošlicu.</li></ul>`, bg: `<h2>Съвети за луксозен престой</h2><ul><li><strong>All-inclusive срещу B&B:</strong> В големите курорти (Ikos) all-inclusive е изгодно, защото включва премиум храни. В бутикови хотели (Ekies) предпочитайте B&B и излизайте в таверни.</li><li><strong>Изглед към морето срещу изглед към градината:</strong> Разлика €50-150/нощ. Струва си за гледки към залеза или Света гора (Урануполи).</li><li><strong>Надграждане на суита:</strong> При настаняване обикновено има наличност. Доплащане €100-300 за суит с частен басейн.</li><li><strong>Спа:</strong> Ритуал за двойки €150-300. Резервация 1-2 дни предварително.</li><li><strong>Екскурзии:</strong> Всички курорти предлагат частни дневни круизи, хеликоптерни турове до Света гора, специални вечери.</li><li><strong>Лоялност:</strong> При повторно посещение винаги искайте надграждане или приветствен подарък.</li></ul>`, ru: `<h2>Советы для роскошного отдыха</h2><ul><li><strong>All-inclusive vs B&B:</strong> На больших курортах (Ikos) all-inclusive выгодно, так как включает премиум питание. В бутик-отелях (Ekies) выбирайте B&B и посещайте таверны.</li><li><strong>Вид на море vs вид на сад:</strong> Разница €50-150/ночь. Стоит для видов на закат или Афон (Урануполи).</li><li><strong>Обновление номера:</strong> При регистрации обычно есть доступность. Доплата €100-300 за номер с частным бассейном.</li><li><strong>Спа:</strong> Ритуал для пар €150-300. Бронирование за 1-2 дня до.</li><li><strong>Экскурсии:</strong> Все курорты предлагают частные дневные круизы, вертолетные туры на Афон, специальные предложения высокой кухни.</li><li><strong>Лояльность:</strong> При повторном визите всегда просите улучшение номера или приветственный подарок.</li></ul>` },
    faqs: [
      { q: { el: `Καλύτερο luxury resort της Χαλκιδικής;`, en: `Best luxury resort in Halkidiki?`, de: `Bestes Luxusresort in Chalkidiki?`, ro: `Cel mai bun resort de lux din Halkidiki?`, sr: `Najbolji luksuzni rizort u Halkidikiju?`, bg: `Най-добрият луксозен курорт в Халкидики?`, ru: `Лучший luxury курорт Халкидики?` }, a: { el: `Δύσκολη επιλογή — <strong>Σάνη Resort</strong> για variety, <strong>Ikos Olivia</strong> για premium all-inclusive, <strong>Eagles Palace</strong> για location στην Ουρανούπολη, <strong>Ekies All Senses</strong> για boutique experience στη Σιθωνία. Όλα στην λίστα.`, en: `Tough call — <strong>Sani Resort</strong> for variety, <strong>Ikos Olivia</strong> for premium all-inclusive, <strong>Eagles Palace</strong> for Ouranoupoli location, <strong>Ekies All Senses</strong> for boutique Sithonia experience. All in the list.`, de: `Schwierige Wahl — <strong>Sani Resort</strong> für Vielfalt, <strong>Ikos Olivia</strong> für Premium All-inclusive, <strong>Eagles Palace</strong> für die Lage in Ouranoupoli, <strong>Ekies All Senses</strong> für Boutique-Erlebnis in Sithonia. Alle auf der Liste.`, ro: `O alegere dificilă — <strong>Sani Resort</strong> pentru varietate, <strong>Ikos Olivia</strong> pentru all-inclusive premium, <strong>Eagles Palace</strong> pentru locația din Ouranoupoli, <strong>Ekies All Senses</strong> pentru experiența boutique în Sithonia. Toate sunt pe listă.`, sr: `Težak izbor — <strong>Sani Resort</strong> za raznovrsnost, <strong>Ikos Olivia</strong> za premium all-inclusive, <strong>Eagles Palace</strong> za lokaciju u Uranopolisu, <strong>Ekies All Senses</strong> za boutique iskustvo na Sitoniji. Svi su na listi.`, bg: `Труден избор — <strong>Сани Resort</strong> за разнообразие, <strong>Ikos Olivia</strong> за премиум all-inclusive, <strong>Eagles Palace</strong> за местоположение в Урануполи, <strong>Ekies All Senses</strong> за бутиково преживяване в Ситония. Всички в списъка.`, ru: `Сложный выбор — <strong>Сани Resort</strong> за разнообразие, <strong>Ikos Olivia</strong> за премиум all-inclusive, <strong>Eagles Palace</strong> за расположение в Урануполи, <strong>Ekies All Senses</strong> за бутик-опыт на Ситонии. Все в списке.` } },
      { q: { el: `Κόστος ανά βράδυ;`, en: `Cost per night?`, de: `Kosten pro Nacht?`, ro: `Cost pe noapte?`, sr: `Cena po noći?`, bg: `Цена на нощувка?`, ru: `Стоимость за ночь?` }, a: { el: `<strong>Mid-luxury (4*):</strong> €200-400/βράδυ peak season. <strong>Premium (5*):</strong> €400-800. <strong>Suite με ιδιωτική πισίνα:</strong> €800-2500. Σεπτέμβριος -30%.`, en: `<strong>Mid-luxury (4*):</strong> €200-400/night peak season. <strong>Premium (5*):</strong> €400-800. <strong>Suite with private pool:</strong> €800-2500. -30% in September.`, de: `<strong>Mittelklasse-Luxus (4*):</strong> €200-400/Nacht in der Hochsaison. <strong>Premium (5*):</strong> €400-800. <strong>Suite mit privatem Pool:</strong> €800-2500. September -30%.`, ro: `<strong>Mid-luxury (4*):</strong> €200-400/noapte în sezonul de vârf. <strong>Premium (5*):</strong> €400-800. <strong>Suită cu piscină privată:</strong> €800-2500. Septembrie -30%.`, sr: `<strong>Srednji luksuz (4*):</strong> €200-400/noć u vrhuncu sezone. <strong>Premium (5*):</strong> €400-800. <strong>Apartman sa privatnim bazenom:</strong> €800-2500. Septembar -30%.`, bg: `<strong>Среден лукс (4*):</strong> €200-400/нощ в пиков сезон. <strong>Премиум (5*):</strong> €400-800. <strong>Суит с частен басейн:</strong> €800-2500. Септември -30%.`, ru: `<strong>Средний уровень (4*):</strong> €200-400/ночь в пиковый сезон. <strong>Премиум (5*):</strong> €400-800. <strong>Сьют с частным бассейном:</strong> €800-2500. Сентябрь -30%.` } },
      { q: { el: `Καλύτερη χερσόνησος για luxury;`, en: `Best peninsula for luxury?`, de: `Beste Halbinsel für Luxus?`, ro: `Cea mai bună peninsulă pentru lux?`, sr: `Najbolji poluostrvo za luksuz?`, bg: `Най-добрият полуостров за лукс?`, ru: `Лучшая часть полуострова для luxury?` }, a: { el: `<strong>Κασσάνδρα</strong> για variety και υποδομές (Σάνη, Καλλιθέα). <strong>Άθως</strong> για μυστηριώδη εμπειρία (Ουρανούπολη). <strong>Σιθωνία</strong> για boutique και ησυχία.`, en: `<strong>Kassandra</strong> for variety and facilities (Sani, Kallithea). <strong>Athos</strong> for mystical experience (Ouranoupoli). <strong>Sithonia</strong> for boutique and quiet.`, de: `<strong>Kassandra</strong> für Vielfalt und Infrastruktur (Sani, Kallithea). <strong>Athos</strong> für mystische Erfahrung (Ouranoupoli). <strong>Sithonia</strong> für Boutique und Ruhe.`, ro: `<strong>Kassandra</strong> pentru varietate și infrastructură (Sani, Kallithea). <strong>Athos</strong> pentru o experiență misterioasă (Ouranoupoli). <strong>Sithonia</strong> pentru boutique și liniște.`, sr: `<strong>Kasandra</strong> za raznovrsnost i infrastrukturu (Sani, Kalitea). <strong>Athos</strong> za mistično iskustvo (Uranopolis). <strong>Sitonija</strong> za boutique i mir.`, bg: `<strong>Касандра</strong> за разнообразие и инфраструктура (Сани, Калифея). <strong>Атон</strong> за мистериозно преживяване (Урануполи). <strong>Ситония</strong> за бутикови и спокойствие.`, ru: `<strong>Кассандра</strong> за разнообразие и инфраструктуру (Сани, Каллифея). <strong>Афон</strong> за мистический опыт (Урануполи). <strong>Ситония</strong> за бутик и тишину.` } },
    ],
  },
  "camping-spots": {
    intro: { el: `<p>Η Χαλκιδική έχει μερικά από τα καλύτερα οργανωμένα campings της Ελλάδας — με την ιδιαιτερότητα ότι πολλά βρίσκονται κατευθείαν δίπλα σε υπέροχες παραλίες με πευκοδάσος, χωρίς να χρειάζεσαι μετακίνηση. Από beachfront σε <strong>Κασσάνδρα</strong> (Πευκοχώρι, Καλλιθέα), μέχρι πιο φυσικά σε <strong>Σιθωνία</strong> (Παραλία Άρμενιστής, Καλαμίτσι) και <strong>Άθως</strong> (Ουρανούπολη). Οι περισσότερες έχουν πισίνες, εστιατόρια, μίνι-μάρκετ. Αυτή η λίστα συγκεντρώνει τα top-rated camping spots — ιδανικά για budget-friendly οικογενειακές διακοπές ή road trip με trailer.</p>`, en: `<p>Halkidiki has some of Greece's best organised campsites — with the bonus that many sit directly next to stunning beaches with pine forest, no need to travel. From beachfront in <strong>Kassandra</strong> (Pefkochori, Kallithea) to more natural in <strong>Sithonia</strong> (Armenistis Beach, Kalamitsi) and <strong>Athos</strong> (Ouranoupoli). Most have pools, restaurants, mini-markets. This list collects top-rated camping spots — ideal for budget family holidays or trailer road trips.</p>`, de: `<p>Chalkidiki bietet einige der besten organisierten Campingplätze Griechenlands — mit der Besonderheit, dass viele direkt neben wunderschönen Stränden mit Pinienwäldern liegen, ohne dass man sich fortbewegen muss. Von Strandlagen auf <strong>Kassandra</strong> (Pefkochori, Kallithea) bis hin zu natürlicheren Plätzen auf <strong>Sithonia</strong> (Armenistis Beach, Kalamitsi) und <strong>Athos</strong> (Ouranoupoli). Die meisten haben Pools, Restaurants und Mini-Märkte. Diese Liste fasst die bestbewerteten Campingplätze zusammen — ideal für budgetfreundliche Familienurlaube oder Roadtrips mit dem Wohnwagen.</p>`, ro: `<p>Halkidiki are unele dintre cele mai bune campinguri organizate din Grecia — cu particularitatea că multe se află direct lângă plaje superbe cu păduri de pini, fără a fi nevoie de deplasare. De la cele pe plajă în <strong>Kassandra</strong> (Pefkochori, Kallithea), până la cele mai naturale în <strong>Sithonia</strong> (Plaja Armenistis, Kalamitsi) și <strong>Athos</strong> (Ouranoupoli). Majoritatea au piscine, restaurante, mini-marketuri. Această listă adună cele mai bine cotate locuri de camping — ideale pentru vacanțe de familie prietenoase cu bugetul sau excursii cu rulota.</p>`, sr: `<p>Halkidiki ima neka od najboljih organizovanih kampovanja u Grčkoj — sa posebnom karakteristikom da se mnoga nalaze direktno pored prelepih plaža sa borovom šumom, bez potrebe za prevozom. Od kampova na plaži na <strong>Kassandra</strong> (Pefkochori, Kallithea), do prirodnijih na <strong>Sithonia</strong> (Plaža Armenistis, Kalamitsi) i <strong>Athos</strong> (Ouranoupoli). Većina ima bazene, restorane, mini-markete. Ova lista okuplja najbolje ocenjena kamp mesta — idealna za budžet-friendly porodične odmore ili putovanje sa prikolicom.</p>`, bg: `<p>Халкидики има някои от най-добре организираните къмпинги в Гърция — с особеността, че много от тях се намират директно до прекрасни плажове с борови гори, без да е необходимо да се местите. От плажната ивица на <strong>Касандра</strong> (Пефкохори, Калитея), до по-естествените в <strong>Ситония</strong> (Плаж Арменистис, Каламици) и <strong>Атон</strong> (Урануполи). Повечето разполагат с басейни, ресторанти, мини-маркети. Този списък събира топ оценяваните къмпинг места — идеални за бюджетни семейни ваканции или пътешествие с каравана.</p>`, ru: `<p>Халкидики предлагает одни из лучших организованных кемпингов в Греции — многие из них расположены прямо рядом с великолепными пляжами и сосновыми лесами, что избавляет от необходимости перемещаться. От кемпингов на побережье в <strong>Кассандре</strong> (Пефкохори, Каллифея) до более природных в <strong>Ситонии</strong> (пляж Арменистис, Каламици) и <strong>Афоне</strong> (Урануполи). Большинство из них имеют бассейны, рестораны и мини-маркеты. Этот список собрал лучшие кемпинг-места — идеально для бюджетного семейного отдыха или дорожного путешествия с трейлером.</p>` },
    seasonal: { el: `<h2>Πότε να κάνεις camping</h2><p><strong>Ιούνιος-Σεπτέμβριος:</strong> Main season — όλα ανοιχτά, καλύτερα προϊόντα. <strong>Πιο μετά:</strong> Λίγα μένουν ανοιχτά (Καλαμίτσι, Άρμενιστής σε Σιθωνία). <strong>Χειμώνας:</strong> Camping κλειστά. <strong>Καλύτερη ώρα στήσιμο:</strong> Νωρίς πρωί όταν φτάνεις. Πιάνεις το καλύτερο spot.</p>`, en: `<h2>When to camp</h2><p><strong>June-September:</strong> Main season — all open, best offerings. <strong>Beyond:</strong> A few stay open (Kalamitsi, Armenistis in Sithonia). <strong>Winter:</strong> Campsites closed. <strong>Best pitch time:</strong> Early morning on arrival. You get the best spot.</p>`, de: `<h2>Wann campen</h2><p><strong>Juni-September:</strong> Hauptsaison — alles geöffnet, beste Produkte. <strong>Danach:</strong> Wenige bleiben offen (Kalamitsi, Armenistis auf Sithonia). <strong>Winter:</strong> Campingplätze geschlossen. <strong>Beste Zeit zum Aufbauen:</strong> Früh am Morgen, wenn du ankommst. Du bekommst den besten Platz.</p>`, ro: `<h2>Când să faci camping</h2><p><strong>Iunie-Septembrie:</strong> Sezonul principal — totul deschis, cele mai bune produse. <strong>Mai târziu:</strong> Puține rămân deschise (Kalamitsi, Armenistis în Sithonia). <strong>Iarna:</strong> Campingurile sunt închise. <strong>Cel mai bun moment pentru instalare:</strong> Dimineața devreme când ajungi. Prinzi cel mai bun loc.</p>`, sr: `<h2>Kada ići na kampovanje</h2><p><strong>Jun-Septembar:</strong> Glavna sezona — sve otvoreno, najbolji proizvodi. <strong>Kasnije:</strong> Malo ih ostaje otvoreno (Kalamitsi, Armenistis na Sithonia). <strong>Zima:</strong> Kampovi zatvoreni. <strong>Najbolje vreme za postavljanje:</strong> Rano ujutru kada stignete. Zauzimate najbolje mesto.</p>`, bg: `<h2>Кога да къмпингувате</h2><p><strong>Юни-Септември:</strong> Основен сезон — всичко е отворено, най-добрите продукти. <strong>След това:</strong> Малко остават отворени (Каламици, Арменистис в Ситония). <strong>Зима:</strong> Къмпингите са затворени. <strong>Най-добро време за разпъване:</strong> Рано сутрин, когато пристигате. Хващате най-доброто място.</p>`, ru: `<h2>Когда заниматься кемпингом</h2><p><strong>Июнь-сентябрь:</strong> Основной сезон — все открыто, лучшие продукты. <strong>Позже:</strong> Открыты немногие (Каламици, Арменистис в Ситонии). <strong>Зима:</strong> Кемпинги закрыты. <strong>Лучшее время для установки:</strong> Раннее утро, когда приезжаешь. Занимаешь лучшее место.</p>` },
    tips: { el: `<h2>Συμβουλές για camping</h2><ul><li><strong>Κράτηση:</strong> Online ή τηλεφωνική 1-2 βδομάδες πριν για peak season. Στις πιο γνωστές γεμίζει.</li><li><strong>Τιμές 2026:</strong> Σκηνή €15-25/βράδυ + €5-10/άτομο. Caravan €25-40/βράδυ. Bungalow €60-120/βράδυ.</li><li><strong>Εξοπλισμός:</strong> Πάρε σκηνή με αντοχή στον αέρα (μερικά campings σε εκτεθειμένες παραλίες). Σλίπινγκ μπαγκ, στρώμα.</li><li><strong>Φαγητό:</strong> Πολλά campings έχουν εστιατόριο/καντίνα. Mini market για supplies. BBQ συχνά επιτρέπεται.</li><li><strong>Beach access:</strong> Άμεση από όλα τα campings — αυτό είναι το πλεονέκτημα. Δες τις <a href="/best/family-beaches">οικογενειακές παραλίες</a> για κοντινές επιλογές.</li><li><strong>Παροχές:</strong> Wifi συχνά δωρεάν (slow στις πιο φυσικές). Ντουζ, πλυντήρια ρούχων, παιδική χαρά.</li></ul>`, en: `<h2>Camping tips</h2><ul><li><strong>Reservation:</strong> Online or phone 1-2 weeks ahead for peak season. The most famous ones fill up.</li><li><strong>2026 prices:</strong> Tent €15-25/night + €5-10/person. Caravan €25-40/night. Bungalow €60-120/night.</li><li><strong>Gear:</strong> Bring a wind-resistant tent (some sites are on exposed beaches). Sleeping bag, mat.</li><li><strong>Food:</strong> Many campsites have a restaurant/canteen. Mini market for supplies. BBQ usually allowed.</li><li><strong>Beach access:</strong> Direct from all campsites — that's the perk. See our <a href="/best/family-beaches">family beaches</a> for nearby options.</li><li><strong>Amenities:</strong> Wi-Fi often free (slow at the more natural ones). Showers, laundry, playground.</li></ul>`, de: `<h2>Tipps fürs Camping</h2><ul><li><strong>Buchung:</strong> Online oder telefonisch 1-2 Wochen im Voraus für die Hochsaison. Die bekanntesten sind schnell ausgebucht.</li><li><strong>Preise 2026:</strong> Zelt €15-25/Nacht + €5-10/Person. Wohnwagen €25-40/Nacht. Bungalow €60-120/Nacht.</li><li><strong>Ausrüstung:</strong> Nimm ein zelt mit Windbeständigkeit (einige Campingplätze liegen an exponierten Stränden). Schlafsack, Isomatte.</li><li><strong>Essen:</strong> Viele Campingplätze haben ein Restaurant/Kantine. Mini-Markt für Vorräte. Grillen ist oft erlaubt.</li><li><strong>Zugang zum Strand:</strong> Direkter Zugang von allen Campingplätzen — das ist der Vorteil. Sieh dir die <a href="/best/family-beaches">Familienstrände</a> für nahegelegene Optionen an.</li><li><strong>Ausstattung:</strong> WLAN oft kostenlos (langsam bei den natürlicheren). Duschen, Waschmaschinen, Spielplatz.</li></ul>`, ro: `<h2>Sfaturi pentru camping</h2><ul><li><strong>Rezervare:</strong> Online sau telefonic cu 1-2 săptămâni înainte pentru sezonul de vârf. Cele mai cunoscute se umplu.</li><li><strong>Prețuri 2026:</strong> Cort €15-25/noapte + €5-10/persoană. Rulotă €25-40/noapte. Bungalow €60-120/noapte.</li><li><strong>Echipament:</strong> Ia un cort rezistent la vânt (unele campinguri sunt pe plaje expuse). Sac de dormit, saltea.</li><li><strong>Mâncare:</strong> Multe campinguri au restaurant/cantină. Mini market pentru provizii. BBQ este adesea permis.</li><li><strong>Acces la plajă:</strong> Direct din toate campingurile — acesta este avantajul. Vezi <a href="/best/family-beaches">plajele de familie</a> pentru opțiuni apropiate.</li><li><strong>Facilități:</strong> Wifi adesea gratuit (lent în cele mai naturale). Dușuri, mașini de spălat, loc de joacă pentru copii.</li></ul>`, sr: `<h2>Saveti za kampovanje</h2><ul><li><strong>Rezervacija:</strong> Online ili telefonski 1-2 nedelje unapred za vrhunac sezone. Najpoznatiji se brzo popune.</li><li><strong>Cene 2026:</strong> Šator €15-25/noć + €5-10/osoba. Karavan €25-40/noć. Bungalov €60-120/noć.</li><li><strong>Oprema:</strong> Ponesite šator otporan na vetar (neki kampovi su na izloženim plažama). Vreća za spavanje, dušek.</li><li><strong>Hrana:</strong> Mnoga kampovanja imaju restoran/kantinu. Mini market za potrepštine. BBQ je često dozvoljen.</li><li><strong>Pristup plaži:</strong> Direktan iz svih kampova — to je prednost. Pogledajte <a href="/best/family-beaches">porodične plaže</a> za obližnje opcije.</li><li><strong>Pogodnosti:</strong> Wifi često besplatan (sporiji u prirodnijim). Tuševi, veš mašine, dečje igralište.</li></ul>`, bg: `<h2>Съвети за къмпинг</h2><ul><li><strong>Резервация:</strong> Онлайн или по телефона 1-2 седмици предварително за пиковия сезон. На по-известните места се запълва.</li><li><strong>Цени 2026:</strong> Палатка €15-25/нощ + €5-10/човек. Каравана €25-40/нощ. Бунгало €60-120/нощ.</li><li><strong>Оборудване:</strong> Вземете палатка устойчива на вятър (някои къмпинги са на открити плажове). Спален чувал, матрак.</li><li><strong>Храна:</strong> Много къмпинги имат ресторант/кантина. Мини маркет за запаси. BBQ често е позволено.</li><li><strong>Достъп до плажа:</strong> Директен от всички къмпинги — това е предимството. Вижте <a href="/best/family-beaches">семейните плажове</a> за близки опции.</li><li><strong>Удобства:</strong> Wifi често безплатно (бавен в по-естествените). Душове, перални машини, детска площадка.</li></ul>`, ru: `<h2>Советы для кемпинга</h2><ul><li><strong>Бронирование:</strong> Онлайн или по телефону за 1-2 недели до пикового сезона. В самых популярных местах быстро заполняется.</li><li><strong>Цены 2026:</strong> Палатка €15-25/ночь + €5-10/человек. Караван €25-40/ночь. Бунгало €60-120/ночь.</li><li><strong>Оборудование:</strong> Возьмите палатку, устойчивую к ветру (некоторые кемпинги находятся на открытых пляжах). Спальный мешок, матрас.</li><li><strong>Еда:</strong> Во многих кемпингах есть ресторан/кафе. Мини-маркет для покупок. Барбекю часто разрешено.</li><li><strong>Доступ к пляжу:</strong> Прямой из всех кемпингов — это преимущество. Посмотрите <a href="/best/family-beaches">семейные пляжи</a> для близких вариантов.</li><li><strong>Удобства:</strong> Wifi часто бесплатный (медленный в более природных местах). Душ, прачечные, детская площадка.</li></ul>` },
    faqs: [
      { q: { el: `Καλύτερο camping στη Χαλκιδική;`, en: `Best camping in Halkidiki?`, de: `Bester Campingplatz in Chalkidiki?`, ro: `Cel mai bun camping din Halkidiki?`, sr: `Najbolje kampovanje na Halkidikiju?`, bg: `Най-добрият къмпинг в Халкидики?`, ru: `Лучший кемпинг в Халкидиках?` }, a: { el: `<strong>Camping Sithonia</strong> (Σιθωνία) για φυσικό setting και άμεση πρόσβαση παραλία. <strong>Camping Armenistis</strong> για ωραίο sandy beach. <strong>Camping Pefkochori</strong> (Κασσάνδρα) για υποδομές. Δες όλα τα locations στην λίστα.`, en: `<strong>Camping Sithonia</strong> (Sithonia) for natural setting and direct beach access. <strong>Camping Armenistis</strong> for a nice sandy beach. <strong>Camping Pefkochori</strong> (Kassandra) for facilities. See all locations in the list.`, de: `<strong>Camping Sithonia</strong> (Sithonia) für natürliche Umgebung und direkten Strandzugang. <strong>Camping Armenistis</strong> für schönen Sandstrand. <strong>Camping Pefkochori</strong> (Kassandra) für Infrastruktur. Sieh dir alle Standorte in der Liste an.`, ro: `<strong>Camping Sithonia</strong> (Sithonia) pentru un cadru natural și acces direct la plajă. <strong>Camping Armenistis</strong> pentru o plajă cu nisip frumoasă. <strong>Camping Pefkochori</strong> (Kassandra) pentru infrastructură. Vezi toate locațiile în listă.`, sr: `<strong>Camping Sithonia</strong> (Sithonia) za prirodno okruženje i direktan pristup plaži. <strong>Camping Armenistis</strong> za lepu peščanu plažu. <strong>Camping Pefkochori</strong> (Kassandra) za infrastrukturu. Pogledajte sve lokacije na listi.`, bg: `<strong>Къмпинг Ситония</strong> (Ситония) за естествена обстановка и директен достъп до плажа. <strong>Къмпинг Арменистис</strong> за хубав пясъчен плаж. <strong>Къмпинг Пефкохори</strong> (Касандра) за инфраструктура. Вижте всички локации в списъка.`, ru: `<strong>Кемпинг Ситония</strong> (Ситония) для природной обстановки и прямого доступа к пляжу. <strong>Кемпинг Арменистис</strong> для красивого песчаного пляжа. <strong>Кемпинг Пефкохори</strong> (Кассандра) для инфраструктуры. Посмотрите все места в списке.` } },
      { q: { el: `Δέχονται caravans;`, en: `Do they accept caravans?`, de: `Akzeptieren sie Wohnwagen?`, ro: `Acceptă rulote?`, sr: `Da li primaju karavane?`, bg: `Приемат ли каравани?`, ru: `Принимают ли караваны?` }, a: { el: `Ναι σχεδόν παντού. Έχουν specific spots για caravan και motorhome με ηλεκτρισμό. Τιμή 30-50% παραπάνω από σκηνή.`, en: `Yes, almost everywhere. They have specific caravan and motorhome spots with electricity. 30-50% more than a tent pitch.`, de: `Ja, fast überall. Sie haben spezielle Stellplätze für Wohnwagen und Wohnmobile mit Stromanschluss. Preis 30-50% höher als Zelt.`, ro: `Da, aproape peste tot. Au locuri specifice pentru rulote și autorulote cu electricitate. Preț cu 30-50% mai mare decât pentru cort.`, sr: `Da, skoro svuda. Imaju specifična mesta za karavane i motorhome sa strujom. Cena 30-50% viša od šatora.`, bg: `Да, почти навсякъде. Имат специални места за каравани и кемпери с електричество. Цената е с 30-50% по-висока от палатка.`, ru: `Да, почти везде. Есть специальные места для караванов и автодомов с электричеством. Цена на 30-50% выше, чем для палатки.` } },
      { q: { el: `Κατάλληλο για παιδιά;`, en: `Suitable for kids?`, de: `Geeignet für Kinder?`, ro: `Potrivit pentru copii?`, sr: `Pogodno za decu?`, bg: `Подходящо ли е за деца?`, ru: `Подходит ли для детей?` }, a: { el: `Πολύ. Όλα τα μεγάλα campings έχουν παιδικές χαρές, πισίνες με ρηχό κομμάτι, animation, snack bars. Πολλά παιδιά κάνουν φίλους.`, en: `Very much. All major campsites have playgrounds, pools with shallow sections, animation, snack bars. Lots of kids make friends.`, de: `Sehr. Alle großen Campingplätze haben Spielplätze, Pools mit flachem Bereich, Animation, Snackbars. Viele Kinder finden Freunde.`, ro: `Foarte. Toate campingurile mari au locuri de joacă, piscine cu zonă de mică adâncime, animație, snack baruri. Mulți copii își fac prieteni.`, sr: `Veoma. Svi veliki kampovi imaju dečja igrališta, bazene sa plitkim delom, animaciju, snack barove. Mnoga deca sklapaju prijateljstva.`, bg: `Много. Всички големи къмпинги имат детски площадки, басейни с плитка част, анимация, снек барове. Много деца си намират приятели.`, ru: `Очень. Все большие кемпинги имеют детские площадки, бассейны с мелкой частью, анимацию, снэк-бары. Многие дети находят друзей.` } },
    ],
  },
};
